#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_0 0x4000      // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040 // +/- 4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0002 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0001 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int handle)
{
    char buf[2];
    int16_t value;

    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERT, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion register\n");
        return -1;
    }

    value = (buf[0] << 8) | buf[1];
    return value;
}

// Function to calculate current from ADC value
float calculate_current(int16_t adc_value)
{
    float current;
    float vout = (float)adc_value * 4.096 / 32768.0; // Assuming +/- 4.096V range
    current = vout / 0.04; // 40mV/A = 0.04V/A
    return current;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = CONFIG_OS_SINGLE | CONFIG_MUX_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
    config_buf[2] = 0x00; // Dummy byte

    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, config_buf+1, 2) != 2) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int16_t adc_value = read_ads1115(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate current
        float current = calculate_current(adc_value);

        // Log current to console
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500);
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

