#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define CSV_FILE "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float approximate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to approximate temperature
float approximate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -100.0; // Indicate an error
    }

    // Linear mapping: 0-1023 -> 10-40°C
    float temperature = 10.0 + (float)adc_value * (40.0 - 10.0) / 1023.0;
    return temperature;
}

// Function to log data to CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fp != NULL) {
        fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(fp); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Could not write to CSV file.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure flame sensor GPIO as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open CSV file for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature\n");
    }
    fflush(fp);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Approximate temperature
        float temperature = approximate_temperature(adc_value);

        // Log data
        if (flame_detected == 0) { // Flame detected (LOW signal)
            log_data(1, temperature);
        } else {
            // No flame detected or error occurred
            // Log_data(0, temperature); // Optionally log even if no flame
            //printf("No flame detected or error occurred.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Clean up
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

