#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define HEAT_SENSOR_I2C_ADDR 0x48
#define HEAT_SENSOR_CHANNEL 0x00
#define BUZZER_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define BUZZER_DURATION_S 2
#define TEMP_THRESHOLD 60.0
#define LOG_FILE_NAME "fire_log.txt"

// Global variables
static volatile int running = 1;
static volatile unsigned int last_flame_time = 0;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int read_heat_sensor(float *temperature);
int log_event(const char *message);
void signal_handler(int signal);
void flame_detected_isr(int gpio, int level, unsigned int tick, void *userdata);

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Use internal pull-up

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, HEAT_SENSOR_I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
