#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip4" // Try this first, then fall back to 0
#define FAN_GPIO 18
#define DEFAULT_SENSITIVITY 0.1 // 100 mV/A = 0.1 V/A
#define DEFAULT_THRESHOLD 5.0
#define LOG_FILE "current_log.txt"

// Global variables (minimize usage)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
float adc_to_current(int adc_value, float sensitivity);
int gpio_init(const char *chip_name, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(FILE *fp, float current);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_bits = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_bits) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_hz = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC to current conversion function
float adc_to_current(int adc_value, float sensitivity) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    return voltage / sensitivity;
}

// GPIO initialization function
int gpio_init(const char *chip_name, int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "current_monitor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s, %.2f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_chip) {
        if (fan_line) {
            gpiod_line_release(fan_line);
        }
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Falling back to GPIO chip 0.\n");
        gpio_chip = gpiod_chip_open_by_name("gpiochip0");
        if (!gpio_chip) {
            fprintf(stderr, "GPIO initialization failed. Exiting.\n");
            close(spi_fd);
            return EXIT_FAILURE;
        }
    }

    fan_line = gpiod_chip_get_line(gpio_chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpio_init(GPIO_CHIP, FAN_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(fan_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3] = {0};
    int adc_value;
    float current;

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Check for sensor-absent condition
        if (adc_value == 0) {
            fprintf(stderr, "Sensor-absent condition detected. Check sensor connection.\n");
            log_data(log_file, -1.0); // Log an error value
        } else if (adc_value == 1023) {
            fprintf(stderr, "Sensor-absent condition detected. Check sensor connection.\n");
            log_data(log_file, -1.0); // Log an error value
        } else {
            // Convert ADC value to current
            current = adc_to_current(adc_value, sensitivity);

            // Control fan based on current threshold
            if (current > threshold) {
                if (gpio_set_value(fan_line, 1) < 0) {
                    fprintf(stderr, "Failed to turn fan ON.\n");
                }
            } else {
                if (gpio_set_value(fan_line, 0) < 0) {
                    fprintf(stderr, "Failed to turn fan OFF.\n");
                }
            }

            // Log data
            if (log_data(log_file, current) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

