#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000 // AIN0, GND
#define ADS1115_CONFIG_PGA_4_096V 0x0040 // +/- 4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_ACTIVE_LOW 0x0000 // Active low
#define ADS1115_CONFIG_COMP_LAT_NON_LATCHING 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

#define CO_LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float calculate_ppm(int16_t raw_value);
int log_ppm(float ppm_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read 16-bit ADC value from ADS1115
int16_t read_adc() {
    uint8_t config[3];
    uint8_t read_data[2];
    int16_t adc_value;

    // Construct the configuration register value
    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_ACTIVE_LOW | ADS1115_CONFIG_COMP_LAT_NON_LATCHING | ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Write the configuration register
    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, (char *)config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)read_data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    adc_value = (read_data[0] << 8) | read_data[1];

    return adc_value;
}

// Calculate CO concentration in PPM from raw ADC value
float calculate_ppm(int16_t raw_value) {
    // Logarithmic curve calibration parameters (example values)
    float a = 0.01;  // Example slope
    float b = 10.0; // Example intercept

    // Calculate PPM using the logarithmic curve
    float ppm = a * raw_value + b;

    // Ensure PPM is not negative
    if (ppm < 0) {
        ppm = 0;
    }

    return ppm;
}

// Log CO concentration to file
int log_ppm(float ppm_value) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO_LOG_FILE);
        return -1;
    }

    // Write the timestamp and PPM value to the log file
    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm_value);

    // Close the log file
    fclose(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C communication
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        int16_t raw_value = read_adc();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in 5 seconds...\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Calculate PPM value
        float ppm_value = calculate_ppm(raw_value);

        // Log PPM value
        if (log_ppm(ppm_value) != 0) {
            fprintf(stderr, "Error logging PPM value\n");
        }

        // Print PPM value to console
        printf("CO concentration: %.2f PPM\n", ppm_value);

        // Wait for 5 seconds
        gpioDelay(5000000);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("CO sensor monitoring stopped.\n");

    return 0;
}

