// Function prototypes
int read_flame_sensor();
int read_adc(int channel);
float convert_adc_to_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to read the ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to temperature
float convert_adc_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -100.0; // Indicate error
    }

    float temperature = MIN_TEMP + (float)adc_value / 1023.0 * (MAX_TEMP - MIN_TEMP);
    return temperature;
}

// Function to log data to CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fp != NULL) {
        fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(fp); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: File pointer is NULL in log_data\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure flame sensor GPIO as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature\n");
    }
    fflush(fp);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, skipping log entry.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping log entry.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);
        if (temperature < -99.0) {
            fprintf(stderr, "Error converting ADC to temperature, skipping log entry.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Log data
        log_data(flame_detected, temperature);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Close file
    fclose(fp);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

