#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MICS_4514_ADDR 0x49
#define CO_REG 0x01 // Example register address for CO
#define NO2_REG 0x02 // Example register address for NO2
#define CO_PPM_SCALE 0.1 // Example scaling factor for CO to PPM
#define ALERT_THRESHOLD 25.0 // PPM
#define READ_INTERVAL 5 // Seconds

// Global variables
int i2c_handle;
FILE *co_log_file = NULL;
FILE *alert_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char *data);
float calculate_co_ppm(unsigned char *data);
int log_co_level(float co_ppm);
int check_alert(float co_ppm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS_4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadI2CBlockData(i2c_handle, CO_REG, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CO level in PPM
float calculate_co_ppm(unsigned char *data) {
    unsigned int co_raw = (data[0] << 8) | data[1];
    return (float)co_raw * CO_PPM_SCALE;
}

// Log CO level to file
int log_co_level(float co_ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (co_log_file == NULL) {
        co_log_file = fopen("co_log.txt", "a");
        if (co_log_file == NULL) {
            fprintf(stderr, "Error opening co_log.txt\n");
            return -1;
        }
    }

    fprintf(co_log_file, "%s, %.2f PPM\n", timestamp, co_ppm);
    fflush(co_log_file); // Ensure data is written to disk
    return 0;
}

// Check for alert condition
int check_alert(float co_ppm) {
    if (co_ppm > ALERT_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        if (alert_log_file == NULL) {
            alert_log_file = fopen("alert_log.txt", "a");
            if (alert_log_file == NULL) {
                fprintf(stderr, "Error opening alert_log.txt\n");
                return -1;
            }
        }

        fprintf(alert_log_file, "%s, ALERT: CO level exceeded %.2f PPM\n", timestamp, ALERT_THRESHOLD);
        fflush(alert_log_file);
        return 1; // Alert triggered
    }
    return 0; // No alert
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char sensor_data[4];
    float co_ppm;

    printf("Starting CO monitoring...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Calculate CO level
            co_ppm = calculate_co_ppm(sensor_data);

            // Log CO level
            if (log_co_level(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO level\n");
            }

            // Check for alert
            if (check_alert(co_ppm) != 0) {
                printf("CO alert triggered!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (co_log_file != NULL) {
        fclose(co_log_file);
    }
    if (alert_log_file != NULL) {
        fclose(alert_log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

