#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define I2C addresses for the microphones
#define MICROPHONE1_ADDRESS 0x48
#define MICROPHONE2_ADDRESS 0x49

// Define the I2C bus
#define I2C_BUS 1

// Define the register to read from (assuming no register address is needed)
#define I2C_REGISTER 0x00

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL 100

// Define the microphone sensitivity in dBV/Pa
#define MICROPHONE_SENSITIVITY -38.0

// Define the reference pressure in Pascals
#define REFERENCE_PRESSURE 20e-6

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold microphone data
typedef struct {
    int16_t microphone1;
    int16_t microphone2;
} MicrophoneData;

// Function prototypes
int initialize_i2c(int bus, int address);
int read_microphone_data(int handle, int16_t *data);
double convert_to_dbs(int16_t raw_data);
double calculate_average_dbs(double db1, double db2);
void log_data(double average_dbs);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize I2C communication
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", address, handle);
        return -1;
    }
    return handle;
}

// Function to read data from a microphone
int read_microphone_data(int handle, int16_t *data) {
    char buffer[2];
    int result = i2cReadDevice(handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to convert raw data to dB
double convert_to_dbs(int16_t raw_data) {
    // Assuming a linear relationship between raw data and sound pressure level
    // and using the microphone sensitivity and reference pressure.
    // This is a simplified conversion and may need calibration.
    double voltage = (double)raw_data / 65535.0; // Normalize to 0-1 range
    double pressure = voltage * pow(10, MICROPHONE_SENSITIVITY / 20.0) * REFERENCE_PRESSURE;
    return 20 * log10(pressure / REFERENCE_PRESSURE);
}

// Function to calculate the average dB value
double calculate_average_dbs(double db1, double db2) {
    return (db1 + db2) / 2.0;
}

// Function to log the data to a file
void log_data(double average_dbs) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, average_dbs);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C communication for both microphones
    i2c_handle1 = initialize_i2c(I2C_BUS, MICROPHONE1_ADDRESS);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, MICROPHONE2_ADDRESS);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    printf("Acoustic leak detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        MicrophoneData data;
        double db1, db2, average_dbs;

        // Read data from microphone 1
        if (read_microphone_data(i2c_handle1, &data.microphone1) != 0) {
            db1 = -999.0;
        } else {
            db1 = convert_to_dbs(data.microphone1);
        }

        // Read data from microphone 2
        if (read_microphone_data(i2c_handle2, &data.microphone2) != 0) {
            db2 = -999.0;
        } else {
            db2 = convert_to_dbs(data.microphone2);
        }

        // Calculate the average dB value
        average_dbs = calculate_average_dbs(db1, db2);

        // Log the data
        log_data(average_dbs);

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C handles
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

