int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int channel;
    int ce_pin;
    int adc_channel;
} Microphone;

// Function prototypes
int initialize_spi();
int read_adc(int ce_pin, int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int ce_pin, int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(ce_pin, 0); // Select the ADC
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(ce_pin, 1); // Deselect the ADC

