#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000 // AIN0, GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060 // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define CIRCULAR_BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_circular_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char read_data[2];

    // Construct the configuration register value
    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    // Write the configuration to the ADS1115
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *raw_value = (read_data[0] << 8) | read_data[1];

    return 0;
}

// Convert raw ADC value to current (Amps)
float convert_to_current(int16_t raw_value) {
    // Assuming a linear relationship between voltage and current:
    // 0.5V = 0A, 4.5V = 100A
    // 5V = 100A (ADS1115 reference voltage)
    // raw_value is a 16-bit signed integer, so the range is -32768 to 32767
    // Scale the raw value to the voltage range (0-5V) and then to the current range (0-100A)
    float voltage = (float)raw_value / 32767.0 * 5.0; // Scale to 0-5V
    float current = (voltage - 0.5) / 4.0 * 100.0; // Scale to 0-100A
    return current;
}

// Add current reading to circular buffer
void add_to_circular_buffer(float current) {
    current_buffer.buffer[current_buffer.head] = current;
    current_buffer.head = (current_buffer.head + 1) % CIRCULAR_BUFFER_SIZE;
    if (current_buffer.count < CIRCULAR_BUFFER_SIZE) {
        current_buffer.count++;
    }
}

// Calculate the average current from the circular buffer
float calculate_average_current() {
    if (current_buffer.count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < current_buffer.count; i++) {
        sum += current_buffer.buffer[i];
    }
    return sum / current_buffer.count;
}

// Control the LED based on the average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    current_buffer.head = 0;
    current_buffer.count = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        float current;

        // Read from ADS1115
        if (read_ads1115(&raw_value) == 0) {
            // Convert to current
            current = convert_to_current(raw_value);

            // Add to circular buffer
            add_to_circular_buffer(current);

            // Calculate average current
            float average_current = calculate_average_current();

            // Control LED
            control_led(average_current);

            printf("Raw: %d, Current: %.2f A, Average: %.2f A\n", raw_value, current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

