#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor_id(int handle);
int configure_sensor(int handle);
int read_sensor_data(int handle, sensor_data_t *data);
int log_sensor_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg, uint8_t *value);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Verify sensor ID
int verify_sensor_id(int handle) {
    uint8_t id;
    if (read_register(handle, 0x12, &id) != 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }

    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Configure sensor
int configure_sensor(int handle) {
    if (write_register(handle, TCS34725_ATIME, 0xFF) != 0) return -1;
    if (write_register(handle, TCS34725_CONTROL, 0x01) != 0) return -1;
    return 0;
}

// Write to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Read from a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t buffer[8];

    if (i2cReadI2CBlockData(handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    data->clear = (buffer[1] << 8) | buffer[0];
    data->red   = (buffer[3] << 8) | buffer[2];
    data->green = (buffer[5] << 8) | buffer[4];
    data->blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Log sensor data to CSV file
int log_sensor_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(1, TCS34725_I2C_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log sensor data
            log_sensor_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's non-blocking delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

