    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (cs_line) {
        gpiod_line_release(cs_line);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_fp) {
        fclose(log_fp);
    }

    printf("Cleanup complete.\n");
}

