    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Moisture1,Moisture2\n");
    }
    rewind(log_fp);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read ADC values
        adc_value1 = read_mcp3008(0);
        adc_value2 = read_mcp3008(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Map ADC values to moisture percentages
        moisture1 = map_adc_to_moisture(adc_value1);
        moisture2 = map_adc_to_moisture(adc_value2);

