#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define PRESSURE_MAX 500.0
#define PRESSURE_MIN 0.0
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_pressure(int *raw_value);
float convert_to_kPa(int raw_value);
char* get_iso8601_utc_timestamp(char* timestamp_buffer, size_t buffer_size);
int log_pressure_data(const char* timestamp, float pressure_kPa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read pressure data from the sensor
int read_pressure(int *raw_value) {
    char buffer[2];
    int result;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);
        if (result == 2) {
            *raw_value = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading pressure data (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw value to kPa
float convert_to_kPa(int raw_value) {
    if (raw_value < 0 || raw_value > 65535) {
        fprintf(stderr, "Invalid raw value: %d\n", raw_value);
        return -1.0; // Indicate error
    }
    return (float)raw_value / 65535.0 * PRESSURE_MAX;
}

// Function to get ISO 8601 UTC timestamp
char* get_iso8601_utc_timestamp(char* timestamp_buffer, size_t buffer_size) {
