#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_REG_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_REG_CONFIG_MUX_SINGLE_1 0x5000 // AIN1 single-ended
#define ADS1115_REG_CONFIG_PGA_2_3V 0x0000 // +/- 6.144V range
#define ADS1115_REG_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_REG_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_ads1115(int channel);
float convert_to_pressure(int adc_value);
float convert_to_temperature(int adc_value);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int channel) {
    unsigned char config[3];
    int retries = 3;
    int adc_value = -1;

    // Configure the ADS1115 for single-ended read on the specified channel
    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_REG_CONFIG_OS_SINGLE | ADS1115_REG_CONFIG_MUX_SINGLE_0 | ADS1115_REG_CONFIG_PGA_2_3V | ADS1115_REG_CONFIG_MODE_SINGLE | ADS1115_REG_CONFIG_DR_128SPS;
    config[2] = 0; // Dummy byte

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)config, 3) == 0) {
            // Wait for conversion to complete (at least 8ms for 128 SPS)
            gpioDelay(10000); // 10ms

            // Read the conversion result
            config[0] = ADS1115_REG_CONVERT;
            if (i2cWriteDevice(i2c_handle, (char *)config, 1) == 0) {
                char buffer[2];
                if (i2cReadDevice(i2c_handle, buffer, 2) == 2) {
                    adc_value = (buffer[0] << 8) | buffer[1];
                    // Sign extend 16-bit value
                    if (adc_value & 0x8000) {
                        adc_value |= 0xFFFF0000;
                    }
                    return adc_value;
                } else {
                    fprintf(stderr, "Error reading ADC value: %d\n", i2c_handle);
                }
            } else {
                fprintf(stderr, "Error writing to ADS1115 for conversion: %d\n", i2c_handle);
            }
        } else {
            fprintf(stderr, "Error writing config to ADS1115: %d\n", i2c_handle);
        }
        retries--;
        gpioDelay(1000); // Wait 1ms before retrying
    }

    fprintf(stderr, "Failed to read ADC value after multiple retries.\n");
    return -1; // Indicate failure
}

// Convert ADC value to pressure (kPa)
float convert_to_pressure(int adc_value) {
    return (adc_value / 32767.0) * 400.0; // Linear transfer function
}

// Convert ADC value to temperature (°C)
float convert_to_temperature(int adc_value) {
    return (adc_value / 32767.0) * 100.0; // Simplified linear NTC approximation
}

// Control the warning LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure and temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int pressure_adc = read_ads1115(0);
        int temperature_adc = read_ads1115(1);

        if (pressure_adc != -1 && temperature_adc != -1) {
            // Convert ADC values to pressure and temperature
            float pressure = convert_to_pressure(pressure_adc);
            float temperature = convert_to_temperature(temperature_adc);

            // Display pressure and temperature
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

            // Control the warning LED
            control_led(pressure);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

