#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VCC 3.3
#define ZERO_CURRENT_VOLTAGE VCC / 2.0
#define SENSITIVITY 66.0 // mV/A
#define OVERCURRENT_THRESHOLD 10.0
#define OVERCURRENT_GPIO 27
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void safety_monitor(float current);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended channel select
    spi_tx_buf[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return ((float)adc_value / 1023.0) * VCC;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - ZERO_CURRENT_VOLTAGE) / (SENSITIVITY / 1000.0);
}

// Function to log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to implement safety monitor
void safety_monitor(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        gpioWrite(OVERCURRENT_GPIO, 1); // Assert GPIO HIGH
        fprintf(log_file, "OVERCURRENT, Current: %.2f A\n", current);
        fflush(log_file);
        fprintf(stderr, "OVERCURRENT detected! Motor shutdown triggered.\n");
        terminate = 1; // Signal termination
    } else {
        gpioWrite(OVERCURRENT_GPIO, 0); // De-assert GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0 CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure OVERCURRENT_GPIO as output
    gpioSetMode(OVERCURRENT_GPIO, PI_OUTPUT);
    gpioWrite(OVERCURRENT_GPIO, 0); // Initialize LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);
        if (voltage < 0) {
            fprintf(stderr, "Error: Failed to convert ADC to voltage\n");
            continue;
        }

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current reading
        log_current(current);

        // Implement safety monitor
        safety_monitor(current);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(OVERCURRENT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();

    return 0;
}

