#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define ZERO_PRESSURE_VOLTAGE 0.5
#define SENSITIVITY 0.1
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    char *log_file_path;
} config_t;

// Function prototypes
int initialize_i2c(config_t *config);
int read_adc(int handle);
float convert_to_voltage(int adc_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config->i2c_bus, config->ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc(int handle) {
    char config[3];
    int16_t adc_value;

    // Configure ADS1115 for single-ended AIN0, 4.096V range, single conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // 0b11000011: Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // 0b10000011: 128 SPS, Disable comparator

    if (i2cWriteDevice(handle, config, 3) != 0) {
