#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_THERMISTOR 1
#define ALERT_THRESHOLD 80.0
#define ALERT_EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MCP3208 ADC
int read_mcp3208(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate relative humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A transfer function: Vout = 0.824 + 0.0315 * RH
    // Assuming 5V supply, Vout = (ADC_value / 1023) * 5
    float vout = (float)adc_value / 1023.0 * 5.0;
    float rh = (vout - 0.824) / 0.0315;
    return rh;
}

// Calculate temperature from thermistor voltage
float calculate_temperature(int adc_value) {
    // Thermistor parameters: Beta = 3950K, R0 = 10kΩ at 25°C
    float vout = (float)adc_value / 1023.0 * 5.0; // Assuming 5V supply
    float r_t = ((5.0 - vout) / vout) * 10000.0; // R_t = (5 - Vt) / Vt * R0
    float t = 25.0 + (1.0 / (0.003908 + (0.000001227 * r_t))); // Temperature calculation
    return t;
}

// Log data to file
int log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Send email alert
int send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity exceeded threshold! Current humidity: %.2f%%\" | ssmtp -s \"Humidity Alert\" %s", humidity, ALERT_EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Failed to execute ssmtp command\n");
        return 1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL_HUMIDITY);
        int thermistor_adc = read_mcp3208(MCP3208_CHANNEL_THERMISTOR);

        if (humidity_adc == -1 || thermistor_adc == -1) {
            fprintf(stderr, "Failed to read ADC values, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(thermistor_adc);

        // Log data
        log_data(humidity, temperature);

        // Check for alert condition
        if (humidity > ALERT_THRESHOLD) {
            printf("Humidity alert! Current humidity: %.2f%%\n", humidity);
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

