#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define VREF 3.3 // Reference voltage
#define ADXL335_ZERO_G_VOLTAGE 1.65
#define ADXL335_SENSITIVITY 300e-3 // 300 mV/g
#define IMPACT_THRESHOLD 2.0 // g
#define LOG_FILE "impact_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
int read_adc(int channel);
float calculate_acceleration(int adc_value);
void log_data(int adc_x, int adc_y, int adc_z, float acceleration_x, float acceleration_y, float acceleration_z, float magnitude);
void impact_detection(float magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int adc_x;
    int adc_y;
    int adc_z;
    float acceleration_x;
    float acceleration_y;
    float acceleration_z;
    float magnitude;
} accelerometer_data_t;

int main() {
    accelerometer_data_t data;

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read ADC values
        data.adc_x = read_adc(ADC_CHANNEL_X);
        data.adc_y = read_adc(ADC_CHANNEL_Y);
        data.adc_z = read_adc(ADC_CHANNEL_Z);

        // Calculate acceleration
        data.acceleration_x = calculate_acceleration(data.adc_x);
        data.acceleration_y = calculate_acceleration(data.adc_y);
        data.acceleration_z = calculate_acceleration(data.adc_z);

        // Calculate magnitude
        data.magnitude = (data.acceleration_x * data.acceleration_x +
                          data.acceleration_y * data.acceleration_y +
                          data.acceleration_z * data.acceleration_z) /
                         3.0;

        // Log data
        log_data(data.adc_x, data.adc_y, data.adc_z, data.acceleration_x, data.acceleration_y, data.acceleration_z, data.magnitude);

        // Impact detection
        impact_detection(data.magnitude);

        // Delay
        gpioDelay(10000); // 10 ms = 100 Hz
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and SPI
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Activate CS
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deactivate CS

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Calculate acceleration in g
float calculate_acceleration(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float acceleration = (voltage - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    return acceleration;
}

// Log data to file
void log_data(int adc_x, int adc_y, int adc_z, float acceleration_x, float acceleration_y, float acceleration_z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, adc_x, adc_y, adc_z, acceleration_x, acceleration_y, acceleration_z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Impact detection
void impact_detection(float magnitude) {
    if (magnitude > IMPACT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
        printf("IMPACT DETECTED at %s\n", timestamp);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

