#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel connected to the sensor
#define FLOW_LOG_FILE "flow_log.csv"
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel(int channel, int baud);
int read_mcp3008(int channel);
float convert_to_flow_rate(int adc_value);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    char *log_file_name;
    float flow_rate_min;
    float flow_rate_max;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_BAUD,
    MCP3008_CHANNEL,
    FLOW_LOG_FILE,
    FLOW_RATE_MIN,
    FLOW_RATE_MAX
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = open_spi_channel(config.spi_channel, config.spi_baud);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,flow_rate\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Log flow rate
        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Failed to log flow rate. \n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00; // Don't care

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float convert_to_flow_rate(int adc_value) {
    if (adc_value == 0) {
        fprintf(stderr, "Sensor-absent condition: ADC value 0\n");
        return 0.0;
    } else if (adc_value == 1023) {
        fprintf(stderr, "Sensor-absent condition: ADC value 1023\n");
        return 5.0;
    }

    float flow_rate = ((float)adc_value / 1023.0) * 5.0;
    return flow_rate;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct timespec ts;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    struct tm *timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 7, ".%06ld", ts.tv_nsec / 1000);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

