#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASURE_COMMAND 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write(int fd, unsigned char command);
int i2c_read(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_close(int fd);
int log_data(FILE *fp, float temperature, float pressure);
void display_data(float temperature, float pressure);
sensor_data_t read_sensor_data(int fd);
void signal_handler(int signum);
int write_csv_header(FILE *fp);

// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char command) {
    unsigned char buf[1];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Display data on console
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data = {0.0, 0.0};
    unsigned char raw_data[6];

    // Trigger measurement
    if (i2c_write(fd, MEASURE_COMMAND) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return data; // Return default values on error
    }

    // Wait for conversion (adjust as needed based on sensor datasheet)
    usleep(100000); // 100 ms

    // Read 6 bytes of data
    if (i2c_read(fd, 0x00, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return data; // Return default values on error
