#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for SPI communication
#define SPI_CE0 8  // Chip Enable 0 (CE0)
#define SPI_MOSI 10 // Master Out Slave In (MOSI)
#define SPI_MISO 9  // Master In Slave Out (MISO)
#define SPI_SCLK 11 // Serial Clock (SCLK)

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define gain factor
float gain = 1.0;

// Global variable for SPI handle
int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7)
    {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0)
    {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to apply gain to audio data
int apply_gain(int adc_value, float gain)
{
    return (int)(adc_value * gain);
}

// Function to subtract two audio streams
int subtract_audio_streams(int audio1, int audio2)
{
    return audio1 - audio2;
}

// Function to print audio data to terminal
void print_audio_data(int audio_data)
{
    printf("%d\n", audio_data);
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments for gain
    if (argc > 1)
    {
        char *endptr;
        gain = strtof(argv[1], &endptr);
        if (*endptr != '\0')
        {
            fprintf(stderr, "Error: Invalid gain value: %s\n", argv[1]);
            return 1;
        }
        printf("Gain set to: %f\n", gain);
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI communication
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0)
    {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1)
    {
        // Read audio data from microphones
        int audio1 = read_mcp3008(0);
        int audio2 = read_mcp3008(1);

        // Check for errors during ADC reading
        if (audio1 == -1 || audio2 == -1)
        {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Apply gain to audio data
        audio1 = apply_gain(audio1, gain);
        audio2 = apply_gain(audio2, gain);

        // Subtract audio streams
        int difference = subtract_audio_streams(audio1, audio2);

        // Print audio data to terminal
        print_audio_data(difference);

        // Delay for a short period
        gpioDelay(1000); // 1ms delay
    }

    // This point will not be reached due to the infinite loop
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

