#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_PIN 18
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define VOLTAGE_SCALE 3.3
#define TEMPERATURE_COEFFICIENT 0.001
#define FLAME_THRESHOLD 1.0
#define MAX_RETRIES 3

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int channel);
float read_temperature();
float read_voltage(int adc_value);
int detect_flame(float compensated_voltage);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int sig);
int initialize_gpio();
void cleanup_gpio();

// SPI transfer function
int spi_transfer(int channel) {
    int ret = 0;
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_transfer spi_xfer[1];
    struct spi_device *spi_dev;

    spi_dev = gpiod_chip_open(SPI_DEVICE);
    if (!spi_dev) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    spi_xfer[0].tx_buf = (unsigned long)tx_buf;
    spi_xfer[0].rx_buf = (unsigned long)rx_buf;
    spi_xfer[0].len = 3;

    ret = gpiod_spi_transfer(spi_dev, spi_xfer, 1);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_chip_close(spi_dev);
        return -1;
    }

    gpiod_chip_close(spi_dev);
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2]; // Extract 10-bit ADC value
}

// Read temperature from file
float read_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = 25.0; // Default temperature

    fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return temperature;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (sscanf(buffer, "%f", &temperature) != 1) {
            fprintf(stderr, "Error parsing temperature from file\n");
        }
    }

    fclose(fp);
    return temperature;
}

// Read voltage from ADC
float read_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VOLTAGE_SCALE;
}

// Detect flame based on compensated voltage
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;
}

// Log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_fp);
}

