void control_buzzer(int flame_detected) {
    if (flame_detected) {
        gpiod_line_set_value(buzzer_line, 1); // Turn buzzer ON
    } else {
        gpiod_line_set_value(buzzer_line, 0); // Turn buzzer OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int raw_adc, retries;
    float voltage, compensated_voltage, temperature;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        temperature = read_temperature();
        retries = 0;
        do {
            raw_adc = spi_transfer(0);
            if (raw_adc < 0) {
                fprintf(stderr, "SPI transfer failed, retrying...\n");
                log_fp != NULL ? fprintf(log_fp, "SPI transfer failed, retrying...\n") : fprintf(stderr, "SPI transfer failed, retrying...\n");
                sleep(1); // Wait before retrying
            } else if (raw_adc < 0 || raw_adc > 1023) {
                fprintf(stderr, "Invalid ADC value %d, retrying...\n", raw_adc);
                log_fp != NULL ? fprintf(log_fp, "Invalid ADC value %d, retrying...\n", raw_adc) : fprintf(stderr, "Invalid ADC value %d, retrying...\n", raw_adc);
                sleep(1);
            } else {
                break; // Exit retry loop if ADC value is valid
            }
            retries++;
        } while (retries < MAX_RETRIES && !terminate);

        if (raw_adc >= 0 && raw_adc <= 1023) {
            voltage = read_voltage(raw_adc);
            compensated_voltage = voltage + (temperature - 25.0) * TEMPERATURE_COEFFICIENT;
            int flame_detected = detect_flame(compensated_voltage);

            log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);
            control_buzzer(flame_detected);
        } else {
            fprintf(stderr, "Failed to read ADC value after multiple retries.\n");
            log_fp != NULL ? fprintf(log_fp, "Failed to read ADC value after multiple retries.\n") : fprintf(stderr, "Failed to read ADC value after multiple retries.\n");
        }

        usleep(500000); // 500ms
    }

    // Cleanup
    control_buzzer(0); // Turn off buzzer
    fclose(log_fp);
    cleanup_gpio();

    return 0;
}

