#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level_percentage(int adc_value);
void control_led(float water_level_percentage);
void log_water_level(float water_level_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        gpioError(result, "SPI transfer failed");
        gpioDelay(100); // Small delay before retrying
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control LED based on water level
void control_led(float water_level_percentage) {
    if (water_level_percentage > WATER_LEVEL_THRESHOLD_HIGH && gpioRead(LED_GPIO) == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
    } else if (water_level_percentage < WATER_LEVEL_THRESHOLD_LOW && gpioRead(LED_GPIO) == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
    }
}

// Function to log water level to JSON file
void log_water_level(float water_level_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char json_string[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"water_level\": %.2f}", timestamp, water_level_percentage);

    // Append to JSON file
    if (json_file != NULL) {
        fseek(json_file, -1, SEEK_END); // Go to the last character in the file
        if (ftell(json_file) == 0) {
            fprintf(json_file, "["); // Add opening bracket if file is empty
        } else {
            fprintf(json_file, ","); // Add comma if file is not empty
        }
        fprintf(json_file, "%s]", json_string);
        fflush(json_file); // Flush the buffer to ensure data is written
    } else {
        fprintf(stderr, "Error: Could not open JSON file for writing.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED OFF

    // Open JSON file for appending
    json_file = fopen(JSON_FILE, "a");
    if (json_file == NULL) {
        fprintf(stderr, "Error opening JSON file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue; // Skip to the next iteration
        }

        // Calculate water level percentage
        float water_level_percentage = calculate_water_level_percentage(adc_value);

        // Control LED
        control_led(water_level_percentage);

        // Log water level
        log_water_level(water_level_percentage);

        // Print water level percentage to stdout
        printf("Water level: %.2f%%\n", water_level_percentage);

        // Wait 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED OFF
    fclose(json_file);
    gpioTerminate();

    printf("Water level monitoring stopped.\n");
    return 0;
}

