    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    VREF,
    MAX_FLOW_RATE,
    MAX_ADC_VALUE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

