        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to flow rate
        float flow_rate = voltage_to_lpm(voltage);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, flow_rate) != 0) {
            fprintf(stderr, "Failed to log data. Retrying.\n");
        }

        free(timestamp); // Free the timestamp string

        // Wait 100 milliseconds
        gpioDelay(100);
    }

