#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_frequency;
    char recipient_email[256];
    char msmtp_config_file[256];
} Config;

// Global variables
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_mcp3008(int spi_handle, int channel);
float calculate_moisture(int raw_value, int min_raw, int max_raw);
int log_data(const char *filename, float moisture);
int send_email_alert(const char *recipient_email, float moisture);
void signal_handler(int signal);
int initialize_spi(int channel);
int cleanup();

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", filename);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_raw") == 0) {
            config->min_raw = atoi(value);
        } else if (strcmp(key, "max_raw") == 0) {
            config->max_raw = atoi(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atoi(value);
        } else if (strcmp(key, "logging_frequency") == 0) {
            config->logging_frequency = atoi(value);
        } else if (strcmp(key, "recipient_email") == 0) {
            strncpy(config->recipient_email, value, sizeof(config->recipient_email) - 1);
            config->recipient_email[sizeof(config->recipient_email) - 1] = '\0';
        } else if (strcmp(key, "msmtp_config_file") == 0) {
            strncpy(config->msmtp_config_file, value, sizeof(config->msmtp_config_file) - 1);
            config->msmtp_config_file[sizeof(config->msmtp_config_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Invalid SPI handle.\n");
        return -1;
    }

    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel. Channel must be between 0 and 7.\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed. pigpio error code: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (raw_value < min_raw) {
        raw_value = min_raw;
    }
    if (raw_value > max_raw) {
        raw_value = max_raw;
    }

    float moisture = 100.0 * (float)(raw_value - min_raw) / (float)(max_raw - min_raw);
    return moisture;
}

// Function to log data to file
int log_data(const char *filename, float moisture) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, moisture);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to send email alert
int send_email_alert(const char *recipient_email, float moisture) {
    char command[512];
    snprintf(command, sizeof(command), "echo \"Moisture level is below threshold (%.2f%%).\" | msmtp -t -f plant_data.txt %s", moisture, recipient_email);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to send email alert.\n");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d.\n", status);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating program.\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, 500000, 0); // SPI channel, baud rate, flags
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed. pigpio error code: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to cleanup resources
int cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        fprintf(stderr, "SPI connection closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        fprintf(stderr, "Log file closed.\n");
    }
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

int main(int argc, char *argv[]) {
    Config config;

    // Set default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw = 300;
    config.max_raw = 700;
    config.moisture_threshold = 30;
    config.logging_frequency = 60;
    strncpy(config.recipient_email, "recipient@example.com", sizeof(config.recipient_email) - 1);
    config.recipient_email[sizeof(config.recipient_email) - 1] = '\0';
    strncpy(config.msmtp_config_file, "/etc/msmtp.conf", sizeof(config.msmtp_config_file) - 1);
    config.msmtp_config_file[sizeof(config.msmtp_config_file) - 1] = '\0';

    // Read configuration from file
    if (read_config("plant_monitor.conf", &config) != 0) {
        fprintf(stderr, "Using default configuration.\n");
    }

    // Parse command-line arguments (optional)
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--spi_channel") == 0 && i + 1 < argc) {
            config.spi_channel = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--adc_channel") == 0 && i + 1 < argc) {
            config.adc_channel = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--min_raw") == 0 && i + 1 < argc) {
            config.min_raw = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--max_raw") == 0 && i + 1 < argc) {
            config.max_raw = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--moisture_threshold") == 0 && i + 1 < argc) {
            config.moisture_threshold = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--logging_frequency") == 0 && i + 1 < argc) {
            config.logging_frequency = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--recipient_email") == 0 && i + 1 < argc) {
            strncpy(config.recipient_email, argv[i + 1], sizeof(config.recipient_email) - 1);
            config.recipient_email[sizeof(config.recipient_email) - 1] = '\0';
            i++;
        } else if (strcmp(argv[i], "--msmtp_config_file") == 0 && i + 1 < argc) {
            strncpy(config.msmtp_config_file, argv[i + 1], sizeof(config.msmtp_config_file) - 1);
            config.msmtp_config_file[sizeof(config.msmtp_config_file) - 1] = '\0';
            i++;
        } else {
            fprintf(stderr, "Usage: %s [options]\n", argv[0]);
            fprintf(stderr, "Options:\n");
            fprintf(stderr, "  --spi_channel <channel>   SPI channel (0 or 1)\n");
            fprintf(stderr, "  --adc_channel <channel>  ADC channel (0-7)\n");
            fprintf(stderr, "  --min_raw <value>        Minimum raw ADC value\n");
            fprintf(stderr, "  --max_raw <value>        Maximum raw ADC value\n");
            fprintf(stderr, "  --moisture_threshold <value> Moisture threshold (percentage)\n");
            fprintf(stderr, "  --logging_frequency <seconds> Logging frequency in seconds\n");
            fprintf(stderr, "  --recipient_email <email> Recipient email address\n");
            fprintf(stderr, "  --msmtp_config_file <path> Path to msmtp config file\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(config.spi_channel);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
