#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL_SEC 5

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float adc_to_moisture(int adc_value, int min_adc, int max_adc);
int gpio_init(const char *chip, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_num = (mode == SPI_MODE_0) ? 0 : ((mode == SPI_MODE_1) ? 1 : ((mode == SPI_MODE_2) ? 2 : 3));
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_num) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// ADC to moisture conversion function
float adc_to_moisture(int adc_value, int min_adc, int max_adc) {
    if (adc_value < min_adc) {
        return 0.0;
    }
    if (adc_value > max_adc) {
        return 100.0;
    }
    return ((float)(adc_value - min_adc) / (float)(max_adc - min_adc)) * 100.0;
}

// GPIO initialization function
int gpio_init(const char *chip, int pin) {
    struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name(chip);
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ptr = gpiod_chip_get_line(chip_ptr, pin);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    if (gpiod_line_request_output(line_ptr, "soil_moisture_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            cleanup();
            return 1;
        }

        // Convert ADC value to moisture percentage
        float moisture_percentage = adc_to_moisture(adc_value, MIN_ADC_VALUE, MAX_ADC_VALUE);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to console
        printf("%s - ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);

        // Activate LED for 500ms
        if (gpio_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO high\n");
            cleanup();
            return 1;
        }
        usleep(500000); // 500ms
        if (gpio_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO low\n");
            cleanup();
            return 1;
        }

        // Wait for the next reading
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

