#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f
#define NUM_SENSORS 4
#define SAMPLE_INTERVAL_SEC 1

// GPIO Chip and Line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8 // CE0

// Global Variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device, unsigned int mode, unsigned int bits, unsigned int speed);
int read_mcp3008(int spi_fd, int channel);
float adc_to_voltage(int adc_value, float vref);
int log_data(FILE *fp, float voltages[NUM_SENSORS]);
void signal_handler(int sig);
int gpio_init(int chip_num, int line_num);
int gpio_set_value(struct gpiod_line *line, int value);

// SPI Initialization Function
int spi_init(const char *device, unsigned int mode, unsigned int bits, unsigned int speed) {
    int fd;
    unsigned int mode_bits = mode;
    unsigned int bits_per_word = bits;
    unsigned int speed_hz = speed;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_bits) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) == -1) {
        perror("Error setting max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Read MCP3008 Function
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// ADC to Voltage Conversion Function
float adc_to_voltage(int adc_value, float vref) {
    return (float)adc_value * vref / 1023.0f;
}

// Data Logging Function
int log_data(FILE *fp, float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(fp, ",%.3f", voltages[i]);
    }
    fprintf(fp, "\n");
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// GPIO Initialization Function
int gpio_init(int chip_num, int line_num) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "spi_cs", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value Function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int main() {
    float voltages[NUM_SENSORS];
    int adc_value;
    struct timespec sleep_time;
    sleep_time.tv_sec = SAMPLE_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(0, GPIO_LINE) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp");
        for (int i = 0; i < NUM_SENSORS; i++) {
            fprintf(log_file, ",Sensor%d", i);
        }
        fprintf(log_file, "\n");
    }

    // Main loop
    while (!terminate) {
        // Set CS low
        if (gpio_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting CS low\n");
            break;
        }

        // Read ADC values
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_value = read_mcp3008(spi_fd, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC channel %d\n", i);
                // Attempt to recover by setting CS high and retrying
                if (gpio_set_value(gpio_line, 1) < 0) {
                    fprintf(stderr, "Error setting CS high during recovery\n");
                    break; // Exit loop if recovery fails
                }
                sleep_time.tv_sec = 0;
                sleep_time.tv_nsec = 100000000; // 100ms
                nanosleep(&sleep_time, NULL);
                continue; // Retry reading the channel
            }
            voltages[i] = adc_to_voltage(adc_value, VREF);
        }

        // Log data
        log_data(log_file, voltages);

        // Set CS high
        if (gpio_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting CS high\n");
            break;
        }

        // Sleep for the sample interval
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

