        return -1;
    }

    if (gpiod_line_request_output(line, "spi_cs", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value Function
