        return -1;
    }
    return 0;
}

int main() {
    float voltages[NUM_SENSORS];
    int adc_value;
    struct timespec sleep_time;
    sleep_time.tv_sec = SAMPLE_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(0, GPIO_LINE) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp");
        for (int i = 0; i < NUM_SENSORS; i++) {
            fprintf(log_file, ",Sensor%d", i);
        }
        fprintf(log_file, "\n");
    }

    // Main loop
    while (!terminate) {
        // Set CS low
        if (gpio_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting CS low\n");
            break;
        }

        // Read ADC values
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_value = read_mcp3008(spi_fd, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC channel %d\n", i);
                // Attempt to recover by setting CS high and retrying
                if (gpio_set_value(gpio_line, 1) < 0) {
                    fprintf(stderr, "Error setting CS high during recovery\n");
                    break; // Exit loop if recovery fails
                }
                sleep_time.tv_sec = 0;
                sleep_time.tv_nsec = 100000000; // 100ms
                nanosleep(&sleep_time, NULL);
                continue; // Retry reading the channel
            }
            voltages[i] = adc_to_voltage(adc_value, VREF);
        }

        // Log data
        log_data(log_file, voltages);

        // Set CS high
        if (gpio_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting CS high\n");
            break;
        }

        // Sleep for the sample interval
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

