#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define LOG_BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for log entries
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer for logging
LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void signal_handler(int signal);
void timer_callback();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        printf("Pump turned ON\n");
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        printf("Pump turned OFF\n");
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;

    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Timer callback function
void timer_callback() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level == -1) {
        fprintf(stderr, "Error reading moisture level, skipping this sample.\n");
        return;
    }

    control_pump(moisture_level);
    log_data(moisture_level, gpioRead(PUMP_GPIO));

    // Print the log buffer
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        time_t timestamp = log_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %d, Pump: %s\n", time_str, log_buffer[i].moisture_level, log_buffer[i].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 5 seconds)
    gpioSetTimerFunc(0, 5000, timer_callback);

    printf("Soil Moisture Monitoring and Irrigation System\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop (wait for termination signal)
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioSetTimerFunc(0, 0, NULL); // Disable timer
    gpioWrite(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

