    if (i2cWriteByteData(i2c_handle, 0x06, 0x40) < 0) {
        fprintf(stderr, "Error resetting MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, 0x07, 0x00) < 0) {
        fprintf(stderr, "Error clearing interrupts\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, 0x06, 0x03) < 0) {
        fprintf(stderr, "Error configuring SpO2 mode\n");
        return -1;
    }

    // Set SpO2 config
    if (i2cWriteByteData(i2c_handle, 0x08, 0x27) < 0) {
