        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
    }

    data->red_data = (uint32_t)buffer[0] | ((uint32_t)buffer[1] << 8) | ((uint32_t)buffer[2] << 16);
    data->ir_data = (uint32_t)buffer[3] | ((uint32_t)buffer[4] << 8) | ((uint32_t)buffer[5] << 16);

    return 0;
}

