    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), ISO_8601_FORMAT, &tm);

    fprintf(fp, "%s - SpO2: %.2f%%, Heart Rate: %d BPM\n", timestamp, spo2, hr);
    fclose(fp);

    return 0;
}

