    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read FIFO data
        if (read_fifo_data(&sensor_data) == 0) {
            // Calculate SpO2 and heart rate
            float spo2 = calculate_spo2(&sensor_data);
            int hr = calculate_hr(&sensor_data);

            // Log data if thresholds are exceeded
            if (spo2 < SPO2_THRESHOLD || hr > HR_THRESHOLD) {
                if (log_data(spo2, hr) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }

            printf("SpO2: %.2f%%, Heart Rate: %d BPM\n", spo2, hr);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Sample once per second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

