volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_buzzer(int gpio, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the buzzer
void control_buzzer(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", gpio);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure buzzer GPIO as output
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read gas sensor value
        int gas_value = read_mcp3008(0);
        if (gas_value < 0) {
            fprintf(stderr, "Error: Failed to read gas sensor value\n");
            break; // Exit loop on error
        }

        printf("Gas value: %d\n", gas_value);

        // Control buzzer based on gas value
        if (gas_value < GAS_THRESHOLD) {
            control_buzzer(BUZZER_GPIO, 0); // Turn buzzer OFF
        } else {
            control_buzzer(BUZZER_GPIO, 1); // Turn buzzer ON
        }

        // Delay for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    control_buzzer(BUZZER_GPIO, 0); // Ensure buzzer is OFF on exit
    gpioTerminate();

    return 0;
}

