#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define RELAY_ON_TIME_MS 3000
#define POLL_INTERVAL_MS 200
#define NUM_BASELINE_SAMPLES 10
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *door_sensor_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(const char *device);
int read_ads1115(int fd, int channel);
int init_gpio(int chip_num, int pin, const char *label);
int set_gpio_value(struct gpiod_line *line, int value);
int read_gpio_value(struct gpiod_line *line);
int calibrate_sensor(int fd, int num_samples);
int check_threshold(int distance, int threshold);
int control_relay(int state);
int read_door_sensor();
int log_event(const char *event);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// ADS1115 read function
int read_ads1115(int fd, int channel) {
    unsigned char config[3];
    int16_t value;

    // Configure ADS1115 for single-ended read on the specified channel
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC2; // 4.096V, 128 SPS, Single-shot mode
    config[2] = (channel << 4) | 0x83; // Channel selection

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    config[0] = ADS1115_REG_CONVERT;
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    unsigned char read_buffer[2];
    if (read(fd, read_buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    value = (read_buffer[0] << 8) | read_buffer[1];

    return value;
}

// GPIO initialization function
int init_gpio(int chip_num, int pin, const char *label) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = label;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_open_by_name(gpiod_chip, label);
    if (!line) {
        perror("Error opening GPIO line");
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        return -1;
    }

    return line;
}

// GPIO set value function
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO read value function
int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Calibration function
int calibrate_sensor(int fd, int num_samples) {
    int sum = 0;
    for (int i = 0; i < num_samples; i++) {
        int reading = read_ads1115(fd, 0);
        if (reading < 0) {
            fprintf(stderr, "Error reading sensor during calibration, retrying...\n");
            usleep(50000); // Wait 50ms before retrying
            i--; // Retry the current sample
            continue;
        }
        sum += reading;
        usleep(50000); // 50ms delay
    }
    return sum / num_samples;
}

// Threshold check function
int check_threshold(int distance, int threshold) {
    return distance < threshold;
}

// Relay control function
int control_relay(int state) {
    if (set_gpio_value(relay_line, state) < 0) {
        return -1;
    }
    return 0;
}

// Door sensor read function
int read_door_sensor() {
    int value = read_gpio_value(door_sensor_line);
    if (value < 0) {
        return -1;
    }
    return (value == 0) ? 1 : 0; // Active-low, so LOW means door is open
}

// Logging function
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;
    }
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        log_event("I2C initialization failed");
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        log_event("GPIO initialization failed");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    relay_line = init_gpio(0, GPIO_RELAY, "relay");
    if (!relay_line) {
        log_event("Relay GPIO initialization failed");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    door_sensor_line = init_gpio(0, GPIO_DOOR_SENSOR, "door_sensor");
    if (!door_sensor_line) {
        log_event("Door sensor GPIO initialization failed");
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Calibrate sensor
    int baseline = calibrate_sensor(i2c_fd, NUM_BASELINE_SAMPLES);
    if (baseline < 0) {
        log_event("Sensor calibration failed");
        gpiod_line_release(relay_line);
        gpiod_line_release(door_sensor_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    int threshold = (int)(0.8 * baseline);
    char threshold_str[50];
    snprintf(threshold_str, sizeof(threshold_str), "Threshold set to: %d", threshold);
    log_event(threshold_str);

    // Main loop
    while (keep_running) {
        int distance = read_ads1115(i2c_fd, 0);
        if (distance < 0) {
            log_event("Failed to read distance, retrying...");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        char distance_str[50];
        snprintf(distance_str, sizeof(distance_str), "Distance: %d", distance);
        log_event(distance_str);

        if (check_threshold(distance, threshold)) {
            log_event("Distance below threshold, releasing lock...");
            if (control_relay(1) < 0) {
                log_event("Failed to energize relay");
            } else {
                usleep(RELAY_ON_TIME_MS * 1000); // Wait for relay to activate
                if (control_relay(0) < 0) {
                    log_event("Failed to de-energize relay");
                }
                int door_open = read_door_sensor();
                if (door_open < 0) {
                    log_event("Failed to read door sensor");
                } else {
                    if (door_open) {
                        log_event("Door opened");
                    } else {
                        log_event("Door not opened");
                    }
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Wait before next poll
    }

    // Cleanup
    log_event("Shutting down...");
