#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for chip select
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device and speed
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz

// Define log file name
#define LOG_FILE "soil_moisture_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *cs0_line = NULL;
struct gpiod_line *cs1_line = NULL;
struct gpiod_line *cs2_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int spi_fd, int channel);
int log_data(FILE *log_file, int sensor1, int sensor2, int sensor3);
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **cs0_line_ptr, struct gpiod_line **cs1_line_ptr, struct gpiod_line **cs2_line_ptr);
int cleanup_gpio(struct gpiod_line *cs0_line, struct gpiod_line *cs1_line, struct gpiod_line *cs2_line, struct gpiod_chip *chip);
void signal_handler(int signum);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(FILE *log_file, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("fprintf failed");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to setup GPIO lines
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **cs0_line_ptr, struct gpiod_line **cs1_line_ptr, struct gpiod_line **cs2_line_ptr) {
    *chip_ptr = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip_ptr) {
        perror("gpiod_chip_open_by_name failed");
        return -1;
    }

    *cs0_line_ptr = gpiod_chip_get_line(*chip_ptr, CS0_PIN);
    if (!*cs0_line_ptr) {
        perror("gpiod_chip_get_line CS0 failed");
        gpiod_chip_close(*chip_ptr);
        return -1;
    }

    *cs1_line_ptr = gpiod_chip_get_line(*chip_ptr, CS1_PIN);
    if (!*cs1_line_ptr) {
        perror("gpiod_chip_get_line CS1 failed");
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*cs0_line_ptr);
        return -1;
    }

    *cs2_line_ptr = gpiod_chip_get_line(*chip_ptr, CS2_PIN);
    if (!*cs2_line_ptr) {
        perror("gpiod_chip_get_line CS2 failed");
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*cs0_line_ptr);
        gpiod_line_release(*cs1_line_ptr);
        return -1;
    }

    if (gpiod_line_request_output(*cs0_line_ptr, "soil_moisture", 0) < 0) {
        perror("gpiod_line_request_output CS0 failed");
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*cs0_line_ptr);
        gpiod_line_release(*cs1_line_ptr);
        gpiod_line_release(*cs2_line_ptr);
        return -1;
    }

    if (gpiod_line_request_output(*cs1_line_ptr, "soil_moisture", 0) < 0) {
        perror("gpiod_line_request_output CS1 failed");
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*cs0_line_ptr);
        gpiod_line_release(*cs1_line_ptr);
        gpiod_line_release(*cs2_line_ptr);
        return -1;
    }

    if (gpiod_line_request_output(*cs2_line_ptr, "soil_moisture", 0) < 0) {
        perror("gpiod_line_request_output CS2 failed");
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*cs0_line_ptr);
        gpiod_line_release(*cs1_line_ptr);
        gpiod_line_release(*cs2_line_ptr);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
int cleanup_gpio(struct gpiod_line *cs0_line, struct gpiod_line *cs1_line, struct gpiod_line *cs2_line, struct gpiod_chip *chip) {
    if (cs0_line) gpiod_line_release(cs0_line);
    if (cs1_line) gpiod_line_release(cs1_line);
    if (cs2_line) gpiod_line_release(cs2_line);
    if (chip) gpiod_chip_close(chip);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device failed");
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE failed");
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ failed");
        close(spi_fd);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(&chip, &cs0_line, &cs1_line, &cs2_line) < 0) {
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen failed");
        cleanup_gpio(cs0_line, cs1_line, cs2_line, chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int sensor1_value = read_mcp3008(spi_fd, 0);
        int sensor2_value = read_mcp3008(spi_fd, 0);
        int sensor3_value = read_mcp3008(spi_fd, 0);

        if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        sleep(5);
    }

    // Cleanup resources
    cleanup_gpio(cs0_line, cs1_line, cs2_line, chip);
    close(spi_fd);
    fclose(log_file);

    return 0;
}

