        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen failed");
        cleanup_gpio(cs0_line, cs1_line, cs2_line, chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int sensor1_value = read_mcp3008(spi_fd, 0);
        int sensor2_value = read_mcp3008(spi_fd, 0);
        int sensor3_value = read_mcp3008(spi_fd, 0);

        if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        sleep(5);
    }

    // Cleanup resources
    cleanup_gpio(cs0_line, cs1_line, cs2_line, chip);
    close(spi_fd);
    fclose(log_file);

    return 0;
