#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_CLOCK 1000000 // 1 MHz
#define SPI_MODE 0
#define DRY_ADC 200
#define WET_ADC 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], int *threshold, int *duration, int *sleep_interval);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode
    tx_buffer[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    float moisture = ((float)(adc_value - DRY_ADC) / (WET_ADC - DRY_ADC)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
    log_event("Shutting down...");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], int *threshold, int *duration, int *sleep_interval) {
    *threshold = DEFAULT_THRESHOLD;
    *duration = DEFAULT_DURATION;
    *sleep_interval = DEFAULT_SLEEP_INTERVAL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            *threshold = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            *duration = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            *sleep_interval = atoi(argv[i + 1]);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
            return 1; // Indicate error
        }
    }
    return 0; // Indicate success
}

int main(int argc, char *argv[]) {
    int threshold, duration, sleep_interval;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &threshold, &duration, &sleep_interval) != 0) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_CLOCK, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Starting irrigation system...");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC, skipping irrigation cycle");
            sleep(sleep_interval);
            continue;
        }

        float moisture = map_adc_to_moisture(adc_value);
        char moisture_str[64];
        snprintf(moisture_str, sizeof(moisture_str), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
        log_event(moisture_str);

        if (moisture < threshold) {
            log_event("Moisture below threshold, activating pump");
            control_pump(1);
            sleep(duration);
            control_pump(0);
            log_event("Pump deactivated");
        }

        sleep(sleep_interval);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

