#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 10
#define EMA_ALPHA 0.2
#define PEAK_THRESHOLD 20.0
#define LOG_FILE "/var/log/sound_events.log"
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sound_events"

// Global variables
int spi_handle;
double ema = 0.0;
struct mosquitto *mosq = NULL;

// Function prototypes
int read_adc(int channel);
double calculate_ema(double new_value, double old_ema, double alpha);
int detect_peak(double raw_value, double ema, double threshold);
int log_event(int adc_value);
int publish_mqtt(int adc_value);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate exponential moving average
double calculate_ema(double new_value, double old_ema, double alpha) {
    return alpha * new_value + (1 - alpha) * old_ema;
}

// Function to detect peak
int detect_peak(double raw_value, double ema, double threshold) {
    double difference = raw_value - ema;
    if (difference > threshold) {
        return 1; // Peak detected
    } else {
        return 0; // No peak
    }
}

// Function to log event to file
int log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %d\n", timestamp, adc_value);
    fclose(fp);
    return 0;
}

// Function to publish MQTT message
int publish_mqtt(int adc_value) {
    if (mosq == NULL) {
        fprintf(stderr, "Error: MQTT client not initialized\n");
        return -1;
    }

    char payload[64];
    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%ld\", \"value\": %d}", time(NULL), adc_value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: MQTT initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT connect failed: %s\n", mosquitto_strerror(ret));
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            continue; // Continue to the next iteration
        }

        // Calculate EMA
        ema = calculate_ema((double)adc_value, ema, EMA_ALPHA);

        // Detect peak
        if (detect_peak((double)adc_value, ema, PEAK_THRESHOLD)) {
            printf("Peak detected: ADC Value = %d\n", adc_value);

            // Log event
            if (log_event(adc_value) != 0) {
                fprintf(stderr, "Error: Logging failed\n");
            }

            // Publish MQTT message
            if (publish_mqtt(adc_value) != 0) {
                fprintf(stderr, "Error: MQTT publish failed\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    spiClose(spi_handle);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

