// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read data from the PCF8591 ADC
int read_pcf8591(int fd) {
    uint8_t control_byte = 0x40; // Single-ended, AIN0, no analog output
    uint8_t dummy_read;
    uint8_t data;

    // Write the control byte to the PCF8591
    if (write(fd, &control_byte, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read a dummy byte to discard the previous conversion result
    if (read(fd, &dummy_read, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Read the ADC value
    if (read(fd, &data, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return data;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (init_i2c() < 0) {
        return 1;
    }

    // Main loop to continuously read and print the ADC value
    while (1) {
        int adc_value = read_pcf8591(i2c_fd);
        if (adc_value >= 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop,
    // but close the I2C device just in case.
    close(i2c_fd);
    return 0;
}

