#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define VCC 3.3
#define ZERO_FIELD_VOLTAGE 2.5
#define SENSITIVITY 0.0014
#define THRESHOLD 500.0
#define GPIO_SHUTDOWN 27
#define SAMPLE_RATE 1 // Hz
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int16_t read_adc();
float adc_to_voltage(int16_t adc_value);
float voltage_to_gauss(float voltage);
void buffer_init(CircularBuffer *cb);
void buffer_add(CircularBuffer *cb, float value);
float buffer_average(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of circular buffer
float buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // Single-ended AIN0, 4.096V, Continuous conversion
    config[2] = 0x83; // 128 SPS, Traditional comparator

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value
int16_t read_adc() {
    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return 0; // Return 0 on failure
    }

    int16_t adc_value = (data[0] << 8) | data[1];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int16_t adc_value) {
    float voltage = (adc_value * REF_VOLTAGE) / 32768.0;
    return voltage;
}

// Convert voltage to Gauss
float voltage_to_gauss(float voltage) {
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY;
    return gauss;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer gauss_buffer;
    buffer_init(&gauss_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Hall sensor monitoring started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Check for invalid voltage readings
        if (voltage < 0.0 || voltage > VCC) {
            syslog(LOG_WARNING, "Invalid voltage reading: %.3f V", voltage);
            usleep(1000000 / SAMPLE_RATE); // Delay for sample rate
            continue;
        }

        // Convert voltage to Gauss
        float gauss = voltage_to_gauss(voltage);

        // Add reading to circular buffer
        buffer_add(&gauss_buffer, gauss);

        // Calculate rolling average
        float average_gauss = buffer_average(&gauss_buffer);

        // Check if threshold is exceeded
        if (average_gauss > THRESHOLD) {
            syslog(LOG_WARNING, "Threshold exceeded: %.3f Gauss", average_gauss);
            gpioWrite(GPIO_SHUTDOWN, 1);
        } else {
            gpioWrite(GPIO_SHUTDOWN, 0);
        }

        // Log data
        syslog(LOG_INFO, "Voltage: %.3f V, Gauss: %.3f, Average: %.3f", voltage, gauss, average_gauss);

        // Delay for sample rate
        usleep(1000000 / SAMPLE_RATE);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

