#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define READ_INTERVAL 60      // seconds
#define MCP3008_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int state);
int log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

// Function to log watering events
int log_event(int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            control_pump(0); // Deactivate pump on error
            break;           // Exit loop on error
        }

        // Log event
        log_event(moisture_level);

        // Control pump based on moisture level
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump.\n");
            if (control_pump(1) == 0) { // Activate pump
                gpioDelay(WATERING_DURATION * 1000); // Wait for watering duration
                control_pump(0); // Deactivate pump
                printf("Pump deactivated.\n");
            } else {
                fprintf(stderr, "Error: Failed to activate pump\n");
                break; // Exit loop on pump activation error
            }
        }

        // Wait for next reading
        gpioDelay(READ_INTERVAL * 1000); // Delay in milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Watering system stopped.\n");
    return 0;
}

