    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure PWM GPIO
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Set PWM duty cycle
        set_pwm_duty_cycle(adc_value);

        // Print ADC value and PWM duty cycle
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, adc_value);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    spiClose(spi_handle);
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

