#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int16_t read_adc();
double calculate_gauss(int16_t adc_value);
void control_led(double gauss);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double threshold;
} config_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    char config[3];
    int16_t adc_value;

    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, continuous conversion mode
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010: Single-ended AIN0, PGA=4.096V, Continuous conversion mode
    config[2] = 0x83; // 0b10000011: 128 SPS, Traditional comparator

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read conversion register
    char data[2];
    if (i2cWriteDevice(i2c_handle, (char[1]){CONVERSION_REG}, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    return adc_value;
}

// Calculate magnetic field strength in Gauss
double calculate_gauss(int16_t adc_value) {
    // Full scale range is 4.096V, sensitivity is 0.001 V/Gauss
    // Convert ADC value to voltage (assuming 16-bit ADC and PGA=4.096V)
    double voltage = (adc_value * 4.096) / 32768.0;

    // Calculate magnetic field strength in Gauss
    return voltage / 0.001;
}

// Control LED based on magnetic field strength
void control_led(double gauss) {
    if (gauss > threshold) {
        // Blink LED rapidly for 1 second
        for (int i = 0; i < 20; i++) { // 20 cycles = 1 second at 50ms on/off
            gpioWrite(LED_GPIO, 1); // Turn LED on
            gpioDelay(50);          // Wait 50ms
            gpioWrite(LED_GPIO, 0); // Turn LED off
            gpioDelay(50);          // Wait 50ms
        }
    } else {
        gpioWrite(LED_GPIO, 0); // Ensure LED is off if below threshold
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate magnetic field strength
        double gauss = calculate_gauss(adc_value);

        // Control LED
        control_led(gauss);

        // Print magnetic field strength
        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

