#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_CONTROL "pump_control"
#define MOISTURE_MIN 0
#define MOISTURE_MAX 1023

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(float moisture);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < MOISTURE_MIN || adc_value > MOISTURE_MAX) {
        syslog(LOG_WARNING, "Sensor out of range: %d", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / MOISTURE_MAX) * 100.0;
}

// Function to control the relay
void control_relay(float moisture) {
    static int pump_on = 0; // Track pump state

    if (moisture < MOISTURE_THRESHOLD_LOW && !pump_on) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay (pump on)
        pump_on = 1;
        syslog(LOG_INFO, "Pump activated (Moisture: %.2f%%)", moisture);
    } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_on) {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay (pump off)
        pump_on = 0;
        syslog(LOG_INFO, "Pump deactivated (Moisture: %.2f%%)", moisture);
    }
}

