void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_CONTROL, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_connack_string(result));
    }
