void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0 && message->payload != NULL) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received MQTT message on topic %s: %s", message->topic, payload);

        if (strcmp(message->topic, MQTT_TOPIC_CONTROL) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                gpioWrite(RELAY_GPIO, 1); // Activate relay
                syslog(LOG_INFO, "Received command: pump_on");
            } else if (strcmp(payload, "pump_off") == 0) {
                gpioWrite(RELAY_GPIO, 0); // Deactivate relay
                syslog(LOG_INFO, "Received command: pump_off");
            } else {
                syslog(LOG_WARNING, "Unknown command: %s", payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received: %d. Terminating...", sig);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Deactivate relay
    gpioWrite(RELAY_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Disconnect MQTT
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();

    syslog(LOG_INFO, "Cleanup complete. Exiting.");
    closelog();
    exit(0);
}

