        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
