#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// SPI device file descriptor
int spi_fd = -1;

// SPI mode
#define SPI_MODE 0

// SPI bits per word
#define SPI_BITS_PER_WORD 8

// SPI clock speed (Hz)
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel to read
#define MCP3008_CHANNEL 0

// VREF voltage
#define VREF 3.3

// Function prototypes
int spi_init(int spi_fd, uint8_t mode, uint8_t bits, uint32_t speed);
int read_mcp3008(int spi_fd, int channel);
float adc_to_voltage(int raw_value, float vref);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting.\n");
        if (spi_fd != -1) {
            close(spi_fd);
        }
        exit(0);
    }
}

// Initialize SPI interface
int spi_init(int spi_fd, uint8_t mode, uint8_t bits, uint32_t speed) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)NULL, // No transmit buffer
        .rx_buf = (unsigned long)NULL,  // No receive buffer
        .len = 0,                       // Initial length
        .speed_hz = speed,
        .bits_per_word = bits,
        .delay_usecs = 0,
    };

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Can't set SPI mode");
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Can't set bits per word");
        return -1;
    }

    // Set max speed hz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Can't set max speed hz");
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                           // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;                           // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract 10-bit value from response
    int raw_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return raw_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int raw_value, float vref) {
    return (float)raw_value * vref / 1024.0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open /dev/spidev0.0");
        return 1;
    }

    // Initialize SPI
    if (spi_init(spi_fd, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED) < 0) {
        close(spi_fd);
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        // Read ADC value
        int raw_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading MCP3008. Retrying in 500ms.\n");
            usleep(500000); // 500ms
            continue;
        }

        // Convert to voltage
        float voltage = adc_to_voltage(raw_value, VREF);

        // Print raw value and voltage
        printf("Raw: %d, Voltage: %.3f V\n", raw_value, voltage);

        // Wait 500ms
        usleep(500000);
    }

    // Close SPI device (this will never be reached in the infinite loop)
    close(spi_fd);

    return 0;
}

