#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 1000
#define MOTOR_GPIO_1 17
#define MOTOR_GPIO_2 27
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_adc(int channel);
int map_adc_to_duty_cycle(int adc_value);
void set_motor_pwm(int gpio, int duty_cycle);
void log_event(int adc_value, int duty_cycle);
void signal_handler(int signal);

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    int mode = SPI_MODE;
    int bits = SPI_BITS_PER_WORD;
    int speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Map ADC value to PWM duty cycle
int map_adc_to_duty_cycle(int adc_value) {
    if (adc_value < NOISE_THRESHOLD) {
        return 0; // Motor off
    } else {
        // Linear mapping
        return (int)(((float)(adc_value - NOISE_THRESHOLD) / (1023.0 - NOISE_THRESHOLD)) * PWM_RANGE);
    }
}

// Set motor PWM duty cycle
void set_motor_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Log event to file
void log_event(int adc_value, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, ADC: %d, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            adc_value, duty_cycle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_GPIO_1, PI_OUTPUT);
    gpioSetMode(MOTOR_GPIO_2, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_GPIO_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_GPIO_2, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_GPIO_1, PWM_RANGE);
    gpioSetPWMrange(MOTOR_GPIO_2, PWM_RANGE);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        int duty_cycle = map_adc_to_duty_cycle(adc_value);
        set_motor_pwm(MOTOR_GPIO_1, duty_cycle);
        set_motor_pwm(MOTOR_GPIO_2, duty_cycle);

        log_event(adc_value, duty_cycle);

        usleep(10000); // Sample every 10ms
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_motor_pwm(MOTOR_GPIO_1, 0);
    set_motor_pwm(MOTOR_GPIO_2, 0);

    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

