// Define constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 30.0
#define PUMP_DURATION 5 // seconds
#define READ_INTERVAL 60 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(float moisture);
void log_data(int adc_value, float moisture);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction with retry
    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming 0V = 0% moisture, 3.3V = 100% moisture
    // ADC value of 0 corresponds to 0% moisture, ADC value of 1023 corresponds to 100% moisture
    // VH400 output is 0-3V, MCP3008 is 0-3.3V, so we need to scale the ADC value
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float moisture = (3.0 / 3.3) * 100.0; // 0V = 0% moisture
    return moisture;
}

// Function to control the water pump
void control_pump(float moisture) {
    if (moisture < MOISTURE_THRESHOLD) {
        printf("Moisture level below threshold (%.2f%% < %.2f%%). Activating pump.\n", moisture, MOISTURE_THRESHOLD);
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        gpioDelay(PUMP_DURATION * 1000000); // Wait for pump duration (in microseconds)
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Pump deactivated.\n");
    }
}

// Function to log data to the console
void log_data(int adc_value, float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            // Calculate moisture percentage
            float moisture = calculate_moisture(adc_value);

            // Control the water pump
            control_pump(moisture);

            // Log the data
            log_data(adc_value, moisture);
        }

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is OFF
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

