#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 20 // cm
#define DEBOUNCE_DELAY 1 // seconds
#define POLLING_INTERVAL 100 // milliseconds
#define LOG_FILE "door_events.log"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
int gpio_init(int pin);
int gpio_set_value(int pin, int value);
int log_event(const char *event);
bool is_proximity_detected(int adc_value);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE;
    unsigned int bits = SPI_BITS_PER_WORD;
    unsigned int speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value (10 bits)
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// GPIO initialization function
int gpio_init(int pin) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "door_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(line);
        return -1;
    }

    relay_line = line;
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    if (gpiod_line_set_value(relay_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log event function
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Proximity detection function
bool is_proximity_detected(int adc_value) {
    return adc_value < (PROXIMITY_THRESHOLD * 10); // Convert cm to mm
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

int main() {
    int adc_value;
    bool proximity_detected;
    time_t last_trigger_time = 0;

    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(RELAY_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return 1;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed. Retrying in %d ms.\n", POLLING_INTERVAL);
            usleep(POLLING_INTERVAL * 1000); // Wait before retrying
            continue;
        }

        // Check for proximity
        proximity_detected = is_proximity_detected(adc_value);

        // Control relay based on proximity and debounce
        time_t current_time = time(NULL);
        if (proximity_detected && (current_time - last_trigger_time) > DEBOUNCE_DELAY) {
            if (gpio_set_value(RELAY_GPIO, 1) == 0) { // Activate relay
                log_event("Door opened");
                printf("Door opened (ADC value: %d)\n", adc_value);
                last_trigger_time = current_time;
            }
        } else if (!proximity_detected) {
            if (gpio_set_value(RELAY_GPIO, 0) == 0) { // Deactivate relay
                //log_event("Door closed"); //Only log on door open
                printf("Door closed (ADC value: %d)\n", adc_value);
            }
        }

        usleep(POLLING_INTERVAL * 1000); // Polling interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }

    return 0;
}

