#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define NUM_SENSORS 3
#define MOISTURE_MIN 0
#define MOISTURE_MAX 1023
#define MOISTURE_PERCENTAGE_MIN 0
#define MOISTURE_PERCENTAGE_MAX 100
#define LOG_FILE "soil_data.txt"
#define RETRY_COUNT 5
#define RETRY_DELAY_BASE_MS 10
#define RETRY_DELAY_MAX_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(int sensor_id, float moisture_percentage);
void signal_handler(int signal);
int spi_init();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int delay_ms = RETRY_DELAY_BASE_MS;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            if (delay_ms > RETRY_DELAY_MAX_MS) {
                delay_ms = RETRY_DELAY_MAX_MS;
            }
        }
    }

    fprintf(stderr, "SPI transfer failed persistently after %d attempts.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > MOISTURE_MAX) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    float moisture_percentage = (float)(adc_value - MOISTURE_MIN) / (MOISTURE_MAX - MOISTURE_MIN) * (MOISTURE_PERCENTAGE_MAX - MOISTURE_PERCENTAGE_MIN) + MOISTURE_PERCENTAGE_MIN;
    return moisture_percentage;
}

// Log data to file
void log_data(int sensor_id, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d, Moisture: %.2f%%\n", timestamp, sensor_id, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; ++i) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                float moisture_percentage = calculate_moisture_percentage(adc_value);
                if (moisture_percentage >= 0.0) {
                    log_data(i, moisture_percentage);
                } else {
                    fprintf(stderr, "Error calculating moisture percentage for sensor %d\n", i);
                }
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

