#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CE 0 // Chip Enable for SPI0

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_FREQUENCY 1000 // Initial PWM frequency (Hz)
#define PWM_DUTYCYCLE 500000 // Initial PWM duty cycle (nanoseconds)

// Define MCP3008 parameters
#define MCP3008_CHANNEL 0 // Channel connected to LDR

// Define calibration file
#define CALIBRATION_FILE "theremin_config.txt"

// Define error value for distance
#define ERROR_DISTANCE -1.0

// Global variables
static volatile int running = 1;
static float distance = ERROR_DISTANCE;
static int last_valid_distance = ERROR_DISTANCE;
static int last_valid_ldr_value = -1;
static int last_valid_frequency = -1;
static int last_valid_dutycycle = -1;
static int last_valid_mcp3008_value = -1;
static int last_valid_pwm_frequency = -1;
static int last_valid_pwm_dutycycle = -1;

// Function prototypes
float read_distance();
int read_ldr_value();
int read_mcp3008(int channel);
void set_pwm_frequency(int frequency);
void set_pwm_dutycycle(int dutycycle);
float map_distance_to_frequency(float distance);
int map_ldr_to_dutycycle(int ldr_value);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);
void echo_callback(int gpio, int level, uint32_t tick);

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return ERROR_DISTANCE;
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 30000) { // Increased timeout
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 30000) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return ERROR_DISTANCE;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * 34300.0) / 2.0; // Distance in cm

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr_value() {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Open SPI channel
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", handle);
