#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define ADC_CHANNEL 0
#define PPM_SCALE 0.5
#define PPM_OFFSET -10.0
#define LIMIT_PPM 50
#define SOBRIETY_PPM 20
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len);
int adc_read(int fd, int channel);
float ppm_calculate(int adc_value);
const char *classify_ppm(float ppm);
int log_data(FILE *fp, int adc_value, float ppm, const char *classification);
void gpio_init(struct gpiod_chip **chip, struct gpiod_line **line, const char *chipname, int pin);
void gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_num = (mode == SPI_MODE_0) ? 0 : (mode == SPI_MODE_1) ? 1 : 2;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_num) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC read function
int adc_read(int fd, int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value;

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended mode + channel
    tx[2] = 0x00; // Dummy byte

    // Retry mechanism
    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (spi_transfer(fd, tx, rx, 3) == 0) {
            // Extract ADC value
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)\n", i + 1, RETRY_COUNT);
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate error
}

// PPM calculation function
float ppm_calculate(int adc_value) {
    return (adc_value * PPM_SCALE) + PPM_OFFSET;
}

// Classification function
const char *classify_ppm(float ppm) {
    if (ppm > LIMIT_PPM) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < SOBRIETY_PPM) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Logging function
int log_data(FILE *fp, int adc_value, float ppm, const char *classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s, ADC: %d, PPM: %.2f, Classification: %s\n", timestamp, adc_value, ppm, classification);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// GPIO initialization function
void gpio_init(struct gpiod_chip **chip, struct gpiod_line **line, const char *chipname, int pin) {
    *chip = gpiod_chip_open_by_name(chipname);
    if (!*chip) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    *line = gpiod_chip_get_line(*chip, pin);
    if (!*line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(*line, "alcohol_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }
}

// GPIO set value function
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int adc_value;
    float ppm;
    const char *classification;
    int init_attempts = 0;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_init(&gpio_chip, &gpio_line, GPIO_CHIP, GPIO_PIN);

    // Initialize SPI
    while (init_attempts < 3) {
        spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
        if (spi_fd != -1) {
            break;
        } else {
            fprintf(stderr, "SPI initialization failed, retrying (%d/3)\n", init_attempts + 1);
            init_attempts++;
            sleep(1); // Wait before retrying
        }
    }

    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialization failed after multiple retries. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp, ADC, PPM, Classification\n"); // Write header

    // Main loop
    while (!terminate) {
        adc_value = adc_read(spi_fd, ADC_CHANNEL);
        if (adc_value != -1) {
            ppm = ppm_calculate(adc_value);
            classification = classify_ppm(ppm);

            log_data(log_file, adc_value, ppm, classification);

            // Control the LED based on PPM level
            if (ppm > LIMIT_PPM) {
                gpio_set_value(gpio_line, 1); // Turn LED on
            } else {
                gpio_set_value(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

