#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
float map_potentiometer_to_speed(int adc_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void motion_profile(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction, int min_speed, int max_speed);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to speed factor
float map_potentiometer_to_speed(int adc_value) {
    // Logarithmic mapping
    float speed_factor = log10(adc_value + 1) / log10(1024) + 0.1; // Add 0.1 to avoid log(0)
    return speed_factor;
}

// Function to set motor speed and direction
void set_motor_speed(int motor_enable, int motor_direction, int speed) {
    gpioWrite(motor_enable, 1); // Enable motor
    gpioWrite(motor_direction, speed > 0 ? 1 : 0); // Set direction based on speed
    gpioPWM(motor_enable, abs(speed)); // Set PWM duty cycle
}

// Function to implement motion profile
void motion_profile(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction, int min_speed, int max_speed) {
    int speed = min_speed;
    int direction = 1; // 1 for forward, -1 for backward

    // Acceleration
    while (speed <= max_speed) {
        set_motor_speed(motor1_enable, motor1_direction, speed * direction);
        set_motor_speed(motor2_enable, motor2_direction, speed * (direction * -1));
        gpioDelay(10000); // 10ms delay
        speed += 5; // Increment speed
    }

    // Constant speed
    gpioDelay(2000000); // 2 seconds

    // Deceleration
    speed = max_speed;
    while (speed >= min_speed) {
        set_motor_speed(motor1_enable, motor1_direction, speed * direction);
        set_motor_speed(motor2_enable, motor2_direction, speed * (direction * -1));
        gpioDelay(10000); // 10ms delay
        speed -= 5; // Decrement speed
    }

    // Reverse direction
    direction = -1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_adc = read_mcp3008(POT1_CHANNEL);
        int pot2_adc = read_mcp3008(POT2_CHANNEL);

        if (pot1_adc == -1 || pot2_adc == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            // Optionally add retry logic here
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Map potentiometer values to speed factors
        float pot1_speed_factor = map_potentiometer_to_speed(pot1_adc);
        float pot2_speed_factor = map_potentiometer_to_speed(pot2_adc);

        // Calculate motor speeds (scaled to 0-255)
        int motor1_speed = (int)(pot1_speed_factor * 255);
        int motor2_speed = (int)(pot2_speed_factor * 255);

        // Motion profile
        motion_profile(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION, 50, 255);

        // Reverse direction
        int direction = -1;
        motion_profile(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION, 50, 255);

        gpioDelay(5000000); // 5 seconds pause
    }

    // Cleanup
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0); // Stop Motor 1
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0); // Stop Motor 2
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

