#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LED_PIN 17
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
float calibrate_noise_level();
void control_led(int state);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int led_pin;
    int cs_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
} gpio_config_t;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud_rate;
} spi_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode.\n");
        return 1;
    }
    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting CS pin mode.\n");
        return 1;
    }
    if (gpioSetMode(MOSI_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MOSI pin mode.\n");
        return 1;
    }
    if (gpioSetMode(MISO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting MISO pin mode.\n");
        return 1;
    }
    if (gpioSetMode(SCLK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting SCLK pin mode.\n");
        return 1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_data[2] = 0x00; // Don't care

    char rx_buffer[3];

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    spiXfer(spi_handle, spi_data, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate noise level
float calibrate_noise_level() {
    int sum = 0;
    for (int i = 0; i < 500; i++) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value during calibration.\n");
            return 0.0; // Return 0.0 to avoid division by zero
        }
        sum += adc_value;
        gpioDelay(20); // Small delay between readings
    }
    return (float)sum / 500.0;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    float noise_level = calibrate_noise_level();
    printf("Calibrated noise level: %.2f\n", noise_level);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        float sound_level = (float)adc_value;

        // Check if sound level exceeds noise threshold
        if (sound_level > noise_level * 1.10) {
            control_led(1); // Turn on LED
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            control_led(0); // Turn off LED
        }

        gpioDelay(10); // Small delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

