#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define TIMER_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_slpm(int adc_value);
void log_airflow(float airflow);
void timer_callback();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "ERROR: Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to SLPM
float convert_to_slpm(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ERROR: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float airflow = (voltage - 0.5) / (4.5 - 0.5) * 200.0;

    return airflow;
}

// Function to log airflow data to file
void log_airflow(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "ERROR: Log file is not open.\n");
    }
}

// Timer callback function
void timer_callback() {
    int adc_value = read_mcp3008(ADC_CHANNEL);
    if (adc_value >= 0) {
        float airflow = convert_to_slpm(adc_value);
        if (airflow >= 0.0) {
            log_airflow(airflow);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, ERROR: SLPM conversion failed\n", timestamp);
            fflush(log_file);
        }
    } else {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "ERROR: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback function
    gpioSetTimerFuncEx(0, TIMER_INTERVAL_MS, timer_callback, NULL); // Timer 0, every 100ms

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (wait for termination signal)
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Airflow monitoring stopped.\n");

    return 0;
}

