#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz
#define SAMPLE_RATE 1000      // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE) // Nanoseconds
#define CS_GPIO 8             // GPIO8 (CE0)
#define LOG_FILE "audio_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int fd, int channel);
void log_data(FILE *fp, uint32_t timestamp, int adc_value);
void signal_handler(int sig);
int gpio_init(int gpio, const char *chipname);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_request(struct gpiod_chip **chip, struct gpiod_line **line, int gpio, const char *label);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log data to file
void log_data(FILE *fp, uint32_t timestamp, int adc_value) {
    fprintf(fp, "%u|%d\n", timestamp, adc_value);
    fflush(fp); // Ensure data is written immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(int gpio, const char *chipname) {
    struct gpiod_chip **chips;
    int num_chips = 1; // Assuming only one chip is needed
    chips = gpiod_chip_open_by_name(chipname);
    if (!chips || !chips[0]) {
        perror("Error opening GPIO chip");
        return -1;
    }
    gpio_chip = chips[0];

    struct gpiod_line **lines;
    lines = gpiod_chip_get_lines(gpio_chip, &num_chips);
    if (!lines || !lines[0]) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    cs_line = lines[0];

    if (gpiod_line_request_output(cs_line, "audio_capture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to request GPIO line
int gpio_request(struct gpiod_chip **chip, struct gpiod_line **line, int gpio, const char *label) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, gpio);
    if (!*line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, label, 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(CS_GPIO, "gpiochip0") < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            continue; // Continue to the next iteration
        }
        uint32_t timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

        // Log data
        log_data(log_file, timestamp, adc_value);

        // Sleep until the next sample deadline
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD_NS;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

