#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define PPM_SCALE 1000.0
#define NUM_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    float ppm_scale;
    char *log_file_name;
} Config;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_ppm(float voltage, float ppm_scale);
int log_data(float voltage, float ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / 1023.0) * vref;
}

// Convert voltage to PPM
float voltage_to_ppm(float voltage, float ppm_scale) {
    return voltage * ppm_scale;
}

// Log data to file
int log_data(float voltage, float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f V, %.3f PPM\n", timestamp, voltage, ppm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .vref = VREF,
        .ppm_scale = PPM_SCALE,
        .log_file_name = "gas_log.txt"
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_name);
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retry_count = 0;

        // Retry reading ADC value
        while (adc_value == -1 && retry_count < NUM_RETRIES) {
            adc_value = read_mcp3008(0);
            if (adc_value == -1) {
                fprintf(stderr, "ADC read failed, retrying (%d/%d)...\n", retry_count + 1, NUM_RETRIES);
                gpioDelay(100); // 100 ms delay
                retry_count++;
            }
        }

        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC after %d retries. Continuing...\n", NUM_RETRIES);
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Convert ADC value to voltage and PPM
        float voltage = adc_to_voltage(adc_value, config.vref);
        float ppm = voltage_to_ppm(voltage, config.ppm_scale);

        // Log data
        log_data(voltage, ppm);

        // Print to console
        printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

