#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI mode
#define SPI_MODE 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 300.0 // mV/g
#define ADXL335_ZERO_G_BIAS 1.5   // V

// Define number of Kalman filter iterations
#define NUM_KALMAN_ITERATIONS 5

// Global variables for Kalman filter state
float kalman_gain_x = 0.0;
float kalman_gain_y = 0.0;
float kalman_gain_z = 0.0;
float process_noise = 0.01; // Adjust as needed
float measurement_noise = 0.1; // Adjust as needed
float error_covariance_x = 1.0;
float error_covariance_y = 1.0;
float error_covariance_z = 1.0;

// Function prototypes
int read_mcp3008(int channel);
float adxl335_to_g(int adc_value);
float kalman_filter(float measurement, float *error_covariance, float *kalman_gain, float *new_error_covariance);
void signal_handler(int signal);

// Global variable to control the main loop
volatile sig_atomic_t running = 1;

// Signal handler function
void signal_handler(int signal)
{
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7)
    {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        return -1;
    }

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: spiXfer failed\n");
        spiClose(spi_handle);
        return -1;
    }

    spiClose(spi_handle);

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to g-force
float adxl335_to_g(int adc_value)
{
    float voltage = (float)adc_value / 1023.0 * 3.3; // Convert ADC value to voltage
    float g = (voltage - ADXL335_ZERO_G_BIAS) / (ADXL335_SENSITIVITY / 1000.0); // Convert voltage to g-force
    return g;
}

// Function to implement a Kalman filter
float kalman_filter(float measurement, float *error_covariance, float *kalman_gain, float *new_error_covariance)
{
    // Prediction step
    float predicted_measurement = 0.0; // Assuming no process model for simplicity
    float predicted_error_covariance = *error_covariance + process_noise;

    // Update step
    float kalman_gain_update = predicted_error_covariance / (predicted_error_covariance + measurement_noise);
    float updated_state = predicted_measurement + kalman_gain_update * (measurement - predicted_measurement);
    *new_error_covariance = (1 - kalman_gain_update) * predicted_error_covariance;

    return updated_state;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running)
    {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1)
        {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to g-force
        float x_g = adxl335_to_g(x_adc);
        float y_g = adxl335_to_g(y_adc);
        float z_g = adxl335_to_g(z_adc);

        // Apply Kalman filter
        float x_filtered = kalman_filter(x_g, &error_covariance_x, &kalman_gain_x, &error_covariance_x);
        float y_filtered = kalman_filter(y_g, &error_covariance_y, &kalman_gain_y, &error_covariance_y);
        float z_filtered = kalman_filter(z_g, &error_covariance_z, &kalman_gain_z, &error_covariance_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

