#include <unistd.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define constants
#define VCC 3.3f
#define V_QUIESCENT (VCC / 2.0f)
#define SENSITIVITY 0.025f // 25 mV/mT
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int pin);
float calculate_magnetic_field(float voltage);
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int sig);
int setup_gpio(int pin, const char *name);
int cleanup_gpio(struct gpiod_line *line);
int open_log_file(const char *filename);
int close_log_file(FILE *file);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpiod_line_get_value(sensor1_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to calculate magnetic field strength
float calculate_magnetic_field(float voltage) {
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

// Function to log data to file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to setup GPIO line
int setup_gpio(int pin, const char *name) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = name;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

