    if (setup_gpio(SENSOR1_PIN, "sensor1") != 0 ||
        setup_gpio(SENSOR2_PIN, "sensor2") != 0 ||
        setup_gpio(SENSOR3_PIN, "sensor3") != 0) {
        gpiod_chip_close(chip);
        close_log_file(log_file);
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);

