#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define SPI_FLAGS 0
#define MOISTURE_THRESHOLD 30.0
#define READ_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_level(int adc_value);
void control_pump(float moisture_level);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture level percentage
float calculate_moisture_level(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump relay
void control_pump(float moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        log_event("Pump ON");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        log_event("Pump OFF");
    }
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("watering.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        log_event("Error: Could not open SPI channel.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (!terminate) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value.");
        } else {
            // Calculate moisture level
            float moisture_level = calculate_moisture_level(adc_value);

            // Control the pump
            control_pump(moisture_level);

            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%%, ADC value: %d", moisture_level, adc_value);
            log_event(log_message);
        }

        // Wait for the next reading
        gpioDelay(READ_INTERVAL * 1000000); // Delay in microseconds
    }

    // Clean up
    log_event("Cleaning up...");
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is OFF on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

