#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sound sensor value
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Print sound level to console
        printf("Sound level: %d\n", sound_level);

        // Check for sound detection
        if (sound_level == 0) {
            // Activate alarm LED
            gpioWrite(ALARM_LED_PIN, 1);

            // Wait for 1 second
            gpioDelay(1000000); // 1 second = 1000000 microseconds

            // Deactivate alarm LED
            gpioWrite(ALARM_LED_PIN, 0);
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

