#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define MAX_TIMESTAMP_LENGTH 30

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp, size_t timestamp_size)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (timeinfo == NULL) {
        perror("gmtime failed");
        return -1;
    }

    if (strftime(timestamp, timestamp_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    return 0;
}

// Function to log the vibration event to a file
int log_vibration_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s Vibration detected! Shutting down...\n", timestamp) < 0) {
        perror("fprintf failed");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush failed");
        return -1;
    }

    return 0;
}

// Function to print the vibration event to stdout
void print_vibration_event(const char *timestamp)
{
    printf("%s Vibration detected! Shutting down...\n", timestamp);
}

// Function to initiate the system shutdown
int initiate_shutdown()
{
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("system failed");
        return -1;
    }
    return 0;
}

// Function to handle the vibration event
void handle_vibration_event(const char *timestamp)
{
    log_vibration_event(timestamp);
    print_vibration_event(timestamp);
    initiate_shutdown();
}

int main()
{
    char timestamp[MAX_TIMESTAMP_LENGTH];
