// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp, size_t timestamp_size)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (timeinfo == NULL) {
        perror("gmtime failed");
        return -1;
    }

    if (strftime(timestamp, timestamp_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    return 0;
}

