#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define FLAME_SENSOR_PIN 17

// Define log file name
#define LOG_FILE "flame_events.log"

// Global variables for GPIO and log file
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the GPIO line
int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line");
        return -1;
    }
    return value;
}

// Function to log the event
int log_event(int pin, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, pin, state);
    fclose(log_file);
    return 0;
}

// Function to handle flame detection
void handle_flame(int state) {
    if (state == 1) {
        printf("ALARM: Flame detected!\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        log_event(FLAME_SENSOR_PIN, sensor_value);
        handle_flame(sensor_value);

        sleep(1);
    }

    return 0;
}

