#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define I2C_BUS 1
#define I2C_ADDRESS 0x62
#define MCP4725_VREF 3.3 // Reference voltage for MCP4725
#define MCP4725_RESOLUTION 4096 // 12-bit resolution
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int set_mcp4725_voltage(int i2c_handle, float voltage);
int log_data(FILE *log_file, int adc_value, float temperature, float dac_voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Retry loop for SPI communication
    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed. Retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * MCP4725_VREF) / MCP4725_RESOLUTION;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to set MCP4725 DAC voltage
int set_mcp4725_voltage(int i2c_handle, float voltage) {
    if (voltage < 0.0 || voltage > MCP4725_VREF) {
        fprintf(stderr, "Error: Voltage out of range: %f\n", voltage);
        return -1;
    }

    // Calculate DAC value
    int dac_value = (int)((voltage / MCP4725_VREF) * MCP4725_RESOLUTION);

    // Construct I2C message
    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    tx_buffer[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    // Retry loop for I2C communication
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, tx_buffer, 3) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed. Retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: I2C write failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to log data to file
int log_data(FILE *log_file, int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, dac_voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Map temperature to DAC voltage
        float dac_voltage = (temperature / 50.0) * MCP4725_VREF;

        // Set DAC voltage
        if (set_mcp4725_voltage(i2c_handle, dac_voltage) != 0) {
            fprintf(stderr, "Error: Failed to set DAC voltage\n");
        }

        // Log data
        log_data(log_file, adc_value, temperature, dac_voltage);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

