#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define MCP3008 channel assignments
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1
#define SENSOR3_CHANNEL 2

// Global variables for SPI handle and log file
int spi_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void log_data(float moisture1, float moisture2, float moisture3);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nGoodbye!\n");

    // Close SPI connection
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    return (1.0 - (float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture1, float moisture2, float moisture3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, moisture1, moisture2, moisture3);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC values from sensors
        int adc_value1 = read_mcp3008(SENSOR1_CHANNEL);
        int adc_value2 = read_mcp3008(SENSOR2_CHANNEL);
        int adc_value3 = read_mcp3008(SENSOR3_CHANNEL);

        // Calculate moisture percentages
        float moisture1 = calculate_moisture(adc_value1);
        float moisture2 = calculate_moisture(adc_value2);
        float moisture3 = calculate_moisture(adc_value3);

        // Log data
        log_data(moisture1, moisture2, moisture3);

        // Wait for 60 seconds
        gpioDelay(60000); // 60 seconds = 60000 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

