#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Array of GPIO pin numbers
int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[4]; // Array to store GPIO lines

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    for (int i = 0; i < num_relays; i++)
    {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0); // Deactivate relay
        }
    }

    // Release GPIO lines
    for (int i = 0; i < num_relays; i++)
    {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip != NULL)
    {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (chip == NULL)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines for output
    for (int i = 0; i < num_relays; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (lines[i] == NULL)
        {
            perror("Error getting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "relay-sequencer";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        int ret = gpiod_line_request(lines[i], &config, 0); // Initial value is 0 (LOW)
        if (ret < 0)
        {
            perror("Error requesting GPIO line for output");
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1)
    {
        for (int i = 0; i < num_relays; i++)
        {
            // Activate relay
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("Error setting GPIO line value");
                // Release previously acquired lines
                for (int j = 0; j < num_relays; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }

            // Wait for 1 second
            sleep(1);

            // Deactivate relay
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("Error setting GPIO line value");
                // Release previously acquired lines
                for (int j = 0; j < num_relays; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }

            // Wait for 1 second
            sleep(1);
        }
    }

    return 0;
}

