#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain level threshold
#define RAIN_THRESHOLD 5

// Define motor PWM duty cycle
#define MOTOR_DUTY 150

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_rain_level(int adc_value);
void control_motor(int rain_level);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Function to calculate rain level from ADC value
int calculate_rain_level(int adc_value) {
    // Invert the ADC value so that higher ADC value corresponds to less rain
    int inverted_adc = 1023 - adc_value;

    // Scale the inverted ADC value to a rain level between 0 and 10
    int rain_level = (int)(((float)inverted_adc / 1023.0) * 10.0);

    return rain_level;
}

// Function to control the DC motor
void control_motor(int rain_level) {
    if (rain_level >= RAIN_THRESHOLD) {
        // Close the window (motor forward)
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, MOTOR_DUTY);
        printf("Closing window (rain level: %d)\n", rain_level);
    } else {
        // Open the window (motor reverse)
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, MOTOR_DUTY);
        printf("Opening window (rain level: %d)\n", rain_level);
    }
}

// Function to log rain data to file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from rain sensor
        int adc_value = read_mcp3008(SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate rain level
        int rain_level = calculate_rain_level(adc_value);

        // Control motor based on rain level
        control_motor(rain_level);

        // Log rain data
        log_rain_data(rain_level);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Stop motor
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");

    return 0;
}

