    gpioWrite(ADC_GPIO, 0);
    gpioDelay(1); // Wait for discharge

    // Set GPIO26 as input
    gpioSetMode(ADC_GPIO, PI_INPUT);

    // Measure charging time
    for (i = 0; i < ADC_BITS; i++) {
        // Wait for the pin to go high
        while (gpioRead(ADC_GPIO) == 0) {
            // Wait for the pin to go high
        }

