#define FEEDER_THRESHOLD 200.0 // mm

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read_value(int pin);
float voltage_to_distance(float voltage);
int log_distance(float distance);
void feeder_control(float distance);
void signal_handler(int signal);

// Structure to hold GPIO file paths
typedef struct {
    char export_path[64];
    char unexport_path[64];
    char direction_path[64];
    char value_path[64];
} gpio_paths_t;

// Function to initialize GPIO paths
void initialize_gpio_paths(int pin, gpio_paths_t *paths) {
    snprintf(paths->export_path, sizeof(paths->export_path), "%s/export", GPIO_PATH);
    snprintf(paths->unexport_path, sizeof(paths->unexport_path), "%s/unexport", GPIO_PATH);
    snprintf(paths->direction_path, sizeof(paths->direction_path), "%s/gpio%d/direction", GPIO_PATH, pin);
    snprintf(paths->value_path, sizeof(paths->value_path), "%s/gpio%d/value", GPIO_PATH, pin);
}

// Function to export the GPIO pin
int gpio_export(int pin) {
    gpio_paths_t paths;
    initialize_gpio_paths(pin, &paths);

    int fd = open(paths.export_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", paths.export_path, strerror(errno));
        return -1;
    }

    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error writing to %s: %s\n", paths.export_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin) {
    gpio_paths_t paths;
    initialize_gpio_paths(pin, &paths);

    int fd = open(paths.unexport_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", paths.unexport_path, strerror(errno));
        return -1;
    }

    char buf[4];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error writing to %s: %s\n", paths.unexport_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    gpio_paths_t paths;
    initialize_gpio_paths(pin, &paths);

    int fd = open(paths.direction_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", paths.direction_path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", paths.direction_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value (0 or 1)
int gpio_read_value(int pin) {
    gpio_paths_t paths;
    initialize_gpio_paths(pin, &paths);

    int fd = open(paths.value_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", paths.value_path, strerror(errno));
        return -1;
    }

    char buf[2];
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from %s: %s\n", paths.value_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return (buf[0] == '1') ? 1 : 0;
}

// Function to convert voltage to distance (mm)
float voltage_to_distance(float voltage) {
    return (26.0 / voltage) + (-6.0);
}

// Function to log the distance to a file
int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %.2f mm\n", s, distance);
    fclose(fp);
    return 0;
}

// Function to control the pet feeder based on distance
void feeder_control(float distance) {
    if (distance < FEEDER_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder Control Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        int gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_PIN);
            sleep(1); // Retry after 1 second
            continue;
        }

        // Convert GPIO value to voltage
        float voltage = (gpio_value == 1) ? 3.3 : 0.0;

        // Convert voltage to distance
        float distance = voltage_to_distance(voltage);

        // Log the distance
        if (log_distance(distance) != 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        // Control the feeder
        feeder_control(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (gpio_unexport(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    printf("Pet Feeder Control Program stopped.\n");

    return 0;
}

