#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pump_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_read_adc(int channel);
float calculate_moisture_percentage(int adc_value, int dry_value, int wet_value);
int gpio_init(int pin);
int gpio_set_value(int pin, int value);
int log_data(float moisture_percentage, int pump_status);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd;
    unsigned int mode_flags = 0;
    unsigned int bits_flags = 0;
    unsigned int speed_flags = 0;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_flags) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_flags) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_flags) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Moisture percentage calculation function
float calculate_moisture_percentage(int adc_value, int dry_value, int wet_value) {
    float percentage = 100.0 - ((float)(adc_value - wet_value) / (float)(dry_value - wet_value)) * 100.0;
    if (percentage < 0.0) percentage = 0.0;
    if (percentage > 100.0) percentage = 100.0;
    return percentage;
}

// GPIO initialization function
int gpio_init(int pin) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "soil_moisture_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    pump_line = line;
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    if (gpiod_line_set_value(pump_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Logging function
int log_data(float moisture_percentage, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    if (pump_line) {
        gpio_set_value(PUMP_GPIO, 0); // Turn off pump
        gpiod_line_release(pump_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    int adc_value;
    float moisture_percentage;
    int pump_status = 0; // 0 = OFF, 1 = ON

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(PUMP_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d. Skipping this sample.\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Calculate moisture percentage
        moisture_percentage = calculate_moisture_percentage(adc_value, DRY_ADC_VALUE, WET_ADC_VALUE);

        // Control pump based on moisture level
        if (moisture_percentage < MOISTURE_THRESHOLD && pump_status == 0) {
            if (gpio_set_value(PUMP_GPIO, 1) == 0) {
                pump_status = 1;
            } else {
                fprintf(stderr, "Failed to turn pump ON.\n");
            }
        } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_status == 1) {
            if (gpio_set_value(PUMP_GPIO, 0) == 0) {
                pump_status = 0;
            } else {
                fprintf(stderr, "Failed to turn pump OFF.\n");
            }
        }

        // Log data
        if (log_data(moisture_percentage, pump_status) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait before next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

