#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables (to be cleaned up on exit)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int fd, int channel);
float calculate_magnetic_field(int adc_value);
int log_data(FILE *fp, float magnetic_field);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip);
int setup_spi(int *fd);
int cleanup_spi(int fd);
int setup_log_file(FILE **fp);
int cleanup_log_file(FILE *fp);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) != 0) {
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate magnetic field function
float calculate_magnetic_field(int adc_value) {
    // DRV5055-A1: 100 mV/mT, 1650 mV quiescent output
    // MCP3008: 0-1023, 0-3.3V
    // Vout_mV = adc_value * 3300 / 1023
    // B (mT) = (Vout_mV - 1650) / 100
    return (float)((adc_value * 3300.0 / 1023.0) - 1650.0) / 100.0;
}

// Log data function
int log_data(FILE *fp, float magnetic_field) {
    time_t now = time(NULL);
    if (fprintf(fp, "%ld,%.2f\n", now, magnetic_field) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Setup GPIO function
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "magnetic_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Setup SPI function
int setup_spi(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

// Cleanup SPI function
int cleanup_spi(int fd) {
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

// Setup log file function
int setup_log_file(FILE **fp) {
    *fp = fopen(LOG_FILE, "a");
    if (*fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup log file function
int cleanup_log_file(FILE *fp) {
    if (fp != NULL) {
        fclose(fp);
    }
    return 0;
}

int main() {
    // Setup signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio(&gpio_chip, &gpio_line) != 0) {
        return 1;
    }

    // Setup SPI
    if (setup_spi(&spi_fd) != 0) {
        cleanup_gpio(gpio_line, gpio_chip);
        return 1;
    }

    // Setup log file
    if (setup_log_file(&log_file) != 0) {
        cleanup_spi(spi_fd);
        cleanup_gpio(gpio_line, gpio_chip);
        return 1;
    }

    fprintf(stdout, "Starting magnetic sensor data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
            continue;
        }

        // Calculate magnetic field
        float magnetic_field = calculate_magnetic_field(adc_value);

        // Log data
        if (log_data(log_file, magnetic_field) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    fprintf(stdout, "Cleaning up and exiting...\n");
    cleanup_gpio(gpio_line, gpio_chip);
    cleanup_spi(spi_fd);
    cleanup_log_file(log_file);

    return 0;
}

