#define VCC 3.3
#define THRESHOLD 10.0
#define LED_GPIO 21
#define SENSITIVITY 1.65 // mV/mT
#define VCC_DIVISION 5.0 // VCC/2 for quiescent output

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_magnetic_field(float voltage);
