    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED off

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * VCC / 1023.0;

        // Convert voltage to magnetic field strength
        float magnetic_field = voltage_to_magnetic_field(voltage);

        // Log data
        log_data(magnetic_field);

        // Control LED
        control_led(magnetic_field);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

