void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close SPI if it's open
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        printf("SPI closed.\n");
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    // Close log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x80 | (channel << 4)); // Single-ended mode + channel selection
    tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log data to file
int log_data(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1; // Indicate failure
    }

    // Write data to log file
    fprintf(log_file, "%s, %d\n", timestamp, adc_value);

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset log_file pointer after closing

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Log data
        if (adc_value >= 0) {
            if (log_data(adc_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        // Wait for 60 seconds
        gpioDelay(60000); // Delay in microseconds
    }

    return 0;
}

