#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 5.0          // Reference voltage
#define VDD 5.0           // Supply voltage
#define FULL_SCALE_CURRENT 50.0 // Full-scale current (A)
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    float vdd;
    float full_scale_current;
    char *log_file;
} config_t;

// Function prototypes
int initialize_pigpio();
int open_spi(int channel, int speed, int mode);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_current(float voltage, float vdd, float full_scale_current);
int log_current(float current, const char *filename);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI channel
int open_spi(int channel, int speed, int mode) {
    int handle = spiOpen(channel, speed, mode);
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit result
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (float)adc_value * vref / 1023.0;
}

// Convert voltage to current
float voltage_to_current(float voltage, float vdd, float full_scale_current) {
    if (voltage < 0.0) {
        fprintf(stderr, "Warning: Voltage below 0V, skipping sample.\n");
        return 0.0;
    } else if (voltage > vdd) {
        fprintf(stderr, "Warning: Voltage above VDD, skipping sample.\n");
        return 0.0;
    }
    return (voltage - (vdd / 2.0)) * (full_scale_current / (vdd / 2.0));
}

// Log current to file
int log_current(float current, const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return 1;
    }

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Open SPI channel
    spi_handle = open_spi(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert to voltage and current
        float voltage = adc_to_voltage(adc_value, VREF);
        float current = voltage_to_current(voltage, VDD, FULL_SCALE_CURRENT);

        // Log current
        if (log_current(current, LOG_FILE)) {
            fprintf(stderr, "Error logging current.\n");
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

