#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to read sensor value with debouncing
int read_sensor(int gpio_pin);

// Function to log sensor data
void log_sensor_data(int sensor1_value, int sensor2_value);

// Function to check if both sensors detect an object
void check_alert(int sensor1_value, int sensor2_value);

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for the sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Error getting GPIO line for sensor 1");
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Error getting GPIO line for sensor 2");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        perror("Error requesting GPIO line for sensor 1 as input");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Error requesting GPIO line for sensor 2 as input");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Log sensor data
        log_sensor_data(sensor1_value, sensor2_value);

        // Check for alert condition
        check_alert(sensor1_value, sensor2_value);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor value with debouncing
int read_sensor(int gpio_pin)
{
    int value = 1; // Initialize to HIGH (no object)
    int i;

    for (i = 0; i < 5; i++) {
        struct gpiod_line *line;
        if (gpio_pin == SENSOR1_PIN) {
            line = sensor1_line;
        } else {
            line = sensor2_line;
        }

        int read_value = gpiod_line_get_value(line);
        if (read_value < 0) {
            perror("Error reading GPIO line value");
            return -1; // Indicate error
        }

        if (read_value == 0) {
            value = 0; // Object present
            break;      // Exit loop if object is detected
        }
        usleep(2000); // 2ms delay
    }

    return value;
}

// Function to log sensor data
void log_sensor_data(int sensor1_value, int sensor2_value)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
}

// Function to check if both sensors detect an object
void check_alert(int sensor1_value, int sensor2_value)
{
    if (sensor1_value == 0 && sensor2_value == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

