#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <sys/wait.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DELAY_MS 500
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_buffer;
}

// Function to construct the output filename
int construct_filename(char* filename_buffer, size_t buffer_size, const char* timestamp) {
    return snprintf(filename_buffer, buffer_size, "/home/pi/security_cam/%s.jpg", timestamp);
}

// Function to check if the output directory exists
int check_directory(const char* directory) {
    struct stat st;
    if (stat(directory, &st) == -1) {
        syslog(LOG_ERR, "Error checking directory: %s", strerror(errno));
        return -1;
    }
    return (st.st_mode & S_IFDIR) != 0; // Check if it's a directory
}

// Function to capture an image using libcamera-still
int capture_image(const char* filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --iso 100", filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    pid_t pid = fork();
    if (pid == -1) {
        syslog(LOG_ERR, "Error forking process: %s", strerror(errno));
        return -1;
    } else if (pid == 0) {
        // Child process
        if (execl("/bin/sh", "sh", "-c", command, (char*)NULL) == -1) {
            syslog(LOG_ERR, "Error executing command: %s", strerror(errno));
            exit(EXIT_FAILURE);
        }
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            syslog(LOG_ERR, "Error waiting for process: %s", strerror(errno));
            return -1;
        }

        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            syslog(LOG_ERR, "Image capture failed with exit status: %d", WEXITSTATUS(status));
            return -1;
        }
    }
    return 0;
}

// Function to log motion detection event
void log_motion_detection(const char* timestamp) {
    syslog(LOG_INFO, "Motion detected at: %s", timestamp);
}

// Function to log image capture event
void log_image_capture(const char* filename) {
    syslog(LOG_INFO, "Image captured: %s", filename);
}

// Function to log image capture failure event
void log_image_capture_failure(const char* filename) {
    syslog(LOG_ERR, "Image capture failed: %s", filename);
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera system...");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    char timestamp_buffer[32];
    char filename_buffer[256];

    // Main loop
    while (!terminate) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == 1) {
            // Motion detected
            get_iso8601_timestamp(timestamp_buffer, sizeof(timestamp_buffer));
            if (construct_filename(filename_buffer, sizeof(filename_buffer), timestamp_buffer) < 0) {
                syslog(LOG_ERR, "Failed to construct filename");
                continue; // Skip to the next iteration
            }

            // Check if the output directory exists
            if (check_directory("/home/pi/security_cam/") != 0) {
                syslog(LOG_ERR, "Output directory does not exist");
                continue; // Skip to the next iteration
            }

            // Capture image
            if (capture_image(filename_buffer) == 0) {
                log_image_capture(filename_buffer);
            } else {
                log_image_capture_failure(filename_buffer);
            }

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
            if (gpioRead(GPIO_PIN) == 1) {
                log_motion_detection(timestamp_buffer);
            }
        }

        gpioDelay(CAPTURE_DELAY_MS * 1000); // Poll every 50ms
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Security camera system terminated.");
    closelog();

    return 0;
}

