#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define BUFFER_COUNT 1
#define FILENAME_BUFFER_SIZE 32

static volatile int keep_running = 1;
static int fd = -1;
static void **buffers = NULL;
static FILE *log_file = NULL;

void signal_handler(int sig);
int initialize_camera(int *fd, void ***buffers, int *buffer_count);
int capture_frame(int fd, void **buffer, int buffer_count);
int save_image(int fd, void *buffer, int buffer_count, int frame_number);
void cleanup(int fd, void **buffers, int buffer_count);
int select_with_timeout(int fd, int timeout_sec);

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, stopping...\n", sig);
        keep_running = 0;
    }
}

int initialize_camera(int *fd, void ***buffers, int *buffer_count) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd == -1) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(*fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(*fd);
        return -1;
    }

    *buffer_count = req.count;

    *buffers = calloc(req.count, sizeof(void*));
    if (*buffers == NULL) {
        perror("Error allocating buffers");
        close(*fd);
        return -1;
    }

    for (i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            cleanup(*fd, *buffers, req.count);
            return -1;
        }

        (*buffers)[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if ((*buffers)[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            cleanup(*fd, *buffers, req.count);
            return -1;
        }
    }

    return 0;
}

int capture_frame(int fd, void **buffer, int buffer_count) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
