    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a frame
static int capture_frame(int fd, int buffer_index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Log the timestamp
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld\n", tv.tv_sec, tv.tv_usec);
    fflush(log_file);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to stop streaming
static int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to unmap buffers
static int uninit_device(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to close the device
static int close_device(int fd) {
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("frame_log.txt", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Open the video device
    fd = open_device(VIDEO_DEVICE);
    if (fd == -1) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        uninit_device(fd);
        close_device(fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    // Main loop
    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            perror("Error in select");
            break;
        } else if (r == 0) {
            fprintf(stderr, "Select timeout\n");
            continue; // Continue to the next iteration
        }

        // Capture a frame
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (capture_frame(fd, i) == -1) {
                fprintf(stderr, "Error capturing frame, exiting.\n");
                break;
            }
        }
    }

    // Stop capturing
    if (stop_capturing(fd) == -1) {
        fprintf(stderr, "Error stopping capturing.\n");
    }

    // Unmap buffers
    if (uninit_device(fd) == -1) {
        fprintf(stderr, "Error uninitializing device.\n");
    }

    // Close the device
    if (close_device(fd) == -1) {
        fprintf(stderr, "Error closing device.\n");
    }

    // Close the log file
    if (fclose(log_file) == EOF) {
        perror("Error closing log file");
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

