#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <pthread.h>

#define VIDEO_DEVICE "/dev/video0"
#define NUM_BUFFERS 4
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE 2 * FRAME_WIDTH * FRAME_HEIGHT / 2 // YUYV format
#define MAX_FRAGMENT_SIZE 65000
#define UDP_BUFFER_SIZE 65536

// Structure to hold video buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int running = 1;
static int video_fd = -1;
static int udp_socket = -1;
static buffer_t buffers[NUM_BUFFERS];
static unsigned int frame_index = 0;
static unsigned int fragment_index = 0;
static unsigned int total_fragment_count = 0;
static char *udp_buffer = NULL;
static size_t udp_buffer_size = 0;
static pthread_mutex_t fragment_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t fragment_cond = PTHREAD_COND_INITIALIZER;

// Function prototypes
int init_v4l2(const char *device, int *fd);
int configure_v4l2(int fd);
int map_v4l2_buffers(int fd, buffer_t *buffers, int num_buffers);
int unmap_v4l2_buffers(int fd, buffer_t *buffers, int num_buffers);
int start_capturing(int fd);
int stop_capturing(int fd);
int capture_frame(int fd, buffer_t *buffer);
int create_udp_socket(const char *server_ip, int server_port, int *socket_fd);
int send_udp_packet(int socket_fd, const char *server_ip, int server_port, const char *data, size_t data_len);
void *fragmentation_thread(void *arg);
void signal_handler(int signum);
void cleanup();

// Helper function to convert YUYV to RGB
void yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < width * height; i++) {
        // YUYV to RGB conversion (simplified)
        unsigned char y = yuyv[2 * i];
        unsigned char u = yuyv[2 * i + 1] - 128;
        unsigned char v = yuyv[2 * i + 3] - 128;

        int r = y + 1.370705 * v;
        int g = y - 0.698001 * v - 0.336331 * u;
        int b = y + 1.732446 * u;

        r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
        g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
        b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

        rgb[2 * i] = r;
        rgb[2 * i + 1] = g;
        rgb[2 * i + 2] = b;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    openlog("video_streamer", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize V4L2
    if (init_v4l2(VIDEO_DEVICE, &video_fd) != 0) {
        syslog(LOG_ERR, "Failed to initialize V4L2");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure V4L2
    if (configure_v4l2(video_fd) != 0) {
        syslog(LOG_ERR, "Failed to configure V4L2");
        cleanup();
        return EXIT_FAILURE;
    }

    // Map V4L2 buffers
    if (map_v4l2_buffers(video_fd, buffers, NUM_BUFFERS) != 0) {
        syslog(LOG_ERR, "Failed to map V4L2 buffers");
        cleanup();
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(video_fd) != 0) {
        syslog(LOG_ERR, "Failed to start capturing");
        cleanup();
        return EXIT_FAILURE;
    }

    // Create UDP socket
    if (create_udp_socket(server_ip, server_port, &udp_socket) != 0) {
        syslog(LOG_ERR, "Failed to create UDP socket");
        cleanup();
        return EXIT_FAILURE;
    }

    // Allocate UDP buffer
    udp_buffer_size = MAX_FRAGMENT_SIZE + 8; // Header + payload
    udp_buffer = (char *)malloc(udp_buffer_size);
    if (udp_buffer == NULL) {
        syslog(LOG_ERR, "Failed to allocate UDP buffer");
        cleanup();
        return EXIT_FAILURE;
    }

    // Create fragmentation thread
    pthread_t fragmentation_thread_id;
    if (pthread_create(&fragmentation_thread_id, NULL, fragmentation_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create fragmentation thread");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop (dummy, capturing is done in the threads)
    while (running) {
        sleep(1);
    }

    // Cleanup
    pthread_join(fragmentation_thread_id, NULL);
    cleanup();

    closelog();
    return EXIT_SUCCESS;
}

int init_v4l2(const char *device, int *fd) {
    *fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (*fd == -1) {
        perror("Error opening video device");
        return -1;
    }
    return 0;
}

int configure_v4l2(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    // Query buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    return 0;
}

int map_v4l2_buffers(int fd, buffer_t *buffers, int num_buffers) {
    for (int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }
    return 0;
}

int unmap_v4l2_buffers(int fd, buffer_t *buffers, int num_buffers) {
    for (int i = 0; i < num_buffers; i++) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
            return -1;
        }
    }
    return 0;
}

int start_capturing(int fd) {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    for (int i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    return 0;
}

int capture_frame(int fd, buffer_t *buffer) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    // Copy the frame data to the global buffer
    memcpy(buffer->start, buffer->start, buffer->length);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

int create_udp_socket(const char *server_ip, int server_port, int *socket_fd) {
    struct sockaddr_in server_addr;

    *socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (*socket_fd == -1) {
        perror("socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(*socket_fd);
        return -1;
    }

    return 0;
}

int send_udp_packet(int socket_fd, const char *server_ip, int server_port, const char *data, size_t data_len) {
    struct sockaddr_in server_addr;
    socklen_t server_addr_len = sizeof(server_addr);

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        return -1;
    }

    ssize_t bytes_sent = sendto(socket_fd, data, data_len, 0, (struct sockaddr *)&server_addr, server_addr_len);
    if (bytes_sent == -1) {
        perror("sendto");
        return -1;
    }

    return 0;
}

void *fragmentation_thread(void *arg) {
    unsigned char *yuyv_frame = NULL;
    unsigned char *rgb_frame = NULL;
    size_t frame_size = FRAME_SIZE;
    size_t fragment_size = 0;
    size_t remaining_size = frame_size;
    size_t bytes_sent = 0;
    ssize_t bytes_to_send;
    unsigned char *fragment = NULL;
    size_t fragment_offset = 0;
    unsigned int current_fragment_index = 0;
    unsigned int current_frame_index = 0;

    while (running) {
        pthread_mutex_lock(&fragment_mutex);
        while (fragment_index < total_fragment_count && running) {
            pthread_cond_wait(&fragment_cond, &fragment_mutex);
        }
        pthread_mutex_unlock(&fragment_mutex);

        if (!running) break;

        // Capture a frame
        if (capture_frame(video_fd, &buffers[0]) != 0) {
            syslog(LOG_ERR, "Failed to capture frame");
            continue;
        }

        // Convert YUYV to RGB (optional)
        yuyv_frame = (unsigned char *)buffers[0].start;
        rgb_frame = (unsigned char *)malloc(FRAME_WIDTH * FRAME_HEIGHT * 3);
        if (rgb_frame == NULL) {
            syslog(LOG_ERR, "Failed to allocate RGB frame buffer");
            continue;
        }
        yuyv_to_rgb(yuyv_frame, rgb_frame, FRAME_WIDTH, FRAME_HEIGHT);

        // Fragment the frame
        fragment = (unsigned char *)malloc(MAX_FRAGMENT_SIZE);
        if (fragment == NULL) {
            syslog(LOG_ERR, "Failed to allocate fragment buffer");
            free(rgb_frame);
            continue;
        }

        fragment_size = 0;
        while (remaining_size > 0 && running) {
            fragment_size = (remaining_size < MAX_FRAGMENT_SIZE) ? (size_t)remaining_size : MAX_FRAGMENT_SIZE;
            memcpy(fragment + fragment_offset, rgb_frame + (frame_size - remaining_size), fragment_size);

            // Create UDP packet header
            unsigned char header[8];
            header[0] = (current_frame_index >> 24) & 0xFF;
            header[1] = (current_frame_index >> 16) & 0xFF;
            header[2] = (current_frame_index >> 8) & 0xFF;
            header[3] = current_frame_index & 0xFF;
            header[4] = (current_fragment_index >> 24) & 0xFF;
            header[5] = (current_fragment_index >> 16) & 0xFF;
            header[6] = (current_fragment_index >> 8) & 0xFF;
            header[7] = current_fragment_index & 0xFF;

            // Combine header and fragment data
            char *packet = (char *)malloc(fragment_size + 8);
            if (packet == NULL) {
                syslog(LOG_ERR, "Failed to allocate packet buffer");
                free(fragment);
                free(rgb_frame);
                continue;
            }
            memcpy(packet, header, 8);
            memcpy(packet + 8, fragment, fragment_size);

            // Send UDP packet
            if (send_udp_packet(udp_socket, server_ip, server_port, packet, fragment_size + 8) != 0) {
                syslog(LOG_ERR, "Failed to send UDP packet");
                free(packet);
                free(fragment);
                free(rgb_frame);
                continue;
            }
            bytes_sent += fragment_size + 8;

            // Update indices and remaining size
            current_fragment_index++;
            remaining_size -= fragment_size;
            fragment_offset += fragment_size;

            // Free packet buffer
            free(packet);
        }

        // Update global frame and fragment indices
        frame_index++;
        pthread_mutex_lock(&fragment_mutex);
        fragment_index = current_fragment_index;
        pthread_cond_signal(&fragment_cond);
        pthread_mutex_unlock(&fragment_mutex);

        // Free local buffers
        free(rgb_frame);
        free(fragment);

        // Reset fragment index and condition variable
        current_fragment_index = 0;
        pthread_mutex_lock(&fragment_mutex);
        total_fragment_count = 0;
        pthread_cond_signal(&fragment_cond);
        pthread_mutex_unlock(&fragment_mutex);
    }

    pthread_exit(NULL);
}

void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, stopping...");
    running = 0;
}

void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    // Stop capturing
    if (video_fd != -1) {
        stop_capturing(video_fd);
    }

    // Unmap buffers
    if (video_fd != -1) {
        unmap_v4l2_buffers(video_fd, buffers, NUM_BUFFERS);
    }

    // Close socket
    if (udp_socket != -1) {
        close(udp_socket);
    }

    // Free UDP buffer
    if (udp_buffer != NULL) {
        free(udp_buffer);
    }

    // Destroy mutex and condition variable
    pthread_mutex_destroy(&fragment_mutex);
    pthread_cond_destroy(&fragment_cond);

    // Close video device
    if (video_fd != -1) {
        close(video_fd);
    }

    syslog(LOG_INFO, "Cleanup complete.");
}

