    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Function to query a buffer
int query_buffer(int fd, unsigned int buffer_index, struct v4l2_buffer *buf)
{
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = buffer_index;

    if (ioctl(fd, VIDIOC_QUERYBUF, buf) == -1) {
        perror("Error querying buffer");
        return -1;
    }
    return 0;
}

// Function to map a buffer
int map_buffer(int fd, struct v4l2_buffer *buf, struct buffer *buffer_info)
{
    buffer_info->length = buf->length;
    buffer_info->start = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);

    if (buffer_info->start == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }
    return 0;
}

// Function to queue a buffer
int queue_buffer(int fd, struct v4l2_buffer *buf)
{
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf)
{
    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }
    return 0;
}

// Function to unmap a buffer
void unmap_buffer(struct buffer *buffer_info)
{
    if (buffer_info->start != NULL && buffer_info->start != MAP_FAILED) {
        if (munmap(buffer_info->start, buffer_info->length) == -1) {
            perror("Error unmapping buffer");
        }
        buffer_info->start = NULL;
    }
}

// Function to write the MJPEG data to a file
int write_jpeg_to_file(const void *data, size_t size, const char *filename)
{
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    if (fwrite(data, 1, size, fp) != size) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query device capabilities
    struct v4l2_capability cap;
    if (query_device(fd, &cap) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Check if the device supports capture and streaming
    if (!check_capabilities(&cap)) {
        fprintf(stderr, "Device does not support capture and streaming\n");
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Set the video format
    if (set_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT, JPEG_FORMAT, FIELD_NONE) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, NUM_BUFFERS) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the buffers
    buffers = calloc(NUM_BUFFERS, sizeof(struct buffer));
    if (buffers == NULL) {
        perror("Error allocating memory for buffers");
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Query and map each buffer
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        if (query_buffer(fd, i, &buf) == -1) {
            close_device(fd);
            free(buffers);
            return EXIT_FAILURE;
        }

        if (map_buffer(fd, &buf, &buffers[i]) == -1) {
            close_device(fd);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        close_device(fd);
        free(buffers);
        return EXIT_FAILURE;
    }

    // Dequeue a frame
    struct v4l2_buffer frame_buf;
    memset(&frame_buf, 0, sizeof(frame_buf));
    frame_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    frame_buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &frame_buf) == -1) {
        perror("Error dequeuing frame");
        close_device(fd);
        free(buffers);
        return EXIT_FAILURE;
    }

    // Write the MJPEG data to a file
    if (write_jpeg_to_file(buffers[frame_buf.index].start, buffers[frame_buf.index].length, "image.jpg") == -1) {
        fprintf(stderr, "Failed to write JPEG to file.\n");
        close_device(fd);
        free(buffers);
        return EXIT_FAILURE;
    }

    // Requeue the frame
    if (ioctl(fd, VIDIOC_QBUF, &frame_buf) == -1) {
        perror("Error requeuing frame");
        close_device(fd);
        free(buffers);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        close_device(fd);
        free(buffers);
        return EXIT_FAILURE;
    }

    // Clean up resources
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        unmap_buffer(&buffers[i]);
    }
    free(buffers);
    close_device(fd);

    fprintf(stderr, "Image captured and saved as image.jpg\n");

    return EXIT_SUCCESS;
}

