#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define MIN_POSITION 25
#define MAX_POSITION 125

// Define PWM frequency
#define PWM_FREQUENCY 50

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to set servo position
int set_servo_position(int gpio, int position) {
    if (position < MIN_POSITION || position > MAX_POSITION) {
        fprintf(stderr, "Error: Position out of range (%d)\n", position);
        return -1;
    }

    // Calculate pulse width based on position
    int pulse_width = (int)(((float)(position - MIN_POSITION) / (MAX_POSITION - MIN_POSITION)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    // Set PWM duty cycle
    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }

    return 0;
}

// Function to handle button press
void handle_button_press(int button_pin, int servo_pin, int *position) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (active-low)
        *position += (button_pin == LEFT_BUTTON_PIN) ? -5 : 5;
        if (*position < MIN_POSITION) {
            *position = MIN_POSITION;
        } else if (*position > MAX_POSITION) {
            *position = MAX_POSITION;
        }
        if (set_servo_position(servo_pin, *position) != 0) {
            fprintf(stderr, "Error: Failed to set servo position for GPIO %d\n", servo_pin);
        }
        gpioDelay(200); // Debounce delay
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", UP_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistors
    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistor for GPIO %d\n", UP_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistor for GPIO %d\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistor for GPIO %d\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistor for GPIO %d\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial servo positions
    int pan_position = 75;
    int tilt_position = 75;

    if (set_servo_position(PAN_SERVO_PIN, pan_position) != 0) {
        fprintf(stderr, "Error: Failed to set initial pan servo position\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_position(TILT_SERVO_PIN, tilt_position) != 0) {
        fprintf(stderr, "Error: Failed to set initial tilt servo position\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(PAN_SERVO_PIN, 1000);
    gpioSetPWMrange(TILT_SERVO_PIN, 1000);

    // Set initial PWM duty cycle (center position)
    gpioPWM(PAN_SERVO_PIN, 1500);
    gpioPWM(TILT_SERVO_PIN, 1500);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        handle_button_press(UP_BUTTON_PIN, TILT_SERVO_PIN, &tilt_position);
        handle_button_press(DOWN_BUTTON_PIN, TILT_SERVO_PIN, &tilt_position);
        handle_button_press(LEFT_BUTTON_PIN, PAN_SERVO_PIN, &pan_position);
        handle_button_press(RIGHT_BUTTON_PIN, PAN_SERVO_PIN, &pan_position);

        gpioDelay(50); // Poll buttons every 50 ms
    }

    // Clean up and terminate
    gpioTerminate();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

