#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 75

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
static int fd = -1; // File descriptor for the camera device
static buffer_t *buffers = NULL; // Array of camera buffers
static unsigned int n_buffers = 0; // Number of camera buffers
static unsigned char *yuyv_frame = NULL; // Pointer to the YUYV frame data
static unsigned char *rgb_frame = NULL; // Pointer to the RGB frame data
static unsigned char *jpeg_buffer = NULL; // Pointer to the JPEG buffer
static struct jpeg_compress_struct cinfo; // JPEG compression structure
static struct jpeg_error_mgr jerr; // JPEG error manager
static volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Function prototypes
static int xioctl(int fd, int request, void *arg);
static int init_camera(int fd);
static int capture_frame(int fd, buffer_t *buffers, unsigned int n_buffers);
static unsigned char *convert_yuyv_to_rgb24(unsigned char *yuyv_data, int width, int height);
static unsigned char *apply_box_blur(unsigned char *rgb_data, int width, int height, int radius);
static int encode_jpeg(unsigned char *rgb_data, int width, int height, int quality, unsigned char **jpeg_buffer, unsigned long *jpeg_size);
static int save_jpeg(unsigned char *jpeg_buffer, unsigned long jpeg_size, const char *filename);
static void signal_handler(int signum);
static void cleanup(int fd, buffer_t *buffers, unsigned int n_buffers, unsigned char *yuyv_frame, unsigned char *rgb_frame, unsigned char *jpeg_buffer);

// Helper function to get current timestamp
static char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    static char timestamp[20]; //YYYYMMDD_HHMMSS\0
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to perform I/O control on the camera device
static int xioctl(int fd, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

// Function to initialize the camera device
static int init_camera(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    // Check device capabilities
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "Error: VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming I/O\n");
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "Error: VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "Error: VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        fprintf(stderr, "Error: Out of memory\n");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "Error: VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "Error: mmap failed: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to capture a single frame from the camera
static int capture_frame(int fd, buffer_t *buffers, unsigned int n_buffers)
{
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    // Dequeue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "Error: VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    // Wait for frame readiness using select()
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        fprintf(stderr, "Error: select failed: %s\n", strerror(errno));
        return -1;
    } else if (0 == r) {
        fprintf(stderr, "Error: Timeout waiting for frame\n");
        return -1;
    }

    // Requeue buffer
    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        fprintf(stderr, "Error: VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return buf.index;
}

// Function to convert YUYV to RGB24
static unsigned char *convert_yuyv_to_rgb24(unsigned char *yuyv_data, int width, int height)
{
    unsigned char *rgb_data = malloc(width * height * 3 * sizeof(unsigned char));
    if (!rgb_data) {
        fprintf(stderr, "Error: Out of memory allocating RGB data\n");
        return NULL;
    }

    int i, j;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            // YUYV to RGB conversion (simplified)
            unsigned char y = yuyv_data[(i * width + j) * 2];
            unsigned char u = yuyv_data[(i * width + j) * 2 + 1] - 128;
            unsigned char v = yuyv_data[(i * width + j) * 2 + 3] - 128;

            int r = y + 1.370705 * v;
            int g = y - 0.698001 * v - 0.336331 * u;
            int b = y + 1.732446 * u;

            r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
            g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
            b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

            rgb_data[(i * width + j) * 3 + 0] = r;
            rgb_data[(i * width + j) * 3 + 1] = g;
            rgb_data[(i * width + j) * 3 + 2] = b;
        }
    }

    return rgb_data;
}

// Function to apply a 5x5 box blur filter
static unsigned char *apply_box_blur(unsigned char *rgb_data, int width, int height, int radius)
{
    unsigned char *blurred_data = malloc(width * height * 3 * sizeof(unsigned char));
    if (!blurred_data) {
        fprintf(stderr, "Error: Out of memory allocating blurred data\n");
        return NULL;
    }

    int i, j, x, y;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            long r_sum = 0, g_sum = 0, b_sum = 0;
            long r_count = 0, g_count = 0, b_count = 0;

            for (x = i - radius; x <= i + radius; x++) {
                for (y = j - radius; y <= j + radius; y++) {
                    if (x >= 0 && x < height && y >= 0 && y < width) {
                        r_sum += rgb_data[(x * width + y) * 3 + 0];
                        g_sum += rgb_data[(x * width + y) * 3 + 1];
                        b_sum += rgb_data[(x * width + y) * 3 + 2];
                        r_count++;
                        g_count++;
                        b_count++;
                    }
                }
            }

            blurred_data[(i * width + j) * 3 + 0] = (unsigned char)(r_sum / r_count);
            blurred_data[(i * width + j) * 3 + 1] = (unsigned char)(g_sum / g_count);
            blurred_data[(i * width + j) * 3 + 2] = (unsigned char)(b_sum / b_count);
        }
    }

    return blurred_data;
}

// Function to encode the RGB image as JPEG
static int encode_jpeg(unsigned char *rgb_data, int width, int height, int quality, unsigned char **jpeg_buffer, unsigned long *jpeg_size)
{
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    *jpeg_buffer = NULL;
    *jpeg_size = 0;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_mem_dest(&cinfo, jpeg_buffer, jpeg_size);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to save the JPEG image to a file
static int save_jpeg(unsigned char *jpeg_buffer, unsigned long jpeg_size, const char *filename)
{
