        cleanup(fd, buffers, n_buffers, yuyv_frame, rgb_frame, jpeg_buffer);
        return EXIT_FAILURE;
    }

    // Save JPEG
    snprintf(filename, sizeof(filename), "capture_%s.jpg", get_timestamp());
    if (save_jpeg(jpeg_data, jpeg_size, filename) == -1) {
        fprintf(stderr, "Error: JPEG saving failed\n");
        cleanup(fd, buffers, n_buffers, yuyv_frame, rgb_frame, jpeg_buffer);
        return EXIT_FAILURE;
    }

    printf("Image saved as %s\n", filename);

    // Cleanup
    cleanup(fd, buffers, n_buffers, yuyv_frame, rgb_frame, jpeg_buffer);

    return EXIT_SUCCESS;
}

