#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_RESOLUTIONS 10
#define MAX_FRAME_RATES 10

// Structure to hold camera capabilities
typedef struct {
    unsigned int supported_resolutions;
    unsigned int supported_frame_rates;
    int autofocus_supported;
} camera_capabilities_t;

// Function to check if a file exists
int file_exists(const char *filename) {
    if (access(filename, F_OK) == 0) {
        return 1;
    } else {
        return 0;
    }
}

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query camera capabilities
int query_camera_capabilities(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    capabilities->supported_resolutions = 0;
    capabilities->supported_frame_rates = 0;
    capabilities->autofocus_supported = 0;

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Enumerate frame sizes
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsizeenum;
    int i = 0;

    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        frmsizeenum.index = 0;
        frmsizeenum.pixel_format = fmtdesc.pixelformat;

        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsizeenum) == 0) {
            if (frmsizeenum.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
                capabilities->supported_resolutions++;
                if (capabilities->supported_resolutions >= MAX_RESOLUTIONS) {
                    fprintf(stderr, "Too many resolutions, limiting to %d\n", MAX_RESOLUTIONS);
                    break;
                }
            }
        } else {
            fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
            break;
        }
        fmtdesc.index++;
    }

    // Enumerate frame intervals
    struct v4l2_frmsizeenum frmsizeenum2;
    struct v4l2_frmivalenum frmivalenum;
    int j = 0;

    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        frmsizeenum2.index = 0;
        frmsizeenum2.pixel_format = fmtdesc.pixelformat;

        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsizeenum2) == 0) {
            if (frmsizeenum2.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
                frmivalenum.index = 0;
                frmivalenum.pixel_format = fmtdesc.pixelformat;
                frmivalenum.width = frmsizeenum2.discrete.width;
                frmivalenum.height = frmsizeenum2.discrete.height;

                if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmivalenum) == 0) {
                    capabilities->supported_frame_rates++;
                    if (capabilities->supported_frame_rates >= MAX_FRAME_RATES) {
                        fprintf(stderr, "Too many frame rates, limiting to %d\n", MAX_FRAME_RATES);
                        break;
                    }
                } else {
                    fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
                    break;
                }
            }
        } else {
            fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
            break;
        }
        fmtdesc.index++;
    }

    // Check for autofocus support
    struct v4l2_control ctrl;

    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) == 0) {
        if (ctrl.type == V4L2_CTRL_TYPE_BOOLEAN) {
            capabilities->autofocus_supported = 1;
        }
    } else {
        fprintf(stderr, "Error querying autofocus control: %s\n", strerror(errno));
    }

    return 0;
}

// Function to print camera capabilities
void print_camera_capabilities(const camera_capabilities_t *capabilities) {
    printf("Camera Capabilities:\n");
    printf("  Supported Resolutions: %u\n", capabilities->supported_resolutions);
    printf("  Supported Frame Rates: %u\n", capabilities->supported_frame_rates);
    printf("  Autofocus Supported: %s\n", capabilities->autofocus_supported ? "Yes" : "No");
}

int main() {
    if (!file_exists(DEVICE_NAME)) {
        fprintf(stderr, "Device %s does not exist\n", DEVICE_NAME);
        return 1;
    }

    int fd = open_camera(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    camera_capabilities_t capabilities;

    if (query_camera_capabilities(fd, &capabilities) == 0) {
        print_camera_capabilities(&capabilities);
    } else {
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

