#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo parameters
#define SERVO_CENTER_PULSE_WIDTH 1500
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_FREQUENCY 50 // Hz

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Function to set servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width)
{
    gpioServo(gpio, pulse_width);
}

// Function to handle button presses
void handle_button_presses()
{
    static int pan_position = SERVO_CENTER_PULSE_WIDTH;
    static int tilt_position = SERVO_CENTER_PULSE_WIDTH;
    static int up_pressed = 0;
    static int down_pressed = 0;
    static int left_pressed = 0;
    static int right_pressed = 0;

    if (gpioRead(UP_BUTTON_PIN) == 0 && !up_pressed)
    {
        pan_position += 10;
        up_pressed = 1;
    }
    else if (gpioRead(UP_BUTTON_PIN) == 1)
    {
        up_pressed = 0;
    }

    if (gpioRead(DOWN_BUTTON_PIN) == 0 && !down_pressed)
    {
        pan_position -= 10;
        down_pressed = 1;
    }
    else if (gpioRead(DOWN_BUTTON_PIN) == 1)
    {
        down_pressed = 0;
    }

    if (gpioRead(LEFT_BUTTON_PIN) == 0 && !left_pressed)
    {
        tilt_position += 10;
        left_pressed = 1;
    }
    else if (gpioRead(LEFT_BUTTON_PIN) == 1)
    {
        left_pressed = 0;
    }

    if (gpioRead(RIGHT_BUTTON_PIN) == 0 && !right_pressed)
    {
        tilt_position -= 10;
        right_pressed = 1;
    }
    else if (gpioRead(RIGHT_BUTTON_PIN) == 1)
    {
        right_pressed = 0;
    }

    // Clamp pulse widths
    if (pan_position < SERVO_MIN_PULSE_WIDTH)
    {
        pan_position = SERVO_MIN_PULSE_WIDTH;
    }
    else if (pan_position > SERVO_MAX_PULSE_WIDTH)
    {
        pan_position = SERVO_MAX_PULSE_WIDTH;
    }

    if (tilt_position < SERVO_MIN_PULSE_WIDTH)
    {
        tilt_position = SERVO_MIN_PULSE_WIDTH;
    }
    else if (tilt_position > SERVO_MAX_PULSE_WIDTH)
    {
        tilt_position = SERVO_MAX_PULSE_WIDTH;
    }

    set_servo_pulse_width(PAN_SERVO_PIN, pan_position);
    set_servo_pulse_width(TILT_SERVO_PIN, tilt_position);
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Print startup message
    printf("Pan-Tilt Camera Control\n");
    printf("Pan Servo: GPIO %d\n", PAN_SERVO_PIN);
    printf("Tilt Servo: GPIO %d\n", TILT_SERVO_PIN);
    printf("Up Button: GPIO %d\n", UP_BUTTON_PIN);
    printf("Down Button: GPIO %d\n", DOWN_BUTTON_PIN);
    printf("Left Button: GPIO %d\n", LEFT_BUTTON_PIN);
    printf("Right Button: GPIO %d\n", RIGHT_BUTTON_PIN);
    printf("Center Position: %d microseconds\n", SERVO_CENTER_PULSE_WIDTH);
    printf("Frequency: %d Hz\n", SERVO_FREQUENCY);
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        handle_button_presses();
        gpioDelay(50); // 50 ms delay
    }

    // Clean up
    set_servo_pulse_width(PAN_SERVO_PIN, 0);
    set_servo_pulse_width(TILT_SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

