// Global Variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static int i2c_fd = -1;
static struct bmp280_calib_data bmp280_calib;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_gpio(void);
