// GPIO Initialization
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        perror("Error getting PIR GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        perror("Error requesting PIR GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
