// BMP280 Sensor Reading
int read_bmp280_sensor(float *temperature, float *pressure) {
    unsigned char data[6];
    int32_t raw_temperature, raw_pressure;
    int32_t var1, var2, T;
    double p;

    // Read calibration data
    if (read_bmp280_calibration(i2c_fd, &bmp280_calib) != 0) {
        log_event("Error reading BMP280 calibration data");
        return -1;
    }

    // Read raw temperature and pressure data
    if (read_i2c_block_data(i2c_fd, 0xFA, 6, data) != 0) {
        log_event("Error reading BMP280 data");
        return -1;
    }

    raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    // Temperature compensation
    var1 = ((((raw_temperature >> 3) - ((int32_t)bmp280_calib.dig_T1 << 1))) * ((int32_t)bmp280_calib.dig_T2)) >> 11;
    var2 = (((((raw_temperature >> 4) - ((int32_t)bmp280_calib.dig_T1)) * ((raw_temperature >> 4) - ((int32_t)bmp280_calib.dig_T1))) >> 12) * ((int32_t)bmp280_calib.dig_T3)) >> 14;
    T = var1 + var2;
    *temperature = (T * 5 + 128) >> 8;
    *temperature = *temperature / 100.0;

    // Pressure compensation
    var1 = (((int32_t)T) >> 1) - (int32_t)64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)bmp280_calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)bmp280_calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)bmp280_calib.dig_P4) << 16);
    var1 = (((bmp280_calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)bmp280_calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = (((32768 + var1)) * ((int32_t)bmp280_calib.dig_P1)) >> 15;
    if (var1 == 0) {
        *pressure = 0;
    } else {
        p = (((1048576 - raw_pressure) - (var2 >> 12))) * 3125;
        if (p < 0) {
            p = (p << 1) / var1;
        } else {
            p = (p / var1) * 2;
        }
        var1 = (((int32_t)bmp280_calib.dig_P9) * ((int32_t)(p / 8192) * ((int32_t)(p / 8192)))) >> 19;
        var2 = (((int32_t)bmp280_calib.dig_P8) * ((int32_t)(p / 8192))) >> 13;
        p = p + ((var1 + var2 + bmp280_calib.dig_P7) / 16);
        *pressure = p;
    }

    return 0;
}

// BMP280 Calibration Data Reading
int read_bmp280_calibration(int fd, struct bmp280_calib_data *calib) {
    unsigned char data[24];
    if (read_i2c_block_data(fd, 0x88, 24, data) != 0) {
        return -1;
    }

    calib->dig_T1 = (data[1] << 8) | data[0];
    calib->dig_T2 = (data[3] << 8) | data[2];
    calib->dig_T3 = (data[5] << 8) | data[4];
    calib->dig_P1 = (data[7] << 8) | data[6];
    calib->dig_P2 = (data[9] << 8) | data[8];
    calib->dig_P3 = (data[11] << 8) | data[10];
    calib->dig_P4 = (data[13] << 8) | data[12];
    calib->dig_P5 = (data[15] << 8) | data[14];
    calib->dig_P6 = (data[17] << 8) | data[16];
    calib->dig_P7 = (data[19] << 8) | data[18];
    calib->dig_P8 = (data[21] << 8) | data[20];
    calib->dig_P9 = (data[23] << 8) | data[22];

    return 0;
}

// I2C Helper Functions
int read_i2c_block_data(int fd, unsigned char reg, unsigned char len, unsigned char *data) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

