    int ret = system(command);
    if (ret == -1) {
        perror("Error executing libcamera-still");
        return -1;
    }
    return WEXITSTATUS(ret);
}

// Timestamped Filename Generation
char *generate_filename(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char *)malloc(64 * sizeof(char));
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 64, "%Y%m%d_%H%M%S", timeinfo);
    strcat(filename, "_mmm.jpg");

    return filename;
}

// Logging
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
