#include <unistd.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define NUM_BUFFERS 1

struct buffer {
    void   *start;
    size_t  length;
};

static volatile int keep_running = 1;
static int fd = -1;
static struct buffer *buffers = NULL;

void signal_handler(int sig) {
    printf("Signal received, stopping...\n");
    keep_running = 0;
}

int xioctl(int fd, int request, void *arg) {
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *yuyv_frame = NULL;
    unsigned char *cropped_frame = NULL;
    size_t frame_size = WIDTH * HEIGHT * 2; // YUYV format
    size_t crop_size = CROP_WIDTH * CROP_HEIGHT * 2;
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", VIDEO_DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            perror("mmap");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Queue the buffers
    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for a frame using select()
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        perror("select");
        close(fd);
        return EXIT_FAILURE;
    }

    if (0 == r) {
        fprintf(stderr, "select timeout\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify the captured frame
    if (WIDTH != fmt.fmt.pix.width || HEIGHT != fmt.fmt.pix.height || V4L2_PIX_FMT_YUYV != fmt.fmt.pix.pixelformat) {
        fprintf(stderr, "Error: Captured frame does not match requested format.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the frame
    yuyv_frame = (unsigned char *)buffers[buf.index].start;
    cropped_frame = (unsigned char *)malloc(crop_size);
    if (!cropped_frame) {
        perror("Failed to allocate memory for cropped frame");
        close(fd);
        return EXIT_FAILURE;
    }

    // Crop the frame
    for (int y = CROP_Y; y < CROP_Y + CROP_HEIGHT; y++) {
        for (int x = CROP_X; x < CROP_X + CROP_WIDTH; x++) {
            // Calculate the index in the original frame
            int frame_x = x - CROP_X;
            int frame_y = y - CROP_Y;
            int frame_index = frame_y * WIDTH * 2 + frame_x * 2;

            // Copy the YUYV macroblock
            cropped_frame[y - CROP_Y * 2 * 2 + x - CROP_X * 2 * 2 * 0] = yuyv_frame[frame_index + 0];
            cropped_frame[y - CROP_Y * 2 * 2 + x - CROP_X * 2 * 2 * 1] = yuyv_frame[frame_index + 1];
            cropped_frame[y - CROP_Y * 2 * 2 + x - CROP_X * 2 * 2 * 2] = yuyv_frame[frame_index + 2];
            cropped_frame[y - CROP_Y * 2 * 2 + x - CROP_X * 2 * 2 * 3] = yuyv_frame[frame_index + 3];
        }
    }

    // Save the cropped frame to a file
    FILE *fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("Failed to open cropped.yuv for writing");
        free(cropped_frame);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t bytes_written = fwrite(cropped_frame, 1, crop_size, fp);
    if (bytes_written != crop_size) {
        fprintf(stderr, "Error writing to cropped.yuv: wrote %zu bytes, expected %zu\n", bytes_written, crop_size);
        fclose(fp);
        free(cropped_frame);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(fp);
    free(cropped_frame);

    // Requeue the buffer
    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        perror("VIDIOC_QBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffer
    for (i = 0; i < req.count; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    free(buffers);

    // Close the device
    close(fd);

    printf("Cropped frame saved as cropped.yuv\n");

    return EXIT_SUCCESS;
}

