#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define neutral angle (90 degrees)
#define NEUTRAL_ANGLE 90

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Define angle increment (5 degrees)
#define ANGLE_INCREMENT 5

// Global variables to store pan and tilt angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int set_pan_angle(int angle);
int set_tilt_angle(int angle);
int get_pan_angle();
int get_tilt_angle();
void handle_input();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Setting servos to neutral position and exiting.\n");
        set_pan_angle(NEUTRAL_ANGLE);
        set_tilt_angle(NEUTRAL_ANGLE);
        gpioTerminate();
        exit(0);
    }
}

// Function to set the pan angle
int set_pan_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180).\n");
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(((float)angle / 180.0) * 2000.0); // 500us - 2500us

    // Set PWM pulse width
    gpioPWM(PAN_GPIO, pulse_width);

    // Update global pan angle
    pan_angle = angle;

    return 0;
}

// Function to set the tilt angle
int set_tilt_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180).\n");
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(((float)angle / 180.0) * 2000.0); // 500us - 2500us

    // Set PWM pulse width
    gpioPWM(TILT_GPIO, pulse_width);

    // Update global tilt angle
    tilt_angle = angle;

    return 0;
}

// Function to get the pan angle
int get_pan_angle() {
    return pan_angle;
}

// Function to get the tilt angle
int get_tilt_angle() {
    return tilt_angle;
}

// Function to handle user input
void handle_input() {
    int input;

    // Read input from stdin
    input = getchar();

    // Handle arrow key input
    switch (input) {
        case 'a':
            // Move left
            pan_angle -= ANGLE_INCREMENT;
            if (pan_angle < 0) pan_angle = 0;
            set_pan_angle(pan_angle);
            break;
        case 'd':
            // Move right
            pan_angle += ANGLE_INCREMENT;
            if (pan_angle > 180) pan_angle = 180;
            set_pan_angle(pan_angle);
            break;
        case 'w':
            // Move up
            tilt_angle -= ANGLE_INCREMENT;
            if (tilt_angle < 0) tilt_angle = 0;
            set_tilt_angle(tilt_angle);
            break;
        case 's':
            // Move down
            tilt_angle += ANGLE_INCREMENT;
            if (tilt_angle > 180) tilt_angle = 180;
            set_tilt_angle(tilt_angle);
            break;
        case 'q':
            // Quit
            printf("Exiting.\n");
            set_pan_angle(NEUTRAL_ANGLE);
            set_tilt_angle(NEUTRAL_ANGLE);
            gpioTerminate();
            exit(0);
        default:
            // Invalid input
            fprintf(stderr, "Error: Invalid input. Use arrow keys (a/d/w/s) or 'q' to quit.\n");
            break;
    }

    // Delay to prevent excessive CPU usage
    gpioDelay(100);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Set initial pan and tilt angles
    set_pan_angle(NEUTRAL_ANGLE);
    set_tilt_angle(NEUTRAL_ANGLE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        handle_input();
    }

    // Terminate pigpio library (this will never be reached in the current loop)
    gpioTerminate();

    return 0;
}

