// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0f; // Default error value

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0f;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0f;
    } else {
        perror("Error reading temperature");
    }

    fclose(fp);
    return temp;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float usage = -1.0f; // Default error value

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0f;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        perror("Error reading CPU stats");
        fclose(fp);
        return -1.0f;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        perror("Error reading CPU stats");
        fclose(fp);
        return -1.0f;
    }

    fclose(fp);

    unsigned long long total_prev = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;

    unsigned long long idle_time = idle + iowait;
    unsigned long long total_time = total - idle_time;

    if (total_prev == 0) {
        return 0.0f; // Avoid division by zero
    }

    float diff = (float)(total_time - total_prev) / (float)(total_prev);
    usage = 100.0f * (1.0f - (float)idle_time / (float)total_time);

    return usage;
}

// Function to render a character to the SSD1306 buffer
void render_char(int x, int y, char c, unsigned char *buffer) {
    if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
    c -= 32; // Adjust index to font array

    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 8; j++) {
            if ((font[c][i] >> j) & 0x01) {
                int pixel_x = x + i;
                int pixel_y = y + j;
                if (pixel_x >= 0 && pixel_x < SCREEN_WIDTH && pixel_y >= 0 && pixel_y < SCREEN_HEIGHT) {
                    buffer[(pixel_y * SCREEN_WIDTH) + pixel_x] = 1; // Set pixel to 1
                }
            }
        }
    }
}

// Function to render a string to the SSD1306 buffer
void render_string(int x, int y, const char *str, unsigned char *buffer) {
    while (*str) {
        render_char(x, y, *str++, buffer);
        x += 6; // Character width + 1 pixel spacing
    }
}

// Function to clear the SSD1306 buffer
void clear_buffer(unsigned char *buffer) {
    memset(buffer, 0, sizeof(buffer));
}

// Function to initialize the SSD1306 display
int init_ssd1306() {
    // Initialization sequence (refer to SSD1306 datasheet)
    char init_commands[] = {
        0x00, // Command
        0xAE, // Display off
        0xD5, 0x80, // Set display clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Set multiplex ratio
        0xD3, 0x00, // Set display offset
        0x40, 0x00, // Set display start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode
        0xA1,        // Segment remap
        0xC8,        // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,        // Entire display ON/OFF
        0xA6,        // Normal/Inverse display
        0xAF         // Display on
    };

    for (int i = 0; i < sizeof(init_commands) / 2; i++) {
        char data[2] = {init_commands[2 * i], init_commands[2 * i + 1]};
        if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
            fprintf(stderr, "Error writing to I2C device during initialization\n");
            return -1;
        }
    }

    return 0;
}

// Function to display the buffer on the SSD1306
void display_ssd1306(unsigned char *buffer) {
    char data[SCREEN_WIDTH * (SCREEN_HEIGHT / 8) + 1];
    data[0] = 0x40; // Data command

    for (int i = 0; i < SCREEN_HEIGHT / 8; i++) {
        for (int j = 0; j < SCREEN_WIDTH; j++) {
            data[(i * SCREEN_WIDTH) + j + 1] = buffer[(i * SCREEN_WIDTH) + j];
        }
    }

    if (i2cWriteDevice(i2c_handle, data, SCREEN_WIDTH * (SCREEN_HEIGHT / 8) + 1) != 0) {
        fprintf(stderr, "Error writing to I2C device during display\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SSD1306_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SSD1306 display
    if (init_ssd1306() != 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned char buffer[SCREEN_WIDTH * (SCREEN_HEIGHT / 8)];

    while (!terminate) {
        // Read CPU temperature
        float temp = read_cpu_temp();
        char temp_str[20];
        if (temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: Error");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temp);
        }

        // Read CPU usage
        float usage = read_cpu_usage();
        char usage_str[20];
        if (usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: Error");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", usage);
        }

        // Clear the buffer
        clear_buffer(buffer);

        // Render the strings
        render_string(0, 0, temp_str, buffer);
        render_string(0, 16, usage_str, buffer);

        // Display the buffer
        display_ssd1306(buffer);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    clear_buffer(buffer);
    display_ssd1306(buffer);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

