#include <time.h>

// Define constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_WIDTH 16

// Global variables
volatile int pulse_count = 0;
int i2c_handle;
double total_volume = 0.0;
double current_flow_rate = 0.0;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to update the LCD display
void update_lcd(double flow_rate, double total_volume) {
    char buffer[32];
    int result;

    // Clear the LCD
    result = i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display command
    if (result < 0) {
        fprintf(stderr, "Error clearing LCD: %d\n", result);
        return;
    }
    gpioDelay(2000); // Wait for clear command to complete

    // Display flow rate
    snprintf(buffer, sizeof(buffer), "Flow: %.2f LPM", flow_rate);
    result = i2cWriteI2CBlockData(i2c_handle, 0x80, buffer, strlen(buffer));
    if (result < 0) {
        fprintf(stderr, "Error writing flow rate to LCD: %d\n", result);
        return;
    }

    // Display total volume
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    result = i2cWriteI2CBlockData(i2c_handle, 0xC0, buffer, strlen(buffer));
    if (result < 0) {
        fprintf(stderr, "Error writing total volume to LCD: %d\n", result);
        return;
    }

    gpioDelay(2000); // Wait for display to update
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt callback for rising edge detection
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate flow rate and total volume
        current_flow_rate = (double)pulse_count / PULSES_PER_LITER / (gpioTick() / 1000000.0) * 60.0; // Liters per minute
        total_volume += current_flow_rate / 60.0; // Add to total volume (liters)

        // Update LCD display every 10 seconds
        if (gpioTick() % 10000000 == 0) {
            update_lcd(current_flow_rate, total_volume);
        }

        // Print flow rate and total volume to console every 1 second
        printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", current_flow_rate, total_volume);
        fflush(stdout); // Ensure output is displayed immediately

        // Reset pulse count
        pulse_count = 0;

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

