#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Define constants
#define FLOW_SENSOR_GPIO 17
#define CALIBRATION_FACTOR 7.5
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_WIDTH 16

// Global variables
volatile int pulse_count = 0;
int i2c_fd;
int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
int lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void display_flow_rate(float flow_rate);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses) {
    return (float)pulses / CALIBRATION_FACTOR * 60.0;
}

// Function to initialize the LCD1602 display
int lcd_init() {
    i2c_fd = wiringPiI2CSetup(I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C communication.\n");
        return -1;
    }

    // Initialize LCD (example initialization sequence, may vary)
    lcd_byte(0x33, 0); // Initialize
    lcd_byte(0x32, 0); // Initialize
    lcd_byte(0x06, 0); // Cursor move direction
    lcd_byte(0x0C, 0); // Turn on display, cursor, blink
    lcd_byte(0x28, 0); // Data length, number of lines, font size
    lcd_byte(0x01, 0); // Clear display
    gpioDelay(500);     // Delay for clear display to work

    return 0;
}

// Function to send a byte to the LCD
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | 0x08;  // Enable bit high
    int bits_low = mode | ((bits << 4) & 0xF0) | 0x08; // Enable bit low

    // High bits
    wiringPiI2CWrite(i2c_fd, bits_high);
    wiringPiI2CWrite(i2c_fd, bits_high | 0x04); // Enable pulse
    gpioDelay(1); // Delay for pulse
    wiringPiI2CWrite(i2c_fd, bits_high & ~0x04); // Disable pulse
    gpioDelay(1);

    // Low bits
    wiringPiI2CWrite(i2c_fd, bits_low);
    wiringPiI2CWrite(i2c_fd, bits_low | 0x04); // Enable pulse
    gpioDelay(1); // Delay for pulse
    wiringPiI2CWrite(i2c_fd, bits_low & ~0x04); // Disable pulse
    gpioDelay(1);
}

// Function to display a string on the LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, 0);
    }
}

// Function to clear the LCD display
void lcd_clear() {
    lcd_byte(0x01, 0); // Clear display command
    gpioDelay(500);     // Delay for clear display to work
}

// Function to display the flow rate on the LCD
void display_flow_rate(float flow_rate) {
    char buffer[17]; // Buffer to hold the formatted string

    lcd_clear();
    lcd_string("Flow Rate: ");
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt service routine for rising edge detection
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL);

    // Initialize the LCD display
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Measure flow rate over a 1-second interval
        pulse_count = 0;
        gpioDelay(1000); // Wait for 1 second

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Log flow rate to console
        printf("Flow Rate: %.2f L/min\n", flow_rate);
    }

    // Clean up resources before exiting
    gpioTerminate();
    lcd_clear(); // Clear LCD before exiting
    return 0;
}

