#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"

// Define row and column GPIO line numbers (BCM numbering)
const int rows[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int cols[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Number of rows and columns in the matrix
const int NUM_ROWS = 8;
const int NUM_COLS = 8;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int init_gpio();

// Function to set the state of a row
int set_row(int row_num, int state);

// Function to set the state of a column
int set_col(int col_num, int state);

// Function to clear the matrix
int clear_matrix();

// Function to display a wave pattern
int display_wave(int direction);

// Function to release GPIO lines
void release_gpio();

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Display left-to-right wave
        if (display_wave(1) != 0) {
            fprintf(stderr, "Failed to display left-to-right wave.\n");
        }

        // Display right-to-left wave
        if (display_wave(0) != 0) {
            fprintf(stderr, "Failed to display right-to-left wave.\n");
        }

        // Delay for 1 second
        sleep(1);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    release_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int init_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    // Get row lines
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, rows[i]);
        if (!row_lines[i]) {
            perror("gpiod_chip_get_line (row)");
            release_gpio();
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led-matrix", 0) < 0) {
            perror("gpiod_line_request_output (row)");
            release_gpio();
            return -1;
        }
    }

    // Get column lines
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, cols[i]);
        if (!col_lines[i]) {
            perror("gpiod_chip_get_line (col)");
            release_gpio();
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led-matrix", 0) < 0) {
            perror("gpiod_line_request_output (col)");
            release_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to set the state of a row
int set_row(int row_num, int state) {
    if (row_num < 0 || row_num >= NUM_ROWS) {
        fprintf(stderr, "Invalid row number: %d\n", row_num);
        return -1;
    }
    if (gpiod_line_set_value(row_lines[row_num], state) < 0) {
        perror("gpiod_line_set_value (row)");
        return -1;
    }
    return 0;
}

// Function to set the state of a column
int set_col(int col_num, int state) {
    if (col_num < 0 || col_num >= NUM_COLS) {
        fprintf(stderr, "Invalid column number: %d\n", col_num);
        return -1;
    }
    if (gpiod_line_set_value(col_lines[col_num], state) < 0) {
        perror("gpiod_line_set_value (col)");
        return -1;
    }
    return 0;
}

// Function to clear the matrix
int clear_matrix() {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (set_row(i, 0) != 0) {
            return -1;
        }
    }
    return 0;
}

// Function to display a wave pattern
int display_wave(int direction) {
    int offset = 0;
    int step = (direction == 1) ? 1 : -1;

    for (int i = 0; i < 64; i++) {
        // Clear the matrix
        if (clear_matrix() != 0) {
            return -1;
        }

        // Set the column based on the wave pattern
        if (set_col((i + offset) % NUM_COLS, 1) != 0) {
            return -1;
        }

        // Delay for 800 microseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 800000; // 800 microseconds
        nanosleep(&delay, NULL);

        // Update the offset for the next frame
        offset += step;
    }

    return 0;
}

// Function to release GPIO lines
void release_gpio() {
    // Release column lines
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Release row lines
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

