#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define ROW1 2
#define ROW2 3
#define ROW3 4
#define ROW4 17
#define ROW5 27
#define ROW6 22
#define ROW7 10
#define ROW8 9

#define COL1 14
#define COL2 15
#define COL3 18
#define COL4 23
#define COL5 24
#define COL6 25
#define COL7 8
#define COL8 7

// Define the number of rows and columns
#define NUM_ROWS 8
#define NUM_COLS 8

// Define the delay between columns in milliseconds
#define DELAY_MS 150

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_row(int row, int value);
void set_column(int col, int value);
void clear_matrix();
void display_column(int col, int value);
void wave_animation();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    int i;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request row lines as output
    for (i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW1 + i);
        if (!row_lines[i]) {
            perror("Error getting row line");
            return -1;
        }

        ret = gpiod_line_request_output(row_lines[i], "led_matrix", 0);
        if (ret < 0) {
            perror("Error requesting row line as output");
            return -1;
        }
    }

    // Request column lines as output
    for (i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL1 + i);
        if (!col_lines[i]) {
            perror("Error getting column line");
            return -1;
        }

        ret = gpiod_line_request_output(col_lines[i], "led_matrix", 0);
        if (ret < 0) {
            perror("Error requesting column line as output");
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    int i;
    int ret;

    // Release row lines
    for (i = 0; i < NUM_ROWS; i++) {
        ret = gpiod_line_release(row_lines[i]);
        if (ret < 0) {
            perror("Error releasing row line");
        }
    }

    // Release column lines
    for (i = 0; i < NUM_COLS; i++) {
        ret = gpiod_line_release(col_lines[i]);
        if (ret < 0) {
            perror("Error releasing column line");
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to set the value of a row
void set_row(int row, int value) {
    if (row < 0 || row >= NUM_ROWS) {
        fprintf(stderr, "Error: Invalid row number: %d\n", row);
        return;
    }

    ret = gpiod_line_set_value(row_lines[row], value);
    if (ret < 0) {
        perror("Error setting row value");
    }
}

// Function to set the value of a column
void set_column(int col, int value) {
    if (col < 0 || col >= NUM_COLS) {
        fprintf(stderr, "Error: Invalid column number: %d\n", col);
        return;
    }

    ret = gpiod_line_set_value(col_lines[col], value);
    if (ret < 0) {
        perror("Error setting column value");
    }
}

// Function to clear the LED matrix
void clear_matrix() {
    int i;
    for (i = 0; i < NUM_ROWS; i++) {
        set_row(i, 0);
    }
}

// Function to display a single column on the matrix
void display_column(int col, int value) {
    int i;
    for (i = 0; i < NUM_ROWS; i++) {
        set_row(i, value);
    }
    set_column(col, value);
    usleep(DELAY_MS * 1000); // Delay in microseconds
}

