#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// VL53L3CX register addresses (example, adjust based on datasheet)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_RATE 0x001E
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM 0x001A

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t range_status;
    uint16_t spad_nb;
    uint16_t peak_signal_rate;
    uint16_t distance_mm;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L3CX sensor
int init_vl53l3cx() {
    // Placeholder for VL53L3CX initialization sequence
    // Replace with actual initialization code based on the datasheet
    // This example just checks the model ID
    uint8_t model_id;
    int result = i2cReadByteData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID);
    if (result < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", result);
        return -1;
    }
    model_id = (uint8_t)result;

    if (model_id != 0xE1) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    printf("VL53L3CX sensor initialized successfully. Model ID: 0x%02X\n", model_id);
    return 0;
}

// Function to read distance measurements from the VL53L3CX sensor
int read_distance(sensor_data_t *data) {
    uint8_t buffer[8]; // Adjust size based on register reads needed
    int result;

    // Read range status
    result = i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_RANGE_STATUS, (char*)buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }
    data->range_status = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);

    // Read SPAD number
    result = i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_SPAD_NB, (char*)buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading SPAD number: %d\n", result);
        return -1;
    }
    data->spad_nb = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);

    // Read peak signal rate
    result = i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_PEAK_SIGNAL_RATE, (char*)buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading peak signal rate: %d\n", result);
        return -1;
    }
    data->peak_signal_rate = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);

    // Read distance in mm
    result = i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM, (char*)buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }
    data->distance_mm = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);

    return 0;
}

