#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor I2C address and register address
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (milliseconds)
#define SAMPLING_INTERVAL 100

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int write_register(int handle, int reg);
int read_register(int handle, int reg);
int read_distance(int handle);
void log_data(FILE *fp, int distance);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    const char *log_file_name;
    int sampling_interval_ms;
} config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write to a register
int write_register(int handle, int reg) {
    int result = i2cWriteByteData(handle, reg, 0); // Send 0 as data
    if (result < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read from a register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Read distance from the sensor
int read_distance(int handle) {
    int distance_low, distance_high;

    distance_low = read_register(handle, DISTANCE_REG);
    if (distance_low < 0) {
        return -1;
    }

    distance_high = read_register(handle, DISTANCE_REG + 1);
    if (distance_high < 0) {
        return -1;
    }

    return (distance_high << 8) | distance_low;
}

// Log data to file
void log_data(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance == -1) {
        fprintf(fp, "%s,-1\n", timestamp);
    } else {
        fprintf(fp, "%s,%d\n", timestamp, distance);
    }
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75031_ADDR,
        .log_file_name = "depth_log.csv",
        .sampling_interval_ms = SAMPLING_INTERVAL
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (1) {
        int distance = read_distance(i2c_handle);
        log_data(log_file, distance);
        gpioDelay(config.sampling_interval_ms * 1000); // pigpioDelay takes microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper cleanup in case the loop were to terminate.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

