#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18
#define PROX_REG 0x0A
#define ALS_REG 0x0C
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145(uint16_t *prox, uint16_t *als);
void log_data(uint16_t prox, uint16_t als);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1145 sensor
int init_si1145() {
    int result;
    uint8_t part_id;

    // Read PART ID register
    result = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading PART ID register: %s\n", strerror(errno));
        return -1;
    }
    part_id = (uint8_t)result;

    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID (0x%02X, expected 0x45)\n", part_id);
        return -1;
    }

    // Reset the sensor (example command, adjust as needed)
    result = i2cWriteByteData(i2c_handle, COMMAND_REG, 0x00); // Example reset command
    if (result < 0) {
        fprintf(stderr, "Error writing to command register (reset): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rates (example configuration, adjust as needed)
    result = i2cWriteByteData(i2c_handle, COMMAND_REG, 0x07); // Example config command
    if (result < 0) {
        fprintf(stderr, "Error writing to command register (config): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_si1145(uint16_t *prox, uint16_t *als) {
    int result;

    // Read proximity data
    result = i2cReadWordData(i2c_handle, PROX_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    *prox = (uint16_t)result;

    // Read ambient light data
    result = i2cReadWordData(i2c_handle, ALS_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ambient light data: %s\n", strerror(errno));
        return -1;
    }
    *als = (uint16_t)result;

    return 0;
}

// Function to log data to a file with ISO-8601 timestamp
void log_data(uint16_t prox, uint16_t als) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, prox, als);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    uint16_t prox, als;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_si1145(&prox, &als);
        if (result == 0) {
            // Log data
            log_data(prox, als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

