#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO lines
#define SENSOR_PIN 4
#define LED_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip4"

// Global variables for signal handling
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
int control_led(int state);
int log_event(void);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Signal received, exiting gracefully.\n");
        keep_running = 0;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request sensor line for input
    ret = gpiod_line_request_input(sensor_line, "proximity_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor line %d as input: %s\n", SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line for output
    ret = gpiod_line_request_output(led_line, "proximity_led", 0); // Initial state LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Control LED state
int control_led(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED state: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(void) {
    FILE *fp;
    time_t rawtime;
    struct tm *info;
    char buffer[80];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", info);

    fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s Object detected\n", buffer);
    fclose(fp);
    return 0;
}

// Cleanup GPIO resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int sensor_value;
    int led_state = 0; // 0 = LOW, 1 = HIGH
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (sensor_value == 0) { // Object detected (LOW)
            if (led_state == 0) { // Blink LED
                if (control_led(1) < 0) {
                    fprintf(stderr, "Error controlling LED, exiting.\n");
                    break;
                }
                nanosleep(&sleep_time, NULL);
                if (control_led(0) < 0) {
                    fprintf(stderr, "Error controlling LED, exiting.\n");
                    break;
                }
                led_state = 1; // Ensure LED is off after blink
            }
            if (log_event() < 0) {
                fprintf(stderr, "Error logging event, exiting.\n");
                break;
            }
        } else {
            led_state = 0; // Reset LED state if no object detected
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Proximity sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

