#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x07
#define SI1145_CH_LIST 0x4F
#define SI1145_MEAS_RATE0 0x08
#define SI1145_MEAS_RATE1 0x09
#define SI1145_COMMAND 0x30
#define SI1145_PS1_DATA_L 0x18
#define SI1145_PS1_DATA_H 0x19
#define SI1145_ALS_VIS_DATA_L 0x22
#define SI1145_ALS_VIS_DATA_H 0x23

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    int status;

    // Verify PART_ID
    status = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", status);
        return -1;
    }

    // Unlock the sensor
    status = i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Configure measurement rates
    status = i2cWriteByteData(i2c_handle, SI1145_MEAS_RATE0, 0x08); // PS1 every 10ms
    if (status < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, SI1145_MEAS_RATE1, 0x08); // ALS every 10ms
    if (status < 0) {
        fprintf(stderr, "Error writing MEAS_RATE1: %d\n", status);
        return -1;
    }

    // Enable PS1 and ALS_VIS channels
    status = i2cWriteByteData(i2c_handle, SI1145_CH_LIST, 0x77); // PS1 + ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CH_LIST: %d\n", status);
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int status;
    uint8_t buffer[2];

    // Trigger measurement
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, 0x06); // ALS_FORCE
    if (status < 0) {
        fprintf(stderr, "Error writing COMMAND (ALS_FORCE): %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait for measurement

    // Read proximity data
    status = i2cReadI2CBlockData(i2c_handle, SI1145_PS1_DATA_L, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }
    *proximity = (buffer[1] << 8) | buffer[0];

    // Trigger measurement
    status = i2cWriteByteData(i2c_handle, SI1145_COMMAND, 0x07); // PS_FORCE
    if (status < 0) {
        fprintf(stderr, "Error writing COMMAND (PS_FORCE): %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait for measurement

    // Read ambient light data
    status = i2cReadI2CBlockData(i2c_handle, SI1145_ALS_VIS_DATA_L, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    *ambient_light = (buffer[1] << 8) | buffer[0];

    return 0;
}

// Log data to a CSV file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main() {
    int proximity, ambient_light;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            // Log data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

