#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define WATERING_THRESHOLD 15.0 // cm
#define TIMEOUT_US 30000        // 30ms timeout
#define TRIGGER_PULSE_US 10     // 10us trigger pulse

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio(gpio_config_t *config);
void trigger_pulse(int trigger_pin);
double measure_pulse_width(int echo_pin);
double calculate_distance(double pulse_width);
void log_data(double distance, const char *message);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(config->trigger_pin, 0);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(trigger_pin, 0);
}

// Measure the pulse width on the echo pin
double measure_pulse_width(int echo_pin) {
    uint32_t start_tick, end_tick, diff;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(echo_pin) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(echo_pin) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return (double)diff;
}

// Calculate distance in centimeters
double calculate_distance(double pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Log data to file
void log_data(double distance, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm, Message: %s\n", timestamp, distance, message);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    gpio_config_t gpio_config = {TRIGGER_PIN, ECHO_PIN};

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(&gpio_config) != 0) {
        fclose(log_file);
        return 1;
    }

    printf("Plant Watering Reminder System started.\n");

    while (running) {
        // Trigger the sensor
        trigger_pulse(gpio_config.trigger_pin);

        // Measure the pulse width
        double pulse_width = measure_pulse_width(gpio_config.echo_pin);

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Log the data
        if (pulse_width > 0) {
            char message[100];
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                if (distance < WATERING_THRESHOLD) {
                    snprintf(message, sizeof(message), "Time to water the plant!");
                } else {
                    snprintf(message, sizeof(message), "Plant is at a safe distance.");
                }
                log_data(distance, message);
            } else {
                snprintf(message, sizeof(message), "Invalid distance reading: %.2f cm", distance);
                log_data(distance, message);
            }
        } else {
            log_data(-1.0, "Sensor absent or error");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

