#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// APDS-9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS-9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint8_t proximity;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the APDS-9960 sensor
int apds9960_init() {
    int retries = 3;
    while (retries > 0) {
        // Verify sensor ID
        int id = i2cReadByteData(i2c_handle, APDS9960_ID);
        if (id < 0) {
            fprintf(stderr, "Error reading sensor ID: %d\n", id);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0); // Re-open I2C bus
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000); // Wait 100ms before retry
            retries--;
            continue;
        }
        if (id != 0xAB) {
            fprintf(stderr, "Incorrect sensor ID: 0x%X\n", id);
            return -1;
        }

        // Configure sensor registers
        if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
            fprintf(stderr, "Error writing to ENABLE register: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }
        if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
            fprintf(stderr, "Error writing to ATIME register: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }
        if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
            fprintf(stderr, "Error writing to WTIME register: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }
        if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
            fprintf(stderr, "Error writing to PPULSE register: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }
        if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
            fprintf(stderr, "Error writing to CONTROL register: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }
        if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
            fprintf(stderr, "Error writing to CONFIG2 register: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "APDS9960 initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int retries = 3;
    while (retries > 0) {
        data->red = i2cReadWordData(i2c_handle, APDS9960_CDATAL);
        data->red |= (i2cReadWordData(i2c_handle, APDS9960_CDATAH) << 8);
        data->green = i2cReadWordData(i2c_handle, APDS9960_GDATAL);
        data->green |= (i2cReadWordData(i2c_handle, APDS9960_GDATAH) << 8);
        data->blue = i2cReadWordData(i2c_handle, APDS9960_RDATAL);
        data->blue |= (i2cReadWordData(i2c_handle, APDS9960_RDATAH) << 8);
        data->proximity = i2cReadByteData(i2c_handle, APDS9960_PDATA);

        if (data->red < 0 || data->green < 0 || data->blue < 0 || data->proximity < 0) {
            fprintf(stderr, "Error reading sensor data: %d\n", i2c_handle);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                return -1;
            }
            gpioDelay(100000);
            retries--;
            continue;
        }

        return 0; // Data read successfully
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Data read failed
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.red, data.green, data.blue, data.proximity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (apds9960_init() != 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Check proximity threshold
            if (sensor_data.proximity > PROXIMITY_THRESHOLD) {
                // Log the data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // Delay for 100ms
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

