volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c(int handle, int reg, int val);
int read_i2c(int handle, int reg, uint16_t *val);
uint16_t trigger_measurement(int handle);
uint16_t read_distance(int handle);
char* get_timestamp();
