int read_i2c(int handle, int reg, uint16_t *val) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    *val = (uint16_t)result;
    return 0;
}

