#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 20 // cm
#define MEASUREMENT_INTERVAL 100 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void control_led(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg1;
    uint8_t config_reg2;
} sensor_config_t;

// Initialize the sensor configuration
sensor_config_t sensor_config = {
    .config_reg1 = 0x01, // Example configuration value
    .config_reg2 = 0x02
};

int main() {
    uint16_t distance;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance from the sensor
        if (read_distance(&distance) == 0) {
            // Log the distance
            log_distance(distance);

            // Control the LED based on distance
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying.\n");
        }

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the pigpio library, I2C bus, and GPIO pin
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read distance from the ICU-20201 sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    // Write the register address to read from (example: 0x00)
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Example register address
    if (result < 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return 1;
    }

    // Read two bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return 1;
    }

    // Combine the two bytes into a 16-bit distance value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Log the distance to a file with an ISO-8601 timestamp
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format the timestamp in ISO-8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write the timestamp and distance to the log file
    fprintf(log_file, "%s, %u cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control the LED based on the distance
void control_led(uint16_t distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    // Close I2C bus
    i2cClose(i2c_handle);

    // Turn off LED
    gpioWrite(GPIO_LED, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

