#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
int log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, PROXIMITY_REG);
        if (result >= 0) {
            *proximity = (uint16_t)result;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retry
            continue;
        }

        result = i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REG);
        if (result >= 0) {
            *ambient_light = (uint16_t)result;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retry
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to file
int log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

