#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_REG 0x00 // Example register, adjust as needed
#define DISTANCE_DATA_LEN 2 // Example length, adjust as needed
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100 // mm
#define LOG_FILE "tof_log.txt"

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int verify_sensor();
int read_distance(uint16_t *distance);
void log_data(uint16_t distance);
void control_led(uint16_t distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        return -1;
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor WHO_AM_I register
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }
    printf("WHO_AM_I value: 0x%02X (OK)\n", who_am_i);
    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char buffer[DISTANCE_DATA_LEN];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, DISTANCE_DATA_LEN);
    if (bytes_read != DISTANCE_DATA_LEN) {
        fprintf(stderr, "Error reading distance data: %d\n", bytes_read);
        return -1;
    }

    // Convert the buffer to a uint16_t (assuming little-endian)
    *distance = (uint16_t)((buffer[1] << 8) | buffer[0]);

    return 0;
}

