        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Validate header function
int validate_header(const uint8_t *data) {
    if (data[0] != 0x50) {
        fprintf(stderr, "Invalid header: 0x%02X\n", data[0]);
        return -1;
    }
    return 0;
}

// Parse distance function
uint16_t parse_distance(const uint8_t *data) {
    return (uint16_t)((((uint16_t)data[11]) << 8) | ((uint16_t)data[12]));
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        i2c_close(i2c_fd);
        return 1;
    }

    printf("I2C bus opened successfully.\n");

    // Main loop
    while (program_running) {
        uint8_t response_frame[RESPONSE_FRAME_SIZE];
        uint16_t distance;

        // Send the command frame
        if (i2c_write(i2c_fd, command_frame, COMMAND_FRAME_SIZE) < 0) {
            fprintf(stderr, "Error writing command frame, exiting.\n");
            break;
        }

        // Wait for 10 ms
        usleep(10000); // 10000 microseconds = 10 milliseconds

        // Read the response frame
        if (i2c_read(i2c_fd, response_frame, RESPONSE_FRAME_SIZE) < 0) {
            fprintf(stderr, "Error reading response frame, exiting.\n");
            break;
        }

        // Validate the header
        if (validate_header(response_frame) < 0) {
            fprintf(stderr, "Invalid header, exiting.\n");
            break;
        }

        // Parse the distance
        distance = parse_distance(response_frame);

        // Calculate the average distance
        uint16_t sum = 0;
        for (int i = 0; i < 10; i++) {
            // Send the command frame
            if (i2c_write(i2c_fd, command_frame, COMMAND_FRAME_SIZE) < 0) {
                fprintf(stderr, "Error writing command frame, exiting.\n");
                break;
            }

            // Wait for 10 ms
            usleep(10000); // 10000 microseconds = 10 milliseconds

            // Read the response frame
            if (i2c_read(i2c_fd, response_frame, RESPONSE_FRAME_SIZE) < 0) {
                fprintf(stderr, "Error reading response frame, exiting.\n");
                break;
            }

            // Validate the header
            if (validate_header(response_frame) < 0) {
                fprintf(stderr, "Invalid header, exiting.\n");
                break;
            }

            // Parse the distance
            sum += parse_distance(response_frame);
        }

        uint16_t average_distance = 0;
        if (sum >= 0) {
            average_distance = sum / 10;
        }

        // Log the event if the average distance is less than 1000 mm
        if (average_distance < 1000) {
            if (log_event(LOG_FILE, average_distance) < 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        // Delay for 100 ms
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close the I2C bus and log file
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program finished.\n");
    return 0;
}

