#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a byte from an I2C register
int read_byte(int handle, int reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Warning: I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to write a byte to an I2C register
int write_byte(int handle, int reg, int value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Warning: I2C write error (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to read the VL53L0X model ID
int read_model_id(int handle)
{
    int model_id = read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        return -1;
    }
    return model_id;
}

// Function to perform a single-shot ranging measurement
int single_shot_ranging(int handle)
{
    // Start a single measurement
    if (write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        return -1;
    }

    // Wait for the measurement to complete (polling RESULT_INTERRUPT_STATUS)
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        int status = read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            return -1;
        }
        if (status & 0x01) { // Bit 0 is set
            break;
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Warning: Timeout waiting for measurement to complete.\n");
        return -1;
    }

    // Read the distance (16-bit value, little-endian)
    int distance_high = read_byte(handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (distance_high < 0) {
        return -1;
    }
    int distance_low = read_byte(handle, VL53L0X_REG_RESULT_RANGE_STATUS + 1);
    if (distance_low < 0) {
        return -1;
    }

    int distance = (distance_low << 8) | distance_high;

    // Clear the interrupt
    if (write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    return distance;
}

// Function to format the timestamp and distance reading
void format_output(time_t timestamp, int distance)
{
    struct tm *timeinfo;
    char buffer[80];

    timeinfo = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Distance: %d mm\n", distance);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Verify sensor ID
    int model_id = read_model_id(i2c_handle);
    if (model_id < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X, expected 0xEE).\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get current timestamp
        time_t now = time(NULL);

        // Perform single-shot ranging
        int distance = single_shot_ranging(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Warning: Failed to read distance.\n");
        } else {
            // Format and print output
            format_output(now, distance);
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

