#define SI1182_CONFIG 0x18
#define SI1182_IRQ_STATUS 0x25
#define SI1182_PROXIMITY_LSB 0x2A
#define SI1182_PROXIMITY_MSB 0x2B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to initialize the Si1182 sensor
int init_si1182() {
    int status;

    // Enable proximity mode
    status = i2cWriteByteData(i2c_handle, SI1182_CONFIG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read proximity data from the Si1182 sensor
int read_proximity() {
    int lsb, msb, proximity;
    int status;

    // Read proximity LSB
    lsb = i2cReadByteData(i2c_handle, SI1182_PROXIMITY_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading proximity LSB: %d\n", lsb);
        return -1;
    }

    // Read proximity MSB
    msb = i2cReadByteData(i2c_handle, SI1182_PROXIMITY_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading proximity MSB: %d\n", msb);
        return -1;
    }

    // Combine LSB and MSB to get the 16-bit proximity value
    proximity = (msb << 8) | lsb;

    return proximity;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1182() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            printf("Proximity: %d\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

