#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define MM_PER_COUNT 0.125

int i2c_fd = -1; // Global file descriptor for signal handler

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX75030_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Verify device presence by reading a register
    uint8_t buf[1];
    buf[0] = DISTANCE_REG; // Register to read from
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (read(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (buf[0] != DISTANCE_REG) {
        fprintf(stderr, "Error: Device did not respond correctly. Expected 0x%02X, got 0x%02X\n", DISTANCE_REG, buf[0]);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    printf("I2C bus initialized successfully.\n");
    return 0;
}

// Function to read distance from the sensor
float read_distance() {
    uint8_t buf[2];
    int retries = 3;

    while (retries > 0) {
        buf[0] = DISTANCE_REG; // Register to read from
        if (write(i2c_fd, buf, 1) != 1) {
            fprintf(stderr, "I2C write error (address setup) during retry: %s\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read error during retry: %s\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        // Combine the two bytes into a 16-bit value (little-endian)
        int16_t raw_distance = (buf[1] << 8) | buf[0];
        return (float)raw_distance * MM_PER_COUNT;
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1.0; // Indicate error
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    while (1) {
        float distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %.2f mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }
        usleep(500000); // 500ms delay
    }

    return 0;
}

