#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 200000      // 200 ms timeout
#define MAX_RANGE_US 38000     // 38 ms max range

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
void signal_handler(int signal);
void log_distance(float distance);

// Function to send a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        // Falling edge
        end_tick = tick;
        echo_received = 2; // Indicate falling edge received
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to log distance with timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin (for protection)
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo pulse
        unsigned int start_time = gpioTick();
        while (echo_received != 2 && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (echo_received != 2) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            echo_received = 0; // Reset echo_received flag
            continue;           // Skip to the next iteration
        }

        // Calculate pulse duration
        unsigned int pulse_duration = end_tick - start_tick;

        // Validate pulse duration
        if (pulse_duration <= 0 || pulse_duration > MAX_RANGE_US) {
            fprintf(stderr, "Invalid pulse duration: %u us\n", pulse_duration);
            echo_received = 0; // Reset echo_received flag
            continue;           // Skip to the next iteration
        }

        // Calculate distance
        float distance = (float)pulse_duration * SPEED_OF_SOUND / 2.0;

        // Log the distance
        log_distance(distance);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 us
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

