#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_PIN 17
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define RANGE_BINS 64
#define DATA_FRAME_SIZE 136 // 8 (header) + 128 (data)
#define LED_ON_TIME 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    int gpio_pin;
    float range_resolution;
    float distance_threshold;
    int range_bins;
    int data_frame_size;
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int size);
int validate_header(const unsigned char *buffer, int size);
int parse_range_profile(const unsigned char *buffer, int size, int *range_profile);
float calculate_distance(int range_bin);
int detect_intrusion(float distance, float threshold);
int control_led(int gpio_pin, int on);
int log_intrusion(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, int size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return 0; // Timeout
    }
    return (int)bytes_read;
}

// Validate header
int validate_header(const unsigned char *buffer, int size) {
    if (size != 8) {
        fprintf(stderr, "Invalid header size: %d\n", size);
        return 0;
    }

    unsigned char expected_header[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    for (int i = 0; i < 8; i++) {
        if (buffer[i] != expected_header[i]) {
            fprintf(stderr, "Invalid header byte %d: expected 0x%02x, got 0x%02x\n", i, expected_header[i], buffer[i]);
            return 0;
        }
    }
    return 1;
}

// Parse range profile data
int parse_range_profile(const unsigned char *buffer, int size, int *range_profile) {
    if (size != 128) {
        fprintf(stderr, "Invalid range profile size: %d\n", size);
        return 0;
    }

    for (int i = 0; i < RANGE_BINS; i++) {
        range_profile[i] = (buffer[2 * i + 1] << 8) | buffer[2 * i];
    }
    return 1;
}

// Calculate distance from range bin
float calculate_distance(int range_bin) {
    return range_bin * RANGE_RESOLUTION;
}

// Detect intrusion
int detect_intrusion(float distance, float threshold) {
    return (distance <= threshold) ? 1 : 0;
}

// Control LED
int control_led(int gpio_pin, int on) {
    gpioWrite(gpio_pin, on);
    return 1;
}

// Log intrusion
int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 0;
    }

    fprintf(log_file, "%s,%.4f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 1;
}

int main() {
    // Configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .gpio_pin = GPIO_PIN,
        .range_resolution = RANGE_RESOLUTION,
        .distance_threshold = DISTANCE_THRESHOLD,
        .range_bins = RANGE_BINS,
        .data_frame_size = DATA_FRAME_SIZE
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.gpio_pin, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    unsigned char buffer[DATA_FRAME_SIZE];
    int range_profile[RANGE_BINS];
    int bytes_read;

    printf("Radar intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, buffer, config.data_frame_size);
        if (bytes_read > 0) {
            if (validate_header(buffer, bytes_read)) {
                if (parse_range_profile(buffer + 8, bytes_read - 8, range_profile)) {
                    for (int i = 0; i < RANGE_BINS; i++) {
                        float distance = calculate_distance(i);
                        if (detect_intrusion(distance, config.distance_threshold)) {
                            printf("Intrusion detected at distance: %.4f meters\n", distance);
                            control_led(config.gpio_pin, 1); // Turn LED on
                            log_intrusion(distance);
                            sleep(LED_ON_TIME);
                            control_led(config.gpio_pin, 0); // Turn LED off
                        }
                    }
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }
    }

    // Cleanup
    close(uart_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Radar intrusion detection system stopped.\n");
    return 0;
}

