// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_REG_HIGH 0x31
#define DISTANCE_REG_LOW 0x32
#define ALERT_GPIO 17
#define ALERT_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_distance(uint16_t *distance);
float convert_to_cm(uint16_t raw_distance);
int log_distance(float distance);
int trigger_alert(float distance);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int alert_gpio;
    float alert_threshold;
} sensor_config_t;

// Initialize the sensor and pigpio library
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure alert GPIO as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_HIGH, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw distance to centimeters (example conversion)
float convert_to_cm(uint16_t raw_distance) {
    // Replace with actual conversion formula from the datasheet
    return (float)raw_distance * 0.1; // Example: 0.1 cm per unit
}

// Log distance to file with ISO 8601 timestamp
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Trigger alert if distance is below threshold
int trigger_alert(float distance) {
    if (distance < ALERT_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Turn on alert
        printf("Alert triggered! Distance: %.2f cm\n", distance);
    } else {
        gpioWrite(ALERT_GPIO, 0); // Turn off alert
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Starting distance measurement...\n");

    uint16_t raw_distance;
    float distance_cm;

    // Main loop
    while (!terminate) {
        // Check for signal-requested shutdown
        if (terminate) break;

        // Read distance
        if (read_distance(&raw_distance) == 0) {
            // Convert to centimeters
            distance_cm = convert_to_cm(raw_distance);

            // Log distance
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Failed to log distance\n");
            }

            // Trigger alert
            trigger_alert(distance_cm);

            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

