#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x007
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_VAL 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_data(time_t timestamp, int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error writing reset command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error writing start command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for sensor to be ready
    int ready = 0;
    int timeout = 100; // 100 ms timeout
    while (!ready && timeout > 0) {
