#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define LED_GPIO 18
#define DISTANCE_MIN 50
#define DISTANCE_MAX 500
#define FREQUENCY_MIN 10
#define FREQUENCY_MAX 1
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_frequency(uint16_t distance);
void set_led_frequency(float frequency);
void log_data(uint16_t distance, float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 3 - retries + 1, result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate blink frequency from distance
float calculate_frequency(uint16_t distance) {
    float frequency;

    if (distance < DISTANCE_MIN) {
        frequency = FREQUENCY_MIN;
    } else if (distance > DISTANCE_MAX) {
        frequency = FREQUENCY_MAX;
    } else {
        frequency = FREQUENCY_MAX + (FREQUENCY_MIN - FREQUENCY_MAX) * (DISTANCE_MAX - distance) / (DISTANCE_MAX - DISTANCE_MIN);
    }

    return frequency;
}

// Function to set the LED blink frequency
void set_led_frequency(float frequency) {
    float period = 1000.0 / frequency; // Period in milliseconds
    float on_time = period / 2.0;
    float off_time = period / 2.0;

    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(on_time * 1000); // Delay in microseconds

    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(off_time * 1000); // Delay in microseconds
}

// Function to log data to stdout
void log_data(uint16_t distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %u mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

int main() {
    uint16_t distance;
    float frequency;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Starting distance measurement and LED blinking...\n");

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Calculate blink frequency
            frequency = calculate_frequency(distance);

            // Set LED frequency
            set_led_frequency(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

