#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A // Default I2C address
#define MEASURE_CMD 0x00 // Command to trigger measurement
#define MEASURE_DELAY_US 10000 // Delay after measurement command (10ms)
#define READ_DISTANCE_CMD 0x01 // Command to read distance
#define READ_DISTANCE_DELAY_US 5000 // Delay before reading distance (5ms)
#define DISTANCE_REG 0x00 // Register to read distance from
#define DISTANCE_REG_SIZE 2 // Size of distance data in bytes
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    const char *log_file_name;
} sensor_config_t;

// Function prototypes
int init_i2c(int i2c_bus, int i2c_address);
int write_command(int i2c_handle, uint8_t command);
int read_distance(int i2c_handle, uint16_t *distance);
int log_data(FILE *log_file, uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c(int i2c_bus, int i2c_address) {
    i2c_handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Write a command to the sensor
int write_command(int i2c_handle, uint8_t command) {
    int result = i2cWriteByte(i2c_handle, command);
    if (result != 0) {
        fprintf(stderr, "Error writing command 0x%02X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read distance data from the sensor
int read_distance(int i2c_handle, uint16_t *distance) {
    char buffer[DISTANCE_REG_SIZE];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, DISTANCE_REG_SIZE);
    if (result != DISTANCE_REG_SIZE) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Log data to a CSV file
int log_data(FILE *log_file, uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sensor configuration
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75030_ADDR,
        .log_file_name = "distance_log.csv"
    };

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t distance;
    while (!terminate) {
        // Trigger measurement
