#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define POLLING_DELAY_MS 10

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates current_states = {1, 1}; // Initialize to 'clear' state (HIGH)

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce_sensor(int gpio, int current_state);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce a sensor
int debounce_sensor(int gpio, int current_state) {
    int new_state = current_state;
    int i;

    for (i = 0; i < DEBOUNCE_DELAY_MS / POLLING_DELAY_MS; ++i) {
        new_state = read_sensor(gpio);
        if (new_state != current_state) {
            return current_state; // State changed during debounce
        }
        gpioDelay(POLLING_DELAY_MS);
    }

    return new_state;
}

// Function to log an event to the log file
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        // Debounce sensor readings
        sensor1_state = debounce_sensor(SENSOR_1_GPIO, current_states.sensor1_state);
        sensor2_state = debounce_sensor(SENSOR_2_GPIO, current_states.sensor2_state);

        // Log state transitions
        if (sensor1_state != current_states.sensor1_state) {
            if (sensor1_state == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            current_states.sensor1_state = sensor1_state;
        }

        if (sensor2_state != current_states.sensor2_state) {
            if (sensor2_state == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            current_states.sensor2_state = sensor2_state;
        }

        gpioDelay(POLLING_DELAY_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

