#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define MEASUREMENT_DELAY_MS 500
#define POLLING_DELAY_MS 50
#define TIMEOUT_MS 50
#define LOG_FILE "distance_log.csv"

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_distance(int fd);
void log_data(FILE *fp, long distance_mm);
void signal_handler(int sig);
int setup_i2c(const char *bus, int addr);
void cleanup();

// Helper function to read a single register
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write error (address): %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return buf[0];
}

// Helper function to write a single register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd) {
    // Trigger measurement
    if (i2c_write_reg(fd, MEAS_TRIGGER_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    // Poll for data ready
    int status;
    int timeout_counter = 0;
    do {
        status = i2c_read_reg(fd, MEAS_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Failed to read MEAS_STATUS_REG\n");
            return -1;
        }
        if (status & 0x01) break; // Data ready
        usleep(POLLING_DELAY_MS * 1000); // Delay in microseconds
        timeout_counter++;
    } while (timeout_counter < TIMEOUT_MS);

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance data
    int dist_high = i2c_read_reg(fd, DIST_HIGH_REG);
    if (dist_high < 0) {
        fprintf(stderr, "Failed to read DIST_HIGH_REG\n");
        return -1;
    }

    int dist_low = i2c_read_reg(fd, DIST_LOW_REG);
    if (dist_low < 0) {
        fprintf(stderr, "Failed to read DIST_LOW_REG\n");
        return -1;
    }

    return (dist_high << 8) | dist_low;
}

// Function to log the data to a CSV file
void log_data(FILE *fp, long distance_mm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%ld\n", timestamp, distance_mm);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// Function to setup I2C communication
int setup_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    i2c_fd = setup_i2c(I2C_BUS, CH101_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            log_data(log_file, (long)distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        usleep(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

