void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    i2c_fd = setup_i2c(I2C_BUS, CH101_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            log_data(log_file, (long)distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        usleep(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

