    // Wait for measurement to complete (polling ResultRangeStatus)
    int timeout = 100; // 100 attempts
    while (timeout > 0) {
        uint8_t status;
        if (read_register(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if (status & 0x01) break; // Data ready
        usleep(1000); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement data\n");
        return -1;
    }

    // Read distance data for all 64 zones
    for (int i = 0; i < 64; i++) {
        uint8_t distance_msb, distance_lsb;
        if (read_register(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2), &distance_msb) < 0) return -1;
        if (read_register(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2) + 1, &distance_lsb) < 0) return -1;

        distances[i] = (distance_msb << 8) | distance_lsb;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t distances[64];

    // Main loop
    while (1) {
        // Read distance data
        if (read_distance_data(i2c_fd, distances) < 0) {
            fprintf(stderr, "Error reading distance data\n");
            break; // Exit loop on error
        }

        // Print distance data
        printf("Zone\tDistance (mm)\n");
        for (int i = 0; i < 64; i++) {
            printf("%d\t%5d\n", i, distances[i]);
        }
        printf("\n");

        // Wait 500 ms
        usleep(500000);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

