    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t distances[64];

    // Main loop
    while (1) {
        // Read distance data
        if (read_distance_data(i2c_fd, distances) < 0) {
            fprintf(stderr, "Error reading distance data\n");
            break; // Exit loop on error
        }

        // Print distance data
        printf("Zone\tDistance (mm)\n");
        for (int i = 0; i < 64; i++) {
            printf("%d\t%5d\n", i, distances[i]);
        }
        printf("\n");

        // Wait 500 ms
        usleep(500000);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

