{
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize the pigpio library
int initialize_pigpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device(int i2c_bus, int i2c_address)
{
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read a register from the MLX75030
int read_register(int i2c_handle, uint8_t reg_addr, uint16_t *data)
{
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0)
    {
        result = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);
        if (result == 2)
        {
            // Combine the two bytes into a 16-bit value
            *data = (buf[0] << 8) | buf[1];
            return 0; // Success
        }
        else
        {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure
}

