    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0)
    {
        return 1;
    }

    // Open the I2C device
    i2c_handle = open_i2c_device(I2C_BUS, MLX75030_ADDR);
    if (i2c_handle < 0)
    {
        cleanup(-1);
        return 1;
    }

    // Main loop
    while (running)
