#include <string.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00C0
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x00C2
#define VL53L4CX_REG_SYSRANGE_START 0x0009
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0046
#define VL53L4CX_REG_RESULT_SPAD_NB 0x0056
#define VL53L4CX_REG_RESULT_DISTANCE 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to write a byte to a VL53L4CX register
int vl53l4cx_write_byte(int handle, uint16_t reg, uint8_t data)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L4CX register
int vl53l4cx_read_byte(int handle, uint16_t reg, uint8_t *data)
{
    int result = i2cWriteDevice(handle, (char[2]){(reg >> 8) & 0xFF, reg & 0xFF}, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from VL53L4CX registers
int vl53l4cx_read_word(int handle, uint16_t reg, uint16_t *data)
{
    char buf[2];
    int result = i2cWriteDevice(handle, (char[2]){(reg >> 8) & 0xFF, reg & 0xFF}, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for word read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading word from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the VL53L4CX sensor
int vl53l4cx_init(int handle)
{
    // Soft reset
    if (vl53l4cx_write_byte(handle, 0x7FFF, 0x00) != 0) {
        fprintf(stderr, "Error during soft reset\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Check device ID
    uint8_t model_id;
    if (vl53l4cx_read_byte(handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xE1) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Start ranging
    if (vl53l4cx_write_byte(handle, VL53L4CX_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int vl53l4cx_get_distance(int handle, uint16_t *distance)
{
    // Check interrupt status
    uint16_t interrupt_status;
    if (vl53l4cx_read_word(handle, VL53L4CX_REG_RESULT_RANGE_STATUS, &interrupt_status) != 0) {
        fprintf(stderr, "Error reading interrupt status\n");
        return -1;
    }

    if (interrupt_status & 0x01) {
        // Read distance
        if (vl53l4cx_read_word(handle, VL53L4CX_REG_RESULT_DISTANCE, distance) != 0) {
            fprintf(stderr, "Error reading distance\n");
            return -1;
        }
        return 0;
    } else {
        return -1; // No new data available
    }
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
