        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t distance;
    struct timespec ts;
    char timestamp[30];
    while (!terminate) {
