int init_vl53l1x() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0001, 0x01) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set I2C address (optional, but good practice)
    if (i2cWriteByteData(i2c_handle, 0x0001, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    unsigned char data[2];
    int range_status;

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, (char *)data, 1) < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }
