    while (!terminate) {
        int range_status = read_distance(&distance);

        if (range_status >= 0) {
            printf("Distance: %d mm, Range Status: %d\n", distance, range_status);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_vl53l1x() < 0) {
                    fprintf(stderr, "Error: VL53L1X re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(50000); // Delay 50ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

