#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 400.0     // Maximum distance in cm
#define MIN_ANGLE -90.0        // Minimum angle in degrees
#define MAX_ANGLE 90.0         // Maximum angle in degrees
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
float measure_distance();
float calculate_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    set_servo_angle(0.0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    return 0; // Indicate success
}

// Measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * 34300.0 / 2000000.0; // Speed of sound in cm/s

    return distance;
}

// Calculate servo angle based on distance
float calculate_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Set servo angle using pulse width modulation
void set_servo_angle(float angle) {
    // Convert angle to pulse width (us)
    float pulse_width = (angle + 90.0) * 2000.0 / 180.0 + 1000.0; // Map -90 to 0, 90 to 2000
    if (pulse_width < 1000.0) pulse_width = 1000.0;
    if (pulse_width > 2000.0) pulse_width = 2000.0;

    gpioServo(SERVO_PIN, (int)pulse_width);
}

// Log data to file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            float angle = calculate_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Timeout occurred. Distance: %.2f\n", distance);
            log_data(-1.0, -1.0); // Log error
        }

        gpioDelay(200); // Delay 200ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_angle(0.0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

