#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/tmp/distance_queue"
#define POLL_INTERVAL_MS 50

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
bool running = true;

// Function prototypes
int init_i2c();
int check_sensor_id();
int reset_sensor();
int set_timing_budget(int budget_ms);
int start_ranging();
int read_distance(int *distance);
void activate_buzzer();
void deactivate_buzzer();
void log_distance(int distance);
void signal_handler(int signal);
int create_message_queue();
int send_message(int distance);

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to check the VL53L1X sensor ID
int check_sensor_id() {
    char data[1];
    int result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }
    printf("Sensor ID: 0x%02X\n", data[0]);
    return 0;
}

// Function to reset the VL53L1X sensor
int reset_sensor() {
    char data[2];
    data[0] = 0x00;
    data[1] = 0x01;
    int result = i2cWriteI2CBlockData(i2c_handle, 0x0000, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error resetting sensor: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// Function to set the timing budget
int set_timing_budget(int budget_ms) {
    char data[3];
    data[0] = 0x00; // Register address
    data[1] = 0x00; // Value to write
    data[2] = (char)(budget_ms & 0xFF); //LSB
    int result = i2cWriteI2CBlockData(i2c_handle, 0x001E, data, 3);
    if (result < 0) {
        fprintf(stderr, "Error setting timing budget: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to start ranging
int start_ranging() {
    char data[2];
    data[0] = VL53L1X_REG_SYSTEM_START;
    data[1] = 0x01;
    int result = i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance(int *distance) {
    char data[2];
    int result;

    // Check data ready bit
    result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }
    if (!(data[0] & 0x01)) {
        gpioDelay(POLL_INTERVAL_MS * 1000); // Wait for data ready
        return -1; // Retry
    }

    // Read distance
    result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0);
}

// Function to log the distance to a message queue
void log_distance(int distance) {
    int msg_queue_fd = open(MESSAGE_QUEUE_NAME, O_WRONLY | O_CREAT, 0666);
    if (msg_queue_fd == -1) {
        perror("Error opening message queue");
        return;
    }

    // Send the distance as a string
    ssize_t bytes_written = write(msg_queue_fd, &distance, sizeof(distance));
    if (bytes_written == -1) {
        perror("Error writing to message queue");
    }

    close(msg_queue_fd);
}

// Function to create a message queue
int create_message_queue() {
    if (mkfifo(MESSAGE_QUEUE_NAME, 0666) == -1 && errno != EEXIST) {
        perror("Error creating message queue");
        return -1;
    }
    return 0;
}

// Function to send a message to the message queue
int send_message(int distance) {
    int msg_queue_fd = open(MESSAGE_QUEUE_NAME, O_WRONLY | O_CREAT, 0666);
    if (msg_queue_fd == -1) {
        perror("Error opening message queue");
        return -1;
    }

    // Send the distance as a string
    ssize_t bytes_written = write(msg_queue_fd, &distance, sizeof(distance));
    if (bytes_written == -1) {
        perror("Error writing to message queue");
    }

    close(msg_queue_fd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer();

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Check sensor ID
    if (check_sensor_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Reset sensor
    if (reset_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set timing budget
    if (set_timing_budget(50) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    if (start_ranging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    if (create_message_queue() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (running) {
        // Read distance
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            // Log distance to message queue
            log_distance(distance);

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll every 50ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();

    return 0;
}

