void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that echo is rising
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 0; // Reset flag after falling edge
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    // Handle tick wraparound
    if (pulse_width > 0xFFFFFFFF) {
        pulse_width = (uint32_t)(pulse_width - 0xFFFFFFFF - 1);
    }

    // Calculate distance
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for round trip, convert us to s
    return distance;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < BUZZER_THRESHOLD && buzzer_state == 0) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
        buzzer_state = 1;
    } else if (distance >= BUZZER_THRESHOLD && buzzer_state == 1) {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        buzzer_state = 0;
    }
}

// Function to display the distance on the console
void display_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_sensor();
        gpioDelay(100); // Delay between measurements

        if (echo_start_tick != 0 && echo_end_tick != 0) {
            uint32_t pulse_width = echo_end_tick - echo_start_tick;
            float distance = calculate_distance(pulse_width);

            if (distance >= 2.0 && distance <= 400.0) {
                display_distance(distance);
                control_buzzer(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }

            echo_start_tick = 0;
            echo_end_tick = 0;
        } else {
            // Timeout or no echo received
            fprintf(stderr, "Timeout or no echo received\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

