#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate/control"
#define MQTT_CLIENT_ID "gate_controller"

// VL53L1X Register Addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
struct mosquitto *mosq = NULL;
bool gate_open = false;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);
void cleanup();

// VL53L1X Initialization Sequence (Example - adjust based on datasheet)
int init_vl53l1x() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) return -1;
    gpioDelay(10000); // 10ms delay

    // Check device ID (example)
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) return -1;
    if (model_id != 0xEACC) { // Expected value for VL53L1X
        fprintf(stderr, "Error: Incorrect VL53L1X model ID: 0x%X\n", model_id);
        return -1;
    }

    // Start ranging (example)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) return -1;

    return 0;
}

// Function to read distance from VL53L1X
int read_distance() {
    int distance = -1;
    int retries = 3;

    while (retries > 0) {
        // Read range status
        int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error reading range status, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Read distance
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Basic data validation
        if (distance > 8191) {
            fprintf(stderr, "Invalid distance reading: %d, retrying...\n", distance);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        return distance;
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to open the gate
void open_gate() {
    if (!gate_open) {
        gpioServo(SERVO_PIN, 2000); // Move servo to open position (adjust value as needed)
        gate_open = true;
        log_event("Gate opened");
    }
}

// Function to close the gate
void close_gate() {
    if (gate_open) {
        gpioServo(SERVO_PIN, 1000); // Move servo to close position (adjust value as needed)
        gate_open = false;
        log_event("Gate closed");
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        printf("MQTT connected to %s:%d\n", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        printf("Received message on topic %s: %s\n", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC) == 0) {
            if (strcmp((char *)message->payload, "force_open") == 0) {
                open_gate();
            } else if (strcmp((char *)message->payload, "force_close") == 0) {
                close_gate();
            } else if (strcmp((char *)message->payload, "status_request") == 0) {
                // Send status via MQTT (e.g., gate_open variable)
                char status[50];
                snprintf(status, sizeof(status), "{\"gate_open\": %d}", gate_open);
                mosquitto_publish(mosq, NULL, "gate/status", strlen(status), status, 0, false);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, cleaning up...\n");
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (gate_open) {
        close_gate(); // Ensure gate is closed on exit
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance > 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD && !gate_open) {
                open_gate();
            } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
                close_gate();
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

