#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_MS 60
#define MIN_PULSE_WIDTH 100 // Minimum valid pulse width in microseconds
#define MAX_PULSE_WIDTH 30000 // Maximum valid pulse width in microseconds
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MEASUREMENT_INTERVAL_MS 200 // Measurement interval in milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold timestamp data
typedef struct {
    long long rising_edge_tick;
    long long falling_edge_tick;
} Timestamps;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
Timestamps capture_timestamps();
double calculate_distance(long long pulse_duration);
void log_distance(double distance);
void log_warning(const char *message);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure TRIG_PIN is initially LOW
    gpioWrite(TRIG_PIN, 0);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Capture rising and falling edge timestamps
Timestamps capture_timestamps() {
    Timestamps timestamps;
    timestamps.rising_edge_tick = 0;
    timestamps.falling_edge_tick = 0;

    // Wait for rising edge
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_MS * 1000) {
        timestamps.rising_edge_tick = 0; // Timeout
    } else {
        timestamps.rising_edge_tick = gpioTick();
    }

    // Wait for falling edge
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_MS * 1000) {
        timestamps.falling_edge_tick = 0; // Timeout
    } else {
        timestamps.falling_edge_tick = gpioTick();
    }

    return timestamps;
}

// Calculate distance in centimeters
double calculate_distance(long long pulse_duration) {
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0 / 2.0;
}

// Log distance to stdout and file
void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Log warnings to stdout and file
void log_warning(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(stderr, "%s Warning: %s\n", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s Warning: %s\n", timestamp, message);
        fflush(log_file);
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
