        long long pulse_duration = 0;
        if (timestamps.rising_edge_tick != 0 && timestamps.falling_edge_tick != 0) {
            pulse_duration = timestamps.falling_edge_tick - timestamps.rising_edge_tick;

            // Handle tick wraparound
            if (pulse_duration < 0) {
                pulse_duration += 0xFFFFFFFFFFFFFFFFLL; // Add the maximum possible value to get the correct duration
            }
        }

        if (pulse_duration == 0) {
            log_warning("No echo received or timeout occurred.");
        } else if (pulse_duration < MIN_PULSE_WIDTH || pulse_duration > MAX_PULSE_WIDTH) {
            char message[64];
            snprintf(message, sizeof(message), "Invalid pulse width: %lld us", pulse_duration);
            log_warning(message);
