#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SERVO_PIN 18
#define VL53L1X_SDA 2
#define VL53L1X_SCL 3
#define VL53L1X_SHUTDOWN 23
#define VL53L1X_INTERRUPT 24

// Define I2C bus and address
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance thresholds (in cm)
#define OPEN_THRESHOLD 50
#define CLOSE_THRESHOLD 60

// Define servo pulse width limits (in microseconds)
#define SERVO_OPEN 1000
#define SERVO_CLOSED 2000

// Define log file name
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int open);
void log_event(int open, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to write a word (2 bytes) to a VL53L1X register
int vl53l1x_write_word(int handle, uint8_t reg, uint16_t data) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (data >> 8) & 0xFF; // MSB
    buf[2] = data & 0xFF;        // LSB
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(VL53L1X_SHUTDOWN, PI_OUTPUT);
    gpioSetMode(VL53L1X_INTERRUPT, PI_INPUT);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int gate_open = 0; // 0 = closed, 1 = open
    int distance;
    while (program_running) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            continue; // Skip to the next iteration
        }

        if (gate_open == 0 && distance <= OPEN_THRESHOLD) {
            control_servo(1); // Open the gate
            gate_open = 1;
        } else if (gate_open == 1 && distance > CLOSE_THRESHOLD) {
            control_servo(0); // Close the gate
            gate_open = 0;
        }

        log_event(gate_open, distance);
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    control_servo(0); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID (example)
    uint8_t sensor_id;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (sensor_id != 0xEACC) { // Expected value for VL53L1X
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Initialize shutdown pin
    gpioSetMode(VL53L1X_SHUTDOWN, PI_OUTPUT);
    gpioWrite(VL53L1X_SHUTDOWN, 1); // Set high to disable sensor

    // Initialize interrupt pin
    gpioSetMode(VL53L1X_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(VL53L1X_INTERRUPT, PI_PUD_DOWN); // Optional: Set pull-down resistor

    // VL53L1X initialization sequence (simplified)
    if (vl53l1x_write_byte(i2c_handle, 0x88, 0x00) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x80, 0x01) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0xFF, 0x01) != 0) return -1;
    if (vl53l1x_write_byte(i2c_handle, 0x00, 0x00) != 0) return -1;

    // Start continuous ranging
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) return -1;

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    uint16_t range;
    uint8_t status;

    // Read range status
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
        return -1;
    }

    // Read distance (in mm)
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range) != 0) {
        return -1;
    }

    // Convert to centimeters
    range /= 10; // Divide by 10 to convert mm to cm

    return range;
}

// Function to control the servo motor
void control_servo(int open) {
    int pulse_width;

    if (open) {
        pulse_width = SERVO_OPEN;
    } else {
        pulse_width = SERVO_CLOSED;
    }

    gpioPWM(SERVO_PIN, pulse_width); // Set PWM duty cycle
}

// Function to log events to a file
void log_event(int open, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Gate: %s, Distance: %d cm\n", timestamp,
            open ? "Open" : "Closed", distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

