#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_GPIO 18
#define GATE_CLOSE_GPIO 19
#define DISTANCE_THRESHOLD 200 // mm
#define TIMING_BUDGET_MS 50
#define POLLING_INTERVAL_MS 500

// VL53L1X Register Addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Soft reset
    if (i2cWriteI2CBlockData(i2c_handle, 0x0000, 0x00, 0x01) < 0) {
        perror("Failed to reset VL53L1X");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Check sensor ID (example)
    char sensor_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id, 1) < 0) {
        perror("Failed to read sensor ID");
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure timing budget (example)
    if (i2cWriteI2CBlockData(i2c_handle, 0x001E, 0x00, 0x00) < 0) {
        perror("Failed to set timing budget");
        return -1;
    }
    if (i2cWriteI2CBlockData(i2c_handle, 0x001F, 0x00, 0x00) < 0) {
        perror("Failed to set timing budget");
        return -1;
    }

    // Start ranging
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01, 0x01) < 0) {
        perror("Failed to start ranging");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char distance_data[2];
    int distance;

    // Read distance data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) < 0) {
        perror("Failed to read distance data");
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    distance = (distance_data[0] << 8) | distance_data[1];

    return distance;
}

// Control the gate actuator
void control_gate(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GATE_OPEN_GPIO, 1);
        gpioWrite(GATE_CLOSE_GPIO, 0);
        log_event("Gate Opened");
    } else {
        gpioWrite(GATE_OPEN_GPIO, 0);
        gpioWrite(GATE_CLOSE_GPIO, 1);
        log_event("Gate Closed");
    }
}

// Log events to file with ISO 8601 timestamp
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_OPEN_GPIO, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            log_event("Sensor Read Error");
        } else {
            control_gate(distance);
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GATE_OPEN_GPIO, 0);
    gpioWrite(GATE_CLOSE_GPIO, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

