#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 24
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18

// Define I2C bus and address
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance thresholds
#define FORWARD_THRESHOLD 100 // mm
#define BACKWARD_THRESHOLD 300 // mm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int read_distance();
void control_motor(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    // Start measurement
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start measurement\n");
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X sensor
int read_distance() {
    int distance = -1; // Initialize to an error value
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        // Poll data ready bit (0x0089)
        int data_ready = i2cReadByteData(i2c_handle, 0x0089);
        if (data_ready < 0) {
            fprintf(stderr, "Error: Failed to read data ready status, retrying...\n");
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
            continue;
        }

        if (data_ready & 0x01) {
            // Read distance (16-bit value from 0x0096 and 0x0097)
            int msb = i2cReadByteData(i2c_handle, 0x0096);
            int lsb = i2cReadByteData(i2c_handle, 0x0097);

            if (msb < 0 || lsb < 0) {
                fprintf(stderr, "Error: Failed to read distance data, retrying...\n");
                gpioDelay(delay_ms);
                delay_ms *= 2; // Exponential backoff
                retries--;
                continue;
            }

            distance = (msb << 8) | lsb;
            break; // Success, exit retry loop
        } else {
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    if (distance == -1) {
        fprintf(stderr, "Error: Failed to read distance after multiple retries\n");
    }

    return distance;
}

// Function to control the DC motor
void control_motor(int distance) {
    static int motor_state = 0; // 0: stopped, 1: forward, 2: backward

    if (distance < 0) {
        // Sensor error, stop the motor
        if (motor_state != 0) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 0;
            printf("Motor stopped due to sensor error\n");
        }
        return;
    }

    if (distance < FORWARD_THRESHOLD) {
        // Drive forward
        if (motor_state != 1) {
            gpioWrite(MOTOR_FORWARD_PIN, 1);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 1;
            printf("Motor: Forward\n");
        }
    } else if (distance > BACKWARD_THRESHOLD) {
        // Drive backward
        if (motor_state != 2) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 1);
            motor_state = 2;
            printf("Motor: Backward\n");
        }
    } else {
        // Stop
        if (motor_state != 0) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 0;
            printf("Motor: Stopped\n");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance();

        // Control motor
        control_motor(distance);

        // Print distance and motor state
        printf("Distance: %d mm, Motor: %s\n", distance, (motor_state == 1) ? "Forward" : ((motor_state == 2) ? "Backward" : "Stopped"));

        // Wait for a short period
        gpioDelay(100); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    gpioTerminate();

    return 0;
}

