#define MPR121_ADDR 0x5A
#define GPIO_LED1 17
#define GPIO_LED2 18
#define GPIO_LED3 27
#define GPIO_LED4 22
#define NUM_ELECTRODES 12
#define POLLING_INTERVAL_MS 50

