// I2C write function with retry
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    int retries = 3;
    int result;
    unsigned char buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read_reg(int fd, unsigned char reg) {
    int retries = 3;
    int result;
    unsigned char buf[1];

    buf[0] = reg;

    while (retries > 0) {
        if (write(fd, buf, 1) == 1) {
            unsigned char value;
            if (read(fd, &value, 1) == 1) {
                return value; // Success
            } else {
                perror("I2C read failed (first byte write)");
                retries--;
                usleep(10000); // 10ms delay
            }
        } else {
            perror("I2C read failed (first byte write)");
            retries--;
