    gpioWrite(LED_GPIO, on);
}

// Function to log a proximity event
void log_proximity_event() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

