#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELECTRODE_0 0
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LED_GPIO 27
#define PROXIMITY_LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_mpr121_register(int reg);
int write_mpr121_register(int reg, int value);
int is_proximity_detected();
void control_led(int on);
void log_proximity_event();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121 sensor
int initialize_mpr121() {
    // Verify device ID
    int device_id = read_mpr121_register(0x00);
    if (device_id != 0x5A) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", device_id);
        return -1;
    }

    // Configure electrode 0
    if (write_mpr121_register(0x41, TOUCH_THRESHOLD) < 0) return -1;
    if (write_mpr121_register(0x42, RELEASE_THRESHOLD) < 0) return -1;

    // Configure FFI (Filter Configuration)
    if (write_mpr121_register(0x5C, 0x10) < 0) return -1; // Set FFI to 0x10

    // Configure SFI (Sensor Filtering)
    if (write_mpr121_register(0x5D, 0x01) < 0) return -1; // Set SFI to 0x01

    // Configure ESI (Electrode Sensing Configuration)
    if (write_mpr121_register(0x5E, 0x0F) < 0) return -1; // Enable all electrodes

    // Configure debounce
    if (write_mpr121_register(0x5B, 0x01) < 0) return -1; // Set debounce to 1

    // Configure AFE (Analog Front End)
    if (write_mpr121_register(0x2B, 0x01) < 0) return -1; // Set AFE config

    // Configure Baseline Filtering
    if (write_mpr121_register(0x2C, 0x01) < 0) return -1; // Set Baseline config

    return 0;
}

// Function to read an MPR121 register
int read_mpr121_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%X\n", reg);
        return -1;
    }
    return value;
}

// Function to write to an MPR121 register
int write_mpr121_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error: I2C write failed for register 0x%X\n", reg);
        return -1;
    }
    return 0;
}

// Function to check if proximity is detected on electrode 0
int is_proximity_detected() {
    int touch_status = read_mpr121_register(0x00);
    if (touch_status < 0) return 0; // Return 0 on error to avoid false positives

    return (touch_status & (1 << ELECTRODE_0)) ? 1 : 0;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Function to log a proximity event
void log_proximity_event() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Proximity detected on electrode 0\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(PROXIMITY_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (is_proximity_detected()) {
            printf("Proximity detected!\n");
            control_led(1); // Turn on LED
            log_proximity_event(); // Log the event
            gpioDelay(1000); // Wait for 1 second
            control_led(0); // Turn off LED
        }
        gpioDelay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

