#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define distance limits
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

// Define timeout values
#define TRIGGER_TIMEOUT_US 30000 // 30ms
#define ECHO_TIMEOUT_US 30000    // 30ms

// Define speed of sound
#define SPEED_OF_SOUND 34300.0 // cm/s

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static void *zmq_context = NULL;
static void *pub_socket = NULL; // Changed zmq_socket to pub_socket to avoid conflict with zmq.h

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
int trigger_pulse(void);
long long measure_pulse_width(void);
double calculate_distance(long long pulse_width);
int log_data(double distance);
int publish_data(double distance);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("Received SIGINT, exiting...\n");
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request echo line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "echo";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(echo_line, &config, 0) < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
int trigger_pulse(void) {
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line_request_config config;

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Error: Could not get trigger or echo line in trigger_pulse\n");
        return -1;
    }

    // Hold trigger low for 5 microseconds
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return -1;
    }
    usleep(5);

    // Pulse trigger high for 10 microseconds
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return -1;
    }
    usleep(10);

    // Hold trigger low
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return -1;
    }

    return 0;
}

// Measure the pulse width of the echo signal
long long measure_pulse_width(void) {
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line_request_config config;
    long long start_time, end_time, pulse_width;
    int timeout;

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!echo_line) {
        fprintf(stderr, "Error: Could not get echo line in measure_pulse_width\n");
        return -1;
    }

    // Wait for rising edge with timeout
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        if (timeout++ > TRIGGER_TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for rising edge\n");
            return -1;
        }
        usleep(1);
    }

    // Measure pulse width with timeout
    timeout = 0;
    start_time = gpiod_line_get_value(echo_line);
    while (gpiod_line_get_value(echo_line) == start_time) {
        if (timeout++ > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for falling edge\n");
            return -1;
        }
        usleep(1);
    }
    end_time = gpiod_line_get_value(echo_line);

    pulse_width = end_time - start_time;

    return pulse_width;
}

// Calculate distance from pulse width
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * 0.0343 / 2.0;
}

// Log data to file
int log_data(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    return 0;
}

// Publish data via ZeroMQ
int publish_data(double distance) {
    char buffer[100];
    snprintf(buffer, sizeof(buffer), "%.2f", distance);

    zmq_msg_t message;
    zmq_msg_init_size(&message, strlen(buffer));
    memcpy(zmq_msg_data(&message), buffer, strlen(buffer));

    int rc = zmq_msg_send(&message, pub_socket, 0);
    zmq_msg_close(&message);

    if (rc == -1) {
        perror("Error sending message");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close ZeroMQ socket
    if (pub_socket) {
        zmq_close(pub_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    double distance;
    long long pulse_width;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Initialize ZeroMQ
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Error creating ZeroMQ context");
        cleanup();
        return 1;
    }

    pub_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!pub_socket) {
        perror("Error creating ZeroMQ socket");
        cleanup();
        return 1;
    }

    int rc = zmq_bind(pub_socket, ZMQ_ENDPOINT);
    if (rc != 0) {
        perror("Error binding ZeroMQ socket");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Trigger pulse failed\n");
            continue;
        }

        // Measure pulse width
        pulse_width = measure_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Pulse width measurement failed\n");
            continue;
        }

        // Calculate distance
        distance = calculate_distance(pulse_width);
        if (distance < 0) {
            fprintf(stderr, "Distance calculation failed\n");
            continue;
        }

        // Validate distance
        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            // Log data
            if (log_data(distance) < 0) {
                fprintf(stderr, "Logging failed\n");
            }

            // Publish data
            if (publish_data(distance) < 0) {
                fprintf(stderr, "Publishing failed\n");
            }
        } else {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

