void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            pulse_start_tick = tick;
            echo_received = 0; // Reset echo_received flag
        } else if (level == 0) {
            pulse_end_tick = tick;
            echo_received = 1; // Set echo_received flag
        }
    }
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    // Handle tick wraparound
    if (pulse_width > 0xFFFFFFFF) {
        pulse_width = (0xFFFFFFFF - pulse_width) * 2; // Convert to microseconds
    } else {
        pulse_width = pulse_width * 2; // Convert to microseconds
    }
    return (double)pulse_width * 343.0 / 2000000.0;
}

