#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define GPIO_XSHUT 27

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int init_vl53l1x();
int read_distance(int *distance);
int read_status(int *status);
void log_data(int distance, int status);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_XSHUT, PI_OUTPUT);
    gpioWrite(GPIO_XSHUT, 1); // Enable sensor
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Write to register 0x0018 (continuous mode)
    if (i2cWriteByteData(i2c_handle, 0x0018, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        return -1;
    }

    // Write to register 0x0019 (no timeout)
    if (i2cWriteByteData(i2c_handle, 0x0019, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        return -1;
    }

    // Write to register 0x0020 (start ranging)
    if (i2cWriteByteData(i2c_handle, 0x0020, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        return -1;
    }

    return 0;
}

// Read distance from sensor
int read_distance(int *distance) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Read status from sensor
int read_status(int *status) {
    char buffer[1];
    if (i2cReadI2CBlockData(i2c_handle, STATUS_REG, buffer, 1) != 1) {
        syslog(LOG_ERR, "Failed to read status data");
        return -1;
    }

    *status = buffer[0];
    return 0;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s - Distance: %d mm, Status: %d", timestamp, distance, status);
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized");

    int distance, status;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

