#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_gate(int distance);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, 0x010F);
    if (model_id < 0) {
        log_message("Error reading model ID");
        return -1;
    }
    if (model_id != 0xEA) {
        log_message("Incorrect model ID");
        return -1;
    }
    log_message("VL53L1X model ID verified");

    // Set ranging mode to short
    if (i2cWriteByteData(i2c_handle, 0x0021, 0x00) < 0) {
        log_message("Error setting ranging mode");
        return -1;
    }
    log_message("Ranging mode set to short");

    // Start ranging
    if (i2cWriteByteData(i2c_handle, 0x0015, 0x01) < 0) {
        log_message("Error starting ranging");
        return -1;
    }
    log_message("Ranging started");

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, 0x0089);
    if (high_byte < 0) {
        log_message("Error reading high byte of distance");
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, 0x008A);
    if (low_byte < 0) {
        log_message("Error reading low byte of distance");
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;
    return 0;
}

// Control gate actuator
void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GATE_GPIO, 1); // Open gate
        gate_open = 1;
        log_message("Gate opened");
    } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GATE_GPIO, 0); // Close gate
        gate_open = 0;
        log_message("Gate closed");
    }
}

// Log messages to file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_message("I2C connection opened");

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_message("Log file opened");

    // Set GPIO mode for gate control
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is initially closed
    log_message("Gate GPIO set to output, initially closed");

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_message("VL53L1X initialization failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            char message[50];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(message);

            control_gate(distance);
        } else {
            log_message("Error reading distance");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    log_message("Cleaning up...");
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

