        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_message("Log file opened");

    // Set GPIO mode for gate control
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is initially closed
    log_message("Gate GPIO set to output, initially closed");

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_message("VL53L1X initialization failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

