#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0         // degrees
#define MAX_ANGLE 180.0        // degrees
#define MIN_PULSE_WIDTH 500    // us
#define MAX_PULSE_WIDTH 2500   // us
#define TIMEOUT_US 30000       // us (30 ms)
#define SAMPLE_PERIOD_MS 100   // ms
#define MOVING_AVG_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
int pulse_width_data = 0; // Shared data for alert callback and main thread
int pulse_width_data_ready = 0; // Flag indicating data is ready
int moving_average[MOVING_AVG_SIZE];
int moving_average_index = 0;

// Function prototypes
void triggerSensor();
long pulseStart = 0, pulseEnd = 0;
double getDistance();
double mapDistanceToAngle(double distance);
void setServoAngle(double angle);
void logData(double distance, double angle);
void alertFunc(int gpio, int level, uint32_t tick);
void signalHandler(int signal);
int readPulseWidth();

// Alert function to measure pulse width
void alertFunc(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulseStart = tick;
    } else if (level == 0) {
        pulseEnd = tick;
        pulse_width_data = pulseEnd - pulseStart;
        pulse_width_data_ready = 1; // Signal main thread that data is ready
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
double getDistance() {
    triggerSensor();
    long startTime = gpioTick();
    while (!pulse_width_data_ready) {
        if (gpioTick() - startTime > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            pulse_width_data = 0; // Indicate timeout
            pulse_width_data_ready = 1; // Signal main thread that data is ready
            return -1.0; // Indicate error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    pulse_width_data_ready = 0; // Reset flag
    double pulseWidth = (double)pulse_width_data;

    // Calculate distance in centimeters
    double distance = (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map distance to servo angle using logarithmic mapping
double mapDistanceToAngle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    }

    // Logarithmic mapping
    double logDistance = log10(distance / MIN_DISTANCE);
    double logAngle = log10((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) / log10(1.0 - 0.5); // Normalize to 0-1 range and map to 0.5-1.0
    double angle = MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (logAngle + 0.5); // Shift to 0-180 range

    return angle;
}

// Function to set the servo angle using gpioServo
void setServoAngle(double angle) {
    // Convert angle to pulse width
    double pulseWidth = MIN_PULSE_WIDTH + (angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);

    // Set servo pulse width
    gpioServo(SERVO_PIN, (int)pulseWidth);
}

// Function to log data to a CSV file
void logData(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read pulse width data with timeout and error handling
int readPulseWidth() {
    triggerSensor();
    long startTime = gpioTick();
    while (!pulse_width_data_ready) {
        if (gpioTick() - startTime > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            pulse_width_data = 0; // Indicate timeout
            pulse_width_data_ready = 1; // Signal main thread that data is ready
            return -1; // Indicate error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    pulse_width_data_ready = 0; // Reset flag
    return pulse_width_data;
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 20000); // 20 us period
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Initialize moving average buffer with zeros
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        moving_average[i] = 0.0;
    }

    // Main loop
    while (program_running) {
        // Measure distance
        double distance = getDistance();

        // Process distance
        if (distance < 0.0) {
            // Invalid reading, default to 90 degrees
            setServoAngle(90.0);
            logData(-1.0, 90.0);
        } else {
            // Update moving average
            moving_average[moving_average_index] = distance;
            moving_average_index = (moving_average_index + 1) % MOVING_AVG_SIZE;

            // Calculate average distance
            double sum = 0.0;
            for (int i = 0; i < MOVING_AVG_SIZE; i++) {
                sum += moving_average[i];
            }
            double avgDistance = sum / MOVING_AVG_SIZE;

            // Map distance to angle
            double angle = mapDistanceToAngle(avgDistance);

            // Set servo angle
            setServoAngle(angle);

            // Log data
            logData(avgDistance, angle);
        }

        // Wait for the next sample period
        gpioDelay(SAMPLE_PERIOD_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

