#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROX_HIGH_REG 0x08
#define PROX_LOW_REG 0x09
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_proximity();
int log_data(int proximity);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting GPIO pull-down\n");
        return -1;
    }
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        return -1;
    }
    return 0;
}

// Function to read proximity value from the sensor
int read_proximity() {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PROX_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }

    return (buf[1] << 8) | buf[0];
}

// Function to log data to file
int log_data(int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    if (proximity <= threshold) {
        fprintf(log_file, "%s, %d, SAFE\n", timestamp, proximity);
    } else {
        fprintf(log_file, "%s, %d, ALERT\n", timestamp, proximity);
    }

    fclose(log_file);
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    int proximity = read_proximity();
    if (proximity >= 0) {
        log_data(proximity);
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int i2c_address = SI1102_ADDR;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            if (strncmp(argv[i + 1], "0x", 2) == 0) {
                i2c_address = strtol(argv[i + 1], NULL, 16);
            } else {
                i2c_address = atoi(argv[i + 1]);
            }
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atoi(argv[i + 1]);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Proximity sensor monitoring started. I2C address: 0x%02X, threshold: %d\n", i2c_address, threshold);

    // Main loop
    while (!terminate) {
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Proximity sensor monitoring stopped.\n");
    return 0;
}

