#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)

// Global variables
static volatile int running = 1;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int distance = 0; // Store the last valid distance
static volatile int frequency = 500; // Initial frequency

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
double calculateDistance(int pulse_width_us);
double mapDistanceToFrequency(double distance);
void setPWMFrequency(int frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping PWM and exiting...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM output
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioTrigger(TRIGGER_PIN, 10, 1); // 10 us trigger pulse
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Set echo_received flag
    }
}

// Function to calculate distance in centimeters
double calculateDistance(int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to frequency using a logarithmic formula
double mapDistanceToFrequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return frequency; // Return the current frequency if out of range
    }
    return 200.0 * exp(distance / 50.0);
}

// Function to set the PWM frequency
void setPWMFrequency(int frequency) {
    if (gpioSetPWMfrequency(PWM_PIN, frequency) != frequency) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", frequency);
        return;
    }
    gpioPWM(PWM_PIN, 128); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set PWM mode
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, frequency); // Set initial frequency
    gpioPWM(PWM_PIN, 128); // 50% duty cycle

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        triggerSensor(); // Trigger the sensor

        // Wait for echo or timeout
        int start_time = gpioTick();
        while (!echo_received && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (echo_received) {
            // Calculate pulse width
            int pulse_width_us = echo_end_tick - echo_start_tick;

            // Calculate distance
            distance = (int)calculateDistance(pulse_width_us);

            // Map distance to frequency
            double new_frequency = mapDistanceToFrequency((double)distance);

            // Set PWM frequency
            if (new_frequency != frequency) {
                frequency = (int)new_frequency;
                setPWMFrequency(frequency);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(50000); // Delay 50ms
    }

    // Clean up and exit
    gpioPWM(PWM_PIN, 0); // Stop PWM output
    gpioTerminate();      // Terminate pigpio
    return 0;
}

