#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 5.0  // cm
#define MAX_DISTANCE 50.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT 100000 // us (100 ms)

// Global variables
static volatile int running = 1;
static volatile float last_valid_distance = 0.0;

// Function prototypes
float read_distance();
float distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate(); // Terminate pigpio
    printf("\nProgram terminated gracefully.\n");
    exit(0);
}

// Function to read distance from the ultrasonic sensor
float read_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse timeout (high).\n");
        return last_valid_distance; // Return last valid distance
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse timeout (low).\n");
        return last_valid_distance; // Return last valid distance
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff_tick / 1000000.0 * 34300.0 / 2.0; // cm

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Error: Distance out of range (%f cm).\n", distance);
        return last_valid_distance; // Return last valid distance
    }

    last_valid_distance = distance;
    return distance;
}

// Function to map distance to frequency
float distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency using pigpio's hardware PWM
void set_buzzer_frequency(float frequency) {
    int range = 1000; // PWM range (adjust as needed)
    int dutycycle = (int)(range * 0.5 * (1.0 / frequency)); // 50% duty cycle

    if (dutycycle < 0) dutycycle = 0;
    if (dutycycle > range) dutycycle = range;

    gpioPWM(BUZZER_PIN, dutycycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range for buzzer pin
    gpioSetPWMrange(BUZZER_PIN, 1000);
    gpioSetPWMfrequency(BUZZER_PIN, 0); // Initialize PWM frequency to 0

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = read_distance();
        float frequency = distance_to_frequency(distance);
        set_buzzer_frequency(frequency);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

