#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 29.1 // cm/us
#define TIMEOUT_US 50000     // 50 ms
#define MIN_DISTANCE 2.0    // cm
#define MAX_DISTANCE 400.0  // cm
#define TOO_CLOSE_THRESHOLD 10.0 // cm

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04 sensor
float measure_distance()
{
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse width in microseconds
    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        // Measure distance
        float distance = measure_distance();

        // Check for errors
        if (distance < 0)
        {
            fprintf(stderr, "Invalid reading\n");
        }
        else
        {
            // Validate distance
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE)
            {
                fprintf(stderr, "Invalid reading\n");
            }
            else
            {
                // Print distance
                printf("Distance: %.2f cm", distance);

                // Check for proximity warning
                if (distance < TOO_CLOSE_THRESHOLD)
                {
                    printf(" - Too close!\n");
                }
                else
                {
                    printf("\n");
                }
            }
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

