    end_tick = gpioTick();

    // Calculate pulse width in microseconds
    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        // Measure distance
        float distance = measure_distance();

        // Check for errors
        if (distance < 0)
        {
            fprintf(stderr, "Invalid reading\n");
