#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define sensor registers
#define REG_CONTINUOUS_MODE 0x01
#define REG_RANGE 0x02
#define REG_MEASURE 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Define GPIO pin for chip select (CE0)
#define CS_PIN 8

// Define distance range (in mm)
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int continuous_mode;
    int range;
} sensor_config_t;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the sensor
int initialize_sensor() {
    char buf[3];
    int status;

    // Set continuous measurement mode
    buf[0] = REG_CONTINUOUS_MODE;
    buf[1] = 0x01; // Enable continuous mode
    buf[2] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, buf, buf, 3);
    if (status != 0) {
        fprintf(stderr, "Error writing to continuous mode register: %d\n", status);
        return -1;
    }

    // Set range to 5 meters
    buf[0] = REG_RANGE;
    buf[1] = 0x00; // 5m range
    buf[2] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, buf, buf, 3);
    if (status != 0) {
        fprintf(stderr, "Error writing to range register: %d\n", status);
        return -1;
    }

    // Trigger measurement
    buf[0] = REG_MEASURE;
    buf[1] = 0x01; // Trigger measurement
    buf[2] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, buf, buf, 3);
    if (status != 0) {
        fprintf(stderr, "Error writing to measure register: %d\n", status);
        return -1;
    }

    return 0;
}

