int read_distance(uint16_t *distance) {
    char buf[3];
    int status;

    // Read distance data
    buf[0] = REG_DISTANCE_LOW;
    buf[1] = 0x00; // Dummy byte
    buf[2] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, buf, buf, 3);
    if (status != 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", status);
        return -1;
    }

    // Combine low and high bytes to form 16-bit distance
    *distance = (buf[2] << 8) | buf[1];

    return 0;
}

