    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    uint16_t distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        status = read_distance(&distance);
        if (status == 0) {
            // Validate distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                // Log distance
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %u\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

