#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_VIS_LOW_REG 0x22
#define ALS_VIS_HIGH_REG 0x23
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, uint16_t als_value);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }
    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing byte");
        return -1;
    }
    return 0;
}

// Read ALS visible function
uint16_t read_als_visible(int fd) {
    uint8_t low_byte, high_byte;
    if (i2c_read_bytes(fd, ALS_VIS_LOW_REG, &low_byte, 1) < 0) return 0; // Handle error
    if (i2c_read_bytes(fd, ALS_VIS_HIGH_REG, &high_byte, 1) < 0) return 0; // Handle error

    return (uint16_t)((high_byte << 8) | low_byte);
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_str;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, uint16_t als_value) {
    if (fprintf(fp, "%s,%u\n", timestamp, als_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read ALS visible value
        uint16_t als_value = read_als_visible(i2c_fd);

        // Get timestamp
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, als_value) < 0) {
            terminate = 1; // Set terminate to exit the loop on logging error
        }

        // Flush the log file to ensure data is written
        fflush(log_file);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

