#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_RESET_REG 0x30
#define SI1120_PART_ID_REG 0x00
#define SI1120_ALS_LSB_REG 0x22
#define SI1120_ALS_MSB_REG 0x23
#define SI1120_PS1_LSB_REG 0x18
#define SI1120_PS1_MSB_REG 0x19

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int reset_si1120();
int verify_part_id();
int read_als();
int read_proximity();
int log_data(int als, int proximity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reset the Si1120 sensor
int reset_si1120() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, SI1120_RESET_REG, 0x01) == 0) {
            gpioDelay(10); // Wait for reset to complete
            return 0; // Success
        } else {
            fprintf(stderr, "Error resetting Si1120, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }
    fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
    return -1; // Failure
}

// Verify the Si1120 part ID
int verify_part_id() {
    int part_id;
    int retries = 3;
    while (retries > 0) {
        part_id = i2cReadByteData(i2c_handle, SI1120_PART_ID_REG);
        if (part_id >= 0) {
            if (part_id == 0x41) {
                return 0; // Success
            } else {
                fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
                return -1; // Failure
            }
        } else {
            fprintf(stderr, "Error reading part ID, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }
    fprintf(stderr, "Failed to read part ID after multiple retries.\n");
    return -1; // Failure
}

// Read ALS data from the Si1120
int read_als() {
    int als_low, als_high;
    int retries = 3;
    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, SI1120_ALS_LSB_REG);
        if (als_low >= 0) {
            als_high = i2cReadByteData(i2c_handle, SI1120_ALS_MSB_REG);
            if (als_high >= 0) {
