#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <stdint.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define ALS_DATA_REG 0x22
#define PROX_DATA_REG 0x24
#define LUX_CONVERSION_FACTOR 0.1
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int si1182_init(int fd);
int read_sensor_data(int fd, float *lux, int *proximity);
void log_data(FILE *fp, float lux, int proximity);
void signal_handler(int signum);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID register.\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02x\n", part_id);
        return -1;
    }

    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x07) != 0) {
        fprintf(stderr, "Error writing to MEAS_RATE_REG.\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, float *lux, int *proximity) {
    uint8_t data[4];

    if (i2c_read_block(fd, ALS_DATA_REG, data, 4) != 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    uint16_t raw_als = (data[1] << 8) | data[0];
    uint16_t raw_prox = (data[3] << 8) | data[2];

    *lux = raw_als * LUX_CONVERSION_FACTOR;
    *proximity = raw_prox;

    return 0;
}

// Function to log data to file
void log_data(FILE *fp, float lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (si1182_init(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (program_running) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            printf("Timestamp,Lux,Proximity: %s,%.2f,%d\n", __TIME__, lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100 ms
    }

    // Close resources before exiting
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

