#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PROXIMITY_REG_LOW 0x16
#define PROXIMITY_REG_HIGH 0x17
#define LOG_FILE "proximity_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
unsigned int read_proximity();
void log_data(unsigned int proximity);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Hardware Key
        status = i2cWriteByteData(i2c_handle, 0x07, 0x03);
        if (status < 0) {
            fprintf(stderr, "%s I2C write error (0x07, 0x03): %d\n", get_timestamp(), status);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // MEAS_RATE
        status = i2cWriteByteData(i2c_handle, 0x06, 0x02);
        if (status < 0) {
            fprintf(stderr, "%s I2C write error (0x06, 0x02): %d\n", get_timestamp(), status);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // No interrupt
        status = i2cWriteByteData(i2c_handle, 0x1A, 0x00);
        if (status < 0) {
            fprintf(stderr, "%s I2C write error (0x1A, 0x00): %d\n", get_timestamp(), status);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // ALS_VIS_IR_ADC_COUNTER
        status = i2cWriteByteData(i2c_handle, 0x21, 0x0B);
        if (status < 0) {
            fprintf(stderr, "%s I2C write error (0x21, 0x0B): %d\n", get_timestamp(), status);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // ALS_VIS_ADC_GAIN
        status = i2cWriteByteData(i2c_handle, 0x24, 0x00);
        if (status < 0) {
            fprintf(stderr, "%s I2C write error (0x24, 0x00): %d\n", get_timestamp(), status);
            retries--;
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // PS_ADC_COUNTER
