// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define BUZZER_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
volatile static unsigned int rising_edge_tick = 0;
volatile static unsigned int falling_edge_tick = 0;
volatile static int echo_received = 0;
static volatile double distance = 0.0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, unsigned int tick);
void activateBuzzer(double distance);
void printDistance();
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN high\n");
        gpioTerminate();
        exit(1);
    }
    gpioDelay(TRIGGER_PULSE_DURATION);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN low\n");
        gpioTerminate();
        exit(1);
    }
}

// Callback function for echo pin
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        rising_edge_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        falling_edge_tick = tick;
        echo_received = 2; // Indicate falling edge received
    }
}

// Function to activate the buzzer based on distance
void activateBuzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

// Function to print the distance to stdout
void printDistance() {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        triggerSensor();
        gpioDelay(50000); // Delay 50ms

        if (echo_received == 2) {
            // Calculate pulse width
            unsigned int pulse_width = falling_edge_tick - rising_edge_tick;

            // Calculate distance
            distance = (double)pulse_width * SPEED_OF_SOUND / 2.0;

            // Activate buzzer
            activateBuzzer(distance);

            // Print distance
            printDistance();

            echo_received = 0; // Reset echo_received flag
        }
    }

    return 0;
}

