#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 20.0      // Minimum distance in cm
#define MAX_DISTANCE 110.0     // Maximum distance in cm
#define MIN_PULSE_WIDTH 500    // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width in microseconds
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measureDistance();
void setServoAngle(float distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping servo and exiting.\n");
        program_running = 0;
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();         // Terminate pigpio
        exit(0);                // Exit the program
    }
}

// Function to measure distance using the HC-SR04 sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (start)\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (end)\n");
        return -1.0;
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 for us to s conversion, and by 2 for one-way distance

    return distance;
}

// Function to set the servo angle based on the measured distance
void setServoAngle(float distance) {
    float pulse_width;

    // Map distance to pulse width
    if (distance <= MIN_DISTANCE) {
        pulse_width = MAX_PULSE_WIDTH;
    } else if (distance >= MAX_DISTANCE) {
        pulse_width = MIN_PULSE_WIDTH;
    } else {
        pulse_width = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measureDistance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            setServoAngle(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    return 0;
}

