#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int open);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Verify sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set timing budget (example: 50ms)
    if (i2cWriteByteData(i2c_handle, 0x0088, 0x32) < 0) { // 0x0088 is VL53L1X_REG_SYSRANGE_START
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, 0x0088, 0x01) < 0) { // 0x0088 is VL53L1X_REG_SYSRANGE_START
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int distance = -1;
    int data_ready = i2cReadByteData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY);
    if (data_ready < 0) {
