        return -1;
    }

    if (data_ready & 0x01) {
        int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
