    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int gate_open = 0; // 0 = closed, 1 = open
    int distance;

    // Main loop
    while (program_running) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
            control_servo(1);
            log_event("Gate opened");
            gate_open = 1;
        } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            control_servo(0);
            log_event("Gate closed");
            gate_open = 0;
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    control_servo(0); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

