#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0     // Maximum measurable distance (cm)
#define MIN_ANGLE 0.0          // Minimum angle (degrees)
#define MAX_ANGLE 180.0         // Maximum angle (degrees)
#define TIMEOUT_US 50000        // Timeout for echo pulse (us)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
    program_running = 0;
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long start_tick = 0;
    long end_tick = 0;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (gpioTick() > timeout) {
            return -1; // Timeout
        }
    }
    start_tick = gpioTick();

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        if (gpioTick() - start_tick > timeout) {
            return -1; // Timeout
        }
    }
    end_tick = gpioTick();

    width = end_tick - start_tick;
    return width;
}

// Function to calculate the distance in centimeters
double calculateDistance(long pulse_duration_us) {
    if (pulse_duration_us <= 0) {
        return -1.0; // Invalid pulse duration
    }
    return (pulse_duration_us * 0.0343) / 2.0;
}

// Function to map the distance to a servo angle
int mapDistanceToAngle(double distance) {
    if (distance < MIN_DISTANCE) {
        return 0;
    } else if (distance > MAX_DISTANCE) {
        return 180;
    } else {
        // Linear mapping
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 180.0);
    }
}

// Function to set the servo angle
void setServoAngle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d)\n", angle);
        return;
    }

    // Calculate pulse width (500us - 2500us for 0-180 degrees)
    int pulse_width = (int)(500.0 + (angle / 180.0) * 2000.0);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_duration_us = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        // Calculate the distance
        double distance = calculateDistance(pulse_duration_us);

        // Map the distance to a servo angle
        int angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the results
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

