#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define SI7005_CONFIG_REG 0x03
#define SI7005_TEMP_REG 0x01
#define SI7005_HUMIDITY_REG 0x02

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si7005 sensor
int init_si7005()
{
    // Write to the configuration register to select internal temperature sensor and disable heater
    if (i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to configuration register.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_si7005(float *temperature, float *humidity)
{
    unsigned char raw_temperature, raw_humidity;

    // Read temperature register
    if (i2cWriteByte(i2c_handle, SI7005_TEMP_REG) < 0) {
        fprintf(stderr, "Error writing to temperature register.\n");
        return -1;
    }
