#include <pigpio.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }
    printf("MPU-6050 WHO_AM_I register value: 0x%x\n", who_am_i);

    // Reset the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear sleep bit
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x01) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }

    // Set sample-rate divider
    if (i2cWriteByteData(i2c_handle, 0x19, 0x07) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV register\n");
        return -1;
    }

    // Configure accelerometer range
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG register\n");
        return -1;
    }

    // Configure gyroscope range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14);
    if (result < 0) {
        fprintf(stderr, "Error reading data from MPU-6050: %d\n", result);
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("AccelX: %6d, AccelY: %6d, AccelZ: %6d, GyroX: %6d, GyroY: %6d, GyroZ: %6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read MPU-6050 data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

