#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command for high repeatability measurement
#define SHT40_MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, SHT40_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate temperature CRC
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    // Validate humidity CRC
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC error\n");
        return -1;
    }

    // Convert raw temperature to Celsius
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;

    // Convert raw humidity to percentage
    uint16_t raw_humidity = (data[3] << 8) | data[4];
    *humidity = -6.0 + 125.0 * raw_humidity / 65535.0;
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int retries = 3; // Number of retries for I2C communication

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Retry loop for I2C communication
        for (int i = 0; i < retries; i++) {
            if (read_sht40(&temperature, &humidity) == 0) {
                // Print temperature and humidity
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i + 1, retries);
                // Close I2C bus and reopen it
                i2cClose(i2c_handle);
                i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                    gpioTerminate();
                    return 1;
                }
                gpioDelay(1000000); // Wait 1 second before retrying
            }
        }

        if (i == retries) {
            fprintf(stderr, "Failed to read SHT40 after %d retries\n", retries);
        }

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // This point should not be reached due to the infinite loop
    return 0;
}

