                i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                    gpioTerminate();
                    return 1;
                }
                gpioDelay(1000000); // Wait 1 second before retrying
            }
        }

        if (i == retries) {
            fprintf(stderr, "Failed to read SHT40 after %d retries\n", retries);
        }

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // This point should not be reached due to the infinite loop
    return 0;
}

