#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void log_temperature(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    int sample_interval;
    char log_file_name[64];
    char error_log_file_name[64];
} config_t;

config_t config = {
    I2C_BUS,
    STS30_ADDR,
    SAMPLE_INTERVAL_SEC,
    LOG_FILE,
    ERROR_LOG_FILE
};

// Function to read temperature from the STS30-DIS sensor
float read_temperature() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command to sensor.");
        return -1000.0; // Indicate error
    }

    gpioDelay(20); // Wait for measurement (at least 20ms)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        log_error("Failed to read temperature data from sensor.");
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int raw_temperature = (buf[0] << 8) | buf[1];
    float temperature = -45.0 + (175.0 * raw_temperature) / 65535.0;

    return temperature;
}

// Function to log temperature to a file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(config.error_log_file_name, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature.");
        }
        gpioSleep(PI_TIME_RELATIVE, config.sample_interval, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

