#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x36
#define CONTINUOUS_MEASUREMENT_ARG 0x08
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint8_t command, uint8_t arg);
int read_sensor_data(int handle, uint8_t *data);
int validate_crc(uint8_t *data, int offset, uint8_t checksum);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Sends a command to the sensor
int send_command(int handle, uint8_t command, uint8_t arg) {
    char buf[2];
    buf[0] = command;
    buf[1] = arg;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Wait at least 1 ms
    return 0;
}

// Reads data from the sensor
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Validates the CRC-8 checksum
int validate_crc(uint8_t *data, int offset, uint8_t checksum) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < 2; i++) {
        crc ^= data[offset + i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != checksum) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc, checksum);
        return -1;
    }

    return 0;
}

// Converts raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factors
    uint16_t pressure_scale_factor = (data[6] << 8) | data[7];
    uint16_t temperature_scale_factor = (data[8] << 8) | data[9];

    // Convert raw values to physical units
    sensor_data.pressure = (float)raw_pressure / pressure_scale_factor;
    sensor_data.temperature = (float)raw_temperature / temperature_scale_factor;

    return sensor_data;
}

// Logs the data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD, CONTINUOUS_MEASUREMENT_ARG) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

