        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char addr, unsigned char data) {
    unsigned char buf[2];
    buf[0] = addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char addr, unsigned char *data, int count) {
    if (write(fd, &addr, 1) != 1) {
        perror("Error writing address for read");
        return -1;
    }
    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

