    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Starting SHT40 data logging...\n");

    while (!terminate) {
        unsigned char data[6];
        unsigned char temp_crc, humidity_crc;
        unsigned short raw_temperature, raw_humidity;
        float temperature, humidity;
        int retries = 0;

        // Retry loop for I2C communication
        while (retries < RETRY_COUNT) {
