                fflush(log_file);
                sleep(1); // Wait before retrying
                retries++;
            }
        }

        if (retries == RETRY_COUNT) {
            fprintf(log_file, "Failed to write to I2C after %d retries. Skipping.\n", RETRY_COUNT);
            fflush(log_file);
            sleep(5);
            continue; // Skip to the next iteration
        }

