        if (retries == RETRY_COUNT) {
            fprintf(log_file, "Failed to read from I2C after %d retries. Skipping.\n", RETRY_COUNT);
            fflush(log_file);
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Extract temperature and humidity data
        raw_temperature = (data[0] << 8) | data[1];
        raw_humidity = (data[3] << 8) | data[4];

        // CRC validation
        temp_crc = crc8(data, 2);
        humidity_crc = crc8(data + 3, 2);

        if (temp_crc != data[2]) {
            fprintf(log_file, "Temperature CRC error: calculated 0x%02X, received 0x%02X\n", temp_crc, data[2]);
