#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define MEASUREMENT_DELAY_MS 20
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c(int handle, int data);
int read_i2c(int handle, char *buf, int count);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error());
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c(int handle, int data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c(int handle, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buf, count);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to relative humidity
float convert_humidity(unsigned int raw_humidity) {
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting sensor data logging...\n");

    while (!terminate) {
        // Read temperature
        char temp_buf[2];
        if (write_i2c(i2c_handle, TEMP_CMD) == 0) {
            gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
            if (read_i2c(i2c_handle, temp_buf, 2) == 2) {
                unsigned int raw_temp = (temp_buf[0] << 8) | temp_buf[1];
                float temperature = convert_temperature(raw_temp);
                printf("Temperature: %.2f C\n", temperature);
                log_data(temperature, -1.0); // Log temperature, humidity = -1.0 indicates temperature reading
            } else {
                fprintf(stderr, "Failed to read temperature data\n");
            }
        } else {
            fprintf(stderr, "Failed to write temperature command\n");
        }

        // Read humidity
        char humid_buf[2];
        if (write_i2c(i2c_handle, HUMID_CMD) == 0) {
            gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
            if (read_i2c(i2c_handle, humid_buf, 2) == 2) {
                unsigned int raw_humidity = (humid_buf[0] << 8) | humid_buf[1];
                float humidity = convert_humidity(raw_humidity);
                printf("Humidity: %.2f %%RH\n", humidity);
                log_data(-1.0, humidity); // Log humidity, temperature = -1.0 indicates humidity reading
            } else {
                fprintf(stderr, "Failed to read humidity data\n");
            }
        } else {
            fprintf(stderr, "Failed to write humidity command\n");
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

