#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define sensor-specific constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x03
#define SCALE_FACTOR_REG 0x06
#define CRC8_POLYNOMIAL 0x31

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int i2c_write(int fd, unsigned char command);
int i2c_read(int fd, unsigned char reg, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
int validate_crc(unsigned char data[], int len);
sensor_data_t read_sensor_data(int fd);
float convert_pressure(int raw_pressure, int scale_factor);
float convert_temperature(int raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signum);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char command) {
    unsigned char buf[1];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// CRC8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(unsigned char data[], int len) {
    for (int i = 0; i < len; i += 3) {
        unsigned char crc = crc8(data + i, 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC validation failed for register 0x%02X\n", i);
            return -1;
        }
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    unsigned char data[9];
    sensor_data_t sensor_data;

    if (i2c_write(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        sensor_data.pressure = 0.0;
        sensor_data.temperature = 0.0;
        return sensor_data;
    }

    usleep(45000); // Wait for measurement (45 ms)

    if (i2c_read(fd, PRESSURE_REG, data, 9) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        sensor_data.pressure = 0.0;
        sensor_data.temperature = 0.0;
        return sensor_data;
    }

    if (validate_crc(data, 9) < 0) {
        fprintf(stderr, "CRC validation failed\n");
        sensor_data.pressure = 0.0;
        sensor_data.temperature = 0.0;
        return sensor_data;
    }

    // Extract raw data
    int raw_pressure = (data[0] << 8) | data[1];
    int raw_temperature = (data[3] << 8) | data[4];
    int scale_factor = (data[6] << 8) | data[7];

    // Convert data
    sensor_data.pressure = convert_pressure(raw_pressure, scale_factor);
    sensor_data.temperature = convert_temperature(raw_temperature);

    return sensor_data;
}

// Function to convert raw pressure to Pa
float convert_pressure(int raw_pressure, int scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Function to convert raw temperature to °C
float convert_temperature(int raw_temperature) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// Function to log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
