        fprintf(stderr, "Error reading sensor data\n");
        sensor_data.pressure = 0.0;
        sensor_data.temperature = 0.0;
        return sensor_data;
    }

    if (validate_crc(data, 9) < 0) {
        fprintf(stderr, "CRC validation failed\n");
        sensor_data.pressure = 0.0;
        sensor_data.temperature = 0.0;
        return sensor_data;
    }

    // Extract raw data
    int raw_pressure = (data[0] << 8) | data[1];
    int raw_temperature = (data[3] << 8) | data[4];
    int scale_factor = (data[6] << 8) | data[7];

    // Convert data
    sensor_data.pressure = convert_pressure(raw_pressure, scale_factor);
    sensor_data.temperature = convert_temperature(raw_temperature);

    return sensor_data;
