int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read temperature from STS30 sensor
int read_sts30(float *temperature) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char data[3];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(15); // Wait for conversion (at least 15 ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    // Validate CRC
    if (!validate_crc(data, 2)) {
        log_error("CRC validation failed");
        return -1;
    }

    // Convert raw value to Celsius
    unsigned int raw_value = (data[0] << 8) | data[1];
    *temperature = convert_to_celsius(raw_value);

    return 0;
}

// Convert raw value to Celsius
float convert_to_celsius(unsigned int raw_value) {
    return -45.0 + 175.0 * (raw_value / 65535.0);
}

