        fclose(log_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature;

    // Main loop
    while (1) {
        if (read_sts30(&temperature) == 0) {
