#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *bus);
int i2c_ioctl(int fd, int action, unsigned short reg, unsigned char *data, int len);
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
unsigned char crc8(const unsigned char *data, int len);
int log_data(float temperature, float humidity);
void signal_handler(int signum);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C ioctl function
int i2c_ioctl(int fd, int action, unsigned short reg, unsigned char *data, int len) {
    if (ioctl(fd, action, reg) < 0) {
        perror("Error using ioctl");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Temperature conversion function
float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Humidity conversion function
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Data logging function
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        unsigned char data[6];
        unsigned char cmd[1] = {MEASURE_CMD};
        unsigned short raw_temperature, raw_humidity;
        float temperature, humidity;
        int retries = 3; // Number of retries for I2C communication

        // Send measurement command
        while (retries > 0) {
            if (i2c_write(i2c_fd, cmd, 1) == 0) {
                break; // Success, exit retry loop
            }
            retries--;
            sleep(1); // Wait before retrying
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to send measurement command after multiple retries. Exiting.\n");
            break;
        }

        // Wait for measurement to complete (at least 8.5 ms)
        usleep(8500); // 8500 microseconds = 8.5 milliseconds

        // Read sensor data
        retries = 3;
        while (retries > 0) {
            if (i2c_read(i2c_fd, data, 6) == 0) {
                break; // Success, exit retry loop
