            break;
        }

        // Validate CRC for temperature
        unsigned char temp_data[2] = {data[0], data[1]};
        unsigned char temp_crc = data[2];
        if (crc8(temp_data, 2) != temp_crc) {
            fprintf(stderr, "Temperature CRC check failed!\n");
            continue; // Skip to the next iteration
        }

        // Validate CRC for humidity
        unsigned char humidity_data[2] = {data[3], data[4]};
        unsigned char humidity_crc = data[5];
        if (crc8(humidity_data, 2) != humidity_crc) {
            fprintf(stderr, "Humidity CRC check failed!\n");
            continue; // Skip to the next iteration
        }

        // Convert raw data to temperature and humidity
        raw_temperature = (data[0] << 8) | data[1];
        raw_humidity = (data[3] << 8) | data[4];

