FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int read_sdp800(int fd, float *pressure, float *temperature);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
int validate_crc(unsigned char data[], int len, unsigned char checksum);
void log_data(float pressure, float temperature);
