// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from SDP800 sensor
int read_sdp800(int fd, float *pressure, float *temperature) {
    unsigned char cmd[2] = {(CMD_MEASURE_CONTINUOUS >> 8) & 0xFF, CMD_MEASURE_CONTINUOUS & 0xFF};
    unsigned char data[6];

    if (i2c_write(fd, cmd, 2) != 0) {
        fprintf(stderr, "Error writing to SDP800\n");
        return -1;
    }

    usleep(1000); // Wait for measurement (at least 1 ms)

    if (i2c_read(fd, data, 6) != 0) {
        fprintf(stderr, "Error reading from SDP800\n");
        return -1;
    }

    // Validate CRC for pressure data
    if (validate_crc(data, 2, data[2]) != 0) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return -1;
    }

    // Validate CRC for temperature data
    if (validate_crc(data + 3, 2, data[5]) != 0) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int raw_pressure = (data[0] << 8) | data[1];
    int raw_temperature = (data[3] << 8) | data[4];

    *pressure = convert_pressure(raw_pressure);
    *temperature = convert_temperature(raw_temperature);

    return 0;
}

