#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t command, uint16_t *raw_data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void control_fan(float temperature);
void add_reading(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t command, uint16_t *raw_data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, command);
        if (result != 0) {
            fprintf(stderr, "Error writing command 0x%02X: %d\n", command, result);
            gpioDelay(1000); // Wait 1ms before retry
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)raw_data, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading data: %d\n", result);
            gpioDelay(1000); // Wait 1ms before retry
            retries--;
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to convert temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Function to convert humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Function to control the fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to add a reading to the circular buffer
void add_reading(float temperature, float humidity) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char time_str[64];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temp: %.2f C, Humidity: %.2f %%\n", time_str, buffer[i].temperature, buffer[i].humidity);
    }
    printf("-----------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (program_running) {
        // Read temperature
        if (read_sensor_data(0xE3, &raw_temp) == 0) {
            temperature = convert_temperature(raw_temp);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(0xE5, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Control fan
        control_fan(temperature);

        // Add reading to buffer
        add_reading(temperature, humidity);

        // Print buffer
        print_buffer();

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

