#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xEC05
#define DATA_READY 0xE4B8

// CRC-8 polynomial and initialization value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data);
int verify_checksum(uint8_t *data, int count);
sensor_data_t read_sensor_data(int handle);
char *format_data(sensor_data_t data);
int log_data(char *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Send a command to the SCD40
int send_command(int handle, uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < 8; i++) {
        if ((crc ^ data) & 0x80) {
            crc = (crc << 1) ^ CRC_POLYNOMIAL;
        } else {
            crc <<= 1;
        }
        data <<= 1;
    }
    return crc;
}

// Verify checksum for each 2-byte word
int verify_checksum(uint8_t *data, int count) {
    for (int i = 0; i < count / 2; i++) {
        uint16_t word = (data[i * 2] << 8) | data[i * 2 + 1];
        uint8_t crc = calculate_crc(word);
        if (crc != data[i * 2 + 2]) {
            fprintf(stderr, "Checksum verification failed for word 0x%04X\n", word);
            return -1;
        }
    }
    return 0;
}

// Read sensor data from the SCD40
sensor_data_t read_sensor_data(int handle) {
    uint8_t data[9];
    sensor_data_t sensor_data;

    // Check data ready flag
    uint8_t data_ready_flag[2];
    if (send_command(handle, DATA_READY) != 0) {
        sensor_data.co2 = 0; // Indicate error
        sensor_data.temperature = 0;
        sensor_data.humidity = 0;
        return sensor_data;
    }
    if (read_data(handle, data_ready_flag, 2) != 0) {
        sensor_data.co2 = 0; // Indicate error
        sensor_data.temperature = 0;
        sensor_data.humidity = 0;
        return sensor_data;
    }
    if ((data_ready_flag[0] << 8 | data_ready_flag[1]) != 0xE4B8) {
        fprintf(stderr, "Data not ready\n");
        sensor_data.co2 = 0; // Indicate error
        sensor_data.temperature = 0;
        sensor_data.humidity = 0;
        return sensor_data;
    }

    if (send_command(handle, READ_MEASUREMENT) != 0) {
        sensor_data.co2 = 0; // Indicate error
        sensor_data.temperature = 0;
        sensor_data.humidity = 0;
        return sensor_data;
    }

    if (read_data(handle, data, 9) != 0) {
        sensor_data.co2 = 0; // Indicate error
        sensor_data.temperature = 0;
        sensor_data.humidity = 0;
        return sensor_data;
    }

    if (verify_checksum(data, 9) != 0) {
        sensor_data.co2 = 0; // Indicate error
        sensor_data.temperature = 0;
        sensor_data.humidity = 0;
        return sensor_data;
    }

    sensor_data.co2 = (data[0] << 8) | data[1];
    sensor_data.temperature = (data[3] << 8) | data[4];
    sensor_data.humidity = (data[6] << 8) | data[7];

    return sensor_data;
}

// Format sensor data as a CSV string
char *format_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char buffer[256]; // Static buffer to avoid memory allocation issues
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ",%d,%d,%d\n", data.co2, data.temperature, data.humidity);
    return buffer;
}

// Log data to file
int log_data(char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
    if (fprintf(log_file, "%s", data) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c(1, SCD40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data(i2c_handle);

        // Format data
        char *data_string = format_data(sensor_data);

        // Log data
        if (log_data(data_string) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

