#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define TIMEOUT_US 50000   // 50ms
#define MAX_FAILURES 3
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold timestamp data
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
} Timestamps;

// Function prototypes
double calculate_temperature(uint32_t rising_edge, uint32_t falling_edge, uint32_t total_cycle);
int log_temperature(double temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio and log file
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Calculate temperature from pulse width and total cycle
double calculate_temperature(uint32_t rising_edge, uint32_t falling_edge, uint32_t total_cycle) {
    if (total_cycle == 0) {
        return -999.0; // Indicate division by zero
    }

    double temperature = 4215.0 - (2143.0 * (double)(falling_edge - rising_edge) / (double)total_cycle);
    return temperature;
}

// Log temperature to file with ISO-8601 timestamp
int log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        fprintf(log_file, "%s ERROR: Temperature out of range: %.2f\n", timestamp, temperature);
        fflush(log_file);
        return 1; // Indicate error
    }

    fprintf(log_file, "%s Temperature: %.2f\n", timestamp, temperature);
    fflush(log_file);
    return 0; // Indicate success
}

int main() {
    int failures = 0;
    Timestamps timestamps = {0, 0};
    uint32_t start_time, end_time, pulse_width, total_cycle;
    double temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Measure pulse width and total cycle
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            end_time = gpioTick();
            if (end_time - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for rising edge\n");
                break;
            }
        }
        if (gpioRead(GPIO_PIN) != 1) continue; // Skip if timeout

        timestamps.rising_edge = end_time;

        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            end_time = gpioTick();
            if (end_time - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for falling edge\n");
                break;
            }
        }
        if (gpioRead(GPIO_PIN) != 0) continue; // Skip if timeout

        timestamps.falling_edge = end_time;

        pulse_width = timestamps.falling_edge - timestamps.rising_edge;
        total_cycle = timestamps.falling_edge - timestamps.rising_edge;

        // Calculate temperature
        temperature = calculate_temperature(timestamps.rising_edge, timestamps.falling_edge, total_cycle);

        if (temperature == -999.0) {
            fprintf(stderr, "Error: Division by zero in temperature calculation\n");
            failures++;
        } else {
            // Log temperature
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error: Failed to log temperature\n");
                failures++;
            } else {
                failures = 0; // Reset failure count on success
            }
        }

        if (failures >= MAX_FAILURES) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s SENSOR MALFUNCTION\n", timestamp);
            fflush(log_file);
            failures = MAX_FAILURES; // Prevent further logging attempts
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for sample interval
    }

    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

