        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int len) {
    unsigned char crc;
    for (int i = 0; i < len; i += 3) {
        crc = CRC_INITIAL;
        unsigned char byte = data[i];
        for (int j = 0; j < 8; j++) {
