                fprintf(stderr, "CRC validation failed, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

