#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP 0xF3
#define MEASURE_HUMIDITY 0xF5
#define MEASURE_TEMP_HUMIDITY 0xE0
#define RESET_COMMAND 0xFE
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define TIMEOUT_MS 100
#define LOG_INTERVAL_S 5

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, unsigned char command);
int i2c_read(int fd, unsigned char *data, int count);
unsigned char crc8(const unsigned char *data, int len);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int sig);
int reset_sensor(int fd);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char command) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            return -1;
        }
        if (write(fd, &command, 1) == 1) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write failed, retrying...\n");
        usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
        retries--;
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int count) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            return -1;
        }
        ssize_t bytes_read = read(fd, data, count);
        if (bytes_read == count) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read failed, retrying...\n");
        usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
        retries--;
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion
float convert_temperature(unsigned int raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Humidity conversion
float convert_humidity(unsigned int raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen("environment.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Reset sensor function
int reset_sensor(int fd) {
    if (i2c_write(fd, RESET_COMMAND) != 0) {
        fprintf(stderr, "Error resetting sensor.\n");
        return -1;
    }
    usleep(10000); // Wait for reset to complete (10ms)
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        unsigned char data[3];
        unsigned int raw_temp, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (i2c_write(i2c_fd, MEASURE_TEMP) == 0) {
            if (i2c_read(i2c_fd, data, 3) == 0) {
                raw_temp = (data[0] << 8) | data[1];
                unsigned char crc = crc8(data, 2);
                if (crc != data[2]) {
                    fprintf(stderr, "Temperature CRC error!\n");
                    log_data(-999.0, -999.0); // Log error
                } else {
                    temperature = convert_temperature(raw_temp);
                }
            } else {
                fprintf(stderr, "Failed to read temperature data.\n");
                log_data(-999.0, -999.0); // Log error
            }
        } else {
            fprintf(stderr, "Failed to trigger temperature measurement.\n");
            log_data(-999.0, -999.0); // Log error
        }

        // Read humidity
        if (i2c_write(i2c_fd, MEASURE_HUMIDITY) == 0) {
            if (i2c_read(i2c_fd, data, 3) == 0) {
                raw_humidity = (data[0] << 8) | data[1];
                unsigned char crc = crc8(data, 2);
                if (crc != data[2]) {
                    fprintf(stderr, "Humidity CRC error!\n");
                    log_data(-999.0, -999.0); // Log error
                } else {
                    humidity = convert_humidity(raw_humidity);
                }
            } else {
                fprintf(stderr, "Failed to read humidity data.\n");
                log_data(-999.0, -999.0); // Log error
            }
        } else {
            fprintf(stderr, "Failed to trigger humidity measurement.\n");
            log_data(-999.0, -999.0); // Log error
        }

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next interval
        sleep(LOG_INTERVAL_S);
    }

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

