#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the continuous measurement command
#define MEASURE_COMMAND 0x362F

// Global variables for graceful shutdown
int i2c_handle = -1;
FILE *fp = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
float convert_pressure(int16_t raw_pressure, uint8_t scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C connection
int open_i2c_connection() {
    int handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write the measurement command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw pressure to Pascal
float convert_pressure(int16_t raw_pressure, uint8_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor - 1000.0f;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0f - 45.0f;
}

// Function to log data to a file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the I2C connection
    i2c_handle = open_i2c_connection();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open the data file in binary write mode
    fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t data[9];
        int16_t raw_pressure, raw_temperature;
        uint8_t scale_factor[3];
        uint8_t pressure_crc, temperature_crc;

        // Write the measurement command
        if (write_command(i2c_handle, MEASURE_COMMAND) != 0) {
            break;
        }

        // Wait for the conversion time (at least 20ms)
        gpioDelay(20000); // 20ms

        // Read the sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            break;
        }

        // Extract raw data and CRC values
        raw_pressure = (int16_t)((data[0] << 8) | data[1]);
        pressure_crc = data[2];
        raw_temperature = (int16_t)((data[3] << 8) | data[4]);
        temperature_crc = data[5];
        scale_factor[0] = data[6];
        scale_factor[1] = data[7];
        scale_factor[2] = data[8];

        // Validate CRC checksums
        uint8_t pressure_data[2] = {data[0], data[1]};
        uint8_t temperature_data[2] = {data[3], data[4]};

        if (calculate_crc(pressure_data, 2) != pressure_crc) {
            fprintf(stderr, "Pressure CRC check failed\n");
            break;
        }

        if (calculate_crc(temperature_data, 2) != temperature_crc) {
            fprintf(stderr, "Temperature CRC check failed\n");
            break;
        }

        // Convert raw data to physical units
        float pressure = convert_pressure(raw_pressure, scale_factor[0]);
        float temperature = convert_temperature(raw_temperature);

        // Log the data
        if (log_data(fp, pressure, temperature) != 0) {
            break;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close the I2C connection and terminate pigpio
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
