#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CMD_CONTINUOUS 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], int len);
float convert_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc_table[] = {0x31, 0x42, 0x53, 0x64, 0x75, 0x86, 0x97, 0xA8, 0xB9, 0xC2, 0xD3, 0xE4, 0xF5, 0x06, 0x17, 0x28};
    for (int i = 0; i < len - 1; i++) {
        uint8_t index = data[i];
        uint8_t crc = data[i + 1];
        if (crc_table[index] != crc) {
            fprintf(stderr, "CRC validation failed for byte %d: expected 0x%02X, got 0x%02X\n", i, crc_table[index], crc);
            return -1;
        }
    }
    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

// Log data to file
int log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CMD_CONTINUOUS) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        // Wait for conversion time (45ms)
        gpioDelay(45000); // 45ms

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(data, 9) != 0) {
            fprintf(stderr, "CRC validation failed, skipping data point...\n");
            gpioDelay(READ_INTERVAL_SEC * 1000000); // Wait before next read
            continue;
        }

        // Extract raw data
        sensor_data_t sensor_data;
        sensor_data.pressure = (int16_t)((data[0] << 8) | data[1]);
        sensor_data.temperature = (int16_t)((data[3] << 8) | data[4]);
        sensor_data.status = (uint16_t)((data[6] << 8) | data[7]);

        // Convert pressure to Pascals
        float pressure = convert_pressure(sensor_data.pressure);

        // Log data
        if (log_data(pressure) != 0) {
            fprintf(stderr, "Error logging data...\n");
        }

        // Wait before next read
        gpioDelay(READ_INTERVAL_SEC * 1000000); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

