#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // Hz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Sensor calibration parameters
#define ZERO_OFFSET 1638
#define SENSITIVITY 0.75

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor(int *raw_flow);
float convert_to_flow(int raw_flow);
void control_fan(float flow_rate);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int raw_flow;
    float flow_rate;
    float pressure;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_sensor(&sensor_data.raw_flow) == 0) {
            sensor_data.flow_rate = convert_to_flow(sensor_data.raw_flow);
            sensor_data.pressure = sensor_data.flow_rate * SENSITIVITY; // Convert flow to pressure
            control_fan(sensor_data.flow_rate);
            log_data(sensor_data.pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

