    char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }

    // Combine the two bytes into a 16-bit word
    *raw_flow = (buffer[0] << 8) | buffer[1];

    // Mask off status bits and shift right by 2
    *raw_flow = (*raw_flow & 0x3FFF) >> 2;

    return 0;
}

float convert_to_flow(int raw_flow) {
    // Linear transfer function
    float flow_rate = ((float)(raw_flow - ZERO_OFFSET) / (14745.0 - ZERO_OFFSET)) * 10.0;
    return flow_rate;
}

