    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    // Turn off the fan
    gpioPWM(FAN_GPIO, 0);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Flush and close log file
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

