#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_register(int handle, uint8_t reg, uint8_t *value);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_block(int handle, uint8_t reg, char *buf, int len);
int verify_who_am_i(int handle);
int configure_sensor(int handle);
sensor_data_t read_sensor_data(int handle);
char* format_data(sensor_data_t data, char *buffer, size_t buffer_size);
void log_data(const char *data);
void signal_handler(int signal);
int create_log_file();
void close_resources();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read a single register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a single register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a block of registers
int read_block(int handle, uint8_t reg, char *buf, int len) {
    int result = i2cReadI2CBlockData(handle, reg, buf, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to verify the WHO_AM_I register
int verify_who_am_i(int handle) {
    uint8_t who_am_i;
    if (read_register(handle, WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xB1\n", who_am_i);
        return -1;
    }
    return 0;
}

// Function to configure the sensor
int configure_sensor(int handle) {
    if (write_register(handle, CTRL_REG1, 0xB0) != 0) {
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int handle) {
    sensor_data_t data;
    char buffer[6];

    if (read_block(handle, PRESS_OUT_XL, buffer, 6) != 0) {
        data.pressure = -1.0; // Indicate error
        data.temperature = -1.0;
        return data;
    }

    int32_t raw_pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | (uint32_t)buffer[0]);
    int16_t raw_temperature = (int16_t)(((uint16_t)buffer[4] << 8) | (uint16_t)buffer[5]);

    data.pressure = (float)raw_pressure / 4096.0;
    data.temperature = 42.5 + (float)raw_temperature / 480.0;

    return data;
}

// Function to format sensor data into a string
char* format_data(sensor_data_t data, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, buffer_size, "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ", Pressure: %.2f hPa, Temperature: %.2f °C", data.pressure, data.temperature);
    return buffer;
}

// Function to log data to a file
void log_data(const char *data) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", data);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to create the log file
int create_log_file() {
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to close resources before exiting
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Create log file
    if (create_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        close_resources();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(i2c_handle) != 0) {
        close_resources();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        close_resources();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data(i2c_handle);

        // Format data
        char data_string[256];
        format_data(data, data_string, sizeof(data_string));

        // Log data
        log_data(data_string);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close resources
    close_resources();

    return 0;
}

