#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_CONT_MEAS 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_DATA_READY 0x0202

// SCD30 data structure
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} scd30_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_scd30();
int read_scd30_data(scd30_data_t *data);
void log_data(scd30_data_t data);
void control_ventilation(int co2_ppm);
void signal_handler(int signal);

// CRC-8 checksum function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SCD30 sensor
int initialize_scd30() {
    // Start continuous measurement with ambient pressure compensation disabled
    char buf[2];
    buf[0] = (SCD30_CMD_START_CONT_MEAS >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_CONT_MEAS & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD30: %d\n", result);
        return -1;
    }

    // Verify CRC for the start command
    uint8_t crc = crc8((uint8_t *)buf, 2);
    uint8_t received_crc = i2cReadByteData(i2c_handle, 1); // Read CRC byte
    if (received_crc == 0xFF) {
        fprintf(stderr, "Error reading CRC from SCD30\n");
        return -1;
    }
    if (crc != received_crc) {
        fprintf(stderr, "CRC mismatch for start command\n");
        return -1;
    }

    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(scd30_data_t *data) {
    // Check data ready status
    char buf[2];
    buf[0] = (SCD30_CMD_DATA_READY >> 8) & 0xFF;
    buf[1] = SCD30_CMD_DATA_READY & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing data ready command: %d\n", result);
        return -1;
    }

    uint8_t ready_status = i2cReadByteData(i2c_handle, 0); // Read status byte
    if (ready_status == 0) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read measurement data
    result = i2cWriteDevice(i2c_handle, (char[]){(SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF, SCD30_CMD_READ_MEASUREMENT & 0xFF}, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read measurement command: %d\n", result);
        return -1;
    }

    uint8_t buffer[18];
    result = i2cReadDevice(i2c_handle, (char *)buffer, 18);
    if (result != 18) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    // Verify CRC for CO2
    uint8_t co2_data[2] = {buffer[0], buffer[1]};
    uint8_t co2_crc = crc8(co2_data, 2);
    if (co2_crc != buffer[2]) {
        fprintf(stderr, "CRC mismatch for CO2 data\n");
        return -1;
    }

    // Verify CRC for Temperature
    uint8_t temp_data[2] = {buffer[3], buffer[4]};
    uint8_t temp_crc = crc8(temp_data, 2);
    if (temp_crc != buffer[5]) {
        fprintf(stderr, "CRC mismatch for Temperature data\n");
        return -1;
    }

    // Verify CRC for Humidity
    uint8_t humidity_data[2] = {buffer[6], buffer[7]};
    uint8_t humidity_crc = crc8(humidity_data, 2);
    if (humidity_crc != buffer[8]) {
        fprintf(stderr, "CRC mismatch for Humidity data\n");
        return -1;
    }

    // Extract data
    data->co2 = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[3] << 8) | buffer[4];
    data->humidity = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Function to log data to a file
void log_data(scd30_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

// Function to control the ventilation system
void control_ventilation(int co2_ppm) {
    if (co2_ppm < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2_ppm < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 0;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    // Initialize SCD30 sensor
    if (initialize_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    scd30_data_t data;

    // Main loop
    while (!terminate) {
        if (read_scd30_data(&data) == 0) {
            log_data(data);
            control_ventilation(data.co2);
        } else {
            fprintf(stderr, "Failed to read SCD30 data\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Stop continuous measurement
    char buf[2];
    buf[0] = (SCD30_CMD_START_CONT_MEAS >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_CONT_MEAS & 0xFF;
    i2cWriteDevice(i2c_handle, buf, 2);

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

