#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// SDP32 continuous measurement command
#define SDP32_MEASURE_CMD_MSB 0x36
#define SDP32_MEASURE_CMD_LSB 0x2F

// Scaling factor for pressure (Pa)
#define PRESSURE_SCALE_FACTOR 60.0

// Global variables
int i2c_handle;
int sampling_interval_ms = 1000; // Default sampling interval
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_measurement();
int read_sensor_data(sensor_data_t *data);
int verify_checksum(uint8_t data[], int len);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SDP32_ADDR, 0); // Bus 1, address 0x21, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement on the SDP32
int start_measurement() {
    char cmd[2] = {SDP32_MEASURE_CMD_MSB, SDP32_MEASURE_CMD_LSB};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP32
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
