// SDP810 continuous measurement command
#define SDP810_MEASURE_CMD 0x3615

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// CRC-8 initial value
#define CRC_INITIAL_VALUE 0xFF

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {(SDP810_MEASURE_CMD >> 8) & 0xFF, SDP810_MEASURE_CMD & 0xFF};
    uint8_t data[9];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 45 ms)
    gpioDelay(45000); // 45 ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure data
    if (crc8(data, 3) != data[3]) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }

    // Validate CRC for temperature data
    if (crc8(data + 3, 3) != data[6]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }

    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factors
    uint16_t scale_factor_pressure = (data[1] << 8) | data[2];
    uint16_t scale_factor_temperature = (data[4] << 8) | data[5];

    // Convert raw values to physical units
    *pressure = (float)raw_pressure / (float)scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;

    // Main loop
    while (1) {
        // Read data from the sensor
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            // Print the results
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

