#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define MEASUREMENT_DELAY_MS 20
#define READ_DELAY_SEC 5

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_write(int fd, unsigned char reg, unsigned char value);
int i2c_read(int fd, unsigned char reg, unsigned char *data, int len);
int configure_hdc1000(int fd);
sensor_data_t read_hdc1000(int fd);
void log_data(sensor_data_t data);
void signal_handler(int sig);

// I2C write function
int i2c_write(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure HDC1000
int configure_hdc1000(int fd) {
    if (i2c_write(fd, CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Error configuring HDC1000\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1000
sensor_data_t read_hdc1000(int fd) {
    unsigned char data[4];
    sensor_data_t data_read;

    if (i2c_write(fd, TEMP_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing temperature register address\n");
        data_read.temperature = -999.0; // Indicate error
        data_read.humidity = -999.0;
        return data_read;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    if (i2c_read(fd, 0x00, data, 4) != 0) {
        fprintf(stderr, "Error reading temperature and humidity data\n");
        data_read.temperature = -999.0; // Indicate error
        data_read.humidity = -999.0;
        return data_read;
    }

    // Combine the two bytes for temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[2] << 8) | data[3];

    // Convert raw values to temperature and humidity
    data_read.temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    data_read.humidity = (float)raw_humidity / 65536.0 * 100.0;

    return data_read;
}

// Log data to console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, closing I2C device and exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    terminate = 1;
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure HDC1000
    if (configure_hdc1000(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_hdc1000(i2c_fd);
        if (data.temperature != -999.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", READ_DELAY_SEC);
        }
        sleep(READ_DELAY_SEC);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

