    data_read.humidity = (float)raw_humidity / 65536.0 * 100.0;

    return data_read;
}

// Log data to console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, closing I2C device and exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    terminate = 1;
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure HDC1000
    if (configure_hdc1000(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_hdc1000(i2c_fd);
        if (data.temperature != -999.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", READ_DELAY_SEC);
        }
        sleep(READ_DELAY_SEC);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

