// Si7051 I2C address
#define SI7051_ADDR 0x40

// Si7051 commands
#define SI7051_MEASURE_TEMP_HOLD 0xE3

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from Si7051
float read_temperature() {
    char buf[2];
    int result;

    // Send measure temperature command
    result = i2cWriteByte(i2c_handle, SI7051_MEASURE_TEMP_HOLD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Wait for measurement to complete (typical conversion time is 25ms)
    gpioDelay(30); // Wait 30ms

    // Read two bytes of temperature data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to Celsius
    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return temperature;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

