#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90833_ADDR 0x60

// Define the register address for pressure data (example, adjust as needed)
#define PRESSURE_REG 0x01

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read pressure data from the sensor
        char buffer[2];
        int bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buffer, 2);

        if (bytes_read != 2) {
            fprintf(stderr, "I2C read failed: %d\n", bytes_read);
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %d\n", i2c_handle);
                // If re-initialization fails, exit the program
                gpioTerminate();
                return 1;
            }
            gpioDelay(100); // Small delay before retrying
            continue; // Skip to the next iteration
        }

        // Convert the raw data to a pressure value (example, adjust as needed)
        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        float pressure = (float)raw_pressure / 10.0; // Example scaling

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Log the pressure value with timestamp
        printf("%s Pressure: %.2f kPa\n", buf, pressure);

        // Wait for 500 ms
        gpioDelay(500);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

