#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Sensor I2C address
#define I2C_ADDR 0x63

// Sensor commands
#define CMD_OTP_READ 0x50
#define CMD_MEASURE 0x40

// Measurement delay (7 ms)
#define MEASUREMENT_DELAY_US 7000

// Structure to hold calibration coefficients
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
} calibration_coeffs_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_coeffs(calibration_coeffs_t *coeffs);
int trigger_measurement();
int read_sensor_data(int32_t *temperature, int32_t *pressure);
double calculate_temperature(int32_t raw_temperature, const calibration_coeffs_t *coeffs);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature, const calibration_coeffs_t *coeffs);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read calibration coefficients from OTP memory
int read_calibration_coeffs(calibration_coeffs_t *coeffs) {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, CMD_OTP_READ, buf, 8);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    coeffs->c0 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    coeffs->c1 = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    coeffs->c00 = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    coeffs->c10 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, CMD_MEASURE, 0);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data (temperature and pressure)
int read_sensor_data(int32_t *temperature, int32_t *pressure) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6); // Read from register 0x00
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *temperature = (int32_t)buf[0] | ((int32_t)buf[1] << 8);
    *pressure = (int32_t)buf[2] | ((int32_t)buf[3] << 8) | ((int32_t)buf[4] << 16) | ((int32_t)buf[5] << 24);

    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int32_t raw_temperature, const calibration_coeffs_t *coeffs) {
    double temp = raw_temperature;
    double c0 = coeffs->c0;
    double c1 = coeffs->c1;
    double c00 = coeffs->c00;
    double c10 = coeffs->c10;

    double Tsc = c0 * 0.5 + c1 * temp;
    double Tref = c00 * 0.25 + c10 * temp;

    return Tsc / Tref;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature, const calibration_coeffs_t *coeffs) {
    double Psc = raw_pressure;
    double Tsc = raw_temperature;
    double c0 = coeffs->c0;
    double c1 = coeffs->c1;
    double c00 = coeffs->c00;
    double c10 = coeffs->c10;

    double Tref = c00 * 0.25 + c10 * Tsc;
    double P = Psc / Tref;

    return P;
}

// Function to log data to stdout
void log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    calibration_coeffs_t coeffs;
    if (read_calibration_coeffs(&coeffs) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(MEASUREMENT_DELAY_US);

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate temperature and pressure
        double temperature = calculate_temperature(raw_temperature, &coeffs);
        double pressure = calculate_pressure(raw_pressure, raw_temperature, &coeffs);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

