        double temperature = calculate_temperature(raw_temperature, &coeffs);
        double pressure = calculate_pressure(raw_pressure, raw_temperature, &coeffs);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

