// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x60

// Define the registers for pressure reading
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB

// Define the scaling factor
#define SCALING_FACTOR 0.1

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int init_i2c(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", filename);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02x\n", address);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read pressure from the sensor
float read_pressure(int fd) {
    unsigned char msb, lsb;
    int raw_pressure;

    // Trigger measurement (write to any register)
    if (write(fd, NULL, 0) != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10000); // Wait for measurement to complete (10ms)

    // Read MSB
    if (read(fd, &msb, 1) != 1) {
        fprintf(stderr, "Error reading MSB: %s\n", strerror(errno));
        return -1.0;
    }

    // Read LSB
    if (read(fd, &lsb, 1) != 1) {
        fprintf(stderr, "Error reading LSB: %s\n", strerror(errno));
        return -1.0;
    }

    // Combine MSB and LSB to get the raw pressure value
    raw_pressure = (msb << 8) | lsb;

    // Convert raw pressure to kPa
    float pressure_kPa = (float)raw_pressure * SCALING_FACTOR;

    return pressure_kPa;
}

// Function to log the pressure reading with a timestamp
void log_pressure(float pressure_kPa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        float pressure_kPa = read_pressure(i2c_fd);
        if (pressure_kPa >= 0) {
            log_pressure(pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }
        sleep(1);
    }

    // Close I2C device (this part will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

