#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CMD_CONTINUOUS 0x362F
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
sensor_data_t read_sensor_data(int fd);
void log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read sensor data function
sensor_data_t read_sensor_data(int fd) {
    unsigned char data[9];
    sensor_data_t sensor_data = {0.0, 0.0};
    unsigned short pressure_raw, temperature_raw;

    // Send continuous measurement command
    unsigned char cmd[2] = {(CMD_CONTINUOUS >> 8) & 0xFF, CMD_CONTINUOUS & 0xFF};
    if (i2c_write(fd, cmd, 2) < 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return sensor_data; // Return default values on error
    }

    // Wait for 45ms
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 45000 * 1000; // 45ms
    nanosleep(&ts, NULL);

    // Read 9 bytes of data
    if (i2c_read(fd, data, 9) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return sensor_data; // Return default values on error
    }

    // Extract raw values
    pressure_raw = (data[0] << 8) | data[1];
    temperature_raw = (data[3] << 8) | data[4];

    // Validate CRC for pressure
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Pressure CRC error\n");
        return sensor_data; // Return default values on error
    }

    // Validate CRC for temperature
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC error\n");
        return sensor_data; // Return default values on error
    }

    // Convert raw values to physical units
    sensor_data.pressure = (float)pressure_raw / PRESSURE_SCALE;
    sensor_data.temperature = (float)temperature_raw / TEMPERATURE_SCALE;

    return sensor_data;
}

// Log data function
void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data(i2c_fd);
        log_data(log_file, sensor_data.pressure, sensor_data.temperature);
        sleep(1); // Log data every 1 second
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

