#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x36
#define MEASURE_ARG 0x2F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define PRESSURE_SCALE 60.0
#define LOG_FILE "airflow_log.csv"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(int16_t *raw_pressure);
uint8_t calculate_crc(const uint8_t *data, size_t len);
float convert_to_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
int create_log_file();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the SDP800 sensor
int trigger_measurement() {
    char cmd[2] = {MEASURE_CMD, MEASURE_ARG};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP800 sensor
int read_sensor_data(int16_t *raw_pressure) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine the two data bytes into a 16-bit signed integer
    *raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);

    // Verify CRC checksum
    uint8_t crc = calculate_crc(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw pressure data to Pascals
float convert_to_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE;
}

// Log data to a CSV file
int log_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is newly created and write the header
    struct stat st;
    if (stat(LOG_FILE, &st) == -1) {
        fprintf(stderr, "Error getting file status: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (st.st_size == 0) {
        fprintf(fp, "Timestamp,Pressure(Pa)\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to the file
    fprintf(fp, "%s,%.2f\n", timestamp, pressure);

    fclose(fp);
    return 0;
}

// Create the log file if it doesn't exist
int create_log_file() {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
        return -1;
    }
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create the log file if it doesn't exist
    if (create_log_file() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int retry;
    int16_t raw_pressure;
    float pressure;

    // Main loop
    while (!terminate) {
        retry = 0;
