        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Read pressure from the sensor
int read_pressure(int handle, uint16_t *pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        i2cClose(handle);
        handle = open_i2c_bus(I2C_BUS, MLX90821_ADDR);
        if (handle < 0) {
            fprintf(stderr, "Failed to re-open I2C bus after error\n");
            return -1;
        }
        return -1; // Indicate retry needed
    }

    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

