    } else if (pressure > SAFE_MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa is above the safe range (%.2f-%.2f kPa)!\n",
                pressure, SAFE_MIN_PRESSURE, SAFE_MAX_PRESSURE);
    }
}

