    if (create_log_file() != 0) {
        close_resources();
        return 1;
    }

    uint16_t raw_pressure;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            log_pressure(pressure_kPa);
            check_pressure_range(pressure_kPa);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }
        sleep(1);
    }

    // Close resources before exiting
    close_resources();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

