#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASURE_CMD 0x00
#define DATA_LEN 4
#define STATUS_MASK 0xC0
#define TEMP_OFFSET 165.0
#define TEMP_SCALE 16383.0
#define HUMID_SCALE 16383.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
char* get_iso8601_timestamp();
int log_data(float temperature, float humidity, char* timestamp);
void signal_handler(int signal);
int check_file_size(const char* filename, size_t max_size);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity) {
    char buf[1];
    char data[DATA_LEN];

    buf[0] = MEASURE_CMD;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(40000); // Wait 40ms

    if (i2cReadDevice(i2c_handle, data, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    *raw_humidity = (data[2] << 8) | data[3];

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (raw_temperature * TEMP_OFFSET / TEMP_SCALE) - 40.0;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (raw_humidity * 100.0 / HUMID_SCALE);
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float temperature, float humidity, char* timestamp) {
    FILE *fp = fopen("environmental_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Check file size and truncate if necessary
int check_file_size(const char* filename, size_t max_size) {
    struct stat st;
    if (stat(filename, &st) == 0) {
        if (st.st_size > max_size) {
            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                fprintf(stderr, "Error opening log file for truncation!\n");
                return -1;
            }
            fclose(fp);
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;
        char* timestamp;

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Validate status bits
            if ((raw_temperature & STATUS_MASK) == 0) {
                // Convert data
                temperature = convert_temperature(raw_temperature);
                humidity = convert_humidity(raw_humidity);

                // Get timestamp
                timestamp = get_iso8601_timestamp();

                // Log data
                if (log_data(temperature, humidity, timestamp) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Sensor status indicates an error: 0x%04X\n", raw_temperature);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

