int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity) {
    char buf[1];
    char data[DATA_LEN];

    buf[0] = MEASURE_CMD;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(40000); // Wait 40ms

    if (i2cReadDevice(i2c_handle, data, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    *raw_humidity = (data[2] << 8) | data[3];

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (raw_temperature * TEMP_OFFSET / TEMP_SCALE) - 40.0;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (raw_humidity * 100.0 / HUMID_SCALE);
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float temperature, float humidity, char* timestamp) {
    FILE *fp = fopen("environmental_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Check file size and truncate if necessary
int check_file_size(const char* filename, size_t max_size) {
    struct stat st;
    if (stat(filename, &st) == 0) {
        if (st.st_size > max_size) {
            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                fprintf(stderr, "Error opening log file for truncation!\n");
                return -1;
            }
            fclose(fp);
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;
        char* timestamp;

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Validate status bits
            if ((raw_temperature & STATUS_MASK) == 0) {
                // Convert data
                temperature = convert_temperature(raw_temperature);
                humidity = convert_humidity(raw_humidity);

                // Get timestamp
                timestamp = get_iso8601_timestamp();

                // Log data
                if (log_data(temperature, humidity, timestamp) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Sensor status indicates an error: 0x%04X\n", raw_temperature);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

