#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SENT_TICKS 3
#define SYNC_PULSE 56
#define MIN_PULSE_WIDTH 36
#define MAX_PULSE_WIDTH 813
#define MIN_NIBBLE 0
#define MAX_NIBBLE 15
#define MIN_RAW 0
#define MAX_RAW 4095
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define MIN_STATUS 0
#define MAX_STATUS 15
#define MIN_CHECKSUM 0
#define MAX_CHECKSUM 15

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int status;
    int data[3];
    int checksum;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_sent_data();
int validate_checksum(SensorData data);
float convert_to_pressure(int raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read SENT data from the sensor
SensorData read_sent_data() {
    SensorData data = {0, {0, 0, 0}, 0};
    int pulse_width;
    int i;

    // Synchronization pulse
    gpioDelay(SYNC_PULSE * SENT_TICKS);
    pulse_width = gpioTick();

    // Read status nibble
    gpioDelay(12 * SENT_TICKS); // Minimum time for a nibble
    pulse_width = gpioTick();
    if (pulse_width < (MIN_PULSE_WIDTH * SENT_TICKS) || pulse_width > (MAX_PULSE_WIDTH * SENT_TICKS)) {
        fprintf(stderr, "Error: Invalid pulse width for status nibble: %d\n", pulse_width);
        return data; // Return default data with error
    }
    data.status = pulse_width / (SENT_TICKS * 12); // Calculate nibble value

    // Read data nibbles
    for (i = 0; i < 3; i++) {
        gpioDelay(12 * SENT_TICKS); // Minimum time for a nibble
        pulse_width = gpioTick();
        if (pulse_width < (MIN_PULSE_WIDTH * SENT_TICKS) || pulse_width > (MAX_PULSE_WIDTH * SENT_TICKS)) {
            fprintf(stderr, "Error: Invalid pulse width for data nibble %d: %d\n", i, pulse_width);
            return data; // Return default data with error
        }
        data.data[i] = pulse_width / (SENT_TICKS * 12); // Calculate nibble value
    }

    // Read checksum nibble
    gpioDelay(12 * SENT_TICKS); // Minimum time for a nibble
    pulse_width = gpioTick();
    if (pulse_width < (MIN_PULSE_WIDTH * SENT_TICKS) || pulse_width > (MAX_PULSE_WIDTH * SENT_TICKS)) {
        fprintf(stderr, "Error: Invalid pulse width for checksum nibble: %d\n", pulse_width);
        return data; // Return default data with error
    }
    data.checksum = pulse_width / (SENT_TICKS * 12); // Calculate nibble value

    return data;
}

// Function to validate the checksum
int validate_checksum(SensorData data) {
    int calculated_checksum = (data.status + data.data[0] + data.data[1] + data.data[2]) % 16;
    if (calculated_checksum != data.checksum) {
        fprintf(stderr, "Error: Checksum validation failed. Calculated: %d, Received: %d\n", calculated_checksum, data.checksum);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to convert raw data to pressure
float convert_to_pressure(int raw_value) {
    float pressure = (float)raw_value * 0.1 + 10.0; // Example linear transfer function
    return pressure;
}

// Function to log pressure data to a file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Indicate error
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Brake pressure monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        SensorData data = read_sent_data();

        if (validate_checksum(data) == 0) {
            int raw_value = (data.status << 12) | (data.data[0] << 9) | (data.data[1] << 6) | data.data[2];
            float pressure = convert_to_pressure(raw_value);

            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure data.\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid data received.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Brake pressure monitoring system stopped.\n");
    return 0;
}

