#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x11
#define SAMPLE_INTERVAL_SEC 60
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int write_data(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    const char *filename;
    int sample_interval;
} config_t;

config_t config = {
    I2C_BUS,
    TMP117_ADDR,
    FILENAME,
    SAMPLE_INTERVAL_SEC
};

int main() {
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (write_data(temperature) != 0) {
                fprintf(stderr, "Failed to write data to file\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(config.sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.tmp117_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Verify device ID
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read device ID\n");
        i2cClose(i2c_handle);
        return 1;
    }

    if (buf[0] != 0x11 || buf[1] != 0x17) {
        fprintf(stderr, "Incorrect device ID: 0x%02x 0x%02x\n", buf[0], buf[1]);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read temperature from the sensor
int read_temperature(float *temperature) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return 1;
    }

    // Convert to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius (0.0078125 °C per LSB)
    *temperature = (float)raw_temp * 0.0078125;

    return 0;
}

// Write temperature data to file
int write_data(float temperature) {
    fp = fopen(config.filename, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return 1;
    }

    // Write temperature as a little-endian float
    uint8_t data[4];
    memcpy(data, &temperature, 4);

    if (fwrite(data, 1, 4, fp) != 4) {
        fprintf(stderr, "Failed to write data to file\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

