#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 5
#define LSB_RESOLUTION 0.0078125

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
float read_temperature();
void buffer_init(CircularBuffer *cb);
void buffer_add(CircularBuffer *cb, float temp);
float buffer_get_average(CircularBuffer *cb);
void buffer_save(CircularBuffer *cb, const char *filename);
void signal_handler(int signal);

// Initialize the circular buffer
void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a temperature reading to the circular buffer
void buffer_add(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average temperature from the circular buffer
float buffer_get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Save the circular buffer to a binary file
void buffer_save(CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return;
    }

    size_t elements_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (elements_written != cb->count) {
        fprintf(stderr, "Error writing to file: wrote %zu elements, expected %d\n", elements_written, cb->count);
    }

    fclose(fp);
}

// Read temperature from the TMP117 sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate an error
    }

    // Convert big-endian bytes to float
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    return (float)raw_temp * LSB_RESOLUTION;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    buffer_init(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            buffer_add(&temp_buffer, temperature);
            float average_temp = buffer_get_average(&temp_buffer);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temp);
            buffer_save(&temp_buffer, "temperature_log.dat");
        } else {
            fprintf(stderr, "Failed to read temperature, skipping.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

