#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASURE_CMD 0x7866
#define DATA_LEN 6
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MIN_TEMP -40.0
#define MAX_TEMP 125.0
#define MIN_HUMIDITY 0.0
#define MAX_HUMIDITY 100.0
#define LOG_FILE "shtc3_environment.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
int validate_data(const unsigned char *data);
SensorData convert_data(const unsigned char *data);
int log_data(SensorData data);
void signal_handler(int signal);
int open_log_file();
void close_resources();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from SHTC3
int read_sensor_data(unsigned char *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(12); // Wait for measurement (at least 12.4 ms)

    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LEN);
    if (result != DATA_LEN) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate sensor data using CRC
int validate_data(const unsigned char *data) {
    if (calculate_crc(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }
    if (calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
SensorData convert_data(const unsigned char *data) {
    SensorData sensor_data;
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    unsigned int raw_humidity = (data[3] << 8) | data[4];

    sensor_data.temperature = 175.0 * raw_temperature / 65535.0 - 45.0;
    sensor_data.humidity = 100.0 * raw_humidity / 65535.0;

    return sensor_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Open the log file
int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Close resources (I2C, log file, pigpio)
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    unsigned char data[DATA_LEN];
    SensorData sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        close_resources();
        return 1;
    }

    printf("Starting SHTC3 data logging...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate data
            if (validate_data(data) == 0) {
                // Convert data
                sensor_data = convert_data(data);

                // Validate temperature and humidity ranges
                if (sensor_data.temperature >= MIN_TEMP && sensor_data.temperature <= MAX_TEMP &&
                    sensor_data.humidity >= MIN_HUMIDITY && sensor_data.humidity <= MAX_HUMIDITY) {
                    // Log data
                    if (log_data(sensor_data) == 0) {
                        // Print data to stdout
                        printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
                    } else {
                        fprintf(stderr, "Error logging data.\n");
                    }
                } else {
                    fprintf(stderr, "Invalid temperature or humidity range.\n");
                }
            } else {
                fprintf(stderr, "Data validation failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close resources before exiting
