#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_RESOLUTION 0.0078125 // 7.8125 m°C/LSB
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(int16_t *temperature);
float convert_to_celsius(int16_t raw_temperature);
int log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the TMP117 sensor
int read_temperature(int16_t *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    *temperature = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int16_t raw_temperature) {
    return (float)raw_temperature * TEMP_RESOLUTION;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.4f C\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int i2c_init_attempts = 0;
    while (i2c_init_attempts < 3) {
        if (init_i2c() == 0) {
            printf("I2C initialized successfully.\n");
            break;
        } else {
            i2c_init_attempts++;
            fprintf(stderr, "I2C initialization failed, attempt %d/%d\n", i2c_init_attempts, 3);
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (i2c_init_attempts == 3) {
        fprintf(stderr, "Failed to initialize I2C after 3 attempts. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    int16_t raw_temperature;
    float temperature_celsius;

    // Main loop
    while (!terminate) {
        if (read_temperature(&raw_temperature) == 0) {
            temperature_celsius = convert_to_celsius(raw_temperature);
            if (log_temperature(temperature_celsius) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
            printf("Temperature: %.4f C\n", temperature_celsius);
        } else {
            fprintf(stderr, "Error reading temperature. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before retrying I2C
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit the loop if re-initialization fails
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

