// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_REGISTER 0x00 // Example register address for flow
#define TEMP_REGISTER 0x02 // Example register address for temperature
#define FLOW_BYTES 2
#define TEMP_BYTES 2
#define FLOW_SCALE_FACTOR 16384.0
#define TEMP_SCALE_FACTOR 4096.0
#define FLOW_OFFSET 0.1
#define TEMP_OFFSET 0.1
#define FLOW_MAX 25.0
#define TEMP_MAX 80.0
#define SAMPLE_INTERVAL 1 // seconds
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *raw_flow, int *raw_temp);
float convert_flow(int raw_flow);
float convert_temperature(int raw_temp);
int log_data(float flow_rate, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads raw sensor data from the I2C device
int read_sensor_data(int *raw_flow, int *raw_temp) {
    char buffer[4];

    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *raw_temp = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Converts raw flow data to SLPM
float convert_flow(int raw_flow) {
    return ((raw_flow / FLOW_SCALE_FACTOR) - FLOW_OFFSET) / FLOW_MAX * FLOW_MAX;
}

// Converts raw temperature data to Celsius
float convert_temperature(int raw_temp) {
    return ((raw_temp / TEMP_SCALE_FACTOR) - TEMP_OFFSET) / TEMP_MAX * TEMP_MAX - 40.0;
}

// Logs the timestamped flow rate and temperature to a file
int log_data(float flow_rate, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate, temperature);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    int raw_flow, raw_temp;
    float flow_rate, temperature;
    int first_read = 1;
    int second_read = 1;

    while (!terminate) {
        if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
            // Convert data
            flow_rate = convert_flow(raw_flow);
            temperature = convert_temperature(raw_temp);

            // Log data
            if (log_data(flow_rate, temperature) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }

            printf("Flow: %.2f SLPM, Temperature: %.2f °C\n", flow_rate, temperature);

            // Debounce reads
            if (first_read) {
                first_read = 0;
                second_read = 1;
            } else if (second_read) {
                second_read = 0;
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

