#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 10000 // 10ms timeout
#define SAMPLE_INTERVAL_S 2

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
} DHT11Data;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int dht11_read(DHT11Data *data);
int validate_checksum(const DHT11Data *data);
void log_data(const DHT11Data *data, int status);
void signal_handler(int signal);
void log_error(const char *message, int status);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to log errors with timestamp
void log_error(const char *message, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - ERROR: %s (Status: %d)\n", timestamp, message, status);
    fflush(log_file);
}

// Function to log data with timestamp
void log_data(const DHT11Data *data, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %d.%02d, %d.%02d (Status: %d)\n",
            timestamp, data->humidity, 0, data->temperature, 0, status);
    fflush(log_file);
}

// Function to read data from DHT11 sensor
int dht11_read(DHT11Data *data) {
    int i, j;
    int bit; // Changed variable name to avoid conflict
    unsigned int pulse_lengths[40];
    int checksum;

    // 1. Start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20-40us
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    int start_timeout = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_timeout > TIMEOUT_US) {
            log_error("DHT11: Timeout waiting for start signal", -1);
            return -1;
        }
    }
    start_timeout = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_timeout > TIMEOUT_US) {
            log_error("DHT11: Timeout waiting for start signal high", -1);
            return -1;
        }
    }

    // 2. Response signal
    start_timeout = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_timeout > TIMEOUT_US) {
            log_error("DHT11: Timeout waiting for response signal", -1);
            return -1;
        }
    }
    start_timeout = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_timeout > TIMEOUT_US) {
            log_error("DHT11: Timeout waiting for response signal low", -1);
            return -1;
        }
    }

    // 3. Data bits
    for (i = 0; i < 40; i++) {
        start_timeout = gpioTick();
        while (gpioRead(DHT11_GPIO) == 0) {
            if (gpioTick() - start_timeout > TIMEOUT_US) {
                log_error("DHT11: Timeout waiting for data bit start", -1);
                return -1;
            }
        }

        start_timeout = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if (gpioTick() - start_timeout > TIMEOUT_US) {
                log_error("DHT11: Timeout waiting for data bit value", -1);
                return -1;
            }
        }

        pulse_lengths[i] = gpioTick() - start_timeout;
    }

    // 4. Checksum
    checksum = 0;
    for (i = 0; i < 4; i++) {
        checksum += pulse_lengths[i * 8];
    }
    checksum = checksum % 256;

    // 5. Validate checksum
    if (validate_checksum(data, pulse_lengths) != 0) {
        log_error("DHT11: Checksum validation failed", -1);
        return -1;
    }

    // Populate data structure
    data->humidity = (pulse_lengths[0] + pulse_lengths[1] + pulse_lengths[2] + pulse_lengths[3]) & 0xFF;
    data->temperature = (pulse_lengths[8] + pulse_lengths[9] + pulse_lengths[10] + pulse_lengths[11]) & 0xFF;

    return 0;
}

// Function to validate checksum
int validate_checksum(const DHT11Data *data, const int *pulse_lengths) {
    int checksum = (pulse_lengths[0] + pulse_lengths[1] + pulse_lengths[2] + pulse_lengths[3]) & 0xFF;
    return (checksum == (pulse_lengths[4] + pulse_lengths[5] + pulse_lengths[6] + pulse_lengths[7]) & 0xFF);
}

int main() {
    DHT11Data dht11_data;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        status = dht11_read(&dht11_data);
        if (status == 0) {
            log_data(&dht11_data, status);
        } else {
            log_error("DHT11: Read failed", status);
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Sleep for 2 seconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

