#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c(int handle, int data);
int read_i2c(int handle, char *buf, int count);
unsigned char crc8(const unsigned char *data, int len);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Write data to I2C bus
int write_i2c(int handle, int data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C bus: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from I2C bus
int read_i2c(int handle, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buf, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C bus: %d\n", result);
        return -1;
    }
    return result;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Convert raw humidity to percentage
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

