float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Convert raw humidity to percentage
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

