#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor I2C addresses
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

// Define register addresses
#define DEVICE_ID_REG 0x00
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68

// Define I2C bus
#define I2C_BUS 1

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int addr);
int read_device_id(int i2c_handle);
int read_rgb_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
float average_cct(float cct1, float cct2);
int log_cct(float average_cct);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize I2C communication
int init_i2c(int addr) {
    int handle = i2cOpen(I2C_BUS, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read the device ID register
int read_device_id(int i2c_handle) {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    return device_id;
}

// Function to read RGB data from the sensor
int read_rgb_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, RED_REG, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading RGB data: %d\n", bytes_read);
        return -1;
    }

    *red = (uint16_t)((buffer[1] << 8) | buffer[0]);
    *green = (uint16_t)((buffer[3] << 8) | buffer[2]);
    *blue = (uint16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calculate Correlated Color Temperature (CCT) using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float x = (float)red / (float)(red + green + blue);
    float y = (float)green / (float)(red + green + blue);

    float n = (x - 0.3320) / (0.1858 - y);

    float cct = 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;

    return cct;
}

// Function to calculate the average of two CCT values
float average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0;
}

// Function to log the average CCT to a CSV file
int log_cct(float average_cct) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("cct_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C communication for both sensors
    i2c_handle1 = init_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify device ID for sensor 1
    int device_id1 = read_device_id(i2c_handle1);
    if (device_id1 != 0x2A) {
        fprintf(stderr, "Error: Sensor 1 device ID mismatch. Expected 0x2A, got 0x%02X\n", device_id1);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Verify device ID for sensor 2
    int device_id2 = read_device_id(i2c_handle2);
    if (device_id2 != 0x2A) {
        fprintf(stderr, "Error: Sensor 2 device ID mismatch. Expected 0x2A, got 0x%02X\n", device_id2);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1, red2, green2, blue2;
        float cct1, cct2, average_cct_value;

        // Read RGB data from sensor 1
        if (read_rgb_data(i2c_handle1, &red1, &green1, &blue1) == 0) {
            // Calculate CCT for sensor 1
            cct1 = calculate_cct(red1, green1, blue1);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read RGB data from sensor 2
        if (read_rgb_data(i2c_handle2, &red2, &green2, &blue2) == 0) {
            // Calculate CCT for sensor 2
            cct2 = calculate_cct(red2, green2, blue2);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (cct1 >= 0 && cct2 >= 0) {
            average_cct_value = average_cct(cct1, cct2);
            // Log the average CCT
            if (log_cct(average_cct_value) != 0) {
                fprintf(stderr, "Error logging CCT!\n");
            }
        } else {
            fprintf(stderr, "Error: Could not read data from one or more sensors.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

