#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0.0
#define PMAX_KPA 800.0
#define TEMP_OFFSET -40.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *pressure, uint16_t *temperature);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
char* get_iso8601_timestamp();
int log_data(char *timestamp, float pressure_kPa, float temperature_C);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *pressure, uint16_t *temperature) {
    char buf[4];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *pressure = (buf[0] << 8) | buf[1];
    *temperature = (buf[2] << 8) | buf[3];

    return 0;
}

// Convert raw pressure to kPa
float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return raw_temperature * 0.01 - TEMP_OFFSET;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(char *timestamp, float pressure_kPa, float temperature_C) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_kPa, temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    uint16_t raw_pressure, raw_temperature;
    float pressure_kPa, temperature_C;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tire Pressure Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            pressure_kPa = convert_pressure(raw_pressure);
            temperature_C = convert_temperature(raw_temperature);

            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, pressure_kPa, temperature_C) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("%s - Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure_kPa, temperature_C);

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(2);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Tire Pressure Monitoring System stopped.\n");

    return 0;
}

