#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define TEMP_HIGH 28.0
#define TEMP_LOW 26.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_gpio();
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
float calculate_average(CircularBuffer *cb);
void control_fan(float avg_temp);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add temperature reading to circular buffer
void add_to_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate running average of temperature readings
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the cooling fan based on temperature average
void control_fan(float avg_temp) {
    if (avg_temp > TEMP_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (Avg Temp: %.2f °C)\n", avg_temp);
    } else if (avg_temp < TEMP_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (Avg Temp: %.2f °C)\n", avg_temp);
    }
}

// Read temperature from LM75B sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to signed 9-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 1; // Remove the LSB (always 0)

    // Convert to Celsius
    float temp_celsius = (float)raw_temp * 0.5;

    return temp_celsius;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode for fan\n");
        return 1;
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temp = read_temperature();
        if (temp > -999.0) { // Check for read error
            add_to_buffer(&temp_buffer, temp);
            float avg_temp = calculate_average(&temp_buffer);
            control_fan(avg_temp);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan control.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

