#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0625
#define HYSTERESIS_HIGH 28.0
#define HYSTERESIS_LOW 27.0

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_to_celsius(uint16_t raw_temp);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip);
int setup_i2c(int *fd);
int cleanup_i2c(int fd);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (read(fd, buf, 2) != 2) {
            perror("Failed to read data");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        result = (buf[0] << 8) | buf[1];
        return result;
    }

    fprintf(stderr, "I2C read failed after multiple retries. Exiting.\n");
    return -1; // Indicate failure
}

// Temperature conversion function
float convert_to_celsius(uint16_t raw_temp) {
    return (float)((raw_temp >> 4) * TEMP_SCALE);
}

// GPIO control function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "temp_monitor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Setup I2C
int setup_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        return -1;
    }

    return 0;
}

// Cleanup I2C
int cleanup_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

int main() {
    float temperature;
    uint16_t raw_temp;
    int led_state = 0; // 0 = off, 1 = on

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (setup_i2c(&i2c_fd) < 0) {
        return 1;
    }

    // Initialize GPIO
    if (setup_gpio(&gpio_chip, &gpio_line) < 0) {
        cleanup_i2c(i2c_fd);
        return 1;
    }

    fprintf(stderr, "Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        raw_temp = i2c_read_word(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature. Exiting.\n");
            break;
        }

        // Convert to Celsius
        temperature = convert_to_celsius(raw_temp);

        // Control LED with hysteresis
        if (temperature > HYSTERESIS_HIGH && led_state == 0) {
            if (gpio_set_value(gpio_line, 1) == 0) {
                led_state = 1;
            }
        } else if (temperature < HYSTERESIS_LOW && led_state == 1) {
            if (gpio_set_value(gpio_line, 0) == 0) {
                led_state = 0;
            }
        }

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    cleanup_gpio(gpio_line, gpio_chip);
    cleanup_i2c(i2c_fd);

    fprintf(stderr, "Exiting.\n");
    return 0;
}

