#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CMD_CONTINUOUS 0x362F
#define SCALE_FACTOR_OFFSET 6
#define SCALE_FACTOR_SIZE 2
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t checksum);
int read_scale_factor(int16_t *scale_factor);
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == checksum);
}

// Read scale factor from the sensor
int read_scale_factor(int16_t *scale_factor) {
    uint8_t data[3];
    if (read_data(data, 3) != 0) {
        return -1;
    }

    *scale_factor = (int16_t)((data[SCALE_FACTOR_OFFSET] << 8) | data[SCALE_FACTOR_OFFSET + 1]);
    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    uint8_t data[9];
    sensor_data_t sensor_data;
    int16_t scale_factor;

    if (read_data(data, 9) != 0) {
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    // Validate CRC for pressure data
    if (!validate_crc(data, 2, data[2])) {
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    // Validate CRC for temperature data
    if (!validate_crc(data + 3, 2, data[5])) {
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    // Read scale factor
    if (read_scale_factor(&scale_factor) != 0) {
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    // Convert raw data to physical units
    sensor_data.pressure = (float)((int16_t)((data[0] << 8) | data[1])) / scale_factor;
    sensor_data.temperature = (float)((int16_t)((data[3] << 8) | data[4])) / 200.0;

    return sensor_data;
}

// Log sensor data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa, %.2f °C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Send continuous measurement command
    if (send_command(CMD_CONTINUOUS) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.pressure != -999.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

