#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP 0xF3
#define MEASURE_RH 0xF5
#define READ_TEMP 0xE0
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_temp, uint16_t *raw_humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
int validate_sensor();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint16_t *raw_temp, uint16_t *raw_humidity) {
    int retries = RETRY_COUNT;
    int result;

    // Measure Temperature
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &MEASURE_TEMP, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %s, retries left: %d\n", strerror(errno), retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
            continue;
        }
        gpioDelay(20); // Wait for measurement
        result = i2cReadDevice(i2c_handle, (char *)raw_temp, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %s, retries left: %d\n", strerror(errno), retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        return -1;
    }

    // Measure Humidity
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &MEASURE_RH, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing humidity command: %s, retries left: %d\n", strerror(errno), retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
            continue;
        }
        gpioDelay(20); // Wait for measurement
        result = i2cReadDevice(i2c_handle, (char *)raw_humidity, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading humidity data: %s, retries left: %d\n", strerror(errno), retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) {
        humidity = 0.0;
    } else if (humidity > 100.0) {
        humidity = 100.0;
    }
    return humidity;
}

// Log data to file and stdout
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp); // Ensure data is written immediately

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    fclose(fp);
    return 0;
}

// Validate sensor presence
int validate_sensor() {
    uint8_t id[2];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char[]){0x00}, 1); // Command to read ID
        if (result != 0) {
            fprintf(stderr, "Error writing ID command: %s, retries left: %d\n", strerror(errno), retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
            continue;
        }
        gpioDelay(10); // Wait for response
        result = i2cReadDevice(i2c_handle, (char *)id, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading ID: %s, retries left: %d\n", strerror(errno), retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor ID after multiple retries.\n");
        return -1;
    }

    if (id[0] != 0x40 || id[1] != 0x00) {
        fprintf(stderr, "Invalid sensor ID: 0x%02x 0x%02x\n", id[0], id[1]);
        return -1;
    }

    printf("Sensor ID validated.\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Validate sensor
    if (validate_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_temp, &raw_humidity) == 0) {
            temperature = convert_temperature(raw_temp);
            humidity = convert_humidity(raw_humidity);

            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

