// Configure HDC1080 for 14-bit temperature and humidity resolution
int configure_hdc1080() {
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
