        fprintf(stderr, "Error writing to measurement register: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read 4 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

