// Constants
#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD 0x2C
#define MEASURE_ARG 0xE0
#define MEASURE_DELAY_MS 10
#define READ_BYTES 3
#define CRC_POLYNOMIAL 0x31
#define TEMP_SCALE 175.0
#define TEMP_OFFSET -45.0
#define LOG_INTERVAL_SEC 5

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave(int fd, int addr);
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
float convert_to_celsius(unsigned int raw_temp);
int log_temperature(float temperature);
void signal_handler(int sig);
char* iso8601_timestamp(char* buf, size_t buf_size);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_to_celsius(unsigned int raw_temp) {
    return TEMP_OFFSET + (TEMP_SCALE * raw_temp) / 65535.0;
}

// Logging function
int log_temperature(float temperature) {
    char timestamp[32];
    iso8601_timestamp(timestamp, sizeof(timestamp));

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s Temperature: %.2f °C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// ISO 8601 timestamp function
char* iso8601_timestamp(char* buf, size_t buf_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return buf;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        unsigned char write_data[2] = {MEASURE_CMD, MEASURE_ARG};
        unsigned char read_data[READ_BYTES];
        unsigned int raw_temperature;
        float temperature;

        // Send measurement command
        if (i2c_set_slave(i2c_fd, STS40_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave address. Retrying in %d seconds.\n", LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }
        if (i2c_write(i2c_fd, write_data, 2) < 0) {
            fprintf(stderr, "Failed to write measurement command. Retrying in %d seconds.\n", LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }

        // Wait for measurement
        usleep(MEASURE_DELAY_MS * 1000); // Convert ms to us

        // Read temperature data
        if (i2c_set_slave(i2c_fd, STS40_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave address. Retrying in %d seconds.\n", LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }
        if (i2c_read(i2c_fd, read_data, READ_BYTES) < 0) {
            fprintf(stderr, "Failed to read temperature data. Retrying in %d seconds.\n", LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }

        // CRC validation
        unsigned char crc = crc8(read_data, READ_BYTES - 1);
        if (crc != read_data[READ_BYTES - 1]) {
            fprintf(stderr, "CRC validation failed. Retrying in %d seconds.\n", LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }

        // Convert to Celsius
        raw_temperature = (read_data[0] << 8) | read_data[1];
        temperature = convert_to_celsius(raw_temperature);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Failed to log temperature. Retrying in %d seconds.\n", LOG_INTERVAL_SEC);
        }

        // Wait before next measurement
        sleep(LOG_INTERVAL_SEC);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

