#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3615
#define SCALE_FACTOR_LENGTH 3
#define PRESSURE_SCALE_FACTOR_INDEX 6
#define TEMPERATURE_SCALE_FACTOR_INDEX 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize();
int send_command(uint16_t command);
int read_sensor_data(int16_t *pressure, uint16_t *temperature, uint16_t *scale_factor);
uint8_t calculate_crc(const uint8_t *data, size_t length);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
float convert_temperature(uint16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *pressure, uint16_t *temperature, uint16_t *scale_factor) {
    char buf[9];
    int result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Extract data
    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    uint8_t pressure_crc = buf[2];
    *temperature = (uint16_t)((buf[3] << 8) | buf[4]);
    uint8_t temperature_crc = buf[5];
    *scale_factor = (uint16_t)((buf[6] << 8) | (buf[7] << 8) | buf[8]);

    // CRC validation
    if (calculate_crc((uint8_t[]){buf[0], buf[1]}, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }
    if (calculate_crc((uint8_t[]){buf[3], buf[4]}, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

