#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define CSV_BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[CSV_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
circular_buffer_t csv_buffer;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int start_periodic_measurement();
int read_sensor_data(int *co2, float *temperature, float *humidity);
int validate_crc(unsigned char data[], int len);
int write_data_to_csv(circular_buffer_t *buffer);
void *logging_thread(void *arg);
void signal_handler(int signal);
void log_error(const char *message);
void init_circular_buffer(circular_buffer_t *buffer);
int is_buffer_full(circular_buffer_t *buffer);
int is_buffer_empty(circular_buffer_t *buffer);
int enqueue(circular_buffer_t *buffer, sensor_data_t data);
int dequeue(circular_buffer_t *buffer, sensor_data_t *data);

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    char data[9];
    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Extract raw values
    unsigned int raw_co2 = (data[0] << 8) | data[1];
    unsigned int raw_temperature = (data[3] << 8) | data[4];
    unsigned int raw_humidity = (data[6] << 8) | data[7];

    // Validate CRC
    if (!validate_crc(data, 3) || !validate_crc(data + 3, 3) || !validate_crc(data + 6, 3)) {
        log_error("CRC validation failed");
        return -1;
    }

    // Convert to physical values
    *co2 = (int)raw_co2;
    *temperature = -45 + 175 * raw_temperature / 65535;
    *humidity = 100 * raw_humidity / 65535;

    return 0;
}

// Validate CRC-8
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Write data to CSV file
int write_data_to_csv(circular_buffer_t *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return 0; // Nothing to write
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[64];
    strftime(filename, sizeof(filename), "%Y-%m-%d_%H-%M-%S.csv", t);

    char filepath[128];
    snprintf(filepath, sizeof(filepath), "%s%s", LOG_DIR, filename);

    FILE *fp = fopen(filepath, "w");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        pthread_mutex_unlock(&buffer->mutex);
        return -1;
    }

    fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");
    int i = buffer->tail;
    while (i != buffer->head) {
        fprintf(fp, "%ld,%d,%.2f,%.2f\n", buffer->data[i].timestamp, buffer->data[i].co2, buffer->data[i].temperature, buffer->data[i].humidity);
        i = (i + 1) % CSV_BUFFER_SIZE;
    }

    fclose(fp);
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread(void *arg) {
    circular_buffer_t *buffer = (circular_buffer_t *)arg;
    while (running) {
        sleep(60);
        if (write_data_to_csv(buffer) != 0) {
            log_error("Failed to write data to CSV");
        }
    }
    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Log error to file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Check if buffer is full
int is_buffer_full(circular_buffer_t *buffer) {
    return buffer->count == CSV_BUFFER_SIZE;
}

// Check if buffer is empty
int is_buffer_empty(circular_buffer_t *buffer) {
    return buffer->count == 0;
}

// Enqueue data to circular buffer
int enqueue(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    if (is_buffer_full(buffer)) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is full
    }

    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % CSV_BUFFER_SIZE;
    buffer->count++;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Dequeue data from circular buffer
int dequeue(circular_buffer_t *buffer, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (is_buffer_empty(buffer)) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }

    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % CSV_BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&csv_buffer);

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, &csv_buffer) != 0) {
        log_error("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler
    signal(SIGINT, signal_handler);

    int co2, temp_raw, humidity_raw;
    float temperature, humidity;
    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
            sensor_data.timestamp = time(NULL);
            sensor_data.co2 = co2;
            sensor_data.temperature = temperature;
            sensor_data.humidity = humidity;

            if (enqueue(&csv_buffer, sensor_data) != 0) {
                log_error("Failed to enqueue data");
            }
        } else {
            log_error("Failed to read sensor data in main loop");
        }

        sleep(5);
    }

    // Stop periodic measurement
    char buf[2];
    buf[0] = (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, buf, 2);

    // Join logging thread
    pthread_join(logging_thread_id, NULL);

    // Flush remaining data
    write_data_to_csv(&csv_buffer);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

