#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_OFFSET 6
#define TEMPERATURE_OFFSET 4
#define PRESSURE_OFFSET 0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "sdp810_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t raw_temperature;
    uint16_t raw_scale_factor;
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int length, uint8_t initial_value);
int validate_crc(uint8_t data[], int length, uint8_t expected_crc);
int read_sensor_data(int handle, sensor_data_t *data);
float convert_pressure(int16_t raw_pressure, uint16_t raw_scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(FILE *fp, float pressure_Pa, float temperature_C);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int length, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int length, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc(data, length - 1, data[length - 1]);
    return (calculated_crc == expected_crc);
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[9];

    if (send_command(handle, MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Error sending measurement command.\n");
        return -1;
    }
    gpioDelay(45000); // Wait at least 45 ms

    if (read_data(handle, raw_data, 9) != 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    // Extract data
    data->raw_pressure = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    data->raw_temperature = (int16_t)((raw_data[3] << 8) | raw_data[4]);
    data->raw_scale_factor = (uint16_t)((raw_data[6] << 8) | raw_data[7]);

    // Validate CRC
    if (!validate_crc(raw_data, 2, raw_data[1]) ||
        !validate_crc(raw_data + 2, 2, raw_data[3]) ||
        !validate_crc(raw_data + 4, 2, raw_data[5]) ||
        !validate_crc(raw_data + 6, 2, raw_data[7])) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, uint16_t raw_scale_factor) {
    return (float)raw_pressure * (float)raw_scale_factor / 1000.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Log data to file
int log_data(FILE *fp, float pressure_Pa, float temperature_C) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f\n", timestamp, pressure_Pa, temperature_C);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            sensor_data.pressure_Pa = convert_pressure(sensor_data.raw_pressure, sensor_data.raw_scale_factor);
            sensor_data.temperature_C = convert_temperature(sensor_data.raw_temperature);

            if (log_data(log_file, sensor_data.pressure_Pa, sensor_data.temperature_C) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

