#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VALUE 0x08
#define MEASURE_REG 0x00
#define DATA_REG 0x00
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL_SEC 5

// Calibration coefficients
typedef struct {
    int16_t c0;
    int16_t c1;
    int16_t c00;
    int16_t c10;
} icp10110_calibration_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor(icp10110_calibration_t *calibration);
int read_calibration_data(icp10110_calibration_t *calibration);
int trigger_measurement();
int read_sensor_data(int32_t *pressure, int32_t *temperature);
double convert_pressure(int32_t raw_pressure, const icp10110_calibration_t *calibration);
double convert_temperature(int32_t raw_temperature, const icp10110_calibration_t *calibration);
char* get_iso8601_timestamp();
int log_data(double pressure, double temperature);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor(icp10110_calibration_t *calibration) {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    return 0;
}

// Read calibration data
int read_calibration_data(icp10110_calibration_t *calibration) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x05, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration->c0 = (int16_t)((buffer[0] << 8) | buffer[1]);
    calibration->c1 = (int16_t)((buffer[2] << 8) | buffer[3]);
    calibration->c00 = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Read sensor data
int read_sensor_data(int32_t *pressure, int32_t *temperature) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *pressure = (int32_t)((buffer[0] << 16) | (buffer[1] << 8) | buffer[2]);
    *temperature = (int32_t)((buffer[3] << 16) | (buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw pressure to hPa
double convert_pressure(int32_t raw_pressure, const icp10110_calibration_t *calibration) {
    double p = (double)raw_pressure;
    double c0 = (double)calibration->c0;
    double c1 = (double)calibration->c1;
    double c00 = (double)calibration->c00;

    double pressure = c00 + p * c1 + p * p * c0;
    return pressure / 4096.0; // hPa
}

// Convert raw temperature to Celsius
double convert_temperature(int32_t raw_temperature, const icp10110_calibration_t *calibration) {
    double t = (double)raw_temperature;
    double c0 = (double)calibration->c0;
    double c1 = (double)calibration->c1;
    double c00 = (double)calibration->c00;

    double temperature = c00 + t * c1 + t * t * c0;
    return temperature / 4096.0; // Celsius
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(double pressure, double temperature) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
    free(timestamp); // Free the allocated memory
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(NULL) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    icp10110_calibration_t calibration;
    if (read_calibration_data(&calibration) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int32_t raw_pressure, raw_temperature;
    double pressure, temperature;
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        pressure = convert_pressure(raw_pressure, &calibration);
        temperature = convert_temperature(raw_temperature, &calibration);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print data to stdout
        printf("%s, %.2f hPa, %.2f C\n", get_iso8601_timestamp(), pressure, temperature);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
