#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x63
#define LED_GPIO 17 // BCM numbering
#define HIGH_ALTITUDE_PRESSURE 95000.0 // Pascals
#define BLINK_DELAY_MS 500

// Register addresses
#define REG_COEFF1 0x66
#define REG_COEFF2 0x67
#define REG_COEFF3 0x68
#define REG_COEFF4 0x69
#define REG_MEASURE 0x71
#define REG_PRESSURE_MSB 0x00
#define REG_TEMPERATURE_MSB 0x03
#define REG_CRC_MSB 0x05

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration coefficients
static int16_t coeff1, coeff2, coeff3, coeff4;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_calibration_coefficients(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t *data, int len);
float calculate_pressure(int32_t raw_pressure);
float calculate_temperature(int32_t raw_temperature);
void blink_led(struct gpiod_line *line, int frequency_hz);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd) {
    uint8_t data[8];
    if (i2c_read_bytes(fd, REG_COEFF1, data, 8) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    coeff1 = (data[0] << 8) | data[1];
    coeff2 = (data[2] << 8) | data[3];
    coeff3 = (data[4] << 8) | data[5];
    coeff4 = (data[6] << 8) | data[7];

    return 0;
}

// Trigger a measurement
int trigger_measurement(int fd) {
    if (i2c_write_byte(fd, REG_MEASURE, 0x03) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, REG_PRESSURE_MSB, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC
int verify_crc(uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 2);
    uint8_t crc_received = (data[len - 2] << 8) | data[len - 1];

    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC verification failed\n");
        return -1;
    }
    return 0;
}

// Calculate pressure in Pascals
float calculate_pressure(int32_t raw_pressure) {
    float pressure = (float)raw_pressure;
    pressure = (pressure - coeff1) * coeff2;
    pressure = (pressure - coeff3) * coeff4;
    return pressure;
}

// Calculate temperature in Celsius
float calculate_temperature(int32_t raw_temperature) {
    float temperature = (float)raw_temperature;
    temperature = (temperature - 498.0) / 10.0;
    return temperature;
}

// Blink LED
void blink_led(struct gpiod_line *line, int frequency_hz) {
    int on_time_us = (1000000 / frequency_hz) / 2;
    int off_time_us = on_time_us;

    struct timespec on_time = {0, on_time_us * 1000L};
    struct timespec off_time = {0, off_time_us * 1000L};

    gpiod_line_set_value(line, 1); // Turn LED on
    nanosleep(&on_time, NULL);

    gpiod_line_set_value(line, 0); // Turn LED off
    nanosleep(&off_time, NULL);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients, exiting\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "pressure_monitor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int32_t raw_pressure, raw_temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        usleep(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Verify CRC
        if (verify_crc(data, 6) != 0) {
            fprintf(stderr, "CRC verification failed, retrying\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Extract raw pressure and temperature
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        // Calculate pressure and temperature
        float pressure = calculate_pressure(raw_pressure);
        float temperature = calculate_temperature(raw_temperature);

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Blink LED based on pressure
        if (pressure < HIGH_ALTITUDE_PRESSURE) {
            blink_led(led_line, 5); // 5 Hz
        } else {
            blink_led(led_line, 1); // 1 Hz
        }

        sleep(1); // Poll every second
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0); // Turn off LED
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

