#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int read_register(int handle, int reg);
float convert_to_celsius(int raw_temp);
void control_fan(int gpio, float temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Read a register from the I2C device
int read_register(int handle, int reg) {
    int retries = 0;
    int raw_value = -1;

    while (retries < RETRY_COUNT) {
        raw_value = i2cReadWordData(handle, reg);
        if (raw_value >= 0) {
            return raw_value;
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retrying... (%d/%d)\n", reg, retries + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed (reg 0x%02X) after %d retries\n", reg, RETRY_COUNT);
    return -1; // Indicate failure
}

// Convert raw temperature data to Celsius
float convert_to_celsius(int raw_temp) {
    if (raw_temp < 0) return -273.15; // Indicate error
    return (float)raw_temp * 0.02 - 273.15;
}

// Control the cooling fan with hysteresis
void control_fan(int gpio, float temp) {
    if (temp > TEMP_THRESHOLD_HIGH && gpioRead(gpio) == 0) {
        gpioWrite(gpio, 1); // Turn fan on
        printf("Fan ON (Temp: %.2f °C)\n", temp);
    } else if (temp < TEMP_THRESHOLD_LOW && gpioRead(gpio) == 1) {
        gpioWrite(gpio, 0); // Turn fan off
        printf("Fan OFF (Temp: %.2f °C)\n", temp);
    }
}

// Log temperature data to file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, MLX90614_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read raw temperature data
        int ambient_raw = read_register(i2c_handle, AMBIENT_TEMP_REG);
        int object_raw = read_register(i2c_handle, OBJECT_TEMP_REG);

        // Convert to Celsius
        float ambient_temp = convert_to_celsius(ambient_raw);
        float object_temp = convert_to_celsius(object_raw);

        // Validate temperature readings
        if (ambient_temp > -273.0 && object_temp > -273.0) {
            // Control fan
            control_fan(FAN_GPIO, object_temp);

            // Log temperature
            log_temperature(ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading. Skipping logging.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    fclose(log_file);
    gpioTerminate();

    return 0;
}

