#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define PORT 8080
#define MAX_CLIENTS 5

// Global variables for graceful shutdown
int i2c_handle = -1;
int server_fd = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
int start_http_server();
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (server_fd >= 0) {
            close(server_fd);
        }
        gpioTerminate();
        exit(0);
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    char cmd = 0xFD;
    char buf[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10); // Wait 10ms before retry
            retries--;
            continue;
        }

        gpioDelay(10); // Wait at least 10ms

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10); // Wait 10ms before retry
            retries--;
            continue;
        }

        // Convert raw data to temperature and humidity
        int raw_temperature = (buf[0] << 8) | buf[1];
        int raw_humidity = (buf[3] << 8) | buf[4];

        data->temperature = -45 + 175 * (raw_temperature / 65535.0);
        data->humidity = -6 + 125 * (raw_humidity / 65535.0);

        // Clamp humidity to 0-100%
        if (data->humidity < 0) data->humidity = 0;
        if (data->humidity > 100) data->humidity = 100;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after multiple retries.\n");
    return -1; // Failure
}

// Start the HTTP server
int start_http_server() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    int new_socket;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 8080
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 8080
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    printf("Server listening on port %d\n", PORT);
    return server_fd;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    sensor_data_t sensor_data;
    char response[1024];

    if (read_sht40(&sensor_data) == 0) {
        snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>Temperature: %.2f &deg;C, Humidity: %.2f %%</h1></body></html>", sensor_data.temperature, sensor_data.humidity);
    } else {
        snprintf(response, sizeof(response), "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>Error</title></head><body><h1>Error reading sensor data</h1></body></html>");
    }

    send(client_socket, response, strlen(response), 0);
    close(client_socket);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start HTTP server
    if (start_http_server() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in client_address;
    int client_socket;
    socklen_t client_len = sizeof(client_address);

    while (1) {
        if ((client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_len)) < 0) {
            perror("accept");
            break; // Exit loop on accept error
        }

        handle_client(client_socket);
    }

    // Cleanup
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

