// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_MSB 0x00
#define TEMP_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to write to an I2C register
int write_register(int handle, int reg, int val) {
    int result = i2cWriteByteData(handle, reg, val);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read from an I2C register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to trigger a temperature and humidity measurement
int trigger_measurement(int handle) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = write_register(handle, MEASUREMENT_CONFIG, 0x01);
        if (status == 0) {
            // Wait for the measurement to complete (max 500ms)
            int timeout = 500; // milliseconds
            while (read_register(handle, MEASUREMENT_CONFIG) != 0x00 && timeout > 0) {
                gpioDelay(1); // Wait 1 ms
                timeout--;
            }
            if (timeout == 0) {
                fprintf(stderr, "Timeout waiting for measurement to complete.\n");
                return -1;
            }
            return 0; // Success
        } else {
            fprintf(stderr, "Retrying measurement trigger...\n");
            gpioDelay(10); // Wait 10 ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
    return -1;
}

// Function to read temperature and humidity data
int read_data(int handle, float *temperature, float *humidity) {
    int temp_raw, humidity_raw;
    int retries = 3;

    while (retries > 0) {
        temp_raw = read_register(handle, TEMP_MSB) | (read_register(handle, TEMP_LSB) << 8);
        humidity_raw = read_register(handle, HUMIDITY_MSB) | (read_register(handle, HUMIDITY_LSB) << 8);

        if (temp_raw >= 0 && humidity_raw >= 0) {
            *temperature = (float)temp_raw / 65536.0 * 165.0 - 40.0;
            *humidity = (float)humidity_raw / 65536.0 * 100.0;
            return 0; // Success
        } else {
            fprintf(stderr, "Retrying data read...\n");
            gpioDelay(10); // Wait 10 ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read data after multiple retries.\n");
    return -1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure HDC2010 (heater disabled, 14-bit resolution)
    if (write_register(i2c_handle, CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error configuring HDC2010\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (trigger_measurement(i2c_handle) == 0) {
            if (read_data(i2c_handle, &temperature, &humidity) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read temperature and humidity\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement\n");
        }

        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

