#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// Continuous measurement command
#define MEASURE_CMD 0x362F

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len)
{
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Send continuous measurement command
        if (i2cWriteWordData(i2c_handle, 0, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to write measurement command\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Wait for measurement to complete (at least 45ms)
        gpioDelay(45000); // 45ms

        // Read 6 bytes of data
        char buffer[6];
        if (i2cReadI2CBlockData(i2c_handle, 0, buffer, 6) != 6) {
            fprintf(stderr, "Failed to read data\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Extract pressure and temperature data
        int16_t pressure = (buffer[0] << 8) | buffer[1];
        unsigned char pressure_crc = buffer[2];
        int16_t temperature = (buffer[3] << 8) | buffer[4];
        unsigned char temperature_crc = buffer[5];

        // Verify CRC checksums
        if (crc8(buffer, 2) != pressure_crc) {
            fprintf(stderr, "Pressure CRC check failed\n");
        }
        if (crc8(buffer + 3, 2) != temperature_crc) {
            fprintf(stderr, "Temperature CRC check failed\n");
        }

        // Log raw pressure and temperature values
        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);

        // Wait 500ms
        gpioDelay(500000); // 500ms
    }

    // Cleanup (should not reach here in normal execution due to the signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

