#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "reflow_log.csv"
#define TARGET_PROFILE_FILE "profile.txt"
#define NUM_PROFILE_POINTS 10
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_SEC (1.0 / SAMPLE_RATE_HZ)

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static FILE *profile_file = NULL;
static double target_profile[NUM_PROFILE_POINTS][2];
static int profile_index = 0;
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
int spi_init(const char *device);
int spi_read_max6675(int fd, int *raw_data);
double convert_to_celsius(int raw_data);
int gpio_init(const char *chip, int pin);
int gpio_set_output(struct gpiod_line *line);
int gpio_set_duty_cycle(struct gpiod_line *line, double duty_cycle);
int load_target_profile(const char *filename, double profile[][2], int num_points);
double calculate_pid(double setpoint, double actual_temperature);
int log_data(FILE *fp, double time_sec, double target_temp, double actual_temp, double pid_output);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    int mode = 0; // SPI mode 0
    int bits = 8; // 8 bits per word
    int speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read MAX6675
int spi_read_max6675(int fd, int *raw_data) {
    unsigned char tx_buf[3] = {0x00, 0x00, 0x00};
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    *raw_data = ((rx_buf[1] << 8) | rx_buf[2]) >> 3; // Extract 12-bit temperature data
    return 0;
}

// Convert to Celsius
double convert_to_celsius(int raw_data) {
    // Check for open-circuit condition (bit 2)
    if (raw_data & 0x0004) {
        fprintf(stderr, "Error: MAX6675 open-circuit condition detected!\n");
        return NAN; // Not a Number
    }

    // Extract the 12-bit temperature data
    int16_t temp = (raw_data >> 3) & 0x0FFF; // Mask out the status bits

    // Sign extend if negative
    if (temp & 0x0800) {
        temp |= 0xF000; // Sign extend to 16 bits
    }

    return temp * 0.25; // Each LSB is 0.25 degrees C
}

