#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_PERIOD 1000000 / PWM_FREQUENCY // nanoseconds
#define LOG_FILE "greenhouse.log"
#define DEFAULT_SETPOINT 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define DEFAULT_HYSTERESIS 0.5
#define DEFAULT_MAX_DUTY_CYCLE 1000000 // nanoseconds
#define DEFAULT_MIN_DUTY_CYCLE 0
#define DEFAULT_MAX_TEMP 30.0
#define DEFAULT_MIN_TEMP 20.0

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static double setpoint = DEFAULT_SETPOINT;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static double hysteresis = DEFAULT_HYSTERESIS;
static int max_duty_cycle = DEFAULT_MAX_DUTY_CYCLE;
static int min_duty_cycle = DEFAULT_MIN_DUTY_CYCLE;
static double max_temp = DEFAULT_MAX_TEMP;
static double min_temp = DEFAULT_MIN_TEMP;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
int read_temperature(double *temperature);
double calculate_pid(double setpoint, double actual_temperature, PIDState *pid_state);
int set_heater_state(int state);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(double temperature, double setpoint, double pid_output, int duty_cycle);
void signal_handler(int sig);
int initialize_gpio();
void cleanup_gpio();
int initialize_logging();
void cleanup_logging();

// Function to read temperature from DS18B20 sensor
int read_temperature(double *temperature) {
    char sensor_path[256];
    char line[256];
    FILE *fp;
    int i;
    unsigned char data[9];
    unsigned char crc;

    // Find the sensor directory
    snprintf(sensor_path, sizeof(sensor_path), "/sys/bus/w1/devices/28-*");

    DIR *d;
    struct dirent *dir;
    d = opendir(sensor_path);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strncmp(dir->d_name, "28-", 3) == 0) {
                snprintf(sensor_path, sizeof(sensor_path), "%s/%s/w1_slave", "/sys/bus/w1/devices/", dir->d_name);
                break;
            }
        }
        closedir(d);
    } else {
        perror("Error opening sensor directory");
        return -1;
    }

    // Read the temperature file
    fp = fopen(sensor_path, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    // Read the file line by line
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    // Extract the temperature data
    if (sscanf(line, "t=%d", &i) != 1) {
        fclose(fp);
        return -1;
    }

    *temperature = (double)i / 1000.0;

    // CRC Check
    unsigned char *temp_data = (unsigned char *)line;
    crc = 0;
    for (i = 0; i < 8; i++) {
        crc ^= temp_data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ 0x8C;
            } else {
                crc = (crc >> 1);
            }
        }
    }

    if ((crc ^ temp_data[9]) != 0) {
        fprintf(stderr, "CRC check failed\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, PIDState *pid_state) {
    double error = setpoint - actual_temperature;
    pid_state->integral += error;
    double derivative = error - pid_state->previous_error;
    double output = kp * error + ki * pid_state->integral + kd * derivative;
    pid_state->previous_error = error;
    return output;
}

// Function to set the heater state
int set_heater_state(int state) {
    if (gpiod_line_set_value(heater_line, state) < 0) {
        perror("Error setting heater state");
        return -1;
    }
    return 0;
}

