    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "heater_pwm";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(pwm_line, &config, duty_cycle) < 0) {
        perror("Error requesting PWM line");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(double temperature, double setpoint, double pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, temperature, setpoint, pid_output, duty_cycle);
