#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_aht20();
int read_aht20(float *humidity);
void control_dehumidifier(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize AHT20 sensor
int init_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, init_cmd, 3);
        if (result == 0) {
            return 0; // Success
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: AHT20 initialization failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    char data[6];
    int result;
    unsigned char status;

    // Trigger measurement
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
        if (result == 0) {
            break; // Success
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 trigger write failed after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    // Read data
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result == 6) {
            break; // Success
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    if (result != 6) {
        fprintf(stderr, "Error: AHT20 read failed after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Verify status byte
    status = (data[0] << 6) | (data[1] << 4) | (data[2] << 2) | (data[3] >> 2);
    if ((status & 0xC0) != 0) {
        fprintf(stderr, "Error: AHT20 status byte indicates calibration or busy.\n");
        return -1;
    }

    // Calculate humidity
    unsigned long humidity_raw = ((unsigned long)data[1] << 12) | ((unsigned long)data[2] << 4) | ((unsigned long)data[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;

    return 0; // Success
}

// Control dehumidifier relay
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH && gpioRead(DEHUMIDIFIER_GPIO) == 0) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && gpioRead(DEHUMIDIFIER_GPIO) == 1) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF\n");
    }
}

// Log humidity data with timestamp
void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    float humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (init_aht20() != 0) {
        fprintf(stderr, "Error: AHT20 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set dehumidifier GPIO as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is initially off

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_aht20(&humidity) == 0) {
            log_humidity(humidity);
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Error: Failed to read humidity\n");
        }

        gpioDelay(POLL_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

