#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <stdint.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMIDITY_MEASURE 0xE5
#define MEASUREMENT_DELAY_MS 50
#define POST_URL "http://api.example.com/humidity"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SLEEP_SECONDS 60

// Global variables
static int i2c_fd = -1;
static int running = 1;

// Function prototypes
int i2c_init(const char *device);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int read_htu21d_humidity(int fd);
int post_humidity_data(const char *url, const char *data);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device %s: %s", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write register address 0x%02X: %s", reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "Failed to read %d bytes: %s", len, strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to write register 0x%02X with data 0x%02X: %s", reg, data, strerror(errno));
        return -1;
    }
    return 0;
}

// Read humidity from HTU21D sensor
int read_htu21d_humidity(int fd) {
    uint8_t data[3];
    int retries = RETRY_COUNT;
    int status;

    while (retries > 0) {
        if (i2c_write_byte(fd, TRIGGER_HUMIDITY_MEASURE, 0) < 0) {
            syslog(LOG_ERR, "Failed to trigger humidity measurement");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2c_read_bytes(fd, 0, data, 3) < 0) {
            syslog(LOG_ERR, "Failed to read humidity data");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        // CRC check
        uint8_t crc = data[2];
        uint8_t checksum = 0;
        uint8_t data_bytes[2] = {data[0], data[1]};

        for (int i = 0; i < 2; i++) {
            checksum ^= data_bytes[i];
            for (int j = 0; j < 8; j++) {
                if (checksum & 0x80) {
                    checksum = (checksum << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
                } else {
                    checksum <<= 1;
                }
            }
        }

        if (crc != checksum) {
            syslog(LOG_ERR, "CRC check failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Convert to relative humidity
        uint16_t raw_humidity = (data[0] << 8) | data[1];
        float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

        // Data validation
        if (humidity < 0.0 || humidity > 100.0) {
            syslog(LOG_ERR, "Humidity value out of range: %.2f", humidity);
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return (int)(humidity * 100); // Return humidity as integer percentage
    }

    syslog(LOG_ERR, "Failed to read humidity after multiple retries");
    return -1; // Indicate failure
}

// Post humidity data to server
int post_humidity_data(const char *url, const char *data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];
    ssize_t bytes_sent, bytes_received;
    int retries = 3;

    while (retries > 0) {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
            retries--;
            sleep(1);
            continue;
        }

        memset(&servaddr, 0, sizeof(servaddr));
        servaddr.sin_family = AF_INET;
        servaddr.sin_port = htons(80);

        if (inet_pton(AF_INET, url, &servaddr.sin_addr) <= 0) {
            syslog(LOG_ERR, "Invalid address/ Address not supported: %s", url);
            close(sockfd);
            retries--;
            sleep(1);
            continue;
        }

        if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
            syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
            close(sockfd);
            retries--;
            sleep(1);
            continue;
        }

        // Construct the HTTP POST request
        snprintf(buffer, sizeof(buffer), "POST %s HTTP/1.1\r\n" \
                                     "Host: api.example.com\r\n" \
                                     "Content-Type: application/json\r\n" \
                                     "Content-Length: %zu\r\n" \
                                     "Connection: close\r\n" \
                                     "\r\n" \
                                     "%s", url, strlen(data), data);

        bytes_sent = send(sockfd, buffer, strlen(buffer), 0);
        if (bytes_sent < 0) {
            syslog(LOG_ERR, "Send failed: %s", strerror(errno));
            close(sockfd);
            retries--;
            sleep(1);
            continue;
        }

        // Receive the response
        memset(buffer, 0, sizeof(buffer));
        bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
            close(sockfd);
            retries--;
            sleep(1);
            continue;
        }

        // Log the response
        syslog(LOG_INFO, "HTTP Response: %s", buffer);

        close(sockfd);
        return 0; // Success
    }

    syslog(LOG_ERR, "Failed to post data after multiple retries");
    return -1; // Failure
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function to close I2C and socket
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    syslog(LOG_INFO, "Cleanup complete. Exiting.");
    closelog();
}

int main() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity sensor program");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int humidity = read_htu21d_humidity(i2c_fd);
        if (humidity >= 0) {
            // Create JSON payload
            char json_payload[64];
            snprintf(json_payload, sizeof(json_payload), "{\"humidity\": %d}", humidity);

            // Post data to server
            if (post_humidity_data(POST_URL, json_payload) < 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            } else {
                syslog(LOG_INFO, "Humidity data posted successfully");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

