#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <stdbool.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define GPIO_CHIP "gpiochip4"
#define LOG_DIR "/home/pi/logs/"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(void);
int init_gpio(void);
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir(int *motion_detected);
int log_data(float temperature, float humidity, int motion_detected);
void cleanup(void);
void signal_handler(int sig);
char* get_timestamp(void);
bool is_new_day(const char *timestamp);

// Helper function to read a single byte from I2C with retries
int read_i2c_byte(int reg, uint8_t *value) {
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, reg) < 0) {
            perror("Failed to set I2C slave address");
            return -1;
        }

        if (read(i2c_fd, value, 1) == 1) {
            return 0; // Success
        }

        retries++;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
    }

    fprintf(stderr, "Failed to read I2C byte after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Helper function to write a single byte to I2C with retries
int write_i2c_byte(int reg, uint8_t value) {
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;
    uint8_t buf[1];
    buf[0] = value;

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, reg) < 0) {
            perror("Failed to set I2C slave address");
            return -1;
        }

        if (write(i2c_fd, buf, 1) == 1) {
            return 0; // Success
        }

        retries++;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
    }

    fprintf(stderr, "Failed to write I2C byte after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Initialize I2C
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "logger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    uint8_t data[2];
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Failed to set I2C slave address for TMP117");
            return -1;
        }

        if (read(i2c_fd, data, 2) == 2) {
            int16_t raw_temp = (data[0] << 8) | data[1];
            *temperature = (float)raw_temp * 0.0078125;
            return 0;
        }

        retries++;
        usleep(delay_ms * 1000); // Exponential backoff
        delay_ms *= 2;
    }

