// Read humidity and temperature from AHT20
int read_aht20(float *humidity) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    uint8_t data[7];
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;

    // Initialize AHT20
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Failed to set I2C slave address for AHT20 init");
            return -1;
        }

        if (write(i2c_fd, init_cmd, 3) != 3) {
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }
        usleep(15000); // Wait for initialization
        break;
    }
    if (retries == MAX_RETRIES) return -1;

    // Measure temperature and humidity
    retries = 0;
    delay_ms = RETRY_DELAY_MS;
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Failed to set I2C slave address for AHT20 measure");
            return -1;
