#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define I2C address for BH1750 light sensor
#define BH1750_ADDR 0x23

// Define constants
#define RAIN_DETECTED 0
#define NO_RAIN 1
#define MOTOR_FORWARD 1
#define MOTOR_STOP 0
#define MOTOR_DURATION 5 // seconds
#define POLL_INTERVAL 2  // seconds

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *rain_line = NULL;
static struct gpiod_line *motor_enable_line = NULL;
static struct gpiod_line *motor_in1_line = NULL;
static struct gpiod_line *motor_in2_line = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor(struct gpiod_line *line);
int read_light_sensor(int fd);
void control_motor(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int duration);
void log_event(const char *event);
void signal_handler(int sig);
int init_gpio(void);
int init_i2c(void);
int cleanup_gpio(void);
int cleanup_i2c(void);

// Function to read the rain sensor
int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading rain sensor: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to read the light sensor
int read_light_sensor(int fd) {
    unsigned char data[2];
    int lux = -1;

    // Send start measurement command (High Resolution Mode)
    if (write(fd, "\x10\x00", 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    usleep(200000); // Wait for measurement (at least 180ms)

    // Read 2 bytes of data
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    lux = (data[0] << 8) | data[1];
    return lux;
}

// Function to control the motor
void control_motor(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int duration) {
    int ret;

    // Start motor
    ret = gpiod_line_set_value(enable_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting motor enable: %s\n", strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(in1_line, MOTOR_FORWARD);
    if (ret < 0) {
        fprintf(stderr, "Error setting motor IN1: %s\n", strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(in2_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting motor IN2: %s\n", strerror(errno));
        return;
    }

    log_event("Motor started");

    sleep(duration);

    // Stop motor
    ret = gpiod_line_set_value(enable_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error stopping motor enable: %s\n", strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(in1_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error stopping motor IN1: %s\n", strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(in2_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error stopping motor IN2: %s\n", strerror(errno));
        return;
