#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, turning off LED and exiting...\n", signal);
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               user, nice, system, idle, iowait, irq, softirq) != 7) {
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load
float calculate_cpu_load(unsigned long long prev_user, unsigned long long prev_nice, unsigned long long prev_system, unsigned long long prev_idle, unsigned long long prev_iowait, unsigned long long prev_irq, unsigned long long prev_softirq,
                         unsigned long long user, unsigned long long nice, unsigned long long system, unsigned long long idle, unsigned long long iowait, unsigned long long irq, unsigned long long softirq) {
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq;

    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long idle_all = idle + iowait;

    unsigned long long prev_non_idle = prev_total - prev_idle_all;
    unsigned long long non_idle = total - idle_all;

    unsigned long long prev_non_idle_all = prev_total - prev_idle_all;
    unsigned long long non_idle_all = total - idle_all;

    unsigned long long prev_idle = prev_idle;
    unsigned long long idle = idle;

    unsigned long long prev_non_idle = prev_non_idle;
    unsigned long long non_idle = non_idle;

    unsigned long long prev_non_idle_all = prev_non_idle_all;
    unsigned long long non_idle_all = non_idle_all;

    unsigned long long delta_non_idle = non_idle - prev_non_idle;
    unsigned long long delta_idle = idle - prev_idle;
    unsigned long long delta_non_idle_all = non_idle_all - prev_non_idle_all;

    if (delta_non_idle + delta_idle == 0) {
        return 0.0; // Avoid division by zero
    }

    float cpu_usage = (float)(delta_non_idle_all) / (float)(delta_non_idle + delta_idle);
    return cpu_usage;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load <= 0.5) {
        // Green to Yellow
        *green = (int)(cpu_load * 255.0);
        *red = 255 - (int)(cpu_load * 255.0);
        *blue = 0;
    } else if (cpu_load <= 1.0) {
        // Yellow to Red
        *green = 255 - (int)((cpu_load - 0.5) * 255.0);
        *red = (int)((cpu_load - 0.5) * 255.0);
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

