#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000
#define BUFFER_SIZE 20

// Temperature thresholds and duty cycle values
#define TEMP_LOW 25
#define TEMP_MED 40
#define TEMP_HIGH 60

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} log_entry_t;

log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
void add_to_buffer(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4];
    int status;

    status = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (status != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", status);
        return -1; // Indicate error
    }

    // Extract thermocouple temperature (bits 18-31, signed 14-bit value)
    int32_t raw_data = (rx_buf[0] << 24) | (rx_buf[1] << 16) | (rx_buf[2] << 8) | rx_buf[3];

    // Check for fault bits
    if (raw_data & 0x00010000) {
        fprintf(stderr, "MAX31855 Fault detected!\n");
        return -1; // Indicate error
    }

    // Extract thermocouple temperature (bits 18-31, signed 14-bit value)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask out relevant bits

    // Sign extend if negative
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend
    }

    // Convert to temperature (0.25°C resolution)
    *temperature = thermocouple_data * 0.25;

    return 0; // Indicate success
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature < TEMP_MED) {
        duty_cycle = (int)((temperature - TEMP_LOW) * 50.0 / (TEMP_MED - TEMP_LOW));
    } else if (temperature < TEMP_HIGH) {
        duty_cycle = (int)(((temperature - TEMP_MED) * 150.0 / (TEMP_HIGH - TEMP_MED)) + 50.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to add a log entry to the circular buffer
void add_to_buffer(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Temp: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(&temperature) == 0) {
            // Calculate PWM duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set PWM duty cycle
            gpioPWM(FAN_GPIO, duty_cycle);

            // Add to buffer
            add_to_buffer(temperature, duty_cycle);

            // Print buffer every 10 seconds
            if (time(NULL) % 10 == 0) {
                print_buffer();
            }
        } else {
            // Handle SPI transfer error or MAX31855 fault
            fprintf(stderr, "Error reading temperature. Skipping fan update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    // Print the full buffer contents before exiting
    print_buffer();

    return 0;
}

