#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define LOG_FILE "rtd_log.csv"
#define READ_INTERVAL_SEC 5

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// RTD Constants
#define RTD_NOMINAL_RESISTANCE 100.0  // Ohms
#define RTD_REFERENCE_RESISTANCE 430.0 // Ohms
#define RTD_RATED_TEMPERATURE 0.0     // Celsius
#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7
#define RTD_C -4.183e-12

// Global Variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int max31865_init(int fd);
int read_rtd_data(int fd, unsigned char *data);
float calculate_temperature(unsigned int rtd_raw);
int log_data(FILE *fp, float temperature);
void signal_handler(int sig);
int gpio_init(const char *chip, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_get_value(struct gpiod_line *line);

// SPI Initialization
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_arg = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_arg) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_arg = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_arg) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed_arg = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_arg) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MAX31865 Initialization
int max31865_init(int fd) {
    unsigned char config_data[2] = {0x00, 0xC2}; // 3-wire RTD, bias enabled
    unsigned char rx_buf[2];

    if (spi_transfer(fd, config_data, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to MAX31865 config register\n");
        return -1;
    }

    return 0;
}

// Read RTD Data
int read_rtd_data(int fd, unsigned char *data) {
    unsigned char tx_buf[1] = {MAX31865_RTD_MSB_REG};
    unsigned char rx_buf[3];

    if (spi_transfer(fd, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading RTD data\n");
        return -1;
    }

    data[0] = rx_buf[0];
    data[1] = rx_buf[1];
    data[2] = rx_buf[2];

    return 0;
}

// Calculate Temperature
float calculate_temperature(unsigned int rtd_raw) {
    float rtd_resistance = (float)rtd_raw * RTD_REFERENCE_RESISTANCE / 32768.0;
    float temperature = (rtd_resistance - RTD_RATED_TEMPERATURE) / RTD_A + RTD_B * (rtd_resistance - RTD_RATED_TEMPERATURE) * (rtd_resistance - RTD_RATED_TEMPERATURE) + RTD_C * (rtd_resistance - RTD_RATED_TEMPERATURE) * (rtd_resistance - RTD_RATED_TEMPERATURE) * (rtd_resistance - RTD_RATED_TEMPERATURE);
    return temperature;
}

// Log Data
int log_data(FILE *fp, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip, int pin) {
    struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name(chip);
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ptr = gpiod_chip_get_line(chip_ptr, pin);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    if (gpiod_line_request_output(line_ptr, "rtd_monitor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO Get Value
int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    unsigned char rtd_data[3];
    unsigned int rtd_raw;
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init(spi_fd) < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "GPIO chip initialization failed\n");
        close(spi_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "GPIO line initialization failed\n");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }

    // Main loop
    while (!terminate) {
        // Read RTD data
        if (read_rtd_data(spi_fd, rtd_data) == 0) {
            rtd_raw = (rtd_data[1] << 8) | rtd_data[0];
            rtd_raw &= 0x3FFF; // Mask out fault bits

            // Calculate temperature
            temperature = calculate_temperature(rtd_raw);

            // Log data
            if (log_data(log_file, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading RTD data, logging error\n");
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,Error reading RTD data\n", timestamp);
            fflush(log_file);
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    return 0;
}

