float calculate_temperature(unsigned int rtd_raw) {
    float rtd_resistance = (float)rtd_raw * RTD_REFERENCE_RESISTANCE / 32768.0;
    float temperature = (rtd_resistance - RTD_RATED_TEMPERATURE) / RTD_A + RTD_B * (rtd_resistance - RTD_RATED_TEMPERATURE) * (rtd_resistance - RTD_RATED_TEMPERATURE) + RTD_C * (rtd_resistance - RTD_RATED_TEMPERATURE) * (rtd_resistance - RTD_RATED_TEMPERATURE) * (rtd_resistance - RTD_RATED_TEMPERATURE);
