    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (bme280_read_data(i2c_fd, &calib, &temperature, &humidity, &pressure) == 0) {
            // Log data to file
            if (log_data(log_file, temperature, humidity, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
