        printf("Pressure: %.2f hPa, Average: %.2f hPa\n", pressure, average_pressure);

        // Wait 50ms
        gpioDelay(50);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();

    return 0;
}

