        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alert pin
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_temperature, raw_pressure;
    float pressure, average_pressure;

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temperature) != 0) {
            log_message("Error reading raw temperature, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }
        if (read_raw_pressure(&raw_pressure) != 0) {
            log_message("Error reading raw pressure, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate pressure
        pressure = calculate_pressure(raw_temperature, raw_pressure);

        // Add reading to circular buffer
        add_reading(pressure);

        // Calculate rolling average
        average_pressure = calculate_average_pressure();

        // Check for alert condition
        if (fabs(pressure - average_pressure) > 5.0) {
            trigger_alert();
        }

        // Print pressure reading (for debugging)
        printf("Pressure: %.2f hPa, Average: %.2f hPa\n", pressure, average_pressure);

        // Wait 50ms
        gpioDelay(50);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();

    return 0;
}

