#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP280 I2C addresses
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77

// BMP280 register addresses
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_fd = -1;
bmp280_calib_data calib;
int bmp280_address = BMP280_ADDR_1; // Default address

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t value);
int bmp280_init(int fd, bmp280_calib_data *calib);
int bmp280_read_data(int fd, bmp280_calib_data *calib, float *temperature, float *pressure);
void log_data(float temperature, float pressure);
void signal_handler(int signal);
int detect_bmp280_address(int fd);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// BMP280 initialization function
int bmp280_init(int fd, bmp280_calib_data *calib) {
    uint8_t chip_id;
    uint8_t calib_data[24];

    // Read chip ID
    if (i2c_read_bytes(fd, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (i2c_read_bytes(fd, BMP280_REG_CALIB_00, calib_data, 24) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)calib_data[0] | ((uint16_t)calib_data[1] << 8);
    calib->dig_T2 = (int16_t)calib_data[2] | ((int16_t)calib_data[3] << 8);
    calib->dig_T3 = (int16_t)calib_data[4] | ((int16_t)calib_data[5] << 8);
    calib->dig_P1 = (uint16_t)calib_data[6] | ((uint16_t)calib_data[7] << 8);
    calib->dig_P2 = (int16_t)calib_data[8] | ((int16_t)calib_data[9] << 8);
    calib->dig_P3 = (int16_t)calib_data[10] | ((int16_t)calib_data[11] << 8);
    calib->dig_P4 = (int16_t)calib_data[12] | ((int16_t)calib_data[13] << 8);
    calib->dig_P5 = (int16_t)calib_data[14] | ((int16_t)calib_data[15] << 8);
    calib->dig_P6 = (int16_t)calib_data[16] | ((int16_t)calib_data[17] << 8);
    calib->dig_P7 = (int16_t)calib_data[18] | ((int16_t)calib_data[19] << 8);
    calib->dig_P8 = (int16_t)calib_data[20] | ((int16_t)calib_data[21] << 8);
    calib->dig_P9 = (int16_t)calib_data[22] | ((int16_t)calib_data[23] << 8);

    // Set oversampling and mode
    uint8_t ctrl_meas = (0x03 << 5) | (0x03 << 2) | 0x01; // Temperature x1, Pressure x1, Forced mode
    if (i2c_write_byte(fd, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    return 0;
}

// BMP280 read data function
int bmp280_read_data(int fd, bmp280_calib_data *calib, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_temperature, raw_pressure;
    int32_t var1, var2, T, p;
    double var1_double, var2_double;

    // Trigger measurement
    uint8_t ctrl_meas = (0x03 << 5) | (0x03 << 2) | 0x01; // Temperature x1, Pressure x1, Forced mode
    if (i2c_write_byte(fd, BMP280_REG_CTRL_MEAS, ctrl_meas) != 0) {
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    // Wait for measurement to complete (with timeout)
    int timeout = 0;
    while (1) {
        uint8_t status;
        if (i2c_read_bytes(fd, BMP280_REG_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Error reading status register\n");
            return -1;
        }
        if (status & 0x04) break; // Measuring bit is set
        usleep(10000); // 10ms
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read raw data
    if (i2c_read_bytes(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    raw_pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    // Temperature compensation
    var1_double = ((double)raw_temperature / 16384.0 - (double)calib->dig_T1 / 1024.0) * (double)calib->dig_T2;
    var2_double = ((double)raw_temperature / 131072.0 - (double)calib->dig_T1 / 8192.0);
    var2_double = var2_double * var2_double * (double)calib->dig_T3;
    double t_fine = var1_double + var2_double;
    T = (int32_t)(t_fine / 5120.0);

    // Pressure compensation
    var1_double = (double)t_fine / 2.0 - 64000.0;
    var2_double = var1_double * var1_double * (double)calib->dig_P6 / 32768.0;
    var2_double = var2_double + var1_double * (double)calib->dig_P5 * 2.0;
    var2_double = (var2_double / 4.0) + ((double)calib->dig_P4 * 65536.0);
    var1_double = ((double)calib->dig_P3 * var1_double * var1_double / 524288.0 + (double)calib->dig_P2 * var1_double) / 524288.0;
    var1_double = (1.0 + var1_double / 32768.0) * (double)calib->dig_P1;
    if (var1_double == 0)
    {
        *pressure = 0;
        *temperature = T;
        return 0;
    }
    p = 1048576.0 - raw_pressure;
    p = (p - var2_double / 4096.0) * 6250.0 / var1_double;
    var1_double = (double)calib->dig_P9 * p * p / 2147483648.0;
    var2_double = p * (double)calib->dig_P8 / 32768.0;
    p = p + (var1_double + var2_double + (double)calib->dig_P7) / 16.0;

    *temperature = T;
    *pressure = p / 100.0; // Convert to hPa

    return 0;
}

// Data logging function
void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("weather_data.txt", "a");
    if (fp == NULL) {
        perror("Failed to open weather_data.txt");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to detect the BMP280 address
int detect_bmp280_address(int fd) {
    int result1 = i2c_smbus_read_byte_data(fd, 0xD0);
    if (result1 >= 0) {
        return BMP280_ADDR_1;
    }

    int result2 = i2c_smbus_read_byte_data(fd, 0xD0);
    if (result2 >= 0) {
        return BMP280_ADDR_2;
    }

    fprintf(stderr, "Error: Could not detect BMP280 address. Check I2C connection.\n");
    return -1; // Indicate error
}

int main() {
    float temperature, pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Detect BMP280 address
    bmp280_address = detect_bmp280_address(i2c_fd);
    if (bmp280_address == -1) {
        close(i2c_fd);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280
    if (bmp280_init(i2c_fd, &calib) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (bmp280_read_data(i2c_fd, &calib, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

