#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_PIN 18
#define CIRCULAR_BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_DURATION_SEC 1

// Data structures
typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureReading;

typedef struct {
    TemperatureReading readings[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static CircularBuffer circular_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
float read_temperature();
void add_reading(CircularBuffer *buffer, float temperature);
float calculate_average(CircularBuffer *buffer);
void control_led(float average_temperature);
void *data_acquisition_thread(void *arg);
void signal_handler(int signal);
int init_gpio();
int init_i2c();
void cleanup();

// Function to read temperature from LM75 sensor
float read_temperature() {
    int16_t raw_temp;
    int ret;

    ret = i2c_smbus_read_word_data(i2c_fd, TEMP_REG);
    if (ret < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return NAN; // Return NaN on error
    }

    raw_temp = (int16_t)ret;
    // Convert from two's complement
    if (raw_temp & 0x8000) {
        raw_temp |= 0xC000; // Sign extend
    }

    // Divide by 256.0 to get degrees Celsius
    return (float)raw_temp / 256.0;
}

// Function to add a temperature reading to the circular buffer
void add_reading(CircularBuffer *buffer, float temperature) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->readings[buffer->head].temperature = temperature;
    buffer->readings[buffer->head].timestamp = time(NULL);
    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;
    if (buffer->count < CIRCULAR_BUFFER_SIZE) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to calculate the running average of the temperature readings
float calculate_average(CircularBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    float sum = 0.0;
    int i;
    for (i = 0; i < buffer->count; i++) {
        sum += buffer->readings[i].temperature;
    }
    float average = sum / buffer->count;
    pthread_mutex_unlock(&buffer->mutex);
    return average;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpiod_line_set_value(gpio_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(gpio_line, 0); // Turn LED off
    }
}

// Data acquisition thread function
void *data_acquisition_thread(void *arg) {
    while (program_running) {
        float temperature = read_temperature();
        if (!isnan(temperature)) {
            add_reading(&circular_buffer, temperature);
        }
        sleep(SLEEP_DURATION_SEC);
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2c_open(I2C_BUS, LM75_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    pthread_mutex_destroy(&circular_buffer.mutex);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    pthread_mutex_init(&circular_buffer.mutex, NULL);
    circular_buffer.head = 0;
    circular_buffer.count = 0;

    // Create data acquisition thread
    pthread_t acquisition_thread;
    if (pthread_create(&acquisition_thread, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating data acquisition thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Check every second
        float average_temperature = calculate_average(&circular_buffer);
        control_led(average_temperature);
        printf("Average temperature: %.2f°C\n", average_temperature);
    }

    // Join data acquisition thread
    pthread_join(acquisition_thread, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

