#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define GPIO_HEATER 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define TARGET_TEMPERATURE 25.0 // Default target temperature
#define Kp 1.0 // Default proportional gain
#define Ki 0.1 // Default integral gain
#define Kd 0.01 // Default derivative gain
#define MAX_TEMPERATURE 80.0 // Failsafe temperature limit
#define LOG_FILE "heater_control.log"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// Global variables (minimize usage)
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Structure to hold PID parameters
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDParams;

// Structure to hold configuration data
typedef struct {
    double target_temperature;
    PIDParams pid;
} Config;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int initialize_logging();
void cleanup();
void signal_handler(int signal);
int read_config(const char *filename, Config *config);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_pwm_duty_cycle(double duty_cycle);
void log_message(const char *message);
void log_error(const char *message);
int max31865_write_register(int reg, int value);
int max31865_read_register(int reg);
int max31865_read_rtd();

// Global PID variables
double integral = 0.0;
double previous_error = 0.0;

int main() {
    Config config;

    // Read configuration from file
    if (read_config("config.json", &config) != 0) {
        log_error("Failed to read configuration file. Using default values.");
        config.target_temperature = TARGET_TEMPERATURE;
        config.pid.Kp = Kp;
        config.pid.Ki = Ki;
        config.pid.Kd = Kd;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature < -273.0) {
            log_error("Failed to read temperature. Shutting down.");
            running = 0;
            continue;
        }

        // PID control
        double pid_output = calculate_pid(config.target_temperature, temperature, &integral, &previous_error);

        // Set PWM duty cycle
        set_pwm_duty_cycle(pid_output);

        // Log data
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Temperature: %.2f C, PID Output: %.2f, Duty Cycle: %.2f", temperature, pid_output, gpioGetPWMdutycycle(GPIO_HEATER));
        log_message(log_buffer);

        // Failsafe check
        if (temperature > MAX_TEMPERATURE || (max31865_read_register(MAX31865_FAULT_REG) & 0x01)) {
            log_error("Failsafe triggered! Shutting down.");
            running = 0;
        }

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        log_error("SPI initialisation failed");
        return 1;
    }

    // Initialize MAX31865
    if (max31865_write_register(MAX31865_CONFIG_REG, 0xC1) != 0) {
