int read_calibration_data(int fd) {
    ac1 = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_AC1) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC1 + 1));
    ac2 = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_AC2) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC2 + 1));
    ac3 = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_AC3) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC3 + 1));
    ac4 = (uint16_t)((i2c_read_reg(fd, BMP180_REG_CAL_AC4) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC4 + 1));
    ac5 = (uint16_t)((i2c_read_reg(fd, BMP180_REG_CAL_AC5) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC5 + 1));
    ac6 = (uint16_t)((i2c_read_reg(fd, BMP180_REG_CAL_AC6) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_AC6 + 1));
    b1 = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_B1) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_B1 + 1));
    b2 = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_B2) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_B2 + 1));
    mb = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_MB) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MB + 1));
    mc = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_MC) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MC + 1));
    md = (int16_t)((i2c_read_reg(fd, BMP180_REG_CAL_MD) << 8) | i2c_read_reg(fd, BMP180_REG_CAL_MD + 1));

    return 0;
}

// Read raw temperature value
int read_raw_temperature(int fd) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Failed to write temperature conversion command.\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms (minimum)

    int msb = i2c_read_reg(fd, BMP180_REG_MSB);
    int lsb = i2c_read_reg(fd, BMP180_REG_LSB);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Failed to read raw temperature data.\n");
        return -1;
    }

    return (msb << 8) | lsb;
}

// Read raw pressure value
int read_raw_pressure(int fd) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Failed to write pressure conversion command.\n");
        return -1;
    }
    usleep(26000); // Wait 25.5ms (OSS = 3)

    int msb = i2c_read_reg(fd, BMP180_REG_MSB);
    int lsb = i2c_read_reg(fd, BMP180_REG_LSB);
    int xlsb = i2c_read_reg(fd, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Failed to read raw pressure data.\n");
        return -1;
    }

    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
