void signal_handler(int signal);

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    char buffer[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CALIB_START, buffer, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration_data->ac1 = (buffer[0] << 8) | buffer[1];
    calibration_data->ac2 = (buffer[2] << 8) | buffer[3];
    calibration_data->ac3 = (buffer[4] << 8) | buffer[5];
    calibration_data->ac4 = (buffer[6] << 8) | buffer[7];
    calibration_data->ac5 = (buffer[8] << 8) | buffer[9];
    calibration_data->ac6 = (buffer[10] << 8) | buffer[11];
    calibration_data->b1 = (buffer[12] << 8) | buffer[13];
    calibration_data->b2 = (buffer[14] << 8) | buffer[15];
    calibration_data->mb = (buffer[16] << 8) | buffer[17];
    calibration_data->mc = (buffer[18] << 8) | buffer[19];
    calibration_data->md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle) {
    char write_buffer[2] = {BMP180_REG_CONTROL, 0x2E};
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buffer + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature conversion command: %d\n", result);
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    char read_buffer[2];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    return (read_buffer[0] << 8) | read_buffer[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle) {
    char write_buffer[2] = {BMP180_REG_CONTROL, 0x34};
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buffer + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure conversion command: %d\n", result);
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    char read_buffer[3];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, read_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    return ((read_buffer[0] << 16) | (read_buffer[1] << 8) | read_buffer[2]) >> 8;
}

// Function to calculate true temperature in degrees Celsius
float calculate_temperature(int raw_temperature, const bmp180_calibration_data_t *calibration_data) {
    long x1 = ((long)raw_temperature - (long)calibration_data->ac6) * ((long)calibration_data->ac5) / pow(2, 15);
    long x2 = ((long)calibration_data->mc * pow(2, 11)) / (x1 + calibration_data->md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temperature, const bmp180_calibration_data_t *calibration_data) {
    long x1 = ((long)raw_temperature - (long)calibration_data->ac6) * ((long)calibration_data->ac5) / pow(2, 15);
    long x2 = ((long)calibration_data->mc * pow(2, 11)) / (x1 + calibration_data->md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration_data->b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)calibration_data->ac2 * b6) / pow(2, 11);
    long b3 = (((long)calibration_data->ac1 * 4 + x3 + x4 + 2) / 4);

    unsigned long b4 = ((unsigned long)calibration_data->ac4 * (unsigned long)(x3 + x4 + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> 0);

    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);

    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to add a reading to the circular buffer
void add_reading(time_t timestamp, float temperature, float pressure) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get a reading from the circular buffer
sensor_reading_t get_reading(int index) {
    return circular_buffer[index];
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    time_t current_time = time(NULL);

    // Read raw temperature and pressure
    raw_temperature = read_raw_temperature(i2c_handle);
    if (raw_temperature == -1) {
        fprintf(stderr, "Error reading raw temperature, skipping sample.\n");
        return;
    }

    raw_pressure = read_raw_pressure(i2c_handle);
    if (raw_pressure == -1) {
        fprintf(stderr, "Error reading raw pressure, skipping sample.\n");
        return;
    }

    // Calculate true temperature and pressure
    float temperature = calculate_temperature(raw_temperature, &calibration_data);
    float pressure = calculate_pressure(raw_pressure, raw_temperature, &calibration_data);

    // Add reading to circular buffer
    add_reading(current_time, temperature, pressure);

    // Control the fan
    control_fan(temperature);

    // Print the reading to stdout
    printf("Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n", current_time, temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Error reading calibration data, exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Keep the program running until a signal is received
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Clean up
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

