// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cWriteByte(handle, reg) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
