        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *raw_temperature = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *raw_pressure = (int32_t)((buf[0] << 16 | buf[1] << 8 | buf[2]) >> (8 - BMP180_OSS));
    return 0;
}

