double calculate_pressure(int raw_pressure, double temperature)
{
    int32_t B6 = ((int32_t)temperature * 10 - (int32_t)ac6) * ((int32_t)ac5) >> 15;
    int32_t X1 = ((int32_t)b2 * ((B6 * B6) >> 12)) >> 11;
    int32_t X2 = ((int32_t)ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
