    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Data logging program started. Press GPIO27 to toggle logging.\n");

    // Main loop
    while (!terminate_flag) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            double temperature, pressure;

            if (read_raw_temperature(&raw_temperature) == 0 &&
                read_raw_pressure(&raw_pressure) == 0) {

                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, temperature);

                log_data(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

