        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *raw_temperature = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *raw_pressure = (int32_t)((buf[0] << 16 | buf[1] << 8 | buf[2]) >> (8 - BMP180_OSS));
    return 0;
}

// Function to calculate the compensated temperature
double calculate_temperature(int raw_temperature)
{
    int32_t X1 = (((int32_t)raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate the compensated pressure
double calculate_pressure(int raw_pressure, double temperature)
{
    int32_t B6 = ((int32_t)temperature * 10 - (int32_t)ac6) * ((int32_t)ac5) >> 15;
    int32_t X1 = ((int32_t)b2 * ((B6 * B6) >> 12)) >> 11;
    int32_t X2 = ((int32_t)ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    uint32_t X1_u = ((int32_t)ac3 * B6) >> 13;
    uint32_t X2_u = ((int32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t X3_u = ((X1_u + X2_u) + 2) >> 2;
    uint32_t B4 = ((uint32_t)ac4 * (X3_u + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to log the data to a file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler for the logging toggle pin
void interrupt_handler(int gpio, int level, unsigned int tick, void *user)
{
    unsigned long current_time = gpioTick();

    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = current_time;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, terminating...\n", signal);
    terminate_flag = 1;
}

// Function to initialize GPIO
int init_gpio()
{
    if (gpioSetMode(LOG_TOGGLE_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    if (gpioSetPullUpDown(LOG_TOGGLE_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up.\n");
        return -1;
    }
    if (gpioSetISRFuncEx(LOG_TOGGLE_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function.\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c()
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize logging
int init_logging()
{
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return -1;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Data logging program started. Press GPIO27 to toggle logging.\n");

    // Main loop
    while (!terminate_flag) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            double temperature, pressure;

            if (read_raw_temperature(&raw_temperature) == 0 &&
                read_raw_pressure(&raw_pressure) == 0) {

                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, temperature);

                log_data(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

