#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL 1 // seconds

// PI Controller Gains
#define Kp 1.0
#define Ki 0.1

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
double read_temperature();
double calculate_pwm(double temperature);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855 via SPI
double read_temperature() {
    unsigned char data[4];
    int i2c_handle;
    double temperature = -1000.0; // Initialize to an invalid value

    i2c_handle = i2cOpen(1, 0x48, 0); // Open I2C device (MAX31855)
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return temperature; // Return invalid temperature
    }

    if (i2cReadDevice(i2c_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading from I2C device\n");
        i2cClose(i2c_handle);
        return temperature;
    }

    i2cClose(i2c_handle);

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return temperature;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return temperature;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return temperature;
    }

    // Extract temperature data (bits 18-31 are temperature, signed 14-bit value)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_pwm(double temperature) {
    double error = TARGET_TEMPERATURE - temperature;

    // Anti-windup
    integral += error;
    if (integral > MAX_DUTY_CYCLE) {
        integral = MAX_DUTY_CYCLE;
    } else if (integral < 0) {
        integral = 0;
    }

    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + derivative;

    // Limit the output to the safe maximum duty cycle
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    } else if (output < 0) {
        output = 0;
    }

    previous_error = error;
    return output;
}

// Function to log data to a CSV file
void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,DutyCycle\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    gpioPWM(HEATER_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double target_temperature = TARGET_TEMPERATURE;

    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Target temperature: %.2f°C\n", target_temperature);

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature > -999.0) {
            double duty_cycle = calculate_pwm(temperature);
            gpioPWM(HEATER_GPIO, (int)(duty_cycle * 255.0 / 100.0));
            log_data(temperature, duty_cycle);
            printf("Temperature: %.2f°C, Duty Cycle: %.2f%%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature, setting duty cycle to 0%%\n");
            gpioPWM(HEATER_GPIO, 0);
            log_data(temperature, 0.0);
        }

        time_sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

