#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 5 // seconds
#define JSON_BUFFER_SIZE 128

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    unsigned int pulse_lengths[85];

    // 1. Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    // 2. Switch to input mode
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // 3. Read response
    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // 1 us
            if (count > 200) {
                fprintf(stderr, "Timeout waiting for pulse %d\n", i);
                return data; // Return invalid data on timeout
            }
        }
        pulse_lengths[i] = count;
    }

    // 4. Decode data
    for (i = 0; i < 40; i++) {
        int index = 2 + (i * 2);
        if (pulse_lengths[index] > 40) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // 5. Validate checksum
    if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) != raw_data[4]) {
        fprintf(stderr, "Checksum error\n");
        return data; // Return invalid data on checksum error
    }

    // 6. Convert data
    data.humidity = (float)raw_data[0] * 256 + raw_data[1];
    data.temperature = (float)(raw_data[2] & 0x7F) * 256 + raw_data[3];
    if (raw_data[2] & 0x80) {
        data.temperature *= -1;
    }
    data.valid = 1;

    return data;
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    char *json_string = malloc(JSON_BUFFER_SIZE);
    if (json_string == NULL) {
        fprintf(stderr, "Failed to allocate memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, JSON_BUFFER_SIZE, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
    return json_string;
}

// Function to send HTTP POST request
int send_http_post(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        DHT22Data dht22_data;
        int retries = 0;
        int send_success = 0;

        // Retry loop for reading DHT22 data
        while (retries < MAX_RETRIES) {
            dht22_data = read_dht22();
            if (dht22_data.valid) {
                break;
            } else {
                fprintf(stderr, "DHT22 read failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                sleep(RETRY_DELAY);
            }
        }

        if (!dht22_data.valid) {
            fprintf(stderr, "DHT22 read failed after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Retry loop for sending HTTP POST request
        while (retries < MAX_RETRIES) {
            char *json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                if (send_http_post("http://yourserver.com/api/humidity", json_data) == 0) {
                    send_success = 1;
                    break;
                } else {
                    fprintf(stderr, "HTTP POST failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
                    retries++;
                    sleep(RETRY_DELAY);
                }
                free(json_data);
            } else {
                fprintf(stderr, "Failed to format JSON, retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                sleep(RETRY_DELAY);
            }
        }

        if (!send_success) {
            fprintf(stderr, "HTTP POST failed after %d retries\n", MAX_RETRIES);
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up pigpio
    gpioTerminate();

    return 0;
}

