#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// GPIO pin for push-button interrupt
#define PUSH_BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile unsigned int last_interrupt_time = 0;
static int ac1, ac2, ac3, b1, b2, mb, mc, md, ac4, ac5, ac6;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, double temperature);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);
void log_data(double pressure);
void log_status();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    unsigned char buffer[22];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buffer, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (buffer[0] << 8) | buffer[1];
    ac2 = (buffer[2] << 8) | buffer[3];
    ac3 = (buffer[4] << 8) | buffer[5];
    ac4 = (buffer[6] << 8) | buffer[7];
    ac5 = (buffer[8] << 8) | buffer[9];
    ac6 = (buffer[10] << 8) | buffer[11];
    b1 = (buffer[12] << 8) | buffer[13];
    b2 = (buffer[14] << 8) | buffer[15];
    mb = (buffer[16] << 8) | buffer[17];
    mc = (buffer[18] << 8) | buffer[19];
    md = (buffer[20] << 8) | buffer[21];

    // Basic validation (example: check if AC1 is within a reasonable range)
    if (ac1 < 0 || ac1 > 32768) {
        fprintf(stderr, "Error: Invalid AC1 value: %d\n", ac1);
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    int result;

    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[2];
    int result;

    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(26000); // Wait 26ms for OSS = 3

    buf[0] = BMP180_REG_MSB;
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    *raw_pressure = ((unsigned long)buf[0] << 16 | (unsigned long)buf[1] << 8 | (unsigned long)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1, x2, b5;
    double temperature;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;
    temperature = ((b5 + 8) >> 4) / 10.0; // Temperature in degrees Celsius

    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, double temperature) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;
    double pressure;

    long UT = 0; // Dummy value, not used in this implementation
    long UP = raw_pressure; // Use raw pressure directly

    b6 = ((long)temperature * 10) - 400; // Temperature in 0.1 deg C
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)UP - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    pressure = p + ((x1 + x2 + 3791) >> 4); // Pressure in Pa

    pressure /= 100.0; // Convert to hPa

    return pressure;
}

// Interrupt handler for push-button
void interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    unsigned int current_time = tick;

    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;

        if (logging_enabled) {
            log_data(0.0); // Log a dummy value to open the file
        } else {
            log_status();
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Function to log data to file
void log_data(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log status to console
void log_status() {
    printf("Data logging is OFF.\n");
}

int main() {
    int raw_temp, raw_pressure;
    double temperature, pressure;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(PUSH_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(PUSH_BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    gpioSetISRFuncEx(PUSH_BUTTON_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Data logging is OFF. Press the push-button to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            result = read_raw_temperature(&raw_temp);
            if (result != 0) {
                fprintf(stderr, "Error reading raw temperature, retrying...\n");
                gpioDelay(1000000); // Wait 1 second before retrying
                continue;
            }

            result = read_raw_pressure(&raw_pressure);
            if (result != 0) {
                fprintf(stderr, "Error reading raw pressure, retrying...\n");
                gpioDelay(1000000); // Wait 1 second before retrying
                continue;
            }

            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temp);
            pressure = calculate_pressure(raw_pressure, temperature);

            // Log data
            log_data(pressure);
        } else {
            log_status();
        }

        gpioDelay(2000000); // Sample every 2 seconds
    }

    return 0;
}

