#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define DEFAULT_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds

// Structure to hold DHT22 data
typedef struct {
    int humidity;
    int checksum;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *server_url = NULL;

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Function to initialize libcurl
CURL *curl_init_wrapper() {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "libcurl initialization failed");
        return NULL;
    }
    return curl;
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int checksum;

    // 1. Start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(gpio, 1);
    gpioDelay(20); // 20-40 us
    gpioSetMode(gpio, PI_INPUT);
    gpioDelay(30); // Wait for the sensor to respond

    // 2. Read data bits
    for (i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(gpio) == 0) {
            count++;
            gpioDelay(1); // Check every 1 us
            if (count > 100) {
                syslog(LOG_ERR, "Timeout waiting for high signal");
                return -1;
            }
        }

        count = 0;
        while (gpioRead(gpio) == 1) {
            count++;
            gpioDelay(1); // Check every 1 us
            if (count > 100) {
                syslog(LOG_ERR, "Timeout waiting for low signal");
                return -1;
            }
        }

        data_bits[i] = (count > 40) ? 1 : 0; // Determine bit value based on duration
    }

    // 3. Calculate checksum
    checksum = 0;
    for (i = 0; i < 32; i++) {
        checksum += data_bits[i];
    }

    // 4. Validate checksum
    data->checksum = checksum;
    data->humidity = 0;
    for (i = 0; i < 16; i++) {
        data->humidity <<= 1;
        data->humidity |= data_bits[i];
    }

    for (i = 0; i < 8; i++) {
        data->humidity <<= 1;
        data->humidity |= data_bits[i + 16];
    }

    if (data->checksum != data_bits[32] && data->checksum != data_bits[32] && data->checksum != data_bits[32] && data->checksum != data_bits[32]) {
        syslog(LOG_ERR, "Checksum failure");
        return -1;
    }

    return 0;
}

// Function to format data as JSON
char *format_json(int humidity) {
    char *json_string = malloc(50);
    if (json_string == NULL) {
        syslog(LOG_ERR, "Memory allocation failed");
        return NULL;
    }
    snprintf(json_string, 50, "{\"humidity\": %d}", humidity);
    return json_string;
}

// Function to POST data to server
int post_data(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    int retry_count = 0;

    curl = curl_init_wrapper();
    if (curl == NULL) {
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, (struct curl_slist *)malloc(sizeof(struct curl_slist)));
    struct curl_slist *headers = (struct curl_slist *)malloc(sizeof(struct curl_slist));
    headers->next = NULL;
    headers->data = strdup("Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    while (retry_count < MAX_RETRIES) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                syslog(LOG_INFO, "Data posted successfully");
                break;
            } else {
                syslog(LOG_ERR, "HTTP request failed with code: %ld", response_code);
            }
        } else {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        }

        retry_count++;
        if (retry_count < MAX_RETRIES) {
            syslog(LOG_WARNING, "Retrying in %d seconds...", BACKOFF_DELAY * (1 << retry_count));
            sleep(BACKOFF_DELAY * (1 << retry_count));
        }
    }

    curl_easy_cleanup(curl);
    free(headers->data);
    free(headers);
    if (res != CURLE_OK) {
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    DHT22Data dht22_data;
    char *json_data;
    int humidity;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (server_url == NULL) {
        server_url = DEFAULT_URL;
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read DHT22 sensor
        if (read_dht22(DHT22_GPIO, &dht22_data) == 0) {
            humidity = dht22_data.humidity;
            syslog(LOG_INFO, "Humidity: %d", humidity);

            // Format data as JSON
            json_data = format_json(humidity);
            if (json_data != NULL) {
                // Post data to server
                if (post_data(server_url, json_data) != 0) {
                    syslog(LOG_ERR, "Failed to post data");
                }

                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor");
        }

        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    closelog();

    return 0;
}

