#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"

// PID Gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID State
float integral = 0.0;
float previous_error = 0.0;

// Function Prototypes
float read_temperature();
float calculate_pid(float setpoint, float actual_temperature);
void set_heater_pwm(float duty_cycle);
void log_data(float temperature, float duty_cycle, float pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i;
    float temperature = -1000.0; // Initialize to an invalid value
    int fault;

    // Read 4 bytes from SPI
    for (i = 0; i < 4; i++) {
        data[i] = 0;
    }

    if (spiRead(spi_handle, (char *)data, 4) != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate SPI read error
    }

    // Extract temperature data (bits 18-31) and fault bits (bits 2-3)
    int16_t raw_temperature = ((data[0] << 8) | data[1]) >> 2;
    fault = (data[2] >> 6) & 0x03;

    // Check for fault conditions
    if (fault) {
        if (fault & 0x01) {
            fprintf(stderr, "Thermocouple open circuit\n");
        } else if (fault & 0x02) {
            fprintf(stderr, "Thermocouple short to GND\n");
        } else {
            fprintf(stderr, "Thermocouple short to VCC\n");
        }
        return -1000.0; // Indicate thermocouple fault
    }

    // Convert to Celsius
    temperature = raw_temperature * 0.25;

    // Failsafe: Check temperature range
    if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1000.0; // Indicate failsafe error
    }

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature) {
    float error = setpoint - actual_temperature;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) {
        output = 0;
    } else if (output > 100) {
        output = 100;
    }

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(float duty_cycle) {
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Function to log data to file
void log_data(float temperature, float duty_cycle, float pid_output) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable heater
    set_heater_pwm(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float target_temperature = TARGET_TEMPERATURE;
    float actual_temperature;
    float pid_output;
    float duty_cycle;

    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
    }

    // Print PID gains
    printf("PID Gains: Kp=%.2f, Ki=%.2f, Kd=%.2f\n", Kp, Ki, Kd);
    printf("Target Temperature: %.2f\n", target_temperature);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        actual_temperature = read_temperature();

        if (actual_temperature > -999.0) {
            // Calculate PID output
            pid_output = calculate_pid(target_temperature, actual_temperature);

            // Set heater PWM
            duty_cycle = pid_output;
            set_heater_pwm(duty_cycle);

            // Log data
            log_data(actual_temperature, duty_cycle, pid_output);
        } else {
            fprintf(stderr, "Invalid temperature reading, disabling heater.\n");
            set_heater_pwm(0.0);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

