#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASURE_CMD 0x3608
#define FLOW_SCALE_FACTOR 0.01
#define LOG_FILE "flow_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor(int handle, int addr, unsigned char *data);
unsigned char crc8(const unsigned char *data, int len);
float convert_flow_rate(int raw_value);
int log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Read data from the sensor with retries
int read_sensor(int handle, int addr, unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByteData(handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
        if (result >= 0) {
            result = i2cReadI2CBlockData(handle, 0x00, (char *)data, 3);
            if (result == 3) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw sensor reading to flow rate (ml/min)
float convert_flow_rate(int raw_value) {
    return raw_value * FLOW_SCALE_FACTOR;
}

// Log flow rates to file
int log_flow_rates(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char sensor_data[3];
    int raw_flow1, raw_flow2;
    float flow_rate1, flow_rate2;

    // Main loop
    while (!terminate) {
        // Read sensor 1
        if (read_sensor(i2c_handle1, SENSOR1_ADDR, sensor_data) == 0) {
            // Validate CRC
            if (crc8(sensor_data, 2) == sensor_data[2]) {
                raw_flow1 = (sensor_data[0] << 8) | sensor_data[1];
                flow_rate1 = convert_flow_rate(raw_flow1);
            } else {
                fprintf(stderr, "CRC check failed for sensor 1\n");
                flow_rate1 = -1.0; // Indicate error
            }
        } else {
            flow_rate1 = -1.0; // Indicate error
        }

        // Read sensor 2
        if (read_sensor(i2c_handle2, SENSOR2_ADDR, sensor_data) == 0) {
            // Validate CRC
            if (crc8(sensor_data, 2) == sensor_data[2]) {
                raw_flow2 = (sensor_data[0] << 8) | sensor_data[1];
                flow_rate2 = convert_flow_rate(raw_flow2);
            } else {
                fprintf(stderr, "CRC check failed for sensor 2\n");
                flow_rate2 = -1.0; // Indicate error
            }
        } else {
            flow_rate2 = -1.0; // Indicate error
        }

        // Log flow rates
        if (log_flow_rates(flow_rate1, flow_rate2) != 0) {
            fprintf(stderr, "Error logging flow rates.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();

    return 0;
}

