#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 18

// Define the number of pulses per revolution (360 degrees)
#define PULSES_PER_REVOLUTION 360

// Define the number of states in the quadrature state machine
#define NUM_STATES 4

// Global variables
static volatile int running = 1;
static volatile int current_state = 0;
static volatile int pulse_count = 0;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void log_encoder_data(int state, float angular_position);
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log encoder data to a file
void log_encoder_data(int state, float angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, State: %d, Angular Position: %.2f\n", timestamp, state, angular_position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for GPIO interrupts
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static int last_a_state = 0;
    static int last_b_state = 0;
    int a_state, b_state;
    int next_state;
    float angular_position;

    a_state = gpioRead(SENSOR_A_GPIO);
    b_state = gpioRead(SENSOR_B_GPIO);

    if (gpio == SENSOR_A_GPIO) {
        if (a_state != last_a_state) {
            if (b_state != last_b_state) {
                if (a_state == 0 && b_state == 0) {
                    next_state = (current_state + 1) % NUM_STATES;
