#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define RED_DATA_REG 0x62
#define IR_DATA_REG 0x64
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, unsigned char reg);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int read_adpd144ri_data(int fd, int *red, int *ir);
int log_data(FILE *fp, int red, int ir);
void control_led(struct gpiod_line *line, int state);
void signal_handler(int sig);

// I2C read function
int i2c_read_word(int fd, unsigned char reg) {
    unsigned char buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select)");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read (data)");
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write (data)");
        return -1;
    }
    return 0;
}

// Read data from ADPD144RI
int read_adpd144ri_data(int fd, int *red, int *ir) {
    int fifo_data = i2c_read_word(fd, FIFO_DATA_REG);
    if (fifo_data < 0) return -1;

    *red = i2c_read_word(fd, RED_DATA_REG);
    if (*red < 0) return -1;

    *ir = i2c_read_word(fd, IR_DATA_REG);
    if (*ir < 0) return -1;

    return 0;
}

// Log data to file
int log_data(FILE *fp, int red, int ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d\n", timestamp, red, ir) < 0) {
        perror("Log file write");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Control LED
void control_led(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("GPIO set value");
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int red, ir;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000L}; // 100ms

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("I2C set slave address");
        close(i2c_fd);
        return 1;
    }

    // GPIO setup
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("GPIO chip open");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        perror("GPIO line get");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "adpd144ri_monitor", 0) < 0) {
        perror("GPIO request output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Log file setup
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Log file open");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            if (log_data(log_file, red, ir) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            if (ir > IR_THRESHOLD) {
                control_led(gpio_line, 1); // Turn LED on
            } else {
                control_led(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading ADPD144RI data.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    control_led(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

