#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define PULSES 1

volatile int pulses = 0;
pthread_mutex_t pulses_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulses_mutex);
    exit(0);
}

// Interrupt service routine (ISR) for rising edge detection
void isr_rising_edge(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // Unused parameters
    pthread_mutex_lock(&pulses_mutex);
    pulses++;
    pthread_mutex_unlock(&pulses_mutex);
}

// Function to calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0;
}

// Function to log RPM data to a file
void log_rpm_data(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register ISR for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, PULSES, isr_rising_edge, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Measure pulses over 1 second
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        gpioDelay(1000); // Wait for 1 second
        clock_gettime(CLOCK_MONOTONIC, &end);

        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        long elapsed_us = elapsed_ns / 1000;

        // Calculate RPM
        int measured_pulses = 0;
        pthread_mutex_lock(&pulses_mutex);
        measured_pulses = pulses;
        pulses = 0; // Reset pulse count
        pthread_mutex_unlock(&pulses_mutex);

        double rpm = calculate_rpm(measured_pulses);

        // Log RPM data
        log_rpm_data(rpm);

        printf("RPM: %.2f\n", rpm);
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulses_mutex);
    return 0;
}

