        return -1;
    }
    return 0;
}

// Function to read FIFO data (Red and IR channels)
int read_fifo_data(int handle, unsigned short *red, unsigned short *ir) {
    unsigned char buffer[4];
    int result = i2cReadI2CBlockData(handle, RED_REG, (char *)buffer, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }

    *red = (buffer[1] << 8) | buffer[0];
