    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(LED_GPIO) != 0) {
        i2cClose(i2c_handle);
        return 1;
    }

