    int part_id = read_register(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID, exiting\n");
        cleanup_gpio(LED_GPIO);
        i2cClose(i2c_handle);
        return 1;
    }
    printf("ADPD144RI PART_ID: 0x%02X\n", part_id);

