    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set the gain level
int set_gain(int gain_pin, int gain_level) {
    if (gpioWrite(gain_pin, gain_level) != 0) {
        fprintf(stderr, "Error setting gain level on GPIO %d\n", gain_pin);
        return -1;
    }
    return 0;
}

// Function to detect a rising edge
int detect_rising_edge(int audio_input_pin) {
    int current_level = gpioRead(audio_input_pin);
    gpioDelay(1); // Small delay to avoid missing edges
    int next_level = gpioRead(audio_input_pin);

    if (current_level == 0 && next_level == 1) {
        return 1; // Rising edge detected
    }
    return 0; // No rising edge detected
}

// Function to log the timestamp and level to a file
int log_event(const char *timestamp, int level) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening audio_log.txt for writing\n");
        return -1;
    }

    fprintf(fp, "%s %d\n", timestamp, level);
    fclose(fp);
    return 0;
}

// Function to get the current timestamp in the required format
int get_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    if (strftime(timestamp_buffer, buffer_size, "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    return 0;
}

