        fprintf(stderr, "Error setting GPIO %d as input\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GAIN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GAIN_PIN);
        gpioTerminate();
        return 1;
    }

    // Set gain to 60dB
    if (set_gain(GAIN_PIN, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (detect_rising_edge(AUDIO_INPUT_PIN)) {
            char timestamp[20];
            if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_event(timestamp, 1) != 0) {
