            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        }
        gpioDelay(10); // 10ms delay
    }

    // Clean up and terminate
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

