#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define START_MEASUREMENT_CMD 0x3608
#define FLOW_RATE_SCALE_FACTOR 1000.0 // uL/min per raw unit
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c(int handle, int data);
int read_i2c(int handle, char *buf, int count);
uint8_t calculate_crc(uint8_t data, uint8_t crc);
float convert_to_flow_rate(int16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Opens the I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Writes data to the I2C device
int write_i2c(int handle, int data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads data from the I2C device
int read_i2c(int handle, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buf, count);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return result;
}

// Calculates the CRC-8 checksum
uint8_t calculate_crc(uint8_t data, uint8_t crc) {
    crc ^= data;
    for (int i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ CRC_POLYNOMIAL;
        } else {
            crc <<= 1;
        }
    }
    return crc;
}

// Converts the raw flow rate to uL/min
float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE_FACTOR;
}

// Logs the flow rate to a CSV file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

