    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Clamp value to range [0, 100]
float clamp(float value, float min, float max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    float iaq;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ
            iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);

            // Log data
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            printf("IAQ: %.2f, TVOC: %u, eCO2: %u\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", READ_INTERVAL_SEC);
        }

        // Wait for the next interval
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

