#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pin and chip name
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"

// Define intrusion alert duration (seconds)
#define INTRUSION_DURATION 5

// Global variables for signal handling and GPIO
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int check_intrusion(struct gpiod_line *line, int duration);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr);
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to check for intrusion
int check_intrusion(struct gpiod_line *line, int duration) {
    struct timespec start_time, current_time;
    int sensor_state = 1; // Assume touched initially
    int start_value = read_sensor(line);
    if (start_value < 0) return -1; // Propagate error

    if (start_value == 0) {
        sensor_state = 0; // Initially released
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
        fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
        return -1;
    }

    while (1) {
        int current_value = read_sensor(line);
        if (current_value < 0) return -1; // Propagate error

        if (current_value != sensor_state) {
            // State changed
            if (sensor_state == 1) {
                // Touched
                if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                    fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
                    return -1;
                }
                double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
                if (elapsed_time >= duration) {
                    printf("Intrusion detected! Sensor touched for %.2f seconds.\n", elapsed_time);
                    return 1; // Intrusion detected
                }
            }
            sensor_state = current_value;
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
                return -1;
            }
        }
        usleep(10000); // Check every 10ms
    }
    return 0; // No intrusion detected
}

// Function to set up GPIO
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr) {
    *chip_ptr = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip_ptr) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    *line_ptr = gpiod_chip_get_line(*chip_ptr, GPIO_PIN);
    if (!*line_ptr) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(*chip_ptr);
        return -1;
    }

    int ret = gpiod_line_request(*line_ptr, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*line_ptr);
        return -1;
    }

    return 0;
}

// Function to clean up GPIO
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio(&chip, &line) != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Monitoring GPIO %d on chip %s...\n", GPIO_PIN, GPIO_CHIP);

    // Main loop
    while (!terminate) {
        if (check_intrusion(line, INTRUSION_DURATION) == 1) {
            // Intrusion detected, print alert
            printf("Intrusion detected! Sensor touched for %.2f seconds.\n", INTRUSION_DURATION);
        } else if (check_intrusion(line, INTRUSION_DURATION) < 0) {
            // Error occurred during intrusion check
            fprintf(stderr, "Error during intrusion check. Exiting.\n");
            break;
        }
        usleep(100000); // Check every 100ms
    }

    // Clean up GPIO
    if (cleanup_gpio(chip, line) != 0) {
        fprintf(stderr, "GPIO cleanup failed.\n");
    }

    printf("Tamper detection system stopped.\n");

    return EXIT_SUCCESS;
}

