    *chip_ptr = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip_ptr) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    *line_ptr = gpiod_chip_get_line(*chip_ptr, GPIO_PIN);
    if (!*line_ptr) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(*chip_ptr);
        return -1;
    }

    int ret = gpiod_line_request(*line_ptr, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip_ptr);
        gpiod_line_release(*line_ptr);
        return -1;
    }

    return 0;
}

// Function to clean up GPIO
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio(&chip, &line) != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Monitoring GPIO %d on chip %s...\n", GPIO_PIN, GPIO_CHIP);

    // Main loop
    while (!terminate) {
        if (check_intrusion(line, INTRUSION_DURATION) == 1) {
            // Intrusion detected, print alert
            printf("Intrusion detected! Sensor touched for %.2f seconds.\n", INTRUSION_DURATION);
        } else if (check_intrusion(line, INTRUSION_DURATION) < 0) {
            // Error occurred during intrusion check
            fprintf(stderr, "Error during intrusion check. Exiting.\n");
            break;
        }
        usleep(100000); // Check every 100ms
    }

    // Clean up GPIO
    if (cleanup_gpio(chip, line) != 0) {
        fprintf(stderr, "GPIO cleanup failed.\n");
    }

    printf("Tamper detection system stopped.\n");

    return EXIT_SUCCESS;
}

