#include <errno.h>

#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S24_LE
#define PERIOD_SIZE 1024
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Function to initialize the GPIO line
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "audio_capture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set the GPIO line high
int set_gpio_high() {
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting GPIO line high");
        return -1;
    }
    return 0;
}

// Function to set the GPIO line low
int set_gpio_low() {
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting GPIO line low");
        return -1;
    }
    return 0;
}

// Function to initialize ALSA
int init_alsa() {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    snd_pcm_uframes_t frames = PERIOD_SIZE;
    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to read audio data from ALSA
int read_audio_data(short *buffer, int frames) {
    int err = snd_pcm_readi(pcm_handle, buffer, frames);
    if (err < 0) {
        fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
        return -1;
    } else if (err != frames) {
        fprintf(stderr, "Short read, read %d frames instead of %d\n", err, frames);
    }
    return 0;
}

// Function to process 24-bit data to 16-bit PCM
int process_audio_data(short *buffer, int frames) {
    for (int i = 0; i < frames; i++) {
        // Extract 24-bit data from the 32-bit frame
        int32_t raw_data = (int32_t)buffer[i];
        int24_t sample = (int24_t)(raw_data >> 8); // Right-shift to get 24-bit data

        // Convert 24-bit data to 16-bit PCM
        buffer[i] = (short)sample;
    }
    return 0;
}

// Function to write audio data to file
int write_to_file(const short *buffer, int frames) {
    FILE *fp = fopen(FILENAME, "ab");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, sizeof(short), frames, fp);
    if (bytes_written != frames) {
        fprintf(stderr, "Error writing to file: wrote %zu frames, expected %d\n", bytes_written, frames);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    if (init_alsa() < 0) {
        fprintf(stderr, "ALSA initialization failed. Exiting.\n");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (!buffer) {
        perror("Error allocating buffer");
        snd_pcm_close(pcm_handle);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    while (keep_running) {
        if (set_gpio_high() < 0) {
            fprintf(stderr, "Error setting GPIO high. Exiting.\n");
            break;
        }

        if (read_audio_data(buffer, PERIOD_SIZE) < 0) {
            fprintf(stderr, "Error reading audio data. Exiting.\n");
            break;
        }

        if (process_audio_data(buffer, PERIOD_SIZE) < 0) {
            fprintf(stderr, "Error processing audio data. Exiting.\n");
            break;
        }

        if (write_to_file(buffer, PERIOD_SIZE) < 0) {
            fprintf(stderr, "Error writing to file. Exiting.\n");
            break;
        }

        if (set_gpio_low() < 0) {
            fprintf(stderr, "Error setting GPIO low. Exiting.\n");
            break;
        }

        usleep(1000); // Small delay to avoid busy-waiting
    }

    free(buffer);
    snd_pcm_close(pcm_handle);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    printf("Audio capture stopped.\n");
    return 0;
}

