#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency and duty cycle range
#define PWM_FREQUENCY 100
#define DUTY_CYCLE_RANGE 80

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define timeout duration in seconds
#define TIMEOUT_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int duty_cycle);
int calculate_duty_cycle(int flame_duration);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t flame_start_time;
    int duty_cycle;
} ProgramState;

ProgramState state = {0, 0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 1) {
            if (!state.flame_detected) {
                state.flame_detected = 1;
                state.flame_start_time = time(NULL);
                log_event("Flame detected");
            }
        } else {
            if (state.flame_detected) {
                // Calculate duty cycle based on flame duration
                int flame_duration = (int)(time(NULL) - state.flame_start_time);
                state.duty_cycle = calculate_duty_cycle(flame_duration);
                control_fan(state.duty_cycle);
                log_event("Flame ended");
                state.flame_detected = 0;
            }
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    log_event("System stopped");
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 100); // Set PWM range to 100 for percentage

    return 0;
}

// Read flame sensor value with debouncing
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    return value;
}

// Control fan speed using PWM
void control_fan(int duty_cycle) {
    if (state.flame_detected) {
        gpioPWM(FAN_PIN, duty_cycle);
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off fan
    }
}

// Calculate duty cycle based on flame duration using an exponential curve
int calculate_duty_cycle(int flame_duration) {
    // Exponential curve: duty_cycle = a * exp(b * flame_duration)
    // Adjust 'a' and 'b' to control the curve
    double a = 80.0;  // Maximum duty cycle
    double b = -0.05; // Exponential decay rate

    // Clamp duty cycle to 0-100 range
    int duty_cycle = (int)(a * exp(b * flame_duration));
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 100) {
        duty_cycle = 100;
    }

    return duty_cycle;
}

// Log events to file with ISO-8601 timestamp
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set to input to avoid spurious output
    gpioSetMode(FAN_PIN, PI_INPUT); // Set to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

