    return 0;
}

// Read flame sensor value with debouncing
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    return value;
}

// Control fan speed using PWM
void control_fan(int duty_cycle) {
    if (state.flame_detected) {
        gpioPWM(FAN_PIN, duty_cycle);
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off fan
    }
}

// Calculate duty cycle based on flame duration using an exponential curve
int calculate_duty_cycle(int flame_duration) {
    // Exponential curve: duty_cycle = a * exp(b * flame_duration)
    // Adjust 'a' and 'b' to control the curve
    double a = 80.0;  // Maximum duty cycle
    double b = -0.05; // Exponential decay rate

    // Clamp duty cycle to 0-100 range
    int duty_cycle = (int)(a * exp(b * flame_duration));
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 100) {
        duty_cycle = 100;
    }

    return duty_cycle;
}

