#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define data size
#define DATA_SIZE 32768

// Define configuration parameters
#define START_FREQUENCY 77000000000.0 // 77 GHz
#define END_FREQUENCY 79000000000.0  // 79 GHz
#define NUM_CHIRPS 64
#define NUM_SAMPLES 256
#define FRAME_PERIOD_MS 100

// Define magic number
#define MAGIC_NUMBER 0x52444144

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    double start_frequency;
    double end_frequency;
    int num_chirps;
    int num_samples;
    int frame_period_ms;
} config_t;

// Function prototypes
int initialize();
void trigger_frame();
int read_heatmap_data(uint8_t *data);
void log_data(uint8_t *data, int frame_number);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write header
    uint32_t magic = MAGIC_NUMBER;
    fwrite(&magic, sizeof(uint32_t), 1, log_file);
    fwrite("Timestamp", sizeof(char), 8, log_file);
    fwrite("Config", sizeof(char), 8, log_file);

    config_t config;
    config.start_frequency = START_FREQUENCY;
    config.end_frequency = END_FREQUENCY;
    config.num_chirps = NUM_CHIRPS;
    config.num_samples = NUM_SAMPLES;
    config.frame_period_ms = FRAME_PERIOD_MS;

    fwrite(&config, sizeof(config_t), 1, log_file);

    return 0;
}

// Trigger a frame by asserting the trigger pin
void trigger_frame() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

