int read_heatmap_data(uint8_t *data) {
    int result = spiXfer(spi_handle, data, data, DATA_SIZE);
    if (result != DATA_SIZE) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Log the received data to a binary file
void log_data(uint8_t *data, int frame_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fwrite(&frame_number, sizeof(int), 1, log_file);
    fwrite(timestamp, sizeof(char), 80, log_file);
    fwrite(data, sizeof(uint8_t), DATA_SIZE, log_file);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    uint8_t data[DATA_SIZE];
    int frame_number = 0;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        trigger_frame();
        gpioDelay(1); // Small delay after trigger

        // Wait for data ready signal
        int timeout_count = 0;
        while (gpioRead(DATA_READY_PIN) == 0 && timeout_count < 1000) {
            gpioDelay(1); // Check every 1 ms
            timeout_count++;
        }

        if (timeout_count >= 1000) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue; // Skip this frame
        }

        if (read_heatmap_data(data) == 0) {
            log_data(data, frame_number);
            frame_number++;
        } else {
            fprintf(stderr, "Failed to read heatmap data\n");
        }

        gpioDelay(FRAME_PERIOD_MS * 1000); // Delay for frame period
    }

    cleanup();
    return 0;
}

