#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define the GPIO pin and chip name
#define GPIO_PIN 20
#define GPIO_CHIP "gpiochip0"

// Global variables for signal handling and GPIO
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor(struct gpiod_line *line);
int log_event(FILE *fp, const char *event);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr);
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip);
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;
    }
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log an event to the log file
int log_event(FILE *fp, const char *event) {
    char timestamp[32];
    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure the log is written immediately
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime); // Use gmtime for UTC time

    if (strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return NULL;
    }
    return timestamp_buffer;
}

// Function to set up the GPIO line
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr) {
    *chip_ptr = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip_ptr) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *line_ptr = gpiod_chip_get_line(*chip_ptr, GPIO_PIN);
    if (!*line_ptr) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip_ptr);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(*line_ptr, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(*chip_ptr);
        return -1;
    }

    return 0;
}

// Function to clean up the GPIO line
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize GPIO
    if (setup_gpio(&chip, &line) != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio(line, chip);
        return 1;
    }

    int previous_value = -1; // Initialize to an invalid value
    int current_value;

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        current_value = read_flame_sensor(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_value != previous_value) {
            if (current_value == 0) {
                if (log_event(log_file, "Flame Detected") != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            } else {
                if (log_event(log_file, "Flame Cleared") != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            }
            previous_value = current_value;
        }

        usleep(100000); // 100 milliseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file) {
        fclose(log_file);
    }
    cleanup_gpio(line, chip);

    printf("Exiting.\n");
    return 0;
}

