// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_value = 0b1100000000000000; // Continuous conversion, 100ms, Auto range
    char buf[3];
