#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define CHANNEL1 2
#define CHANNEL2 3
#define CHANNEL3 4
#define CHANNEL4 5
#define CHANNEL5 6
#define CHANNEL6 7
#define CHANNEL7 8
#define CHANNEL8 9

// Array of GPIO line numbers
int gpio_lines[] = {CHANNEL1, CHANNEL2, CHANNEL3, CHANNEL4, CHANNEL5, CHANNEL6, CHANNEL7, CHANNEL8};
int num_channels = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8]; // Array to store the GPIO lines

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release the GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Request the GPIO lines
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error requesting GPIO line %d\n", gpio_lines[i]);
            // Release previously requested lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the line for input
        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as input\n", gpio_lines[i]);
            // Release previously requested lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read and print the sensor data
    while (1) {
        for (int i = 0; i < num_channels; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO line %d\n", gpio_lines[i]);
            } else {
                printf("%d", value);
                if (i < num_channels - 1) {
                    printf(",");
                }
            }
        }
        printf("\n");
        usleep(100000); // 100 ms delay
    }

    return 0;
}

