#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure each GPIO pin as input with a pull-down resistor
    for (int i = 0; i < num_channels; i++)
    {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0)
        {
            fprintf(stderr, "Failed to set GPIO %d as input\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }

        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0)
        {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", sensor_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main sampling loop
    while (!terminate)
    {
        // Get the current timestamp in milliseconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Read the state of each channel and log it
        for (int i = 0; i < num_channels; i++)
        {
            int state = gpioRead(sensor_pins[i]);
            printf("CH%d=%d", i + 1, state);
            if (i < num_channels - 1)
            {
                printf(" ");
            }
        }
        printf(" [+%ld ms]\n", timestamp_ms);

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    return 0;
}

