#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO lines for the 8 channels
const int gpio_lines[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Global variable to store the GPIO line requests
struct gpiod_line *lines[8];

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to get the current timestamp in ISO-8601 format
char* get_iso8601_timestamp();

// Function to read the value of a GPIO line
int read_gpio_line(struct gpiod_line *line);

// Function to log the sensor data to the console
void log_sensor_data(int *channel_values);

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request the GPIO lines
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!lines[i]) {
            perror("Error requesting GPIO line");
            goto cleanup;
        }

        // Request the line for input with bias disabled
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        int ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line for input");
            goto cleanup;
        }
    }

    // Main loop to read and log sensor data
    while (1) {
        int channel_values[8];
        for (int i = 0; i < num_channels; i++) {
            channel_values[i] = read_gpio_line(lines[i]);
        }

        log_sensor_data(channel_values);
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50000; // 50 ms
        nanosleep(&delay, NULL);
    }

cleanup:
    // Release the GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release the GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to get the current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to read the value of a GPIO line
int read_gpio_line(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to the console
void log_sensor_data(int *channel_values) {
    char *timestamp = get_iso8601_timestamp();
    printf("%s", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf(",%d", channel_values[i]);
    }
    printf("\n");
    free(timestamp); // Free the allocated memory
}

