#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4 // BCM GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state = -1; // Initialize to an invalid state
    int previous_state = -1;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the current state of the tilt sensor
        current_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the read result
        if (current_state != 0 && current_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read value: %d\n", current_state);
            break; // Exit the loop on error
        }

        // Check for state change
        if (current_state != previous_state) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the tilt state change
            if (current_state == 0) {
                printf("%s Tilted\n", timestamp);
            } else {
                printf("%s Not Tilted\n", timestamp);
            }

            // Update previous state
            previous_state = current_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100); // pigpio's delay function
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    printf("Tilt sensor monitoring stopped.\n");

    return 0;
}

