#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PARTID 0x00
#define SI1145_HW_KEY 0x07
#define SI1145_CHLIST 0x01
#define SI1145_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float uv_index;
    uint16_t als_visible;
} sensor_data_t;

// Function prototypes
int init_si1145();
sensor_data_t read_si1145_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Verify PART ID
    status = i2cReadByteData(i2c_handle, SI1145_PARTID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", status);
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", status);
        return -1;
    }

    // Unlock the sensor
    status = i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Configure CHLIST register
    status = i2cWriteByteData(i2c_handle, SI1145_CHLIST, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing CHLIST: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read UV index and ALS data from the Si1145 sensor
sensor_data_t read_si1145_data() {
    sensor_data_t data;
    int status;

    // Trigger ALS measurement
    status = i2cWriteByteData(i2c_handle, SI1145_ALS_FORCE, 0x06);
    if (status < 0) {
        fprintf(stderr, "Error writing ALS_FORCE: %d\n", status);
        data.uv_index = -1.0; // Indicate error
        data.als_visible = 0;
        return data;
    }

    // Read ALS data
    data.als_visible = i2cReadWordData(i2c_handle, 0x22); // ALS_VIS_DATA0
