#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define ALARM_GPIO 17
#define FLOW_LOG_FILE "flow_log.txt"
#define FLOW_SCALE_FACTOR 0.036
#define FLOW_RATE_THRESHOLD 0.5
#define MEASUREMENT_COMMAND 0x3608
#define MEASUREMENT_DELAY_MS 100
#define READ_DELAY_MS 100
#define READ_SIZE 9

// Global variables
int i2c_fd1 = -1;
int i2c_fd2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(int fd, int address, float *flow_rate1, float *flow_rate2);
float convert_flow_rate(int raw_flow);
int validate_crc(unsigned char data[], int len);
void log_flow_rate(float flow_rate1, float flow_rate2, float avg_flow_rate);
void control_alarm(float avg_flow_rate);
void signal_handler(int signal);

// I2C initialization function
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Send start measurement command
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    if (write(fd, command, 2) != 2) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor_data(int fd, int address, float *flow_rate1, float *flow_rate2) {
    unsigned char data[READ_SIZE];
    int retries = 3;

    while (retries > 0) {
        // Read data from the sensor
        if (read(fd, data, READ_SIZE) != READ_SIZE) {
            perror("Error reading from I2C device");
            retries--;
            usleep(READ_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Extract flow rate data
        int raw_flow1 = (data[0] << 8) | data[1];
        int raw_flow2 = (data[3] << 8) | data[4];

        // Validate CRC for flow rate 1
        if (validate_crc(data, READ_SIZE)) {
            // Convert raw flow rate to ml/min
            *flow_rate1 = convert_flow_rate(raw_flow1);
        } else {
            fprintf(stderr, "CRC validation failed for sensor 1 at address 0x%02X\n", address);
            *flow_rate1 = -1.0; // Indicate error
        }

        // Validate CRC for flow rate 2
        if (validate_crc(data, READ_SIZE)) {
            // Convert raw flow rate to ml/min
            *flow_rate2 = convert_flow_rate(raw_flow2);
        } else {
            fprintf(stderr, "CRC validation failed for sensor 2 at address 0x%02X\n", address);
            *flow_rate2 = -1.0; // Indicate error
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data from address 0x%02X after multiple retries.\n", address);
    return -1; // Failure
}

// Function to convert raw flow rate to ml/min
float convert_flow_rate(int raw_flow) {
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Function to validate CRC
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Function to log flow rate to file
void log_flow_rate(float flow_rate1, float flow_rate2, float avg_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Sensor1: %.3f ml/min, Sensor2: %.3f ml/min, Average: %.3f ml/min\n",
            timestamp, flow_rate1, flow_rate2, avg_flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the alarm
void control_alarm(float avg_flow_rate) {
    if (avg_flow_rate < FLOW_RATE_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Initialize I2C for both sensors
    i2c_fd1 = init_i2c(SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    i2c_fd2 = init_i2c(SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        close(i2c_fd1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2, avg_flow_rate;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_fd1, SENSOR1_ADDR, &flow_rate1, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        }

        if (read_sensor_data(i2c_fd2, SENSOR2_ADDR, &flow_rate1, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        }

        // Calculate average flow rate
        if (flow_rate1 >= 0 && flow_rate2 >= 0) {
            avg_flow_rate = (flow_rate1 + flow_rate2) / 2.0;
        } else {
            avg_flow_rate = 0.0; // Use a default value if one of the sensors failed
        }

        // Log flow rate
        log_flow_rate(flow_rate1, flow_rate2, avg_flow_rate);

        // Control alarm
        control_alarm(avg_flow_rate);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd1);
    close(i2c_fd2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();

    return 0;
}

