#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define MODE_CONTROL_VALUE 0x10
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_REG 0x2A
#define ACCEL_Y_REG 0x2C
#define ACCEL_Z_REG 0x2E
#define SCALE_FACTOR 0.0009765625
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *fp = NULL;

// Structure to hold acceleration data
typedef struct {
    double x;
    double y;
    double z;
} AccelerationData;

// Function prototypes
int init_i2c(const char *bus, int addr);
int write_register(int fd, int reg, int value);
int read_register(int fd, int reg);
int check_status(int fd);
AccelerationData read_acceleration(int fd);
double convert_to_g(int raw_value);
void log_data(FILE *fp, AccelerationData data);
void signal_handler(int sig);

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write to a register
int write_register(int fd, int reg, int value) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(fd, &value, 1) == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %s. Retrying...\n", reg, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            retries--;
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read from a register
int read_register(int fd, int reg) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(fd, &reg, 1) == 1) {
            unsigned char buffer[1];
            if (read(fd, buffer, 1) == 1) {
                return buffer[0];
            } else {
                fprintf(stderr, "Error reading from register 0x%02X: %s. Retrying...\n", reg, strerror(errno));
                usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
                retries--;
            }
        } else {
            fprintf(stderr, "Error writing register address for read 0x%02X: %s. Retrying...\n", reg, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000); // Sleep for 10ms
            retries--;
        }
    }
    fprintf(stderr, "Failed to read from register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to check the operating status
int check_status(int fd) {
    int status = read_register(fd, OPERATING_STATUS_REG);
    if (status < 0) {
        return -1; // Error
    }
    return (status & 0x01); // Check bit 0
}

// Function to read acceleration data
AccelerationData read_acceleration(int fd) {
    AccelerationData data;
    int x_raw, y_raw, z_raw;

    x_raw = (read_register(fd, ACCEL_X_REG) << 8) | read_register(fd, ACCEL_X_REG + 1);
    y_raw = (read_register(fd, ACCEL_Y_REG) << 8) | read_register(fd, ACCEL_Y_REG + 1);
    z_raw = (read_register(fd, ACCEL_Z_REG) << 8) | read_register(fd, ACCEL_Z_REG + 1);

    data.x = convert_to_g(x_raw);
    data.y = convert_to_g(y_raw);
    data.z = convert_to_g(z_raw);

    return data;
}

// Function to convert raw value to g
double convert_to_g(int raw_value) {
    return (double)raw_value * SCALE_FACTOR;
}

// Function to log data to CSV file
void log_data(FILE *fp, AccelerationData data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, D7S_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize sensor
    if (write_register(i2c_fd, MODE_CONTROL_REG, MODE_CONTROL_VALUE) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Wait for sensor to become active
    int status = 0;
    time_t start_time = time(NULL);
    while (status == 0 && (time(NULL) - start_time) < 1) {
        status = check_status(i2c_fd);
        if (status < 0) {
            close(i2c_fd);
            return 1;
        }
        usleep(10000); // Sleep for 10ms
    }

    if (status == 0) {
        fprintf(stderr, "Error: Sensor did not become active within 1 second.\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("fan_health.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    fseek(fp, 0, SEEK_END); // Return to end of file for appending

    // Main loop
    while (keep_running) {
        AccelerationData data = read_acceleration(i2c_fd);
        log_data(fp, data);
        usleep(500000); // Sleep for 500ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(fp);

    return 0;
}

