#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Set sensor pins as inputs
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_1_PIN);
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_2_PIN);
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        return 1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    if (sensor1_value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", SENSOR_1_PIN);
        return 1; // Indicate an error
    }
    if (sensor2_value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", SENSOR_2_PIN);
        return 1; // Indicate an error
    }

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // Return 1 if either sensor detects an obstacle, 0 otherwise
}

// Function to control the LED
void control_led(int obstacle_detected) {
    if (obstacle_detected) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensors();
        control_led(obstacle_detected);
        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and terminate pigpio
    gpioWrite(LED_PIN, 0); // Turn off LED before exiting
    gpioTerminate();

    return 0;
}

