#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x8D
#define CONFIG_REG 0x01
#define CONFIG_VALUE 0x03 // Continuous conversion, all axes enabled, 50mT range
#define X_AXIS_REG 0x04
#define Y_AXIS_REG 0x06
#define Z_AXIS_REG 0x08
#define DATA_RATE 0x02 // 100 Hz
#define RANGE 0x00 // +/- 50 mT

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
float convert_to_mT(int16_t raw_value);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int create_csv_header();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }
    printf("Device ID verified: 0x%02X\n", device_id);
    return 0;
}

// Function to configure the sensor
int configure_sensor() {
    int status = i2cWriteByteData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", status);
        return -1;
    }
    printf("Sensor configured for continuous conversion, all axes enabled, 50mT range.\n");
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int status;
    uint8_t buffer[6];

    status = i2cReadI2CBlockData(i2c_handle, X_AXIS_REG, (char *)buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to mT
float convert_to_mT(int16_t raw_value) {
    // Assuming 16-bit two's complement
    // Scale factor for 50 mT range is 0.122 mT/LSB
    return (float)raw_value * 0.122;
}

// Function to log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to create the CSV header
int create_csv_header() {
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        create_csv_header();
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert raw data to mT
            float x_mT = convert_to_mT(sensor_data.x);
            float y_mT = convert_to_mT(sensor_data.y);
            float z_mT = convert_to_mT(sensor_data.z);

            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

