#include <unistd.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"

static volatile int keepRunning = 1;

// Signal handler for graceful shutdown
void intHandler(int dummy) {
    keepRunning = 0;
}

// Function to read the sensor value
int readSensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to log the alert message
void logAlert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s ALERT: Water detected\n", timestamp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 23 as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    printf("Water level monitoring daemon started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        int sensorValue = readSensor();

        if (sensorValue == 1) {
            logAlert();
            printf("Water detected!\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Water level monitoring daemon stopped.\n");

    return 0;
}

