#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>
#include <sys/file.h>

// Configuration
#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define PULSE_WINDOW_MS 1000 // 1 second
#define MAX_PULSE_BUFFER_SIZE 100

// Global variables (protected by mutex)
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
int running = 1; // Flag to control the main loop

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int log_file_fd;
} program_state_t;

program_state_t state = {0, -1};

// Function prototypes
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulses);
int log_rpm(double rpm);
void signal_handler(int signal);
void *timer_thread(void *arg);

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
