#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex structure
typedef struct {
    pthread_mutex_t mutex;
} Mutex;

// Define the quadrature state structure
typedef struct {
    int state;
} QuadratureState;

// Global variables
static volatile int running = 1;
static Mutex log_mutex;
static FILE *log_file = NULL;

// Function prototypes
void *sensor_a_isr(void *arg);
void *sensor_b_isr(void *arg);
void log_rotation(const char *direction);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Quadrature state machine
static int current_state = 0; // Initial state

// Function to update the quadrature state based on sensor A and B states
static void update_quadrature_state(int sensor_a_state, int sensor_b_state) {
    if (sensor_a_state == 1 && sensor_b_state == 0) {
        current_state = 1; // A rising, B falling
    } else if (sensor_a_state == 0 && sensor_b_state == 1) {
        current_state = 2; // A falling, B rising
    } else if (sensor_a_state == 1 && sensor_b_state == 1) {
        current_state = 3; // A rising, B rising
    } else if (sensor_a_state == 0 && sensor_b_state == 0) {
        current_state = 0; // A falling, B falling
    }
}

// Function to determine the direction of rotation based on the quadrature state
static const char *determine_direction(int current_state) {
    switch (current_state) {
        case 1: return "CW"; // Clockwise
        case 2: return "CCW"; // Counter-Clockwise
        default: return "None"; // No rotation or error
    }
}

// Interrupt service routine for Sensor A
void *sensor_a_isr(void *arg) {
    int sensor_a_state = gpioRead(SENSOR_A_GPIO);
    int sensor_b_state = gpioRead(SENSOR_B_GPIO);

    update_quadrature_state(sensor_a_state, sensor_b_state);

    const char *direction = determine_direction(current_state);

    if (strcmp(direction, "None") != 0) {
        log_rotation(direction);
    }

    return NULL;
}

// Interrupt service routine for Sensor B
void *sensor_b_isr(void *arg) {
    int sensor_a_state = gpioRead(SENSOR_A_GPIO);
    int sensor_b_state = gpioRead(SENSOR_B_GPIO);

    update_quadrature_state(sensor_a_state, sensor_b_state);

    const char *direction = determine_direction(current_state);

    if (strcmp(direction, "None") != 0) {
        log_rotation(direction);
    }

    return NULL;
}

// Function to log the rotation event with a timestamp
void log_rotation(const char *direction) {
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s.%03d: %s\n", timestamp, (int)(time(NULL) * 1000) % 1000, direction);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up interrupt handlers
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_a_isr) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor A\n");
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensor_b_isr) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor B\n");
        return 1;
    }

    return 0;
}

// Function to initialize the log file
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main() {
    // Initialize mutex
    if (pthread_mutex_init(&log_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    cleanup();
    return 0;
}

