#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define line request flags
#define GPIOD_LINE_REQUEST_DIRECTION_INPUT 0
#define GPIOD_LINE_REQUEST_CONSUMER_TOUCH_SENSOR "touch_sensor"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_touch_sensor(void);
int control_led(int state);
void log_event(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, shutting down...");
        terminate = 1;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s: %s", CHIP_NAME, strerror(errno));
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line %d: %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line %d: %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    // Request touch sensor line as input
    ret = gpiod_line_request(touch_line, GPIOD_LINE_REQUEST_DIRECTION_INPUT, GPIOD_LINE_REQUEST_CONSUMER_TOUCH_SENSOR);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request LED line as output
    ret = gpiod_line_request(led_line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, GPIOD_LINE_REQUEST_CONSUMER_TOUCH_SENSOR);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    log_event("GPIO initialized successfully.");
    return 0;
}

// Read touch sensor value
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read touch sensor value: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Control LED state
int control_led(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
