#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", TOUCH_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_PIN);
        return -1;
    }

    // Initialize LED to LOW
    gpioWrite(LED_PIN, 0);
    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED state
void toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
}

// Function to debounce the touch sensor input
int debounce_touch_sensor() {
    int initial_state = read_touch_sensor();
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
    if (read_touch_sensor() == initial_state) {
        return initial_state;
    } else {
        return -1; // Indicate debouncing failed
    }
}

int main() {
    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "Touch sensor and LED initialized. Waiting for touch events...\n");

    // Main loop
    while (!terminate) {
        int touch_state = debounce_touch_sensor();

        if (touch_state == 1) {
            toggle_led();
            fprintf(stderr, "Touch detected, LED toggled\n");
        } else if (touch_state == -1) {
            // Debounce failed, ignore the touch
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Clean up and terminate pigpio
    gpioWrite(LED_PIN, 0); // Turn off LED before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

