#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to store event data
typedef struct {
    int sensor_pin;
    long timestamp;
    int new_state;
} event_t;

// Circular buffer structure
typedef struct {
    event_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} circular_buffer_t;

// Global variables
static volatile int running = 1;
circular_buffer_t event_buffer;

// Function prototypes
int init_gpio();
void handle_touch(int sensor_pin, int led_pin, circular_buffer_t *buffer);
void handle_release(int sensor_pin, int led_pin, circular_buffer_t *buffer);
void log_event(int sensor_pin, int new_state);
void signal_handler(int signal);
void print_log(circular_buffer_t *buffer);

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        return 1;
    }

    return 0;
}

// Handle touch event
void handle_touch(int sensor_pin, int led_pin, circular_buffer_t *buffer) {
    int current_state = gpioRead(sensor_pin);
    if (current_state == 1) {
        gpioWrite(led_pin, 1);
        log_event(sensor_pin, 1);
    }
}

// Handle release event
void handle_release(int sensor_pin, int led_pin, circular_buffer_t *buffer) {
    int current_state = gpioRead(sensor_pin);
    if (current_state == 0) {
        gpioWrite(led_pin, 0);
        log_event(sensor_pin, 0);
    }
}

// Log event to circular buffer
void log_event(int sensor_pin, int new_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    event_buffer.buffer[event_buffer.head].sensor_pin = sensor_pin;
    event_buffer.buffer[event_buffer.head].timestamp = timestamp;
    event_buffer.buffer[event_buffer.head].new_state = new_state;

    event_buffer.head = (event_buffer.head + 1) % BUFFER_SIZE;
    if (event_buffer.count < BUFFER_SIZE) {
        event_buffer.count++;
    } else {
        event_buffer.overflow_count++;
    }
    event_buffer.tail = event_buffer.head; // Simple circular buffer implementation
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Print the contents of the circular buffer
void print_log(circular_buffer_t *buffer) {
    printf("\n--- Log Buffer Contents ---\n");
    int i = buffer->tail;
    for (int j = 0; j < buffer->count; j++) {
        printf("Index: %d, Sensor: %d, Timestamp: %ld, State: %d\n", i, buffer->buffer[i].sensor_pin, buffer->buffer[i].timestamp, buffer->buffer[i].new_state);
        i = (i + 1) % BUFFER_SIZE;
    }
    printf("--- End of Log Buffer ---\n");
    printf("Overflow Count: %d\n", buffer->overflow_count);
}

int main() {
    // Initialize circular buffer
    event_buffer.head = 0;
    event_buffer.tail = 0;
    event_buffer.count = 0;
    event_buffer.overflow_count = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor_1_value = gpioRead(SENSOR_1_PIN);
        int sensor_2_value = gpioRead(SENSOR_2_PIN);

        // Handle touch events
        if (sensor_1_value == 1) {
            handle_touch(SENSOR_1_PIN, LED_1_PIN, &event_buffer);
        } else {
            handle_release(SENSOR_1_PIN, LED_1_PIN, &event_buffer);
        }

        if (sensor_2_value == 1) {
            handle_touch(SENSOR_2_PIN, LED_2_PIN, &event_buffer);
        } else {
            handle_release(SENSOR_2_PIN, LED_2_PIN, &event_buffer);
        }

        // Debounce delay
        gpioDelay(50); // 50 ms
    }

    // Turn off LEDs
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    // Print log buffer contents
    print_log(&event_buffer);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

