#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the debounce time in microseconds
#define DEBOUNCE_TIME 5000 // 5 milliseconds

// Global variables
volatile unsigned long last_interrupt_time1 = 0;
volatile unsigned long last_interrupt_time2 = 0;
FILE *log_file = NULL;
int running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data);
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_rpm(unsigned long time_difference_us);
void log_sensor_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Callback function for Sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = tick;
    if (current_time - last_interrupt_time1 > DEBOUNCE_TIME) {
        last_interrupt_time1 = current_time;
        // Log the event
        log_sensor_data(level, gpio == SENSOR2_GPIO ? gpioRead(SENSOR2_GPIO) : gpioRead(SENSOR1_GPIO));
    }
}

// Callback function for Sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = tick;
    if (current_time - last_interrupt_time2 > DEBOUNCE_TIME) {
        last_interrupt_time2 = current_time;
        // Log the event
        log_sensor_data(gpioRead(SENSOR1_GPIO), level);
    }
}

// Function to calculate RPM
double calculate_rpm(unsigned long time_difference_us) {
    if (time_difference_us == 0) return 0.0; // Avoid division by zero
    return (60000000.0 / time_difference_us) / 2.0; // 60,000,000 us/min / pulses per rev
}

// Function to log sensor data to a file
void log_sensor_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register callback functions
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    unsigned long last_time = gpioTick();
    unsigned long current_time;
    double rpm;
    unsigned long time_difference_us;

    while (running) {
        gpioDelay(1000); // Check every 1 ms
        current_time = gpioTick();
        time_difference_us = current_time - last_time;
        last_time = current_time;

        rpm = calculate_rpm(time_difference_us);
        printf("RPM: %.2f\n", rpm);
    }

    // Clean up and exit
    gpioSetAlertFuncEx(SENSOR1_GPIO, NULL, NULL); // Disable callback
    gpioSetAlertFuncEx(SENSOR2_GPIO, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    return 0;
}

