#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor(int handle);
int configure_sensor(int handle);
int read_sensor_data(int handle, int reg);
int log_data(FILE *fp, int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Verify sensor by reading PART_ID register
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02x (expected 0x82)\n", part_id);
        return -1;
    }
    printf("Sensor verified: PART_ID = 0x%02x\n", part_id);
    return 0;
}

// Configure sensor for continuous measurement
int configure_sensor(int handle) {
    int status = i2cWriteByteData(handle, CONFIG_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Failed to write to CONFIG register: %d\n", status);
        return -1;
    }
    printf("Sensor configured for continuous measurement\n");
    return 0;
}

// Read sensor data from specified register
int read_sensor_data(int handle, int reg) {
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Failed to read data from register 0x%02x: %d\n", reg, data);
        return -1;
    }
    return data;
}

// Log data to file with timestamp
int log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI1182_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int heart_rate = read_sensor_data(i2c_handle, HEART_RATE_REG);
        int spo2 = read_sensor_data(i2c_handle, SPO2_REG);

        // Log data if read was successful
        if (heart_rate >= 0 && spo2 >= 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping logging\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

