#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define LED_GPIO 17
#define THRESHOLD 500.0
#define SAMPLE_RATE_MS 100
#define RETRY_COUNT 3

// Sensor Registers
#define CTRL1 0x1F
#define CTRL2 0x20
#define CTRL3 0x21
#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_event(float magnitude);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize Sensor
int init_sensor() {
    // Verify sensor presence
    if (i2cWriteByteData(i2c_handle, CTRL1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL1 register. Check sensor connection.\n");
        return -1;
    }

    // Clear power-down bit (assuming it's set to 0 initially)
    if (i2cWriteByteData(i2c_handle, CTRL1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not clear power-down bit in CTRL1 register.\n");
        return -1;
    }

    // Configure CTRL2 and CTRL3 (example values, adjust as needed)
    if (i2cWriteByteData(i2c_handle, CTRL2, 0x01) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL2 register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL3, 0x02) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL3 register.\n");
        return -1;
    }

    return 0;
}

// Read Acceleration Data
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB, buffer, 6) == 6) {
            // Combine LSB and MSB, convert to float (assuming 16-bit signed integers)
            *x = (float)((int16_t)((buffer[1] << 8) | buffer[0]));
            *y = (float)((int16_t)((buffer[3] << 8) | buffer[2]));
            *z = (float)((int16_t)((buffer[5] << 8) | buffer[4]));
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d). Retrying...\n", retries + 1);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries. Giving up.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate Vibration Magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log Event
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s, %.2f\n", buf, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open Log File
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn LED on
                gpioDelay(1000);        // Wait 1 second
                gpioWrite(LED_GPIO, 0); // Turn LED off

                log_event(magnitude);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // Sample every 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

