#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line, *sensor4_line;
struct gpiod_line *led_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor3_line) {
        gpiod_line_release(sensor3_line);
    }
    if (sensor4_line) {
        gpiod_line_release(sensor4_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED
int control_led(struct gpiod_line *line, int state)
{
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED state: %d\n", ret);
        return -1; // Indicate error
    }
    return 0;
}

int main()
{
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return 1;
    }

    // Get GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR_3_PIN);
    sensor4_line = gpiod_chip_get_line(chip, SENSOR_4_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!sensor1_line || !sensor2_line || !sensor3_line || !sensor4_line || !led_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input (sensors) and output (LED)
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "obstacle_detector";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sensor1_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor 1 line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(sensor2_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor 2 line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(sensor3_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor 3 line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(sensor4_line, &input_config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor 4 line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "obstacle_detector";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &output_config, 0) < 0) {
        fprintf(stderr, "Error requesting LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);
        int sensor3_value = read_sensor(sensor3_line);
        int sensor4_value = read_sensor(sensor4_line);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0 || sensor4_value < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        // Check if any sensor detects an object (active-low)
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            if (control_led(led_line, 1) < 0) {
                fprintf(stderr, "Error controlling LED, exiting...\n");
                break;
            }
        } else {
            if (control_led(led_line, 0) < 0) {
                fprintf(stderr, "Error controlling LED, exiting...\n");
                break;
            }
        }

        // Poll every 50 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000; // 50 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(SIGTERM);

    return 0;
}

