#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define sensor pins
#define SENSOR1_PIN 2
#define SENSOR2_PIN 3
#define SENSOR3_PIN 4
#define SENSOR4_PIN 17
#define SENSOR5_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Log file path
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor data
typedef struct {
    int pin;
    struct gpiod_line *line;
    int last_value;
    struct timespec last_change_time;
} sensor_t;

// Global variables
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *chip = NULL;
sensor_t sensors[5];

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void signal_handler(int sig);
int read_sensor(int pin);
int log_event(int pin);
void debounce(struct timespec *last_change_time);
int acquire_line(struct gpiod_chip *chip, int pin);
int request_line(struct gpiod_chip *chip, int pin, int direction, int flags);
int release_line(struct gpiod_chip *chip, int pin);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    program_running = 0;
}

// Initialize GPIO
int init_gpio(void) {
    int i;
    struct timespec ts;

    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize sensors
    sensors[0].pin = SENSOR1_PIN;
    sensors[1].pin = SENSOR2_PIN;
    sensors[2].pin = SENSOR3_PIN;
    sensors[3].pin = SENSOR4_PIN;
    sensors[4].pin = SENSOR5_PIN;

    for (i = 0; i < 5; i++) {
        sensors[i].last_value = 1; // Initialize to no flame detected (HIGH)
        clock_gettime(CLOCK_MONOTONIC, &sensors[i].last_change_time);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Acquire and request lines for each sensor
    for (i = 0; i < 5; i++) {
        if (acquire_line(chip, sensors[i].pin) != 0) {
            syslog(LOG_ERR, "Failed to acquire line for sensor %d", sensors[i].pin);
            return -1;
        }
        if (request_line(chip, sensors[i].pin, GPIOD_LINE_REQUEST_DIRECTION_INPUT, 0) != 0) {
            syslog(LOG_ERR, "Failed to request line for sensor %d", sensors[i].pin);
            return -1;
        }
    }

    syslog(LOG_INFO, "GPIO initialized successfully.");
    return 0;
}

// Acquire a GPIO line
int acquire_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for pin %d: %s", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Request a GPIO line for input
int request_line(struct gpiod_chip *chip, int pin, int direction, int flags) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for pin %d: %s", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request(line, NULL, direction | flags);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request line for pin %d: %s", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Release a GPIO line
int release_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for pin %d: %s", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_release(line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to release line for pin %d: %s", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for pin %d: %s", pin, strerror(errno));
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read line for pin %d: %s", pin, strerror(errno));
        return -1;
    }
    return value;
}

// Log event to file
int log_event(int pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return -1;
    }

    // Acquire exclusive lock
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, pin, pin);
    fflush(fp);

    // Release lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", strerror(errno));
    }

    fclose(fp);
    return 0;
}

// Debounce function
void debounce(struct timespec *last_change_time) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    long elapsed_ms = (now.tv_sec - last_change_time->tv_sec) * 1000 + (now.tv_nsec - last_change_time->tv_nsec) / 1000000;

    if (elapsed_ms < DEBOUNCE_TIME_MS) {
        // Debounce period not elapsed
        return;
    }
}

int main(void) {
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        for (i = 0; i < 5; i++) {
            int value = read_sensor(sensors[i].pin);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read sensor %d, retrying...", sensors[i].pin);
                continue; // Retry reading the sensor
            }

            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            if (value == 0 && sensors[i].last_value == 1) {
                // Flame detected (LOW)
                debounce(&sensors[i].last_change_time);
                if ((now.tv_sec - sensors[i].last_change_time.tv_sec) * 1000 + (now.tv_nsec - sensors[i].last_change_time.tv_nsec) / 1000000 >= DEBOUNCE_TIME_MS) {
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d)", sensors[i].pin, sensors[i].pin);
                    log_event(sensors[i].pin);
                    sensors[i].last_value = 0;
                    clock_gettime(CLOCK_MONOTONIC, &sensors[i].last_change_time);
                }
            } else if (value == 1 && sensors[i].last_value == 0) {
                // No flame detected (HIGH)
                debounce(&sensors[i].last_change_time);
                if ((now.tv_sec - sensors[i].last_change_time.tv_sec) * 1000 + (now.tv_nsec - sensors[i].last_change_time.tv_nsec) / 1000000 >= DEBOUNCE_TIME_MS) {
                    sensors[i].last_value = 1;
                    clock_gettime(CLOCK_MONOTONIC, &sensors[i].last_change_time);
                }
            }

            sensors[i].last_value = value; // Update last value
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int i;
    syslog(LOG_INFO, "Cleaning up GPIO resources...");

    // Release and close lines
    for (i = 0; i < 5; i++) {
        if (release_line(chip, sensors[i].pin) != 0) {
            syslog(LOG_ERR, "Failed to release line for sensor %d", sensors[i].pin);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    syslog(LOG_INFO, "GPIO cleanup complete.");
}

