#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_CONF_REG 0x00
#define ALS_DATA_REG 0x04
#define GPIO_LED 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int init_logging();
int read_veml7700(int *raw_value);
float convert_to_lux(int raw_value);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        return 1;
    }
    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQ) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", GPIO_LED);
        return 1;
    }
    if (gpioSetPWMrange(GPIO_LED, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", GPIO_LED);
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_veml7700(int *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return 1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    *raw_value = (buf[1] << 8) | buf[0];
    return 0;
}

// Convert raw value to lux
float convert_to_lux(int raw_value) {
    return (float)raw_value * 0.0576;
}

// Set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness;

    if (lux < LUX_THRESHOLD_1) {
        brightness = PWM_RANGE;
    } else if (lux < LUX_THRESHOLD_2) {
        brightness = (int)(PWM_RANGE * 0.75);
    } else if (lux < LUX_THRESHOLD_3) {
        brightness = (int)(PWM_RANGE * 0.5);
    } else {
        brightness = (int)(PWM_RANGE * 0.25);
    }

    gpioPWM(GPIO_LED, brightness);
    return brightness;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value;
        float lux;
        int brightness;
        int error_code = 0;

        // Read ALS data
        if (read_veml7700(&raw_value) != 0) {
            error_code = 1;
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            // Convert to lux
            lux = convert_to_lux(raw_value);

            // Set LED brightness
            brightness = set_led_brightness(lux);

            // Log data
            log_data(lux, brightness, error_code);
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

