#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors();
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
int get_iso8601_timestamp(char *timestamp);

// Structure to hold the last touch time for debouncing
struct {
    int last_touch_time[8];
} debounce_state = {{0}};

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int touch_state = read_touch_sensors();

        // Check for any touch event
        if (touch_state != 0) {
            // Check each channel for a touch event
            for (int i = 0; i < 8; i++) {
                if ((touch_state >> i) & 1) {
                    // Channel i is touched
                    if (get_iso8601_timestamp(NULL) == 0) {
                        fprintf(stderr, "Error getting timestamp.\n");
                        running = 0; // Exit loop on timestamp error
                        break;
                    }
                    char timestamp[32];
                    if (get_iso8601_timestamp(timestamp) != 0) {
                        fprintf(stderr, "Error getting timestamp.\n");
                        running = 0; // Exit loop on timestamp error
                        break;
                    }

                    log_touch_event(i + 1); // Log the event
                    control_led(1);          // Turn on the LED
                    gpioDelay(500);          // Wait 500ms
                    control_led(0);          // Turn off the LED
                    break; // Exit the inner loop after logging
                }
            }
        } else {
            control_led(0); // Ensure LED is off if no touch
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2-9 as inputs with pull-down resistors
    for (int i = 2; i <= 9; i++) {
        gpioSetMode(i, PI_INPUT);
        gpioSetPullUpDown(i, PI_PUD_DOWN);
    }

    // Set GPIO 17 as an output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    return 0;
}

// Read the state of all touch sensors
int read_touch_sensors() {
    int touch_state = 0;
    for (int i = 2; i <= 9; i++) {
        if (gpioRead(i) == 1) {
            touch_state |= (1 << (i - 2));
        }
    }
    return touch_state;
}

// Log a touch event to the log file
void log_touch_event(int channel) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    char timestamp[32];
    if (get_iso8601_timestamp(timestamp) != 0) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control the LED state
