#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define BUS 1
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_config_word(int handle, uint16_t config_word);
int read_result(int handle, uint16_t *result);
float calculate_lux(uint16_t raw_result);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write the configuration word to the OPT3001
int write_config_word(int handle, uint16_t config_word) {
    uint16_t swapped_config = __builtin_bswap16(config_word);
    int result = i2cWriteWordData(handle, CONFIG_REG, swapped_config);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the result register from the OPT3001
int read_result(int handle, uint16_t *result) {
    int raw_result = i2cReadWordData(handle, RESULT_REG);
    if (raw_result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", raw_result);
        return -1;
    }

    *result = __builtin_bswap16(raw_result);
    return 0;
}

// Calculate lux value from raw result
float calculate_lux(uint16_t raw_result) {
    int exponent = (raw_result >> 12) & 0x0F;
    int mantissa = raw_result & 0x0FFF;
    return mantissa * 0.01 * (1 << exponent);
}

// Log data to file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Write configuration word
    if (write_config_word(i2c_handle, CONFIG_WORD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_result;
        if (read_result(i2c_handle, &raw_result) == 0) {
            float lux = calculate_lux(raw_result);
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading result, skipping logging\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

