#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define the GPIO pin and chip name
#define GPIO_PIN 4
#define GPIO_CHIP "gpiochip0"

// Define debounce interval in milliseconds
#define DEBOUNCE_INTERVAL_MS 50

// Global variables for signal handling
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_touch_sensor(struct gpiod_line *line);
int log_touch_event(FILE *fp, const char *event_type);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr);
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip);
int open_log_file(FILE **fp);
int close_log_file(FILE *fp);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Signal received, terminating program...\n");
        terminate = 1;
    }
}

// Function to read the touch sensor with debouncing
int read_touch_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-value));
        return -1; // Indicate error
    }

    // Debounce: Wait for a short interval to avoid spurious readings
    usleep(DEBOUNCE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds

    return value;
}

// Function to log touch events to a file
int log_touch_event(FILE *fp, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    fflush(fp); // Flush the buffer to ensure immediate write
    return 0;
}

// Function to set up GPIO line
int setup_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    *chip_ptr = chip;
    *line_ptr = line;
    return 0;
}

// Function to clean up GPIO resources
int cleanup_gpio(struct gpiod_line *line, struct gpiod_chip *chip) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Function to open the log file
int open_log_file(FILE **fp) {
    *fp = fopen("touch_log.txt", "a");
    if (*fp == NULL) {
