#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_CONVERSION_FACTOR 90.0
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(uint16_t *raw_flow, uint8_t *crc, uint8_t *flags);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(uint8_t crc, const uint8_t *data, size_t len);
float convert_to_ml_min(uint16_t raw_flow);
int log_data(float flow_rate, uint16_t flags, const char *status);
void signal_handler(int signal);
int initialize_logging();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(2); // Wait at least 2 ms
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_flow, uint8_t *crc, uint8_t *flags) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_flow = (uint16_t)((buffer[0] << 8) | buffer[1]);
    *crc = buffer[2];
    *flags = 0; // Not used in this implementation

    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(uint8_t crc, const uint8_t *data, size_t len) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc) ? 0 : -1;
}

// Convert raw flow to ml/min
float convert_to_ml_min(uint16_t raw_flow) {
    return (float)raw_flow / FLOW_CONVERSION_FACTOR;
}

// Log data to file
int log_data(float flow_rate, uint16_t flags, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%u,%s\n", timestamp, flow_rate, flags, status);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is newly created (empty) and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_flow;
        uint8_t crc;
        uint8_t flags;
        float flow_rate;
        char status[32];

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command. Retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&raw_flow, &crc, &flags) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(crc, (const uint8_t *)&raw_flow, 2) != 0) {
            fprintf(stderr, "CRC validation failed. Retrying...\n");
            log_data(0.0, 0, "ERROR");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert to ml/min
        flow_rate = convert_to_ml_min(raw_flow);

        // Validate flow rate
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            snprintf(status, sizeof(status), "INVALID");
        } else {
            snprintf(status, sizeof(status), "OK");
        }

        // Log data
        if (log_data(flow_rate, flags, status) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Coolant flow monitoring stopped.\n");
    return 0;
}

