// Define the GPIO pin and chip name
#define GPIO_PIN 4
#define GPIO_CHIP "gpiochip0"

// Global variables for signal handling
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler function
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame detection event to a file
int log_event(const char *timestamp)
{
    FILE *fp = fopen("flame_events.txt", "a");
    if (fp == NULL) {
        perror("Failed to open flame_events.txt");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    if (ferror(fp)) {
        perror("Error writing to flame_events.txt");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to print the alert message to stdout
void print_alert(const char *timestamp)
{
    printf("Flame detected at: %s\n", timestamp);
}

// Function to monitor the flame sensor
int monitor_flame()
{
    char *timestamp = NULL;
    int ret;

    while (!terminate) {
        ret = gpiod_line_event_wait(line, 0); // Wait for a falling edge
        if (ret < 0) {
            perror("gpiod_line_event_wait failed");
            break;
        }

        timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping alert.\n");
            continue;
        }

        print_alert(timestamp);
        if (log_event(timestamp) != 0) {
            fprintf(stderr, "Failed to log event.\n");
        }
        free(timestamp); // Free the allocated memory

        // Debounce: Wait for a short period to avoid multiple triggers from a single event
        usleep(100000); // 100ms
    }

    return 0;
}

int main()
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input with edge detection
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Monitor the flame sensor
    monitor_flame();

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

