#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define TOUCH_GPIO 23
#define LED_GPIO 24
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 100

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_spi(void);
int read_mcp3008(int channel);
int log_touch_event(int led_state);
void toggle_led(void);
void cleanup(void);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    touch_line = gpiod_chip_get_line(gpio_chip, TOUCH_GPIO);
    if (!touch_line) {
        perror("Error getting touch GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting LED GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "touch_sensor") < 0) {
        perror("Error requesting touch GPIO line for events");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED GPIO line for output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    return 0;
}

// Initialize SPI
int init_spi(void) {
    int fd;
    unsigned int mode = 0;
    unsigned int bits = 8;
    unsigned int speed = 1000000; // 1 MHz

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read MCP3008 ADC value
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(0, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Log touch event
int log_touch_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LED: %s\n", timestamp, led_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Toggle LED
void toggle_led(void) {
    int current_led_state = gpiod_line_get_value(led_line);
    int new_led_state = !current_led_state;
    if (gpiod_line_set_value(led_line, new_led_state) < 0) {
        perror("Error setting LED value");
    }
}

// Cleanup resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up resources...\n");

    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main(void) {
    int spi_fd;
    int adc_value;
    int led_state = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        close(spi_fd);
        return 1;
    }

    fprintf(stderr, "Touch sensor and LED control started.\n");

    // Main loop
    while (!terminate) {
        // Poll for touch events
        if (gpiod_line_event_pending(touch_line, POLL_TIMEOUT_MS)) {
            gpiod_line_event(touch_line);

            // Read ADC value
            adc_value = read_mcp3008(0);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC value.\n");
            } else {
                printf("ADC Value: %d\n", adc_value);
            }

            // Toggle LED
            toggle_led();
            led_state = gpiod_line_get_value(led_line);

            // Log touch event
            if (log_touch_event(led_state) < 0) {
                fprintf(stderr, "Error logging touch event.\n");
            }
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    close(spi_fd);
    return 0;
}

