    if (init_logging() < 0) {
        fprintf(stderr, "Logging initialization failed. Exiting.\n");
        cleanup(0);
        return 1;
    }

    printf("Flame alert system started. Press Ctrl+C to exit.\n");

    // Main loop
    int last_flame_state = 1; // Assume no flame initially (HIGH)
    struct timespec sleep_time = {0, 500000000}; // 500 ms

    while (!terminate) {
        int flame_state = gpiod_line_get_value(flame_line);
        if (flame_state < 0) {
            perror("Error getting flame sensor value");
            cleanup(0);
            return 1;
        }

        // Detect flame detection (LOW-to-HIGH transition)
        if (last_flame_state == 0 && flame_state == 1) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("Error setting buzzer value to 1");
                cleanup(0);
                return 1;
