            nanosleep(&sleep_time, NULL); // 2 seconds
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("Error setting buzzer value to 0");
                cleanup(0);
                return 1;
            }
        }

        last_flame_state = flame_state;
        nanosleep(&sleep_time, NULL); // Poll every 500 ms
    }

    cleanup(0);
    return 0;
}

