    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
            fprintf(stderr, "Warning: Failed to write to log file.\n");
        }
        fflush(log_file); // Ensure the data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        free(timestamp);
        return -1;
    }
    free(timestamp);
    return 0;
}

// Function to send a message to the server
int send_message(const char *message) {
    struct sockaddr_in server_addr;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc < 0) {
        perror("Error creating socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345); // Example port
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1"); // Example IP, change to your server IP

    // Connect to server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to server");
        close(socket_desc);
        socket_desc = -1; // Reset socket descriptor
        return -1;
    }

    // Send message
    if (send(socket_desc, message, strlen(message), 0) < 0) {
        perror("Error sending message");
        close(socket_desc);
        socket_desc = -1; // Reset socket descriptor
        return -1;
    }

    close(socket_desc);
    socket_desc = -1; // Reset socket descriptor
    return 0;
}

int main() {
    int last_state = 0; // 0 = LOW, 1 = HIGH
    int current_state;
    struct timespec debounce_start, now;
    clock_gettime(CLOCK_MONOTONIC, &debounce_start);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(TOUCH_PIN);

        if (current_state != last_state) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - debounce_start.tv_sec) + (now.tv_nsec - debounce_start.tv_nsec) / 1e9;

            if (current_state == 1 && last_state == 0 && elapsed >= (double)DEBOUNCE_DELAY / 1000.0) {
                // Rising edge detected
                int led_state = gpioRead(LED_PIN);
                led_state = !led_state; // Toggle LED state
                gpioWrite(LED_PIN, led_state);

                char log_message_buffer[100];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Touch detected, LED toggled to %d", led_state);
                log_message(log_message_buffer);

                char message_to_send[100];
                snprintf(message_to_send, sizeof(message_to_send), "Touch detected, LED toggled to %d", led_state);
                send_message(message_to_send);

                clock_gettime(CLOCK_MONOTONIC, &debounce_start); // Reset debounce timer
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY); // Poll every 10 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (socket_desc != -1) {
        close(socket_desc);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

