#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define LED_CURRENT_REG 0x02
#define AVERAGING_REG 0x03
#define ENABLE_REG 0x00
#define HEART_RATE_REG 0x2A
#define RETRY_COUNT 3
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    float buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor(int handle);
int configure_sensor(int handle);
int read_heart_rate(int handle);
float convert_to_bpm(int raw_value);
float apply_moving_average(MovingAverageFilter *filter, float new_value);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Verify sensor ID
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, 0x00);
    int hw_rev = i2cReadByteData(handle, 0x01);

    if (part_id < 0 || hw_rev < 0) {
        fprintf(stderr, "Error reading sensor registers: %s\n", strerror(errno));
        return -1;
    }

    if (part_id != 0x02 || hw_rev != 0x01) {
        fprintf(stderr, "Incorrect sensor ID: PART_ID=0x%02X, HW_REV=0x%02X\n", part_id, hw_rev);
        return -1;
    }

    printf("Sensor verified!\n");
    return 0;
}

// Configure sensor
int configure_sensor(int handle) {
    if (i2cWriteByteData(handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing to LED_CURRENT_REG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing to AVERAGING_REG: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE_REG: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor configured!\n");
    return 0;
}

// Read heart rate data
int read_heart_rate(int handle) {
    int raw_value = i2cReadWordData(handle, HEART_RATE_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading heart rate data: %s\n", strerror(errno));
        return -1;
    }
    return raw_value;
}

// Convert raw value to BPM
float convert_to_bpm(int raw_value) {
    return (float)raw_value * 0.5;
}

// Apply moving average filter
float apply_moving_average(MovingAverageFilter *filter, float new_value) {
    filter->buffer[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->buffer[i];
    }

    return sum / filter->count;
}

// Log data to file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Initialize moving average filter
    MovingAverageFilter filter = {{0.0}, 0, 0};

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value = -1;
        for (int i = 0; i < RETRY_COUNT; i++) {
            raw_value = read_heart_rate(i2c_handle);
            if (raw_value >= 0) {
                break;
            } else {
                fprintf(stderr, "I2C read error, retrying... (%d/%d)\n", i + 1, RETRY_COUNT);
                gpioDelay(100); // Wait 100ms before retrying
            }
        }

        if (raw_value < 0) {
            fprintf(stderr, "Failed to read heart rate after multiple retries\n");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        float bpm = convert_to_bpm(raw_value);
        float filtered_bpm = apply_moving_average(&filter, bpm);

        // Validate BPM
        if (filtered_bpm >= 30.0 && filtered_bpm <= 220.0) {
            if (log_data(filtered_bpm) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

