    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Initialize moving average filter
    MovingAverageFilter filter = {{0.0}, 0, 0};

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value = -1;
        for (int i = 0; i < RETRY_COUNT; i++) {
            raw_value = read_heart_rate(i2c_handle);
            if (raw_value >= 0) {
