            }
        }

        if (raw_value < 0) {
            fprintf(stderr, "Failed to read heart rate after multiple retries\n");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        float bpm = convert_to_bpm(raw_value);
        float filtered_bpm = apply_moving_average(&filter, bpm);

        // Validate BPM
        if (filtered_bpm >= 30.0 && filtered_bpm <= 220.0) {
            if (log_data(filtered_bpm) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

