#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for sensor inputs
#define SENSOR_PIN_1 5
#define SENSOR_PIN_2 6
#define SENSOR_PIN_3 7
#define SENSOR_PIN_4 8
#define SENSOR_PIN_5 9
#define SENSOR_PIN_6 10
#define SENSOR_PIN_7 11
#define SENSOR_PIN_8 12

// Define GPIO pins for output display
#define OUTPUT_PIN_0 17
#define OUTPUT_PIN_1 18
#define OUTPUT_PIN_2 19
#define OUTPUT_PIN_3 20
#define OUTPUT_PIN_4 21
#define OUTPUT_PIN_5 22
#define OUTPUT_PIN_6 23
#define OUTPUT_PIN_7 24

// Define the number of sensor channels
#define NUM_CHANNELS 8

// Define the number of output bits
#define NUM_OUTPUT_BITS 8

// Define the delay in milliseconds
#define DELAY_MS 10

// Define the stabilization delay in milliseconds
#define STABILIZATION_DELAY_MS 200

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor_channel(int channel);
int update_output(int counter);
int log_touch_event(int channel, int counter);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int i;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request each sensor line as input with pull-down resistor
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, SENSOR_PIN_1 + i);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", SENSOR_PIN_1 + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d: %s\n", SENSOR_PIN_1 + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Request each output line as output
    for (i = 0; i < NUM_OUTPUT_BITS; i++) {
        struct gpiod_line *output_line = gpiod_chip_get_line(chip, OUTPUT_PIN_0 + i);
        if (!output_line) {
            fprintf(stderr, "Error getting line %d: %s\n", OUTPUT_PIN_0 + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(output_line, &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d: %s\n", OUTPUT_PIN_0 + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to read a sensor channel
int read_sensor_channel(int channel) {
    int value = gpiod_line_get_value(lines[channel]);
    if (value < 0) {
        fprintf(stderr, "Error reading line %d: %s\n", SENSOR_PIN_1 + channel, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to update the output display
int update_output(int counter) {
    int i;
    for (i = 0; i < NUM_OUTPUT_BITS; i++) {
        int value = (counter >> i) & 1;
        if (gpiod_line_set_value(gpiod_chip_get_line(chip, OUTPUT_PIN_0 + i), value) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n", OUTPUT_PIN_0 + i, strerror(errno));
            return -1; // Indicate an error
        }
    }
    return 0;
}

// Function to log a touch event
int log_touch_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Warning: Log file not opened. Logging to stdout.\n");
        printf("%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        return -1; // Indicate an error
    }
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    int i;
    if (chip) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    int i, counter = 0;
    int sensor_values[NUM_CHANNELS];
    int previous_values[NUM_CHANNELS];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: Could not open log file. Logging to stdout.\n");
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY_MS * 1000); // Convert milliseconds to microseconds

    // Main loop
    while (!terminate) {
        // Read sensor values
        for (i = 0; i < NUM_CHANNELS; i++) {
            sensor_values[i] = read_sensor_channel(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor channel %d. Skipping.\n", i + 1);
                sensor_values[i] = 0; // Set to 0 to avoid further issues
            }
        }

        // Update counter and output display
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (sensor_values[i] == 1 && previous_values[i] == 0) {
                counter = (counter + 1) % 256;
                if (update_output(counter) < 0) {
                    fprintf(stderr, "Error updating output display.\n");
                }
                if (log_file != NULL) {
                    log_touch_event(i + 1, counter);
                } else {
                    printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                }
            }
        }

        // Update previous values
        for (i = 0; i < NUM_CHANNELS; i++) {
            previous_values[i] = sensor_values[i];
        }

        // Delay
        usleep(DELAY_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Reset output pins to 0 before exiting
    for (i = 0; i < NUM_OUTPUT_BITS; i++) {
        if (gpiod_line_set_value(gpiod_chip_get_line(chip, OUTPUT_PIN_0 + i), 0) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n", OUTPUT_PIN_0 + i, strerror(errno));
        }
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

