#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO lines
#define GPIO17 17
#define GPIO18 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Define log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line18;
FILE *log_file;

// Function prototypes
int init_gpio(void);
int read_sensor(int gpio);
int log_event(int sensor_num);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }

    // Release GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get GPIO line for GPIO17
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO17, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for GPIO18
    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for input with active-low pull-up
    ret = gpiod_line_request_input(line17, "tilt_sensor_monitor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line18, "tilt_sensor_monitor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int gpio) {
    int value = -1; // Initialize to an invalid value
    struct timespec delay = {0, 100000}; // 100 ms delay

    // Use nanosleep to introduce a delay
    if (nanosleep(&delay, NULL) != 0) {
        perror("nanosleep");
        return -1; // Indicate an error
    }

    value = gpiod_line_get_value(gpio ? line18 : line17); // Corrected line assignment
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", gpio ? GPIO18 : GPIO17, strerror(errno));
        return -1; // Indicate an error
    }

    return value;
}

// Log event to file
int log_event(int sensor_num) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write event to log file
    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_num);

    // Close log file
    fclose(log_file);

    return 0;
}

int main() {
    int prev_value17 = 1; // Initialize to active state (untilted)
    int prev_value18 = 1; // Initialize to active state (untilted)
    struct timespec debounce_delay17 = {0, DEBOUNCE_TIME_MS * 1000000}; // 50 ms debounce
    struct timespec debounce_delay18 = {0, DEBOUNCE_TIME_MS * 1000000}; // 50 ms debounce
    struct timespec delay = {0, 100000}; // 100 ms delay

    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Tilt sensor monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int value17 = read_sensor(GPIO17);
        int value18 = read_sensor(GPIO18);

        if (value17 < 0 || value18 < 0) {
            fprintf(stderr, "Error reading sensor values. Continuing.\n");
            nanosleep(&delay, NULL); // Wait before retrying
            continue;
        }

        // Check for tilt events on GPIO17
        if (value17 == 0 && prev_value17 == 1) {
            if (log_event(1) == 0) {
                printf("Sensor 1 tilted\n");
            } else {
                fprintf(stderr, "Error logging event for sensor 1.\n");
            }
            nanosleep(&debounce_delay17, NULL); // Debounce
        }

        // Check for tilt events on GPIO18
        if (value18 == 0 && prev_value18 == 1) {
            if (log_event(2) == 0) {
                printf("Sensor 2 tilted\n");
            } else {
                fprintf(stderr, "Error logging event for sensor 2.\n");
            }
            nanosleep(&debounce_delay18, NULL); // Debounce
        }

        // Update previous values
        prev_value17 = value17;
        prev_value18 = value18;

        // Wait before next poll
        nanosleep(&delay, NULL);
    }

    return 0;
}

