    struct timespec delay = {0, 100000}; // 100 ms delay

    // Use nanosleep to introduce a delay
    if (nanosleep(&delay, NULL) != 0) {
        perror("nanosleep");
        return -1; // Indicate an error
    }

    value = gpiod_line_get_value(gpio ? line18 : line17); // Corrected line assignment
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", gpio ? GPIO18 : GPIO17, strerror(errno));
