#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125 // 8 kHz sampling rate
#define PEAK_DURATION_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Sound peak detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int mic_value = gpioRead(MIC_GPIO);
        if (mic_value == 1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Peak detected at: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to set LED GPIO%d HIGH\n", LED_GPIO);
            }
            gpioDelay(PEAK_DURATION_MS * 1000); // Convert ms to us
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to set LED GPIO%d LOW\n", LED_GPIO);
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up before exiting
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

