#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define LEFT_SENSOR_LINE 17
#define CENTER_SENSOR_LINE 27
#define RIGHT_SENSOR_LINE 22

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (center_line) {
        gpiod_line_release(center_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor values
int read_sensors(int *left, int *center, int *right)
{
    int ret;

    ret = gpiod_line_get_value(left_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading left sensor: %s\n", strerror(-ret));
        return -1;
    }
    *left = (ret == 0) ? 0 : 1; // Active-low, so 0 means detected

    ret = gpiod_line_get_value(center_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading center sensor: %s\n", strerror(-ret));
        return -1;
    }
    *center = (ret == 0) ? 0 : 1;

    ret = gpiod_line_get_value(right_line);
    if (ret < 0) {
        fprintf(stderr, "Error reading right sensor: %s\n", strerror(-ret));
        return -1;
    }
    *right = (ret == 0) ? 0 : 1;

    return 0;
}

int main()
{
    int left_sensor_value, center_sensor_value, right_sensor_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_LINE);
    if (!left_line) {
        fprintf(stderr, "Error getting left sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_LINE);
    if (!center_line) {
        fprintf(stderr, "Error getting center sensor line: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_LINE);
    if (!right_line) {
        fprintf(stderr, "Error getting right sensor line: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input with pull-up
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sunfounder_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(left_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting left sensor line: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(center_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting center sensor line: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(right_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting right sensor line: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sensors(&left_sensor_value, &center_sensor_value, &right_sensor_value) == 0) {
            printf("Left: %d, Center: %d, Right: %d\n", left_sensor_value, center_sensor_value, right_sensor_value);
        } else {
            fprintf(stderr, "Error reading sensors, retrying...\n");
        }

        usleep(100000); // 100 ms
    }

    return 0;
}

