#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI1175_ADDR 0x49

// Define the registers to read
#define SI1175_REG_ALS_VIS_LSB 0x24
#define SI1175_REG_ALS_VIS_MSB 0x25

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the Si1175 sensor
int read_si1175_data(int fd, unsigned char reg_lsb, unsigned char reg_msb, unsigned short *data) {
    unsigned char lsb, msb;

    // Read LSB
    if (write(fd, &reg_lsb, 1) != 1) {
        perror("Error writing LSB register address");
        return -1;
    }
    if (read(fd, &lsb, 1) != 1) {
        perror("Error reading LSB data");
        return -1;
    }

    // Read MSB
    if (write(fd, &reg_msb, 1) != 1) {
        perror("Error writing MSB register address");
        return -1;
    }
    if (read(fd, &msb, 1) != 1) {
        perror("Error reading MSB data");
        return -1;
    }

    // Combine LSB and MSB into a 16-bit value
    *data = (msb << 8) | lsb;

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus. Exiting.\n");
        return 1;
    }

    printf("I2C bus initialized successfully.\n");

    // Main loop to read and log data
    while (1) {
        unsigned short als_data;
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms

        // Read data from the sensor
        if (read_si1175_data(i2c_fd, SI1175_REG_ALS_VIS_LSB, SI1175_REG_ALS_VIS_MSB, &als_data) == 0) {
            // Log the raw sensor values
            printf("ALS Visible Data: %u\n", als_data);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Sleep for 100 ms
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
        }
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

