#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 2
#define MIDDLE_SENSOR_PIN 3
#define RIGHT_SENSOR_PIN 4

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variable to store the GPIO chip handle
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to format the sensor data into a string
void format_data(int left, int middle, int right, char *buffer, size_t buffer_size)
{
    snprintf(buffer, buffer_size, "L:%d M:%d R:%d", left, middle, right);
}

// Function to log the sensor data to stdout
void log_data(const char *data)
{
    printf("%s\n", data);
}

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO lines for the sensor pins
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as inputs
    if (gpiod_line_request_input(left_line, "left_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", LEFT_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(middle_line, "middle_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", MIDDLE_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", RIGHT_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to read and log sensor data
    char data_buffer[64]; // Buffer to hold the formatted data
    while (1) {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping this iteration.\n");
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        // Format the data
        format_data(left_value, middle_value, right_value, data_buffer, sizeof(data_buffer));

        // Log the data
        log_data(data_buffer);

        // Wait 100ms
        usleep(100000);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

