#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Structure to represent an RGB color
typedef struct {
    int red;
    int green;
    int blue;
} RGB;

// Global variables
volatile sig_atomic_t terminate = 0;
double hue1, hue2;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
RGB hsv_to_rgb(double h, double s, double v);
void set_led_color(RGB color);
void fade_to_hue(double target_hue);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    terminate = 1;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set RED_PIN as output");
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GREEN_PIN as output");
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set BLUE_PIN as output");
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        log_error("Failed to set PWM frequency for RED_PIN");
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        log_error("Failed to set PWM frequency for GREEN_PIN");
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        log_error("Failed to set PWM frequency for BLUE_PIN");
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        log_error("Failed to set PWM range for RED_PIN");
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        log_error("Failed to set PWM range for GREEN_PIN");
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        log_error("Failed to set PWM range for BLUE_PIN");
        return 1;
    }

    return 0;
}

// Convert HSV color to RGB
RGB hsv_to_rgb(double h, double s, double v) {
    RGB rgb;
    double r, g, b;

    h = fmod(h, 360.0); // Ensure hue is within 0-360
    if (h < 0) h += 360;

    if (s == 0.0) {
        r = g = b = v;
    } else {
        double hh, p, q, t, ff;
        long i;

        hh = h / 60.0;
        i = (long)hh;
        ff = hh - i;
        p = v * (1.0 - s);
        q = v * (1.0 - (s * ff));
        t = v * (1.0 - (s * (1.0 - ff)));

        switch (i) {
            case 0:
                r = v;
                g = t;
                b = p;
                break;
            case 1:
                r = q;
                g = v;
                b = p;
                break;
            case 2:
                r = p;
                g = v;
                b = t;
                break;
            case 3:
                r = p;
                g = q;
                b = v;
                break;
            case 4:
                r = t;
                g = p;
                b = v;
                break;
            case 5:
            default:
                r = v;
                g = p;
                b = q;
                break;
        }
    }

    rgb.red = (int)(r * 255);
    rgb.green = (int)(g * 255);
    rgb.blue = (int)(b * 255);

    return rgb;
}

// Set the color of the LED
void set_led_color(RGB color) {
    gpioPWM(RED_PIN, color.red);
    gpioPWM(GREEN_PIN, color.green);
    gpioPWM(BLUE_PIN, color.blue);
}

// Fade to a target hue
void fade_to_hue(double target_hue) {
    double diff = target_hue - hue1;
    double step_size = diff / 50.0; // 50 steps for 5-second fade
    double hue_increment = step_size / 50.0; // Increment per millisecond

    for (int i = 0; i < 50; i++) {
        hue1 += hue_increment;
        if (hue1 > 360.0) hue1 -= 360.0;
        if (hue1 < 0.0) hue1 += 360.0;

        RGB color1 = hsv_to_rgb(hue1, 1.0, 1.0);
        RGB color2 = hsv_to_rgb(target_hue, 1.0, 1.0);

        double red_diff = (double)(color2.red - color1.red);
        double green_diff = (double)(color2.green - color1.green);
        double blue_diff = (double)(color2.blue - color1.blue);

        int red_increment = (int)(red_diff / 50.0);
        int green_increment = (int)(green_diff / 50.0);
        int blue_increment = (int)(blue_diff / 50.0);

        RGB current_color = color1;
        current_color.red += red_increment;
        current_color.green += green_increment;
        current_color.blue += blue_increment;

        set_led_color(current_color);
        gpioDelay(50); // 50ms delay
    }

    set_led_color(hsv_to_rgb(target_hue, 1.0, 1.0)); // Set final color
    hue1 = target_hue; // Update current hue
}

// Log errors to syslog
void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
    fprintf(stderr, "%s\n", message);
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator
    unsigned int seed;
    FILE *fp = fopen("/dev/urandom", "rb");
    if (fp != NULL) {
        fread(&seed, sizeof(unsigned int), 1, fp);
        fclose(fp);
    } else {
        seed = time(NULL);
    }
    srand(seed);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Generate two random hues
        hue1 = (double)(rand() % 360);
        hue2 = (double)(rand() % 360);

        // Fade to the second hue
        fade_to_hue(hue2);

        // Wait for 5 seconds
        gpioDelay(5000); // 5000ms = 5 seconds

        // Swap hues for the next fade
        double temp = hue1;
        hue1 = hue2;
        hue2 = temp;
    }

    // Turn off the LED
    set_led_color(RGB{0, 0, 0});

    // Release pigpio resources
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

