#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void apply_calibration(uint16_t raw_clear, uint16_t raw_red, uint16_t raw_green, uint16_t raw_blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue);
void control_led(uint16_t calibrated_red);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    // Check sensor ID
    int sensor_id = i2c_read_reg(fd, TCS34725_ID);
    if (sensor_id != 0x44) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Enable power and RGBC
    if (i2c_write_reg(fd, TCS34725_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Error: Failed to enable sensor\n");
        return -1;
    }

    // Set integration time (ATIME = 0x00 for 154ms)
    if (i2c_write_reg(fd, TCS34725_ATIME, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set integration time\n");
        return -1;
    }

    // Set gain (CONTROL = 0x00 for 1x gain)
    if (i2c_write_reg(fd, TCS34725_CONTROL, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 data read function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    // Read all 8 bytes in one go
    if (write(fd, (const uint8_t[]){TCS34725_CDATA}, 1) != 1) {
        perror("Failed to write register address for reading");
        return -1;
    }
    if (read(fd, data, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    // Combine bytes to form 16-bit values (little-endian)
    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];

    return 0;
}

// Calibration function
void apply_calibration(uint16_t raw_clear, uint16_t raw_red, uint16_t raw_green, uint16_t raw_blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue) {
    // Hardcoded calibration values (replace with your actual calibration data)
    float clear_offset = 10.0;
    float red_gain = 1.2;
    float green_gain = 1.1;
    float blue_gain = 1.0;

    *calibrated_clear = raw_clear - clear_offset;
    *calibrated_red = raw_red * red_gain;
    *calibrated_green = raw_green * green_gain;
    *calibrated_blue = raw_blue * blue_gain;
}

// LED control function
void control_led(uint16_t calibrated_red) {
    if (calibrated_red > RED_THRESHOLD) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(led_line, 0); // Turn LED off
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line for LED control
    led_line = gpiod_line_open_by_name("gpio17");
    if (!led_line) {
        perror("Failed to open GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "tcs34725_led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_line_close(led_line);
        close(i2c_fd);
        return 1;
    }

    uint16_t raw_clear, raw_red, raw_green, raw_blue;
    float calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &raw_clear, &raw_red, &raw_green, &raw_blue) == 0) {
            // Apply calibration
            apply_calibration(raw_clear, raw_red, raw_green, raw_blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

            // Display calibrated values
            printf("Calibrated: C=%.2f, R=%.2f, G=%.2f, B=%.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

            // Control LED based on red value
            control_led(calibrated_red);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Poll every POLL_INTERVAL_MS milliseconds
        usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Clean up
    gpiod_line_set_value(led_line, 0); // Turn LED off
    gpiod_line_release(led_line);
    close(i2c_fd);

    return 0;
}

