#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define NUM_LEDS 10
#define MAX_LUX 1000.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
float read_bh1750();
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void ws2812b_send_data(unsigned char *data, int num_leds);
void generate_ws2812b_waveform(unsigned char *data, int num_leds);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
float read_bh1750() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(180); // Wait for measurement (at least 180ms)

        int msb = i2cReadByteData(i2c_handle, 0x00);
        int lsb = i2cReadByteData(i2c_handle, 0x01);

        if (msb < 0 || lsb < 0) {
            fprintf(stderr, "Error reading from I2C: %d\n", i2c_handle);
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        unsigned int raw_value = (msb << 8) | lsb;
        float lux = (float)raw_value / 1.2;
        return lux;
    }
    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1.0; // Indicate error
}

// Map lux value to LED brightness (0-255)
int map_lux_to_brightness(float lux) {
    if (lux < 0) return 0; // Handle error case
    if (lux > MAX_LUX) lux = MAX_LUX; // Cap lux value

    // Logarithmic mapping
    float log_lux = log10(lux + 1); // Add 1 to avoid log(0)
    float brightness = log_lux / log10(MAX_LUX + 1) * 255.0; // Normalize to 0-255

    return (int)brightness;
}

// Set LED brightness using WS2812B protocol
void set_led_brightness(int brightness) {
    unsigned char data[NUM_LEDS * 3]; // 3 bytes per LED (R, G, B)
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i * 3] = 0; // R
        data[i * 3 + 1] = 0; // G
        data[i * 3 + 2] = 0; // B
    }

    // Set all LEDs to the same brightness (white)
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i * 3] = brightness; // R
        data[i * 3 + 1] = brightness; // G
        data[i * 3 + 2] = brightness; // B
    }

    generate_ws2812b_waveform(data, NUM_LEDS);
}

// Generate WS2812B timing waveform
void generate_ws2812b_waveform(unsigned char *data, int num_leds) {
    int num_bytes = num_leds * 3; // Each LED has 3 bytes (R, G, B)
    int num_tones = num_bytes * 24; // 24 bits per byte

    gpioWaveClear(); // Clear any existing waves

    gpioPulse_t pulse[num_tones * 2]; // Each tone has a rising and falling edge
    int pulse_index = 0;

    for (int i = 0; i < num_bytes; i++) {
        unsigned char byte = data[i];
        for (int j = 7; j >= 0; j--) {
            if ((byte >> j) & 1) { // 1 bit
                // High pulse
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 0.8; // 0.8us
                pulse_index++;

                // Low pulse
                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = 0.45; // 0.45us
                pulse_index++;
            } else { // 0 bit
                // High pulse
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 0.8; // 0.8us
                pulse_index++;

                // High pulse
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = 0.8; // 0.8us
                pulse_index++;
            }
        }
    }

    gpioWaveAddGeneric(pulse_index, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send wave once
        while (gpioWaveTxBusy()) {
            gpioDelay(10); // Wait for wave to finish
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("WS2812B LED strip and BH1750 light sensor control started.\n");

    while (!terminate) {
        // Read light level
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading light level, using previous value.\n");
            // Optionally, you could use a default value or a previous valid reading here
            continue; // Skip to the next iteration
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        // Wait for a short period
        gpioDelay(100); // 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("WS2812B LED strip and BH1750 light sensor control terminated.\n");

    return 0;
}

