#include <string.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define BH1750_CMD_HIGH_RES 0x20
#define NUM_LEDS 8
#define LUX_MIN 10.0
#define LUX_MAX 300.0
#define BRIGHTNESS_MIN 0
#define BRIGHTNESS_MAX 31

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux);
int send_apa102_frame(uint8_t brightness);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// SPI initialization
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode and speed
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t cmd = BH1750_CMD_HIGH_RES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(180000); // Wait for conversion (at least 180ms)

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    *lux = (float)raw / 1.2;

    return 0;
}

// Map lux value to APA102 brightness
int map_lux_to_brightness(float lux) {
    if (lux < LUX_MIN) {
        return BRIGHTNESS_MIN;
    } else if (lux > LUX_MAX) {
        return BRIGHTNESS_MAX;
    } else {
        return (int)(((lux - LUX_MIN) / (LUX_MAX - LUX_MIN)) * (BRIGHTNESS_MAX - BRIGHTNESS_MIN));
    }
}

// Send APA102 frame
int send_apa102_frame(uint8_t brightness) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t led_frame[NUM_LEDS * 4] = {0xE0 | brightness, 0x00, 0x00, 0x00}; // White color
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};

    // Start frame
    struct spi_ioc_transfer start_transfer = {
        .tx_buf = (unsigned long)start_frame,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &start_transfer) < 0) {
        perror("Error sending start frame");
        return -1;
    }

    // LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        struct spi_ioc_transfer led_transfer = {
            .tx_buf = (unsigned long)led_frame,
            .len = 4,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        };
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &led_transfer) < 0) {
            perror("Error sending LED frame");
            return -1;
        }
    }

    // End frame
    struct spi_ioc_transfer end_transfer = {
        .tx_buf = (unsigned long)end_frame,
        .len = 4,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &end_transfer) < 0) {
        perror("Error sending end frame");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C and SPI
    if (init_i2c() < 0 || init_spi() < 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    float lux;
    uint8_t brightness;

    printf("Starting ambient light control...\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Send APA102 frame
            if (send_apa102_frame(brightness) != 0) {
                fprintf(stderr, "Error sending APA102 frame.\n");
            }
        } else {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        // Turn off LEDs by sending a frame with all zeros
        uint8_t zero_frame[4] = {0x00, 0x00, 0x00, 0x00};
        struct spi_ioc_transfer off_transfer = {
            .tx_buf = (unsigned long)zero_frame,
            .len = 4,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        };
        ioctl(spi_fd, SPI_IOC_MESSAGE(1), &off_transfer);
        close(spi_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Exiting.\n");
    return 0;
}

