#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_HIGH_RES_2 0x21
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 30
#define FADE_TIME_MS 500
#define DELAY_MS 100

// Global variables
int i2c_handle_low, i2c_handle_high;
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750(int i2c_handle);
float read_lux(int i2c_handle);
float average_lux(float lux1, float lux2, float lux3);
int map_lux_to_brightness(float average_lux);
int set_apa102_brightness(int brightness);
void fade_apa102_brightness(int target_brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CMD_HIGH_RES_2); // Write command to register 0x00
    if (result != 0) {
        fprintf(stderr, "Error initializing BH1750: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux(int i2c_handle) {
    int data[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading lux value: %d\n", result);
        return -1.0f;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2f; // Conversion factor from datasheet
    return lux;
}

// Average lux values from multiple sensors
float average_lux(float lux1, float lux2, float lux3) {
    int valid_count = 0;
    float sum = 0.0f;

    if (lux1 >= 0) {
        sum += lux1;
        valid_count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        valid_count++;
    }
    if (lux3 >= 0) {
        sum += lux3;
        valid_count++;
    }

    if (valid_count == 0) {
        return -1.0f; // Indicate no valid readings
    }

    return sum / valid_count;
}

// Map average lux value to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    if (average_lux < 0) {
        return 31; // Default to brightest if lux is invalid
    }

    // Invert the lux-to-brightness mapping: lower lux -> higher brightness
    int brightness = (int)(31.0f - (average_lux / 100.0f) * 31.0f); // Assuming max lux is 1000
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    return brightness;
}

// Set APA102 strip brightness using SPI
int set_apa102_brightness(int brightness) {
    unsigned char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    unsigned char end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    unsigned char brightness_frame[4] = {0xE0 | (brightness << 5), 0x00, 0x00, 0x00};

    char spi_data[12];
    for (int i = 0; i < 4; i++) {
        spi_data[i * 3] = start_frame[i];
        spi_data[i * 3 + 1] = brightness_frame[i];
        spi_data[i * 3 + 2] = start_frame[i];
    }

    int result = spiWrite(spi_handle, spi_data, 12);
    if (result != 0) {
        fprintf(stderr, "Error writing to SPI: %d\n", result);
        return -1;
    }
    return 0;
}

// Fade APA102 strip brightness over time
void fade_apa102_brightness(int target_brightness) {
    int current_brightness = 0;
    int fade_steps = FADE_TIME_MS / DELAY_MS;
    int brightness_increment = target_brightness / fade_steps;

    for (int i = 0; i < fade_steps; i++) {
        current_brightness += brightness_increment;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 31) current_brightness = 31;

        if (set_apa102_brightness(current_brightness) != 0) {
            fprintf(stderr, "Error setting brightness during fade.\n");
            return;
        }
        gpioDelay(DELAY_MS * 1000); // Delay in microseconds
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
