#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONF_REG 0x00
#define VEML7700_ALS_REG 0x04
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define LUX_MAX 120000.0
#define DEFAULT_THRESHOLD 100.0
#define DEFAULT_LUX 50.0
#define DEFAULT_BRIGHTNESS 50.0
#define DEFAULT_FREQUENCY 800000 // Hz
#define DEFAULT_INTEGRATION_TIME 100 // ms
#define DEFAULT_GAIN 0.125 // 1/8

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Configuration parameters
static float threshold = DEFAULT_THRESHOLD;
static float lux = DEFAULT_LUX;
static float brightness = DEFAULT_BRIGHTNESS;
static int frequency = DEFAULT_FREQUENCY;
static int integration_time = DEFAULT_INTEGRATION_TIME;
static float gain = DEFAULT_GAIN;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(const char *chip, int pin);
int configure_veml7700(int fd);
int read_veml7700_als(int fd, uint16_t *raw_value);
float calculate_lux(uint16_t raw_value);
float map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
int bitbang_led(int brightness);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int init_gpio(const char *chip, int pin) {
    struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name(chip);
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ptr = gpiod_chip_get_line(chip_ptr, pin);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    if (gpiod_line_request_output(line_ptr, "veml7700_led", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_ptr);
        gpiod_line_release(line_ptr);
        return -1;
    }

    return 0;
}

// VEML7700 configuration function
int configure_veml7700(int fd) {
    uint16_t config = 0x0000; // Integration time 100ms, Gain 1/8
    uint8_t buf[3];
    buf[0] = VEML7700_CONF_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to VEML7700 configuration register");
        return -1;
    }

    return 0;
}

// VEML7700 ALS reading function
int read_veml7700_als(int fd, uint16_t *raw_value) {
    uint8_t buf[1];
    uint8_t data[2];

    buf[0] = VEML7700_ALS_REG;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing to VEML7700 ALS register");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from VEML7700 ALS register");
        return -1;
    }

    *raw_value = (data[1] << 8) | data[0];
    return 0;
}

// Lux calculation function
float calculate_lux(uint16_t raw_value) {
    return raw_value * 0.0288;
}

// Brightness mapping function with gamma correction
float map_lux_to_brightness(float lux) {
    float brightness_float = 255.0 * powf(lux / LUX_MAX, 1.0 / 2.2);
    return (int)brightness_float;
}

// LED brightness setting function
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    if (gpiod_line_set_value(gpio_line, brightness > 127 ? 1 : 0) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Bit-banging LED function
int bitbang_led(int brightness) {
    // This is a placeholder.  A real implementation would
    // generate the PWM signal using the GPIO line.
    // For now, just print a message.
    printf("Bit-banging LED with brightness %d\n", brightness);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:l:b:f:i:g:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'l':
                lux = atof(optarg);
                break;
            case 'b':
                brightness = atof(optarg);
                break;
            case 'f':
                frequency = atoi(optarg);
                break;
            case 'i':
                integration_time = atoi(optarg);
                break;
            case 'g':
                gain = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-l lux] [-b brightness] [-f frequency] [-i integration_time] [-g gain]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, VEML7700_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);

    // Configure VEML7700
    if (configure_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "Failed to configure VEML7700. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t raw_value;
    float lux_value;
    int brightness_int;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_veml7700_als(i2c_fd, &raw_value) == 0) {
            // Calculate lux
            lux_value = calculate_lux(raw_value);

            // Map lux to brightness
            brightness_int = map_lux_to_brightness(lux_value);

            // Set LED brightness
            if (set_led_brightness(brightness_int) != 0) {
                fprintf(stderr, "Failed to set LED brightness.\n");
            }

            // Print lux and brightness
            printf("Lux: %.2f, Brightness: %d\n", lux_value, brightness_int);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        usleep(200000); // 200ms delay
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

