#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x48 // Example address for BH1750
#define LOG_FILE "flame_monitor.log"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
