// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// GPIO initialization
int init_gpio(void)
{
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    flame_sensor_line = gpiod_chip_get_line(gpio_chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        perror("Error getting flame sensor GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Error getting buzzer GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting LED GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Error requesting flame sensor GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Error requesting buzzer GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// I2C initialization
int init_i2c(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config[1] = {0x10}; // Continuous H-resolution mode
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error configuring BH1750");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

