        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main(void)
{
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Self-test
    printf("Running self-test...\n");
    for (int i = 0; i < 2; i++) {
        activate_led();
        usleep(500000); // 500 ms
        deactivate_led();
        usleep(500000); // 500 ms
    }

    int flame_sensor_failures = 0;
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor during self-test.\n");
            flame_sensor_failures++;
        } else if (sensor_value == 0) {
            flame_sensor_failures++;
        }
        usleep(100000); // 100 ms
    }

    if (flame_sensor_failures == 5) {
        printf("Flame sensor self-test failed. Sensor may be faulty.\n");
        log_event("ERROR", "Flame Sensor", "SELF-TEST FAILURE");
        for (int i = 0; i < 5; i++) {
            activate_led();
            usleep(100000); // 100 ms
            deactivate_led();
            usleep(100000); // 100 ms
        }
        for (int i = 0; i < 3; i++) {
            activate_buzzer();
            usleep(200000); // 200 ms
            deactivate_buzzer();
            usleep(200000); // 200 ms
            activate_buzzer();
            usleep(600000); // 600 ms
            deactivate_buzzer();
            usleep(200000); // 200 ms
        }
        cleanup();
        return 1;
    }

    printf("Self-test passed.\n");

    // Main loop
    int flame_detected = 0;
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
