                log_event("EVENT", "Flame Sensor", "HIGH");
                deactivate_buzzer();
                deactivate_led();
                flame_detected = 0;
            }
        }

        float temperature, humidity;
        if (read_dht22(&temperature, &humidity) == 0) {
            char temp_str[10], humidity_str[10];
            snprintf(temp_str, sizeof(temp_str), "%.1f", temperature);
            snprintf(humidity_str, sizeof(humidity_str), "%.1f", humidity);
            log_event("READ", "DHT22", temp_str);
            log_event("READ", "DHT22", humidity_str);
        } else {
            log_event("ERROR", "DHT22", "READ ERROR");
        }

        int light_level = read_light_level();
        if (light_level >= 0) {
            char light_str[10];
            snprintf(light_str, sizeof(light_str), "%d", light_level);
            log_event("READ", "Light Sensor", light_str);
        } else {
            log_event("ERROR", "Light Sensor", "READ ERROR");
        }

        usleep(50000); // 50 ms
    }

    cleanup();
    return 0;
}

