    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);

    // Set GPIO direction to output
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
