#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digit 5 (common cathode)
const unsigned char segment_pattern[] = {0b00111110}; // '5'

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *data_line, *clock_line, *latch_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int init_gpio(void);

// Function to shift out data to the 74HC595
int shift_out(unsigned char data);

// Function to latch the data to the output
int latch_data(void);

// Function to display the digit 5
int display_digit_5(void);

// Function to blink the display
int blink_display(int duration_ms);

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop: blink the display indefinitely
    while (1) {
        if (blink_display(500) != 0) {
            fprintf(stderr, "Error blinking display.\n");
        }
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(data_line, "data_line", 0) < 0) {
        perror("Error requesting data line for output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(clock_line, "clock_line", 0) < 0) {
        perror("Error requesting clock line for output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(latch_line, "latch_line", 0) < 0) {
        perror("Error requesting latch line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to shift out data to the 74HC595
int shift_out(unsigned char data) {
    // Set data pin
    if (gpiod_line_set_value(data_line, (data & 0x01) ? 1 : 0) < 0) {
        perror("Error setting data line value");
        return -1;
    }

    // Clock high
    if (gpiod_line_set_value(clock_line, 1) < 0) {
        perror("Error setting clock line value high");
        return -1;
    }

    // Clock low
    if (gpiod_line_set_value(clock_line, 0) < 0) {
        perror("Error setting clock line value low");
        return -1;
    }

    // Shift next bit
    if (gpiod_line_set_value(clock_line, 1) < 0) {
        perror("Error setting clock line value high");
        return -1;
    }

    // Clock low
    if (gpiod_line_set_value(clock_line, 0) < 0) {
        perror("Error setting clock line value low");
        return -1;
    }

    return 0;
}

// Function to latch the data to the output
int latch_data(void) {
    // Latch high
    if (gpiod_line_set_value(latch_line, 1) < 0) {
        perror("Error setting latch line value high");
        return -1;
    }

    // Latch low
    if (gpiod_line_set_value(latch_line, 0) < 0) {
        perror("Error setting latch line value low");
        return -1;
    }

    return 0;
}

// Function to display the digit 5
int display_digit_5(void) {
    // Shift out the segment pattern
    for (size_t i = 0; i < sizeof(segment_pattern); ++i) {
        if (shift_out(segment_pattern[i]) != 0) {
            fprintf(stderr, "Error shifting out data.\n");
            return -1;
        }
    }

    // Latch the data
    if (latch_data() != 0) {
        fprintf(stderr, "Error latching data.\n");
        return -1;
    }

    return 0;
}

// Function to blink the display
int blink_display(int duration_ms) {
    // Display the digit 5
    if (display_digit_5() != 0) {
        fprintf(stderr, "Error displaying digit 5.\n");
        return -1;
    }

    // Wait for the specified duration
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&sleep_time, NULL);

    // Turn off the display (set all segments low)
    for (size_t i = 0; i < sizeof(segment_pattern); ++i) {
        if (shift_out(0xFF) != 0) {
            fprintf(stderr, "Error shifting out data to turn off display.\n");
            return -1;
        }
    }

    // Latch the data
    if (latch_data() != 0) {
        fprintf(stderr, "Error latching data to turn off display.\n");
        return -1;
    }

    // Wait for the specified duration
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&sleep_time, NULL);

    return 0;
}

