        return -1;
    }

    return 0;
}

// Function to blink the display
int blink_display(int duration_ms) {
    // Display the digit 5
    if (display_digit_5() != 0) {
        fprintf(stderr, "Error displaying digit 5.\n");
        return -1;
    }

    // Wait for the specified duration
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&sleep_time, NULL);

    // Turn off the display (set all segments low)
    for (size_t i = 0; i < sizeof(segment_pattern); ++i) {
        if (shift_out(0xFF) != 0) {
            fprintf(stderr, "Error shifting out data to turn off display.\n");
            return -1;
        }
    }

    // Latch the data
    if (latch_data() != 0) {
        fprintf(stderr, "Error latching data to turn off display.\n");
        return -1;
    }

    // Wait for the specified duration
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = duration_ms * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&sleep_time, NULL);

    return 0;
}

