#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *led_line;
struct gpiod_line *button_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(button_line, "blink_button") < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial pull-up on the button line
    if (gpiod_line_set_pullUpDown(button_line, GPIOD_LINE_PULL_UP) < 0) {
        perror("Error setting pull-up on button line");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Blink LED loop
    while (1) {
        // Turn LED on
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Error setting LED value");
            break;
        }
        sleep(1);

        // Turn LED off
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Error setting LED value");
            break;
        }
        sleep(1);

        // Monitor button events with timeout
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(button_line, 1, &event, 1); // 1-second timeout

        if (ret < 0) {
            perror("Error waiting for button event");
            break;
        } else if (ret > 0) {
            // Button event occurred
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                printf("Button pressed (rising edge).\n");
                break;
            }
        }
    }

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

