#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5 // GPIO5, physical pin 29

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO5 as an output
    result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", LED_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Turn LED on
        result = gpioWrite(LED_PIN, 1);
        if (result != 0) {
            fprintf(stderr, "Failed to write to GPIO%d: %d\n", LED_PIN, result);
            break; // Exit loop on error
        }
        printf("LED ON\n");
        fflush(stdout);

        // Wait 750 ms
        gpioDelay(750000); // 750 ms = 750000 microseconds

        // Turn LED off
        result = gpioWrite(LED_PIN, 0);
        if (result != 0) {
            fprintf(stderr, "Failed to write to GPIO%d: %d\n", LED_PIN, result);
            break; // Exit loop on error
        }
        printf("LED OFF\n");
        fflush(stdout);

        // Wait another 750 ms
        gpioDelay(750000); // 750 ms = 750000 microseconds
    }

    // Clean up: Turn LED off and terminate pigpio
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

