// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define LED_LINE 24
#define BUTTON_LINE 22

// Define LED blink interval (milliseconds)
#define BLINK_INTERVAL_MS 500

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO resources
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int init_gpio()
{
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_LINE);
    if (!button_line) {
        fprintf(stderr, "Error getting button line %d: %s\n", BUTTON_LINE, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set LED line as output
    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set button line as input with pull-down
    if (gpiod_line_request_input(button_line, "button_input") < 0) {
        fprintf(stderr, "Error requesting button line as input: %s\n", strerror(errno));
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to control the LED
void control_led(int on)
{
    if (gpiod_line_set_value(led_line, on) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

// Function to read the button state
int read_button()
{
    int value = gpiod_line_get_value(button_line);
    if (value < 0) {
        fprintf(stderr, "Error reading button value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    fprintf(stderr, "GPIO initialized successfully.\n");

    // Main loop
    int button_state = 0; // 0: released, 1: pressed
    int led_on = 0;       // 0: off, 1: on
    struct timespec blink_delay = {0, BLINK_INTERVAL_MS * 1000000L}; // 500ms

    while (1) {
        // Read button state
        int new_button_state = read_button();
        if (new_button_state < 0) {
            // Error reading button, but continue to avoid exiting
            continue;
        }

        // Check if button is pressed (active low)
        if (new_button_state == 0 && button_state == 1) {
            // Button pressed
            if (!led_on) {
                // Blink LED
                control_led(1);
                led_on = 1;
                nanosleep(&blink_delay, NULL);
                control_led(0);
                led_on = 0;
            }
        } else if (new_button_state == 1 && button_state == 0) {
            // Button released
            control_led(0);
            led_on = 0;
        }

        button_state = new_button_state;

        // Small delay to avoid busy-waiting
        struct timespec delay = {0, 10000L}; // 10ms
        nanosleep(&delay, NULL);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup for completeness.
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

