#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for RGB LED (BCM numbering)
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define GPIO chip number
#define GPIOCHIP 0

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM period (microseconds)
#define PWM_PERIOD 10000 // 10 ms

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Function prototypes
int initialize_gpio(void);
void set_led_color(int red, int green, int blue);
void generate_random_color(int *red, int *green, int *blue);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines for each color
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb-led", 0) < 0) {
        perror("Error requesting red line as output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(green_line, "rgb-led", 0) < 0) {
        perror("Error requesting green line as output");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(blue_line, "rgb-led", 0) < 0) {
        perror("Error requesting blue line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the LED color using software PWM
void set_led_color(int red, int green, int blue) {
    // Set the duty cycle for each color
    gpiod_line_set_value(red_line, (red > 50) ? 1 : 0);
    gpiod_line_set_value(green_line, (green > 50) ? 1 : 0);
    gpiod_line_set_value(blue_line, (blue > 50) ? 1 : 0);
}

// Function to generate a random RGB color
void generate_random_color(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
