#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact indication
#define IMPACT_GPIO 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double g_threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int config_lsm303();
accelerometer_data_t read_accelerometer_data();
double calculate_g_force_magnitude(accelerometer_data_t data);
void handle_impact(accelerometer_data_t data);
void log_data(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure LSM303DLHC accelerometer
int config_lsm303() {
    // CTRL_REG1_A: Enable all axes, 100 Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // CTRL_REG4_A: 2G full-scale, sensitivity 16384 LSB/G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate G-force magnitude
double calculate_g_force_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z) / 16384.0;
}

// Handle impact detection and logging
void handle_impact(accelerometer_data_t data) {
    gpioWrite(IMPACT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(50);             // Wait 50 ms
    gpioWrite(IMPACT_GPIO, 0); // Set GPIO LOW

    log_data(data);
}

// Log accelerometer data to file
void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure LSM303DLHC
    if (config_lsm303() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Threshold: %.2fG\n", g_threshold);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        double magnitude = calculate_g_force_magnitude(data);

        if (magnitude > g_threshold) {
            handle_impact(data);
        }

        gpioDelay(100); // Poll every 100 ms (10 Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

