#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define MODE_REG 0x0D
#define MODE_VALUE 0x01
#define GPIO_LED 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_als(uint16_t *als);
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
int set_led_brightness(uint16_t als);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the ADPD188BI sensor
int init_sensor() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, MODE_REG, MODE_VALUE) >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to MODE register: %d, retries left: %d\n", i2c_handle, retries);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1;
}

// Read ambient light sensor data
int read_als(uint16_t *als) {
    char buf[2];
    int retries = 3;
    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 2) == 2) {
            *als = (buf[1] << 8) | buf[0];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading ALS data: %d, retries left: %d\n", i2c_handle, retries);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1;
}

// Read color sensor data
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[2];
    int retries = 3;
    char reg;

    // Read Red
    reg = RED_REG;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, reg) >= 0) {
            if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) == 2) {
                *red = (buf[1] << 8) | buf[0];
                break;
            } else {
                fprintf(stderr, "Error reading Red data: %d, retries left: %d\n", i2c_handle, retries);
                gpioDelay(100); // Wait 100ms before retrying
                retries--;
            }
        } else {
            fprintf(stderr, "Error writing to Red register: %d, retries left: %d\n", i2c_handle, retries);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    if (retries == 0) return -1;

    // Read Green
    reg = GREEN_REG;
    retries = 3;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, reg) >= 0) {
            if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) == 2) {
                *green = (buf[1] << 8) | buf[0];
                break;
            } else {
                fprintf(stderr, "Error reading Green data: %d, retries left: %d\n", i2c_handle, retries);
                gpioDelay(100); // Wait 100ms before retrying
                retries--;
            }
        } else {
            fprintf(stderr, "Error writing to Green register: %d, retries left: %d\n", i2c_handle, retries);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    if (retries == 0) return -1;

    // Read Blue
    reg = BLUE_REG;
    retries = 3;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, reg) >= 0) {
            if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) == 2) {
                *blue = (buf[1] << 8) | buf[0];
                break;
            } else {
                fprintf(stderr, "Error reading Blue data: %d, retries left: %d\n", i2c_handle, retries);
                gpioDelay(100); // Wait 100ms before retrying
                retries--;
            }
        } else {
            fprintf(stderr, "Error writing to Blue register: %d, retries left: %d\n", i2c_handle, retries);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }
    if (retries == 0) return -1;

    return 0;
}

// Log data to CSV file
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Set LED brightness using hardware PWM
int set_led_brightness(uint16_t als) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als / 65535.0) * 255.0);

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(GPIO_LED, duty_cycle);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency for GPIO18
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Register signal handler
