int verify_sensor();
int configure_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0xC7, got 0x%x\n", who_am_i);
        return -1;
    }
    printf("Sensor ID verified!\n");
    return 0;
}

// Configure sensor
int configure_sensor() {
    // Standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    // Configure for ±2g range
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    // Active mode, 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    return 0;
}

