int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x01, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = x * ACCEL_SENSITIVITY;
    float y_g = y * ACCEL_SENSITIVITY;
    float z_g = z * ACCEL_SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

