int log_impact(float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[200];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_entry, sizeof(log_entry), "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, 0, 0, 0, magnitude);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return -1;
    }

    if (fputs(log_entry, fp) == EOF) {
        fprintf(stderr, "Error writing to impact_log.txt\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

