    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > ACCEL_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
                if (log_impact(magnitude) != 0) {
                    fprintf(stderr, "Error logging impact\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US); // Sample every 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

