#include <linux/i2c-dev.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity
#define SENSITIVITY 0.00875

// Alert threshold
#define ALERT_THRESHOLD 50.0

// Log file name
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int init_i2c(int address);
int config_gyro(int fd);
int read_gyro_data(int fd, short *x, short *y, short *z);
float convert_to_dps(short raw_value);
void calibrate_gyro(int fd, int num_samples);
void log_data(float x, float y, float z);
void check_alert(float x, float y, float z);
void signal_handler(int signum);

// Structure to hold gyro data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure the gyroscope
int config_gyro(int fd) {
    unsigned char ctrl_reg1_value = 0x0F; // Normal mode, all axes enabled, 100 Hz ODR
    unsigned char ctrl_reg4_value = 0x00; // 250 dps full-scale, continuous update

    if (write(fd, &ctrl_reg1_value, 1) != 1) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    if (write(fd, &ctrl_reg4_value, 1) != 1) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    return 0;
}

