#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// LED GPIO pin
#define LED_PIN 17

// Acceleration threshold (g)
#define ACCEL_THRESHOLD 2.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize ADXL345
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        accelerometer_data_t accel_data;

        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue; // Continue to the next iteration
        }

        // Log data
        log_data(accel_data.x, accel_data.y, accel_data.z);

        // Control LED
        control_led(accel_data.x > ACCEL_THRESHOLD || accel_data.y > ACCEL_THRESHOLD || accel_data.z > ACCEL_THRESHOLD);

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize ADXL345
int init_adxl345() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Failed to read DEVID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%X\n", devid);
        i2cClose(i2c_handle);
        return -1;
    }

    // Set data format to full resolution and range to ±2g
    if (i2cWriteByteData(i2c_handle, 0x31, 0x0B) < 0) { // Data format register
        fprintf(stderr, "Failed to write data format register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) { // Power control register
        fprintf(stderr, "Failed to write power control register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Convert raw data to g units (assuming full resolution and ±2g range)
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    // Write to log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_g, y_g, z_g);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, terminating program...\n");
}

