    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c(int addr) {
    int handle = i2cOpen(I2C_BUS, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }

    // Enable continuous measurement
    if (write_control_register(handle, CTRL_VALUE) != 0) {
        fprintf(stderr, "Error writing to control register for address 0x%02x\n", addr);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Read data from the sensor
int read_sensor_data(int handle, int16_t *data) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, DATA_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading data from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Write to the control register
int write_control_register(int handle, uint8_t value) {
    int result = i2cWriteByteData(handle, CTRL_REG, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to control register: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate TDOA
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return sensor1_data - sensor2_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%ld,%ld,%d,%d,%d\n", data.sec, data.nsec, data.sensor1, data.sensor2, data.tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C communication for both sensors
    i2c_handle1 = init_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        int16_t sensor1_data, sensor2_data;

        // Get timestamp
        data.sec = time(NULL);
        data.nsec = 0; // nanoseconds are not directly available, using 0 for simplicity

        // Read data from sensors
        if (read_sensor_data(i2c_handle1, &sensor1_data) != 0) {
            fprintf(stderr, "Error reading sensor 1 data, skipping sample\n");
            continue; // Skip to the next iteration
        }
        if (read_sensor_data(i2c_handle2, &sensor2_data) != 0) {
            fprintf(stderr, "Error reading sensor 2 data, skipping sample\n");
            continue; // Skip to the next iteration
        }

        // Calculate TDOA
        data.tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_US);
    }

    // Close I2C handles and log file
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

