#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_FREQUENCY 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // CPOL=1, CPHA=1, aux SPI off

// Sensitivities
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Function Prototypes
int spi_read_register(int handle, uint16_t address, uint16_t *data);
int spi_write_register(int handle, uint16_t address, uint16_t data);
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int log_data(FILE *fp, long long timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int handle, uint16_t address, uint16_t *data) {
    char tx[4];
    char rx[4];

    // Construct the transmit data (dummy read + register address)
    tx[0] = 0x0000; // Dummy data
    tx[1] = (address >> 8) & 0xFF; // MSB of address
    tx[2] = address & 0xFF;      // LSB of address
    tx[3] = 0x0000; // Dummy data

    if (spiXfer(handle, tx, rx, 4) < 0) {
        fprintf(stderr, "Error: SPI read failed for address 0x%02X\n", address);
        return -1;
    }

    // Extract the data from the receive buffer
    *data = ((uint16_t)rx[2] << 8) | (uint16_t)rx[3];

    return 0;
}

// Function to write a register to the ADIS16488A
int spi_write_register(int handle, uint16_t address, uint16_t data) {
    char tx[4];
    char rx[4];

    // Construct the transmit data (register address + data)
    tx[0] = (address >> 8) & 0xFF; // MSB of address
    tx[1] = address & 0xFF;      // LSB of address
    tx[2] = (data >> 8) & 0xFF; // MSB of data
    tx[3] = data & 0xFF;      // LSB of data

    if (spiXfer(handle, tx, rx, 4) < 0) {
        fprintf(stderr, "Error: SPI write failed for address 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(handle, X_GYRO, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(handle, Y_GYRO, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(handle, Z_GYRO, &raw_gyro_z) != 0) return -1;
    if (spi_read_register(handle, X_ACCEL, &raw_accel_x) != 0) return -1;
    if (spi_read_register(handle, Y_ACCEL, &raw_accel_y) != 0) return -1;
    if (spi_read_register(handle, Z_ACCEL, &raw_accel_z) != 0) return -1;

    // Convert raw data to physical units
    *gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SENSITIVITY;
    *gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SENSITIVITY;
    *gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SENSITIVITY;
    *accel_x = (float)((int16_t)raw_accel_x) * ACCEL_SENSITIVITY;
    *accel_y = (float)((int16_t)raw_accel_y) * ACCEL_SENSITIVITY;
    *accel_z = (float)((int16_t)raw_accel_z) * ACCEL_SENSITIVITY;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, long long timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    if (fprintf(fp, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "Error: Failed to write data to file\n");
        return -1;
    }
    return 0;
}

// Cleanup function to be called on exit
void cleanup(int signal) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    long long timestamp_ms;

    // Register cleanup function
    atexit(cleanup);
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_FREQUENCY, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Main loop
    while (running) {
        // Read IMU data
        if (read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Log data to file
            if (log_data(fp, timestamp_ms, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read IMU data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us

        // Check for termination signal every 10 ms
        gpioDelay(10000); // 10 ms
    }

    return 0;
}

