#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Define SPI device and GPIO chip
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

// ADIS16448 register addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scale factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCEL_SCALE 0.00025 // g/LSB

// Global variables for signal handling
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int adis16448_read_register(int fd, uint8_t address, uint16_t *data);
void adis16448_read_gyro(int fd, float *gyro_x, float *gyro_y, float *gyro_z);
void adis16448_read_accel(int fd, float *accel_x, float *accel_y, float *accel_z);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_bits = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_bits) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_bits = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_bits) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 16,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADIS16448 register read function
int adis16448_read_register(int fd, uint8_t address, uint16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set MSB for read operation
    tx_buf[0] = address | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spi_transfer(fd, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", address);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// ADIS16448 gyro read function
void adis16448_read_gyro(int fd, float *gyro_x, float *gyro_y, float *gyro_z) {
    uint16_t raw_x, raw_y, raw_z;

    if (adis16448_read_register(fd, XGYRO_OUT, &raw_x) != 0) {
        fprintf(stderr, "Failed to read X gyro data\n");
        *gyro_x = NAN;
        return;
    }
    if (adis16448_read_register(fd, YGYRO_OUT, &raw_y) != 0) {
        fprintf(stderr, "Failed to read Y gyro data\n");
        *gyro_y = NAN;
        return;
    }
    if (adis16448_read_register(fd, ZGYRO_OUT, &raw_z) != 0) {
        fprintf(stderr, "Failed to read Z gyro data\n");
        *gyro_z = NAN;
        return;
    }

    *gyro_x = (float)((int16_t)raw_x) * GYRO_SCALE;
    *gyro_y = (float)((int16_t)raw_y) * GYRO_SCALE;
    *gyro_z = (float)((int16_t)raw_z) * GYRO_SCALE;
}

// ADIS16448 accelerometer read function
void adis16448_read_accel(int fd, float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_x, raw_y, raw_z;

    if (adis16448_read_register(fd, XACCL_OUT, &raw_x) != 0) {
        fprintf(stderr, "Failed to read X accel data\n");
        *accel_x = NAN;
        return;
    }
    if (adis16448_read_register(fd, YACCL_OUT, &raw_y) != 0) {
        fprintf(stderr, "Failed to read Y accel data\n");
        *accel_y = NAN;
        return;
    }
    if (adis16448_read_register(fd, ZACCL_OUT, &raw_z) != 0) {
        fprintf(stderr, "Failed to read Z accel data\n");
        *accel_z = NAN;
        return;
    }

    *accel_x = (float)((int16_t)raw_x) * ACCEL_SCALE;
    *accel_y = (float)((int16_t)raw_y) * ACCEL_SCALE;
    *accel_z = (float)((int16_t)raw_z) * ACCEL_SCALE;
}

// Signal handler function
