#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read data from ADIS16448 register
int read_adis16448_register(int spi_handle, unsigned short register_address, unsigned short *data) {
    char tx_buffer[4];
    char rx_buffer[4];

    // Construct the transmit buffer: register address (MSB set) + dummy data
    tx_buffer[0] = (register_address << 8) | 0x80; // MSB set for read
    tx_buffer[1] = 0x00;
    tx_buffer[2] = 0x00;
    tx_buffer[3] = 0x00;

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI transfer failed (read) with code %d\n", result);
        return -1;
    }

    // Extract the 16-bit data from the receive buffer
    *data = (rx_buffer[1] << 8) | rx_buffer[2];

    return 0;
}

// Function to convert raw data to physical units
void convert_data(unsigned short raw_data, float *scaled_data) {
    *scaled_data = (float)raw_data * GYRO_SCALE; // Gyroscope
    *scaled_data = (float)raw_data * ACCL_SCALE;  // Accelerometer
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        unsigned short raw_gyro_x, raw_gyro_y, raw_gyro_z;
        unsigned short raw_accl_x, raw_accl_y, raw_accl_z;
        float scaled_gyro_x, scaled_gyro_y, scaled_gyro_z;
        float scaled_accl_x, scaled_accl_y, scaled_accl_z;

        // Read gyroscope data
        if (read_adis16448_register(spi_handle, X_GYRO_OUT, &raw_gyro_x) != 0) {
            fprintf(stderr, "Error reading X_GYRO_OUT\n");
            continue; // Continue to the next iteration
        }
        if (read_adis16448_register(spi_handle, Y_GYRO_OUT, &raw_gyro_y) != 0) {
            fprintf(stderr, "Error reading Y_GYRO_OUT\n");
            continue;
        }
        if (read_adis16448_register(spi_handle, Z_GYRO_OUT, &raw_gyro_z) != 0) {
            fprintf(stderr, "Error reading Z_GYRO_OUT\n");
            continue;
        }

        // Read accelerometer data
        if (read_adis16448_register(spi_handle, X_ACCL_OUT, &raw_accl_x) != 0) {
            fprintf(stderr, "Error reading X_ACCL_OUT\n");
            continue;
        }
        if (read_adis16448_register(spi_handle, Y_ACCL_OUT, &raw_accl_y) != 0) {
            fprintf(stderr, "Error reading Y_ACCL_OUT\n");
            continue;
        }
        if (read_adis16448_register(spi_handle, Z_ACCL_OUT, &raw_accl_z) != 0) {
            fprintf(stderr, "Error reading Z_ACCL_OUT\n");
            continue;
        }

        // Convert raw data to physical units
        convert_data(raw_gyro_x, &scaled_gyro_x);
        convert_data(raw_gyro_y, &scaled_gyro_y);
        convert_data(raw_gyro_z, &scaled_gyro_z);
        convert_data(raw_accl_x, &scaled_accl_x);
        convert_data(raw_accl_y, &scaled_accl_y);
        convert_data(raw_accl_z, &scaled_accl_z);

        // Print the data
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s  |  Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
               scaled_gyro_x, scaled_gyro_y, scaled_gyro_z, scaled_accl_x, scaled_accl_y, scaled_accl_z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI handle and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

