#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %s. Retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %s. Retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_word_data(fd, ACCEL_XOUT_H);
        if (result >= 0) {
            *accel_x = (int16_t)result;
            result = i2c_smbus_read_word_data(fd, ACCEL_XOUT_H + 2);
            if (result >= 0) {
                *accel_y = (int16_t)result;
                result = i2c_smbus_read_word_data(fd, ACCEL_XOUT_H + 4);
                if (result >= 0) {
                    *accel_z = (int16_t)result;
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error reading ACCEL_Z: %s. Retrying...\n", strerror(errno));
                    retries--;
                    usleep(10000); // 10ms delay
                }
            } else {
                fprintf(stderr, "Error reading ACCEL_Y: %s. Retrying...\n", strerror(errno));
                retries--;
                usleep(10000); // 10ms delay
            }
        } else {
            fprintf(stderr, "Error reading ACCEL_X: %s. Retrying...\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to read accelerometer data after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read gyroscope data
int read_gyroscope_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_word_data(fd, GYRO_XOUT_H);
        if (result >= 0) {
            *gyro_x = (int16_t)result;
