#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_DURATION 500 // milliseconds
#define SCALE_FACTOR 256.0f // LSB/g for +-2g range
#define DATA_RATE 0x0A       // 100 Hz
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int configure_adxl345();
accelerometer_data_t read_acceleration();
float calculate_magnitude(accelerometer_data_t data);
void control_led(int on);
void log_impact(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verifies the ADXL345 device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }
    printf("ADXL345 device ID verified.\n");
    return 0;
}

// Configures the ADXL345 for full-resolution mode and +-2g range
int configure_adxl345() {
    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, DATA_RATE, DATA_RATE) < 0) {
        fprintf(stderr, "Error writing data rate register.\n");
        return -1;
    }

    // Set full resolution mode and +-2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing data format register.\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing power control register.\n");
        return -1;
    }

    return 0;
}

// Reads acceleration data from the ADXL345
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data.\n");
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, and convert to g-force units
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    data.x = (float)x / SCALE_FACTOR;
    data.y = (float)y / SCALE_FACTOR;
    data.z = (float)z / SCALE_FACTOR;

    return data;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Controls the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Logs impact data to a file
void log_impact(accelerometer_data_t data, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Impact detected: Magnitude = %.2f g, X = %.2f g, Y = %.2f g, Z = %.2f g\n",
            timestamp, magnitude, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADXL345
    if (configure_adxl345() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_acceleration();
        float magnitude = calculate_magnitude(data);

        if (magnitude > IMPACT_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            control_led(1); // Turn on LED
            log_impact(data, magnitude);
            gpioDelay(IMPACT_DURATION * 1000); // Delay for impact duration
            control_led(0); // Turn off LED
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

