            gpioDelay(IMPACT_DURATION * 1000); // Delay for impact duration
            control_led(0); // Turn off LED
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

