// I2C write block function
int i2c_write_block(int fd, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read acceleration data function
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char data[6];
    if (i2c_read_block(fd, OUT_X_MSB, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]) >> 2;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 2;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 2;

    return 0;
}

// Convert raw value to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 2048.0f; // Assuming +-2g range
}

// Calculate magnitude of acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Control LED function
void control_led(struct gpiod_line *line, int on) {
    if (gpiod_line_set_value(line, on ? 1 : 0) < 0) {
        perror("Failed to set LED value");
    }
}

// Log impact function
void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Failed to open impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Impact detected: X=%.2f g, Y=%.2f g, Z=%.2f g\n", s, x, y, z);
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2c_read_byte(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        close(i2c_fd);
        return 1;
    }
    printf("WHO_AM_I register value: 0x%02X (correct)\n", who_am_i);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "accelerometer-led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Configure accelerometer (e.g., set range to +-2g, enable measurement)
    if (i2c_write_byte(i2c_fd, CTRL_REG1, 0x01) != 0) { // Active mode, 100 Hz ODR
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, CTRL_REG2, 0x00) != 0) { // +/- 2g range
        fprintf(stderr, "Failed to write to CTRL_REG2\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float x_g, y_g, z_g, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(i2c_fd, &x, &y, &z) == 0) {
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);
            magnitude = calculate_magnitude(x_g, y_g, z_g);

            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                control_led(gpio_line, 1); // Turn LED on
                log_impact(x_g, y_g, z_g); // Log the impact
                usleep(LED_ON_TIME_MS * 1000); // Wait for 500ms
                control_led(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data, retrying...\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    control_led(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

