#include <errno.h>

// TMAG5273 I2C address
#define TMAG5273_ADDR 0x35

// TMAG5273 register addresses
#define TMAG5273_REG_X 0x10
#define TMAG5273_REG_Y 0x11
#define TMAG5273_REG_Z 0x12

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *device);
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
sensor_data_t read_sensor_data(int fd);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signum);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// I2C setup function
int i2c_setup(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading register data: %s\n", strerror(errno));
        return -1;
    }

    return (data[1] << 8) | data[0]; // Little-endian
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data function
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    data.x = i2c_read_register(fd, TMAG5273_REG_X);
    data.y = i2c_read_register(fd, TMAG5273_REG_Y);
    data.z = i2c_read_register(fd, TMAG5273_REG_Z);
    return data;
}

// Log data function
void log_data(FILE *fp, sensor_data_t data) {
    char* timestamp = get_iso8601_timestamp();
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
    free(timestamp);
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = i2c_setup("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Check if log file exists, if not create it and write header
    log_file = fopen("magnetic_field_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        sensor_data_t data = read_sensor_data(i2c_fd);
        log_data(log_file, data);
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

