#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x21
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32

// GPIO pin for interrupt
#define GPIO_PIN 17

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte(int fd, unsigned char reg);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int adxl345_init(int fd);
int gpio_request(struct gpiod_chip **chip, struct gpiod_line **line, int pin);
int gpio_set_edge(struct gpiod_line *line, const char *edge);
int gpio_set_consumer(struct gpiod_line *line, const char *consumer);
int gpio_enable_line(struct gpiod_line *line, int rising_edge);
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
int verify_device_id(int fd);

// I2C read byte function
int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    unsigned char value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// I2C write byte function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    if (verify_device_id(fd) != 0) {
        fprintf(stderr, "ADXL345 device ID verification failed.\n");
        return -1;
    }

    if (i2c_write_byte(fd, ADXL345_REG_THRESH_FF, 0x0A) != 0) return -1; // ~300 mg
    if (i2c_write_byte(fd, ADXL345_REG_TIME_FF, 0x20) != 0) return -1;   // ~100 ms
    if (i2c_write_byte(fd, ADXL345_REG_INT_ENABLE, 0x04) != 0) return -1; // Enable freefall interrupt
    if (i2c_write_byte(fd, ADXL345_REG_INT_MAP, 0x00) != 0) return -1;   // Map to INT1
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) != 0) return -1; // Measurement mode

    return 0;
}

// GPIO request function
int gpio_request(struct gpiod_chip **chip, struct gpiod_line **line, int pin) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("gpiod_chip_open_by_name failed");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, pin);
    if (!*line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request(*line, "freefall_detector", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("gpiod_line_request failed");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// GPIO set edge function
int gpio_set_edge(struct gpiod_line *line, const char *edge) {
    if (gpiod_line_set_edge(line, edge) < 0) {
        perror("gpiod_line_set_edge failed");
        return -1;
    }
    return 0;
}

// GPIO set consumer function
int gpio_set_consumer(struct gpiod_line *line, const char *consumer) {
    if (gpiod_line_request_output(line, "freefall_detector", 0) < 0) {
        perror("gpiod_line_request_output failed");
        return -1;
    }
    return 0;
}

// GPIO enable line function
int gpio_enable_line(struct gpiod_line *line, int rising_edge) {
    if (gpiod_line_set_value(line, rising_edge) < 0) {
        perror("gpiod_line_set_value failed");
        return -1;
    }
    return 0;
}

// Read acceleration data function
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char data[6];
    if (write(fd, ADXL345_REG_DATAX0, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, data, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Log data function
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + 19, 3, ".%03d", (int)((timeinfo->tm_sec) * 1000 + (timeinfo->tm_usec) / 1000));

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Verify device ID function
int verify_device_id(int fd) {
    int device_id = i2c_read_byte(fd, ADXL345_REG_DEVID);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read device ID.\n");
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }
    printf("ADXL345 device ID verified: 0x%02X\n", device_id);
    return 0;
}

int main() {
    int16_t x, y, z;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    if (gpio_request(&gpio_chip, &gpio_line, GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO request failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO edge
    if (gpio_set_edge(gpio_line, "falling") != 0) {
        fprintf(stderr, "GPIO set edge failed.\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO consumer
    if (gpio_set_consumer(gpio_line, "freefall_detector") != 0) {
        fprintf(stderr, "GPIO set consumer failed.\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Enable GPIO line
    if (gpio_enable_line(gpio_line, 1) != 0) {
        fprintf(stderr, "GPIO enable line failed.\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (program_running) {
        // Poll GPIO line for interrupt
        ret = gpiod_line_event(gpio_line, NULL);
        if (ret > 0) {
            // Clear interrupt by reading INT_SOURCE register
            i2c_read_byte(i2c_fd, ADXL345_REG_INT_SOURCE);

            // Read acceleration data
            if (read_acceleration_data(i2c_fd, &x, &y, &z) == 0) {
                // Log data
                log_data(log_file, x, y, z);
            } else {
                fprintf(stderr, "Failed to read acceleration data.\n");
            }
        } else if (ret < 0) {
            perror("GPIO poll failed");
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10 ms
    }

    // Disable GPIO line
    gpiod_line_set_value(gpio_line, 0);

    // Release GPIO line
    gpiod_line_release(gpio_line);

    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    printf("Program finished.\n");
    return 0;
}

