#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE_2G 0x00
#define GYRO_RANGE_250DPS 0x00

// Output data rate (ODR)
#define ODR_104HZ 0x60 // 104 Hz, 2g, 250 dps

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f

// Freefall and impact time window (in seconds)
#define TIME_WINDOW 1.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, ODR_104HZ | ACCEL_RANGE_2G) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, ODR_104HZ | GYRO_RANGE_250DPS) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from the LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }
    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw data to g and dps (assuming +/- 2g and +/- 250 dps ranges)
    data->accel_x = (float)raw_accel_x / 16384.0f; // 16384 LSB/g for +/- 2g range
    data->accel_y = (float)raw_accel_y / 16384.0f;
    data->accel_z = (float)raw_accel_z / 16384.0f;
    data->gyro_x = (float)raw_gyro_x / 131.0f; // 131 LSB/dps for +/- 250 dps range
    data->gyro_y = (float)raw_gyro_y / 131.0f;
    data->gyro_z = (float)raw_gyro_z / 131.0f;

    return 0;
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Implement a basic fall detection state machine
void fall_detection(sensor_data_t data) {
    static time_t freefall_start_time = 0;
    static int in_freefall = 0;
    static int in_impact = 0;
    time_t current_time = time(NULL);

    float accel_magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    if (accel_magnitude < FREEFALL_THRESHOLD) {
        if (!in_freefall) {
            freefall_start_time = current_time;
            in_freefall = 1;
        }
    } else {
        in_freefall = 0;
    }

    if (in_freefall && (current_time - freefall_start_time) <= TIME_WINDOW) {
        if (accel_magnitude > IMPACT_THRESHOLD) {
            if (!in_impact) {
                printf("FALL DETECTED: Impact detected!\n");
                fprintf(log_file, "FALL DETECTED: Impact detected!\n");
                fflush(log_file);
                in_impact = 1;
            }
        }
    } else {
        in_impact = 0;
    }
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

