    data->gyro_x = (float)raw_gyro_x / 131.0f; // 131 LSB/dps for +/- 250 dps range
    data->gyro_y = (float)raw_gyro_y / 131.0f;
    data->gyro_z = (float)raw_gyro_z / 131.0f;

    return 0;
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Implement a basic fall detection state machine
void fall_detection(sensor_data_t data) {
    static time_t freefall_start_time = 0;
    static int in_freefall = 0;
    static int in_impact = 0;
    time_t current_time = time(NULL);

    float accel_magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    if (accel_magnitude < FREEFALL_THRESHOLD) {
        if (!in_freefall) {
            freefall_start_time = current_time;
            in_freefall = 1;
        }
    } else {
        in_freefall = 0;
    }

    if (in_freefall && (current_time - freefall_start_time) <= TIME_WINDOW) {
        if (accel_magnitude > IMPACT_THRESHOLD) {
            if (!in_impact) {
                printf("FALL DETECTED: Impact detected!\n");
                fprintf(log_file, "FALL DETECTED: Impact detected!\n");
                fflush(log_file);
                in_impact = 1;
            }
        }
    } else {
        in_impact = 0;
    }
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

