int spi_read_register(uint16_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Set MSB for read operation
    tx_buf[0] = (reg_addr >> 8) & 0xFF;
    tx_buf[1] = reg_addr & 0xFF;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    return (rx_buf[0] << 8) | rx_buf[1];
}

// SPI Write Register Function
int spi_write_register(uint16_t reg_addr, uint16_t data) {
    char tx_buf[2];
    int result;

    // Clear MSB for write operation
    tx_buf[0] = (reg_addr & 0xFF);
    tx_buf[1] = (data & 0xFF);

    result = spiWrite(spi_handle, tx_buf, 2);
    if (result != 2) {
