#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDRESS 0x69

// Gyroscope register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity factor
#define SENSITIVITY 8.75 // mdps/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int result;

    // Check WHO_AM_I register
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (result >= 0 && result == 0xD3) {
            printf("Gyroscope found!\n");
            break;
        } else {
            fprintf(stderr, "Error: Gyroscope not found (WHO_AM_I = 0x%X). Retrying...\n", result);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Gyroscope not found after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (result == 0) {
            printf("CTRL_REG1 configured successfully.\n");
            break;
        } else {
            fprintf(stderr, "Error: Failed to configure CTRL_REG1 (result = %d). Retrying...\n", result);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (+/- 250 dps full-scale range)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result == 0) {
            printf("CTRL_REG4 configured successfully.\n");
            break;
        } else {
            fprintf(stderr, "Error: Failed to configure CTRL_REG4 (result = %d). Retrying...\n", result);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    char buffer[6];
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;
    int result;

    // Read all 6 data bytes in a single block read
    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data (result = %d).\n", result);
        data.x = 0.0; // Set to 0.0 to avoid using uninitialized values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data.x = (float)raw_x / SENSITIVITY;
    data.y = (float)raw_y / SENSITIVITY;
    data.z = (float)raw_z / SENSITIVITY;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    char timestamp[30];

    // Get nanosecond-precision timestamp
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format timestamp
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    // Write data to file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

