#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x53

// Define the register addresses for the sensor data
#define X_LSB 0x28
#define X_MSB 0x29
#define Y_LSB 0x2A
#define Y_MSB 0x2B
#define Z_LSB 0x2C
#define Z_MSB 0x2D

// Global variables for file descriptors and signal handling
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int address);
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char data);
sensor_data_t read_sensor_data(int fd);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, sensor_data_t data);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, unsigned char reg, unsigned char data) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data function
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    unsigned char buffer[6];

    if (i2c_read_bytes(fd, X_LSB, buffer, 6) != 0) {
        data.x = 0; // Indicate error
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_str;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, sensor_data_t data) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SENSOR_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data(i2c_fd);

        // Get timestamp
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, sensor_data) != 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Wait 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Close I2C and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

