#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int log_data(int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a file
int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1; // Indicate an error
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%ld.%03ld, Sensor1: %d, Sensor2: %d\n", ts.tv_sec, milliseconds, sensor1_state, sensor2_state);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

// Function to simulate halting the conveyor
void halt_conveyor() {
    printf("Conveyor halted!\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt safety system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Check for errors during sensor reading
        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensors, skipping logging.\n");
        } else {
            // Log the data
            if (log_data(sensor1_state, sensor2_state) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Check if both sensors are triggered
            if (sensor1_state == 1 && sensor2_state == 1) {
                halt_conveyor();
            }
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

