#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define DATA_RATE_100HZ 0x04
#define ACTIVE_MODE 0x01
#define DATA_REG_X_LSB 0x01
#define DATA_REG_X_MSB 0x02
#define DATA_REG_Y_LSB 0x03
#define DATA_REG_Y_MSB 0x04
#define DATA_REG_Z_LSB 0x05
#define DATA_REG_Z_MSB 0x06
#define FALL_THRESHOLD 45.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int i2c_read_block(int fd, unsigned char reg, char *buf, int len);
int read_accelerometer_data(int fd, short *x, short *y, short *z);
double calculate_tilt_angle(short x, short y, short z);
int log_data(short x, short y, short z);
void signal_handler(int signum);

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_block(int fd, unsigned char reg, char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int fd, short *x, short *y, short *z) {
    char buf[6];
    if (i2c_read_block(fd, DATA_REG_X_LSB, buf, 6) != 0) {
        return -1;
    }

    *x = (short)(((unsigned char)buf[1] << 4) | (buf[0] >> 4));
    *y = (short)(((unsigned char)buf[3] << 4) | (buf[2] >> 4));
    *z = (short)(((unsigned char)buf[5] << 4) | (buf[4] >> 4));

    return 0;
}

// Calculate tilt angle
double calculate_tilt_angle(short x, short y, short z) {
    double angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    return angle;
}

// Log data to file
int log_data(short x, short y, short z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen("fall_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor identity
    unsigned char who_am_i;
    if (i2c_read_block(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        close(i2c_fd);
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VALUE);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8452Q sensor found!\n");

    // Initialize sensor
    if (i2c_write_reg(i2c_fd, CTRL_REG1, (DATA_RATE_100HZ << 5) | ACTIVE_MODE) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return 1;
    }

    short x, y, z;
    double tilt_angle;

    // Main loop
    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            tilt_angle = calculate_tilt_angle(x, y, z);

            if (fabs(tilt_angle) > FALL_THRESHOLD) {
                log_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

