#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x3D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define DATA_RATE_80HZ 0x70
#define HIGH_PERFORMANCE 0x0C
#define CONTINUOUS_CONVERSION 0x00

#define SENSITIVITY 0.146 // mG/LSB
#define THRESHOLD 800.0   // mG

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration offsets
static float x_offset = 0.0;
static float y_offset = 0.0;
static float z_offset = 0.0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int lis3mdl_init(int fd);
int verify_sensor(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer(int fd);
void convert_to_milliGauss(int16_t x, int16_t y, int16_t z, float *x_mG, float *y_mG, float *z_mG);
float calculate_total_magnitude(float x_mG, float y_mG, float z_mG);
void log_data(float x_mG, float y_mG, float z_mG);
void check_threshold(float x_mG, float y_mG, float z_mG);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retrying...\n", reg, value, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X).\n", reg, value);
    return -1; // Indicate failure
}

// Initialize the LIS3MDL sensor
int lis3mdl_init(int fd) {
    // Set CTRL_REG1: Continuous conversion mode, 80 Hz ODR, High-performance mode
    if (i2c_write_reg(fd, CTRL_REG1, DATA_RATE_80HZ | HIGH_PERFORMANCE | CONTINUOUS_CONVERSION) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1.\n");
        return -1;
    }

    // Set CTRL_REG4: High-performance mode
    if (i2c_write_reg(fd, CTRL_REG4, HIGH_PERFORMANCE) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4.\n");
        return -1;
    }

    // Set CTRL_REG3: Continuous conversion mode
    if (i2c_write_reg(fd, CTRL_REG3, CONTINUOUS_CONVERSION) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG3.\n");
        return -1;
    }

    return 0;
}

// Verify the sensor ID
int verify_sensor(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value (0x%02X). Expected 0x%02X.\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }
    printf("WHO_AM_I register value: 0x%02X (OK)\n", who_am_i);
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_l = i2c_read_reg(fd, OUT_X_L);
    int x_h = i2c_read_reg(fd, OUT_X_H);
    int y_l = i2c_read_reg(fd, OUT_Y_L);
    int y_h = i2c_read_reg(fd, OUT_Y_H);
    int z_l = i2c_read_reg(fd, OUT_Z_L);
    int z_h = i2c_read_reg(fd, OUT_Z_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        fprintf(stderr, "Error reading magnetometer data.\n");
        return -1;
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Calibrate the magnetometer
void calibrate_magnetometer(int fd) {
    int16_t x, y, z;
    float x_mG, y_mG, z_mG;
    float sum_x = 0.0, sum_y = 0.0, sum_z = 0.0;
    int num_samples = 100; // Number of samples for calibration

    printf("Calibrating magnetometer...\n");
    for (int i = 0; i < num_samples; i++) {
        if (read_magnetometer_data(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading data during calibration.\n");
            return;
        }
        convert_to_milliGauss(x, y, z, &x_mG, &y_mG, &z_mG);
        sum_x += x_mG;
        sum_y += y_mG;
        sum_z += z_mG;
        usleep(10000); // Small delay between samples
    }

    x_offset = sum_x / num_samples;
    y_offset = sum_y / num_samples;
    z_offset = sum_z / num_samples;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
}

// Convert raw data to milliGauss
void convert_to_milliGauss(int16_t x, int16_t y, int16_t z, float *x_mG, float *y_mG, float *z_mG) {
    *x_mG = (float)x * SENSITIVITY - x_offset;
    *y_mG = (float)y * SENSITIVITY - y_offset;
    *z_mG = (float)z * SENSITIVITY - z_offset;
}

// Calculate the total magnetic field magnitude
float calculate_total_magnitude(float x_mG, float y_mG, float z_mG) {
    return sqrt(x_mG * x_mG + y_mG * y_mG + z_mG * z_mG);
}

// Log data to file
void log_data(float x_mG, float y_mG, float z_mG) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_mG, y_mG, z_mG);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for threshold alert
void check_threshold(float x_mG, float y_mG, float z_mG) {
    float magnitude = calculate_total_magnitude(x_mG, y_mG, z_mG);
    if (magnitude > THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(stderr, "%s - Threshold alert! Total magnitude: %.2f mG\n", timestamp, magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int main() {
    int16_t x, y, z;
    float x_mG, y_mG, z_mG;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    int init_attempts = 0;
    while (init_attempts < 3) {
        if (lis3mdl_init(i2c_fd) == 0) {
            printf("LIS3MDL initialized successfully.\n");
            break;
        } else {
            fprintf(stderr, "LIS3MDL initialization failed. Attempt %d/%d.\n", init_attempts + 1, 3);
            init_attempts++;
            sleep(1); // Wait before retrying
        }
    }
    if (init_attempts == 3) {
        fprintf(stderr, "LIS3MDL initialization failed after multiple attempts.\n");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor verification failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate the sensor
    calibrate_magnetometer(i2c_fd);

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Convert to milliGauss
            convert_to_milliGauss(x, y, z, &x_mG, &y_mG, &z_mG);

            // Log data
            log_data(x_mG, y_mG, z_mG);

            // Check for threshold alert
            check_threshold(x_mG, y_mG, z_mG);
        } else {
            fprintf(stderr, "Error reading magnetometer data in main loop.\n");
        }

        usleep(100000); // 10 Hz sampling rate (100ms delay)
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

