#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_PARTID 0x01
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_XDATA_H 0x09
#define ADXL354B_REG_YDATA_L 0x0B
#define ADXL354B_REG_YDATA_H 0x0C
#define ADXL354B_REG_ZDATA_L 0x0E
#define ADXL354B_REG_ZDATA_H 0x0F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_set_measurement_mode(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx[2], rx[len + 1];
    tx[0] = 0x80 | reg; // Read bit set
    tx[1] = 0x00; // Dummy byte for reading multiple bytes

    for (int i = 0; i < 3; ++i) {
        if (spiXfer(handle, tx, rx, len + 2) == (len + 2)) {
            memcpy(data, rx + 1, len);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retry
        }
    }
    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Write bit clear
    tx[1] = data;

    if (spiXfer(handle, tx, rx, 2) == 2) {
        return 0; // Success
    } else {
        fprintf(stderr, "SPI write error.\n");
        return -1; // Failure
    }
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "ADXL354B reset failed.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Set Measurement Mode Function
int adxl354b_set_measurement_mode(int handle) {
    // Stop measurement
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to stop measurement.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    // Check STABLE bit
    uint8_t status;
    if (spi_read_register(handle, ADXL354B_REG_STATUS, &status, 1) != 0) {
        fprintf(stderr, "Failed to read status.\n");
        return -1;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "STABLE bit not set, measurement not ready.\n");
        return -1;
    }

    // Start measurement
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_data[2], y_data[2], z_data[2];

    if (spi_read_register(handle, ADXL354B_REG_XDATA_L, x_data, 2) != 0) {
        fprintf(stderr, "Failed to read X data.\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_YDATA_L, y_data, 2) != 0) {
        fprintf(stderr, "Failed to read Y data.\n");
        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_L, z_data, 2) != 0) {
        fprintf(stderr, "Failed to read Z data.\n");
        return -1;
    }

    *x = (int16_t)((x_data[1] << 8) | x_data[0]);
    *y = (int16_t)((y_data[1] << 8) | y_data[0]);
    *z = (int16_t)((z_data[1] << 8) | z_data[0]);

    return 0;
}

// Log Data Function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check sensor presence
    uint8_t part_id;
    if (spi_read_register(spi_handle, ADXL354B_REG_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID, sensor may not be present.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X, expected 0x1D\n", part_id);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset ADXL354B
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set measurement mode
    if (adxl354b_set_measurement_mode(spi_handle) != 0) {
        fprintf(stderr, "Failed to set measurement mode.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

