#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip and line numbers
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17

// Define the GPIO line name
#define GPIO_LINE_NAME "gpio17"

// Global variables for signal handling
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed, exiting...\n");
        keep_running = 0;
    }
}

// Function to get the current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log messages with timestamps
void log_message(const char *message)
{
    char timestamp[20];
    get_timestamp(timestamp);
    printf("[%s] %s\n", timestamp, message);
}

// Function to read the sensor value
int read_sensor()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_message("Error reading sensor value");
        return -1; // Indicate an error
    }
    return value;
}

// Function to simulate self-parking
void self_park()
{
    char timestamp[20];
    get_timestamp(timestamp);
    log_message("Self-parking sequence started");

    // Simulate parking actions
    for (int i = 0; i < 5; i++) {
        get_timestamp(timestamp);
        printf("[%s] Parking action %d\n", timestamp, i + 1);
        sleep(1); // Simulate time for each action
    }

    get_timestamp(timestamp);
    log_message("Self-parking sequence completed");
}

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line as an input
    if (gpiod_line_request_input(line, "self_parking_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) {
            // Obstacle detected (LOW signal)
            self_park();
        } else if (sensor_value > 0) {
            // No obstacle detected (HIGH signal)
        } else {
            // Error reading sensor
            log_message("Error reading sensor, retrying...");
        }

        sleep(1); // Poll every 1 second
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

