#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 11
#define GPIO27 13

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line27;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to get the current timestamp
char* get_timestamp();

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value);

// Function to log sensor data
void log_data(int sensor1_value, int sensor2_value);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for sensor 1 and sensor 2
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        perror("Error getting GPIO line 27");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as input
    if (gpiod_line_request_input(line17, "sensor1") < 0) {
        perror("Error requesting GPIO line 17 as input");
        gpiod_line_release(line27);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line27, "sensor2") < 0) {
        perror("Error requesting GPIO line 27 as input");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    int sensor1_value, sensor2_value;

    // Main loop
    while (1) {
        // Read sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            // Log sensor data
