#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define MSC_CTRL_REG 0x24
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08
#define SCALE_FACTOR 0.02 // deg/sec/LSB

// Global variables
int spi_handle;
int cs_gpio;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int channel, int speed);
int gpio_init(int pin);
int adis16266_write_register(int handle, uint8_t reg, uint16_t value);
int adis16266_read_register(int handle, uint8_t reg, uint16_t *value);
int adis16266_enable_data_ready_mode(int handle);
int adis16266_read_gyro_data(int handle, float *x_rate, float *y_rate, float *z_rate);
void signal_handler(int signal);

// SPI initialization function
int spi_init(int channel, int speed) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", channel, 0);

    int handle = spiOpen(spi_device, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// GPIO initialization function
int gpio_init(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    return 0;
}

// ADIS16266 write register function
int adis16266_write_register(int handle, uint8_t reg, uint16_t value) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = (reg << 1) | 0x80; // Set MSB for write
    tx_buf[1] = (value >> 8) & 0xFF; // MSB of value
    tx_buf[2] = value & 0xFF;        // LSB of value

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// ADIS16266 read register function
int adis16266_read_register(int handle, uint8_t reg, uint16_t *value) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = (reg << 1) & 0x7F; // Clear MSB for read
    tx_buf[1] = 0x00; // Dummy byte for reading
    tx_buf[2] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];
    return 0;
}

// ADIS16266 enable data ready mode function
int adis16266_enable_data_ready_mode(int handle) {
    return adis16266_write_register(handle, MSC_CTRL_REG, 0x0004); // Enable Data Ready Mode
}

// ADIS16266 read gyro data function
int adis16266_read_gyro_data(int handle, float *x_rate, float *y_rate, float *z_rate) {
    uint16_t raw_x, raw_y, raw_z;

    if (adis16266_read_register(handle, X_RATE_REG, &raw_x) != 0) return -1;
    if (adis16266_read_register(handle, Y_RATE_REG, &raw_y) != 0) return -1;
    if (adis16266_read_register(handle, Z_RATE_REG, &raw_z) != 0) return -1;

    *x_rate = (float)((int16_t)raw_x) * SCALE_FACTOR;
    *y_rate = (float)((int16_t)raw_y) * SCALE_FACTOR;
    *z_rate = (float)((int16_t)raw_z) * SCALE_FACTOR;

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_handle = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize CS GPIO
    cs_gpio = gpio_init(CS_PIN);
    if (cs_gpio < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Enable data ready mode
    if (adis16266_enable_data_ready_mode(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        if (adis16266_read_gyro_data(spi_handle, &x_rate, &y_rate, &z_rate) == 0) {
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

