// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int handle, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z)
{
    char buffer[12];
    int result = i2cReadI2CBlockData(handle, OUTX_L_G, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

// Function to convert raw data to physical units
void convert_to_physical_units(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, int16_t accel_x_raw, int16_t accel_y_raw, int16_t accel_z_raw,
                               float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z)
{
    *gyro_x = gyro_x_raw * GYRO_SENSITIVITY;
    *gyro_y = gyro_y_raw * GYRO_SENSITIVITY;
    *gyro_z = gyro_z_raw * GYRO_SENSITIVITY;
    *accel_x = accel_x_raw * ACCEL_SENSITIVITY;
    *accel_y = accel_y_raw * ACCEL_SENSITIVITY;
    *accel_z = accel_z_raw * ACCEL_SENSITIVITY;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_handle, WHO_AM_I);
    if (who_am_i != LSM6DSR_ADDR) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", LSM6DSR_ADDR, who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer and gyroscope
    if (write_register(i2c_handle, CTRL1_XL, 0x42) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle, CTRL2_G, 0x42) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_sensor_data(i2c_handle, &gyro_x_raw, &gyro_y_raw, &gyro_z_raw, &accel_x_raw, &accel_y_raw, &accel_z_raw) == 0) {
            convert_to_physical_units(gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw,
                                      &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);

            printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps  |  Accel: X=%.2f mg, Y=%.2f mg, Z=%.2f mg\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

