    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    // Set data format to +/- 2g and full resolution
    if (i2c_write_byte(fd, 0x31, 0x0B) < 0) {
        fprintf(stderr, "Failed to set data format\n");
        return -1;
    }

    // Set power control register to measure mode
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to set power control register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_byte(fd, ADXL345_REG_DATAX0);
    x1 = i2c_read_byte(fd, ADXL345_REG_DATAX1);
    y0 = i2c_read_byte(fd, ADXL345_REG_DATAY0);
    y1 = i2c_read_byte(fd, ADXL345_REG_DATAY1);
    z0 = i2c_read_byte(fd, ADXL345_REG_DATAZ0);
    z1 = i2c_read_byte(fd, ADXL345_REG_DATAZ1);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0;
}

// Calculate tilt angles function
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    float x_f = (float)x;
    float y_f = (float)y;
    float z_f = (float)z;

    *roll = atan2(y_f, z_f) * 180 / M_PI;
    *pitch = atan2(-x_f, sqrt(y_f * y_f + z_f * z_f)) * 180 / M_PI;
}

// Log event function
void log_event(float roll, float pitch) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Roll: %.2f, Pitch: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            roll, pitch);

    fclose(fp);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int16_t x, y, z;
    float roll, pitch;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized successfully\n");

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt angles
            calculate_tilt_angles(x, y, z, &roll, &pitch);

            // Log event if tilt threshold exceeded
            if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
                log_event(roll, pitch);
                printf("Tilt event logged: Roll=%.2f, Pitch=%.2f\n", roll, pitch);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data, retrying...\n");
        }

        // Delay for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

