#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_SEC 5
#define PAUSE_DURATION_SEC 1

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int validate_threshold(int threshold) {
    if (threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t start_time, current_time;
    struct tm *time_info;
    char timestamp[20];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    // Validate threshold
    if (*endptr != '\0' || !validate_threshold(threshold)) {
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring sound levels... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Reset high count and start time for each window
        high_count = 0;
        time(&start_time);

        // Sample GPIO pin for 5 seconds
        while (time(NULL) - start_time < WINDOW_DURATION_SEC) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
        }

        // Get current time for timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print status or alert
        if (high_count >= threshold) {
            printf("%s ALERT: High noise level detected (%d readings)\n", timestamp, high_count);
        } else {
            printf("%s Normal noise level (%d readings)\n", timestamp, high_count);
        }

        // Pause for 1 second
        gpioDelay(PAUSE_DURATION_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

