#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for door locks
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int generate_random_code(unsigned long *code);
int validate_code(const char *input, unsigned long code);
int unlock_door(int door);
int log_access(unsigned long code);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line for Door A
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        perror("Error getting GPIO line for Door A");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for Door B
    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        perror("Error getting GPIO line for Door B");
        gpiod_line_release(door_a_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(door_a_line, "door_access", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for Door A as output");
        gpiod_line_release(door_b_line);
        gpiod_line_release(door_a_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(door_b_line, "door_access", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for Door B as output");
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a random 6-digit security code
int generate_random_code(unsigned long *code) {
    *code = (rand() % 900000) + 100000; // Generates a number between 100000 and 999999
    return 0;
}

// Validate the user's input against the generated code
int validate_code(const char *input, unsigned long code) {
    if (strlen(input) != 6 || input[0] != '1' || input[1] != '0' || input[2] != '0' || input[3] != '0' || input[4] != '0' || input[5] != '0') {
        return -1; // Invalid input format
    }

    unsigned long input_code = atoi(input);
    if (input_code != code) {
        return -1; // Incorrect code
    }

    return 0; // Correct code
}

// Unlock the specified door for 5 seconds
int unlock_door(int door) {
    int ret;
    struct gpiod_line *line = (door == DOOR_A_PIN) ? door_a_line : door_b_line;

    ret = gpiod_line_set_value(line, 1); // Set GPIO HIGH to unlock
    if (ret < 0) {
        perror("Error setting GPIO value to unlock");
        return -1;
    }

    sleep(5); // Keep the door unlocked for 5 seconds

    ret = gpiod_line_set_value(line, 0); // Set GPIO LOW to re-lock
    if (ret < 0) {
        perror("Error setting GPIO value to re-lock");
        return -1;
    }

    return 0;
}

// Log the access event to a file
int log_access(unsigned long code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%lu\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup(void) {
    int ret;

    // Set both GPIOs to LOW (locked)
    ret = gpiod_line_set_value(door_a_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO value to locked");
    }
    ret = gpiod_line_set_value(door_b_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO value to locked");
    }

    // Release GPIO lines
    if (door_a_line) {
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_release(door_b_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    unsigned long security_code;
    char input_code[7]; // Buffer to hold user input (6 digits + null terminator)
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize random number generator
    srand(time(NULL));

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Generate initial security code
    if (generate_random_code(&security_code) < 0) {
        fprintf(stderr, "Failed to generate random security code. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Security code: %lu\n", security_code);

    // Main loop
    while (!terminate) {
        printf("Enter security code (6 digits): ");
        if (fgets(input_code, sizeof(input_code), stdin) == NULL) {
            perror("Error reading input");
            break; // Exit loop on error
        }

        // Remove trailing newline character
        input_code[strcspn(input_code, "\n")] = 0;

        // Validate the input
        ret = validate_code(input_code, security_code);
        if (ret == 0) {
            printf("Access granted!\n");
            if (unlock_door(DOOR_A_PIN) < 0) {
                fprintf(stderr, "Failed to unlock Door A.\n");
            }
            if (unlock_door(DOOR_B_PIN) < 0) {
                fprintf(stderr, "Failed to unlock Door B.\n");
            }
            if (log_access(security_code) < 0) {
                fprintf(stderr, "Failed to log access.\n");
            }
            if (generate_random_code(&security_code) < 0) {
                fprintf(stderr, "Failed to generate new random code.\n");
            }
            printf("New security code: %lu\n", security_code);
        } else if (ret == -1) {
            fprintf(stderr, "Access denied. Invalid code format.\n");
        } else {
            fprintf(stderr, "Access denied. Incorrect code.\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

