    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("BH1750 Light Sensor Reader\n");

    while (1) {
        unsigned char data[2];
        unsigned int raw_value;
        float lux;

        // Write the One-Time High-Resolution Mode 2 command
        if (write_bh1750(i2c_fd, CONTINUOUS_HIGH_RES_MODE_2) != 0) {
            fprintf(stderr, "Failed to write mode command. Retrying in %d seconds.\n", READ_DELAY_SEC);
            sleep(READ_DELAY_SEC);
            continue;
        }

        // Wait for the maximum conversion time
        usleep(MAX_CONVERSION_TIME * 1000); // Convert ms to microseconds

        // Read 2 bytes of data
        if (read_bh1750(i2c_fd, data, 2) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_DELAY_SEC);
            sleep(READ_DELAY_SEC);
            continue;
        }

        // Combine the two bytes into a 16-bit unsigned integer
        raw_value = (data[0] << 8) | data[1];

