        lux = calculate_lux(raw_value);

        // Log the reading to the file
        if (log_reading(lux) != 0) {
            fprintf(stderr, "Failed to log reading. \n");
        }

        printf("Lux: %.2f\n", lux);

        // Wait for 5 seconds
        sleep(READ_DELAY_SEC);
    }

    // The program should never reach here due to the infinite loop,
    // but it's good practice to close the I2C bus if it does.
    close(i2c_fd);
    return 0;
}

