#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define SERVER_PORT 12345
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define SECRET_KEY "MySecretKey"
#define PLAYBACK_DURATION 5 // seconds
#define SAMPLE_RATE 20       // milliseconds
#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
int server_socket = -1;
FILE *log_file = NULL;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *touch_data);
float calculate_frequency(unsigned short touch_data[], int num_electrodes);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (server_socket != -1) {
        close(server_socket);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    // Set operation mode to run
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set operation mode\n");
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Calculate frequency based on touch data
float calculate_frequency(unsigned short touch_data[], int num_electrodes) {
    unsigned short max_value = 0;
    for (int i = 0; i < num_electrodes; i++) {
        if (touch_data[i] > max_value) {
            max_value = touch_data[i];
        }
    }

    // Logarithmic mapping
    float frequency = 220.0 + 660.0 * log10(1.0 + (float)max_value / 4095.0); // Assuming 12-bit ADC
    if (frequency < 220.0) frequency = 220.0;
    if (frequency > 880.0) frequency = 880.0;

    return frequency;
}

// Play tone using hardware PWM
void play_tone(float frequency) {
    int range = 1000; // PWM range
    int duty_cycle = (int)(range * 0.5); // 50% duty cycle

    // Calculate PWM frequency (approximately)
    float pwm_frequency = (float)gpioGetPWMfrequency(PWM_GPIO);
    if (pwm_frequency == 0) {
        fprintf(stderr, "Error: Could not get PWM frequency\n");
        return;
    }

    // Calculate the period in microseconds
    float period_us = 1000000.0 / pwm_frequency;

    // Calculate the on and off times in microseconds
    float on_time_us = period_us * duty_cycle / range;
    float off_time_us = period_us - on_time_us;

    // Convert to microseconds
    int on_time_us_int = (int)on_time_us;
    int off_time_us_int = (int)off_time_us;

    gpioPWM(PWM_GPIO, duty_cycle); // Set duty cycle
    gpioDelay(on_time_us_int);     // On time
    gpioDelay(off_time_us_int);    // Off time
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    // Receive data from client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';

    // Check for MOTION_DETECTED prefix
    if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
        // Extract the secret key
        char *secret_key_start = strstr(buffer, MOTION_DETECTED_PREFIX) + strlen(MOTION_DETECTED_PREFIX);
        char *secret_key_end = strchr(secret_key_start, ':');
        if (secret_key_end != NULL) {
            *secret_key_end = '\0'; // Null-terminate the string
            if (strcmp(secret_key_start, SECRET_KEY) == 0) {
                printf("Motion detected and secret key verified!\n");

                // Open log file
                log_file = fopen("frequency_log.txt", "a");
                if (log_file == NULL) {
                    perror("Error opening log file");
                    close(client_socket);
                    return;
                }

                // Play tones for 5 seconds
                unsigned short touch_data[NUM_ELECTRODES];
                float frequency;
                struct timespec start_time, current_time;
                clock_gettime(CLOCK_MONOTONIC, &start_time);

                while (1) {
                    if (read_touch_data(touch_data) == 0) {
                        frequency = calculate_frequency(touch_data, NUM_ELECTRODES);
                        play_tone(frequency);
                        log_frequency(frequency);
                    } else {
                        fprintf(stderr, "Error reading touch data during playback\n");
                        break;
                    }

                    clock_gettime(CLOCK_MONOTONIC, &current_time);
                    double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                                         (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

                    if (elapsed_time >= PLAYBACK_DURATION) {
                        break;
                    }

                    gpioDelay(SAMPLE_RATE); // Sample every 20ms
                }

                // Close log file
                fclose(log_file);
                log_file = NULL;
            } else {
                fprintf(stderr, "Error: Invalid secret key\n");
            }
        } else {
            fprintf(stderr, "Error: Secret key not found\n");
        }
    } else {
        printf("Received: %s\n", buffer);
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(PWM_GPIO, 1000);    // Set PWM range

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", SERVER_PORT);

    // Accept connections and handle clients
    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_socket);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

