#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define GPIO_LED 17
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(void);
int init_gpio(void);
int init_pwm(void);
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t z);
int set_led_brightness(float magnitude);
void signal_handler(int sig);
void cleanup(void);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int lsm303_address;
    int gpio_pin;
    int pwm_frequency;
    int sample_interval_ms;
} config_t;

config_t config = {
    .i2c_bus = 1,
    .lsm303_address = LSM303_ADDR,
    .gpio_pin = GPIO_LED,
    .pwm_frequency = PWM_FREQUENCY,
    .sample_interval_ms = SAMPLE_INTERVAL_MS
};

int main(void) {
    int16_t x, y, z;
    float magnitude;
    struct timeval tv;
    struct tm *tm_info;
