    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        syslog(LOG_ERR, "Failed to initialize I2C. Exiting.");
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO. Exiting.");
        cleanup();
        closelog();
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        syslog(LOG_ERR, "Failed to initialize PWM. Exiting.");
        cleanup();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Magnetometer and LED control started.");

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(z);

            // Set LED brightness
            if (set_led_brightness(magnitude) != 0) {
                syslog(LOG_ERR, "Failed to set LED brightness.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read magnetometer data.");
        }

        // Sleep for the specified interval
        usleep(config.sample_interval_ms * 1000); // Convert ms to us
    }

    // Cleanup and exit
    syslog(LOG_INFO, "Magnetometer and LED control stopped.");
    cleanup();
    closelog();
    return 0;
}

// Initialize I2C
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, config.lsm303_address) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Initialize magnetometer (set continuous conversion mode)
    uint8_t init_data[2] = {CTRL_REG1_M, 0x20}; // 0x20 for 10 Hz
    if (write(i2c_fd, init_data, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to CTRL_REG1_M: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(config.gpio_pin, PI_OUTPUT);
    gpioSetPWMfrequency(config.gpio_pin, config.pwm_frequency);
    gpioSetPWMrange(config.gpio_pin, 100); // Set range for percentage (0-100)

    return 0;
}

// Initialize PWM
int init_pwm(void) {
    // No specific initialization needed beyond GPIO setup in this example.
    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    uint8_t reg = OUT_X_L_M;

    if (write(i2c_fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write register address: %s", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        syslog(LOG_ERR, "Failed to read magnetometer data: %s", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of Z-axis field
float calculate_magnitude(int16_t z) {
    return (float)z;
}

// Set LED brightness using PWM
int set_led_brightness(float magnitude) {
    // Map magnitude to PWM duty cycle (0-100)
    int duty_cycle = (int)(magnitude / 2.0); // Assuming max magnitude is 2G
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(config.gpio_pin, duty_cycle);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    gpioPWM(config.gpio_pin, 0); // Turn off LED
    gpioTerminate();
}

