#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offset buffers
int16_t x_offset_buffer[100];
int16_t y_offset_buffer[100];
int16_t z_offset_buffer[100];
int offset_index = 0;

// Function prototypes
int hmc5883l_write_register(int handle, uint8_t reg, uint8_t value);
int hmc5883l_read_register(int handle, uint8_t reg);
int16_t hmc5883l_read_data(int handle, uint8_t reg_msb);
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z);
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t *offset_x, int16_t *offset_y, int16_t *offset_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to write a byte to an HMC5883L register
int hmc5883l_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from an HMC5883L register
int hmc5883l_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to read magnetometer data (X, Y, Z)
int16_t hmc5883l_read_data(int handle, uint8_t reg_msb) {
    int msb = i2cReadByteData(handle, reg_msb);
    int lsb = i2cReadByteData(handle, reg_msb + 1);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return 0; // Return 0 on error
    }

    return (int16_t)((msb << 8) | lsb);
}

// Function to update hard-iron offset buffers
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z) {
    x_offset_buffer[offset_index] = x;
    y_offset_buffer[offset_index] = y;
    z_offset_buffer[offset_index] = z;

    offset_index = (offset_index + 1) % 100;
}

// Function to apply hard-iron offsets to raw data
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t *offset_x, int16_t *offset_y, int16_t *offset_z) {
    *x = x - x_offset_buffer[0];
    *y = y - y_offset_buffer[0];
    *z = z - z_offset_buffer[0];
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (hmc5883l_write_register(i2c_handle, HMC5883L_CONFIG_A, 0x70) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (hmc5883l_write_register(i2c_handle, HMC5883L_CONFIG_B, 0x20) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (hmc5883l_write_register(i2c_handle, HMC5883L_MODE, 0x00) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw magnetometer data
        int16_t x = hmc5883l_read_data(i2c_handle, HMC5883L_DATA_X_MSB);
        int16_t y = hmc5883l_read_data(i2c_handle, HMC5883L_DATA_Y_MSB);
        int16_t z = hmc5883l_read_data(i2c_handle, HMC5883L_DATA_Z_MSB);

        // Update hard-iron offset buffers
        update_hard_iron_offsets(x, y, z);

        // Apply hard-iron offsets
        int16_t offset_x, offset_y, offset_z;
        apply_hard_iron_offsets(x, y, z, &offset_x, &offset_y, &offset_z);

        // Print offset-corrected values
        printf("X: %d, Y: %d, Z: %d\n", offset_x, offset_y, offset_z);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

