#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define OUT_X_L_A 0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static acceleration_data_t acceleration_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte_data(int fd, uint8_t reg);
int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value);
int i2c_read_block_data(int fd, uint8_t reg, uint8_t len, uint8_t *data);
int lsm303d_init(int fd);
acceleration_data_t read_acceleration_data(int fd);
void interrupt_handler(int signum);
void signal_handler(int signum);
void print_buffer_data();

// I2C read byte data function
int i2c_read_byte_data(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading byte data from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write byte data function
int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing byte data to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block data function
int i2c_read_block_data(int fd, uint8_t reg, uint8_t len, uint8_t *data) {
    int result = i2c_smbus_read_i2c_block_data(fd, reg, len, data);
    if (result < 0) {
        fprintf(stderr, "Error reading block data from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// LSM303D initialization function
int lsm303d_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte_data(fd, WHO_AM_I);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (50 Hz ODR, all axes enabled)
    if (i2c_write_byte_data(fd, CTRL_REG1, 0x57) < 0) {
        return -1;
    }

    // Configure CTRL_REG4 (full-scale +-2g)
    if (i2c_write_byte_data(fd, CTRL_REG4, 0x00) < 0) {
        return -1;
    }

    // Configure INT1_CFG (threshold interrupt on any-axis-high event)
    if (i2c_write_byte_data(fd, INT1_CFG, 0x2A) < 0) {
        return -1;
    }

    return 0;
}

// Read acceleration data function
acceleration_data_t read_acceleration_data(int fd) {
    acceleration_data_t data;
    uint8_t buffer[6];

    if (i2c_read_block_data(fd, OUT_X_L_A | 0x80, 6, buffer) < 0) {
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Interrupt handler function
void interrupt_handler(int signum) {
    print_buffer_data();
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// Print buffer data function
void print_buffer_data() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Interrupt triggered at: %s\n", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE; // Ensure positive index
        printf("Sample %d: X=%d, Y=%d, Z=%d\n", i + 1, acceleration_buffer[index].x, acceleration_buffer[index].y, acceleration_buffer[index].z);
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize LSM303D
    if (lsm303d_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing LSM303D\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "lsm303d_mon";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read acceleration data
        acceleration_data_t data = read_acceleration_data(i2c_fd);

        // Store data in circular buffer
        acceleration_buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Poll GPIO line for interrupt
        int value = gpiod_line_get_value(gpio_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        } else if (value == 1) {
            // Interrupt occurred
            interrupt_handler(SIGINT);
        }

        // Delay for approximately 10 ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10000000; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Disable accelerometer (set CTRL_REG1 to 0x00)
    i2c_write_byte_data(i2c_fd, CTRL_REG1, 0x00);

    // Close I2C device
    close(i2c_fd);

    // Release GPIO resources
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

