#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;

    // De-energize both solenoids
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure both solenoids are initially de-energized
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    fprintf(stderr, "Solenoid control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Energize solenoid 1
        gpioWrite(SOLENOID_1_PIN, 1);
        gpioWrite(SOLENOID_2_PIN, 0);
        fprintf(stderr, "Solenoid 1 energized\n");
        gpioDelay(500000); // 500 ms

        // De-energize solenoid 1 and energize solenoid 2
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 1);
        fprintf(stderr, "Solenoid 2 energized\n");
        gpioDelay(500000); // 500 ms

        // De-energize solenoid 2
        gpioWrite(SOLENOID_2_PIN, 0);
        fprintf(stderr, "Solenoid 2 de-energized\n");
        gpioDelay(500000); // 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return 0;
}

