int open_uart(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios options;
    tcgetattr(fd, &options);
    options.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    options.c_iflag = IGNPAR;                           // Ignore parity errors
    options.c_oflag = 0;
    options.c_lflag = 0; // Non-canonical mode
