#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define strike duration (in milliseconds)
#define STRIKE_DURATION 1000

// Define failsafe timeout (in milliseconds)
#define FAILSAFE_TIMEOUT 10000

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_pir_sensor(void);
int control_relay(int state);
int check_failsafe(void);
void log_event(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, shutting down...");
        terminate = 1;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s: %s", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR sensor line %d: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR sensor line as input
    ret = gpiod_line_request(pir_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR sensor line %d as input: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line %d: %s", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request relay line as output
    ret = gpiod_line_request(relay_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request relay line %d as output: %s", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    log_event("GPIO initialized successfully.");
    return 0;
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay state to %d: %s", state, strerror(errno));
        return -1;
    }
    return 0;
}

// Check for failsafe condition
int check_failsafe(void) {
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            return -1; // Propagate error
        }

        if (pir_value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            long elapsed_ns = (current.tv_sec - start.tv_sec) * 1000000000L + (current.tv_nsec - start.tv_nsec);
            if (elapsed_ns >= FAILSAFE_TIMEOUT * 1000000) {
                log_event("Failsafe triggered: PIR sensor HIGH for too long.");
                return -2; // Failsafe triggered
            }
        } else {
            clock_gettime(CLOCK_MONOTONIC, &start);
        }

        usleep(50000); // Check every 50ms
    }
}

// Log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main(void) {
    int pir_value;
    int relay_state = 0; // 0 = LOW, 1 = HIGH
    struct timespec strike_duration;
    struct timespec current_time, start_time;
    long elapsed_ns;

    // Open syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Door strike system started.");

    // Main loop
    while (!terminate) {
        pir_value = read_pir_sensor();
        if (pir_value < 0) {
            break; // Exit loop on error
        }

        if (pir_value == 1) {
            log_event("Motion detected!");

            // Energize relay
            if (control_relay(1) == 0) {
                relay_state = 1;
                log_event("Relay energized (HIGH).");
            } else {
                break; // Exit loop on error
            }

            // Start strike duration timer
            clock_gettime(CLOCK_MONOTONIC, &start_time);

            // Wait for strike duration or motion to stop
            while (1) {
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - start_time.tv_nsec);
                if (elapsed_ns >= STRIKE_DURATION * 1000000) {
                    break; // Strike duration elapsed
                }

                pir_value = read_pir_sensor();
                if (pir_value < 0) {
                    break; // Exit loop on error
                }

                if (pir_value == 0) {
                    log_event("Motion stopped during strike duration.");
                    break; // Motion stopped
                }

                usleep(50000); // Check every 50ms
            }

            // De-energize relay
            if (control_relay(0) == 0) {
                relay_state = 0;
                log_event("Relay de-energized (LOW).");
            } else {
                break; // Exit loop on error
            }

            // Check for failsafe condition
            if (check_failsafe() == -2) {
                break; // Failsafe triggered
            }
        } else {
            usleep(50000); // Check every 50ms
        }
    }

    // Clean up GPIO
    log_event("Cleaning up GPIO...");
    if (relay_line) {
        control_relay(0); // Ensure relay is LOW before releasing
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_event("Door strike system stopped.");
    closelog();

    return EXIT_SUCCESS;
}

