    return 0;
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay state to %d: %s", state, strerror(errno));
        return -1;
    }
    return 0;
}

// Check for failsafe condition
int check_failsafe(void) {
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            return -1; // Propagate error
        }

        if (pir_value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            long elapsed_ns = (current.tv_sec - start.tv_sec) * 1000000000L + (current.tv_nsec - start.tv_nsec);
            if (elapsed_ns >= FAILSAFE_TIMEOUT * 1000000) {
                log_event("Failsafe triggered: PIR sensor HIGH for too long.");
                return -2; // Failsafe triggered
            }
        } else {
            clock_gettime(CLOCK_MONOTONIC, &start);
        }

        usleep(50000); // Check every 50ms
    }
}

// Log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main(void) {
    int pir_value;
    int relay_state = 0; // 0 = LOW, 1 = HIGH
    struct timespec strike_duration;
    struct timespec current_time, start_time;
    long elapsed_ns;

    // Open syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Door strike system started.");

    // Main loop
    while (!terminate) {
        pir_value = read_pir_sensor();
        if (pir_value < 0) {
            break; // Exit loop on error
        }

        if (pir_value == 1) {
            log_event("Motion detected!");

            // Energize relay
            if (control_relay(1) == 0) {
                relay_state = 1;
                log_event("Relay energized (HIGH).");
            } else {
                break; // Exit loop on error
            }

            // Start strike duration timer
            clock_gettime(CLOCK_MONOTONIC, &start_time);

            // Wait for strike duration or motion to stop
            while (1) {
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - start_time.tv_nsec);
                if (elapsed_ns >= STRIKE_DURATION * 1000000) {
                    break; // Strike duration elapsed
                }

                pir_value = read_pir_sensor();
                if (pir_value < 0) {
                    break; // Exit loop on error
                }

                if (pir_value == 0) {
                    log_event("Motion stopped during strike duration.");
                    break; // Motion stopped
                }

                usleep(50000); // Check every 50ms
            }

            // De-energize relay
            if (control_relay(0) == 0) {
                relay_state = 0;
                log_event("Relay de-energized (LOW).");
            } else {
                break; // Exit loop on error
            }

            // Check for failsafe condition
            if (check_failsafe() == -2) {
                break; // Failsafe triggered
            }
        } else {
            usleep(50000); // Check every 50ms
        }
    }

    // Clean up GPIO
    log_event("Cleaning up GPIO...");
    if (relay_line) {
        control_relay(0); // Ensure relay is LOW before releasing
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_event("Door strike system stopped.");
    closelog();

    return EXIT_SUCCESS;
}

