#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the duration for which each relay is activated (in seconds)
#define RELAY_DURATION 300

// Define the duration for the pause between relay activations (in seconds)
#define PAUSE_DURATION 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;
int current_relay = 1;
int current_action = 0; // 0: activation, 1: deactivation, 2: pause
time_t last_timer_fire = 0;

// Function prototypes
void signal_handler(int signal);
void timer_callback(void *userdata);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_event(int relay_pin, int state, const char *action);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
        program_running = 0;
    }
}

// Timer callback function
void timer_callback(void *userdata) {
    time_t now = time(NULL);
    if (difftime(now, last_timer_fire) >= TIMER_INTERVAL) {
        last_timer_fire = now;

        switch (current_action) {
            case 0: // Activation
                activate_relay(current_relay);
                current_action = 1; // Deactivation
                break;
            case 1: // Deactivation
                deactivate_relay(current_relay);
                current_action = 2; // Pause
                break;
            case 2: // Pause
                // Do nothing, just wait for the next timer event
                break;
        }

        current_relay = (current_relay % NUM_RELAYS) + 1; // Move to the next relay
    }
}

// Function to activate a relay
void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) { // Active-LOW
        syslog(LOG_ERR, "Failed to activate relay on pin %d", relay_pin);
        perror("gpioWrite");
    } else {
        log_event(relay_pin, 0, "activate");
    }
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) { // Active-LOW
        syslog(LOG_ERR, "Failed to deactivate relay on pin %d", relay_pin);
        perror("gpioWrite");
    } else {
        log_event(relay_pin, 1, "deactivate");
    }
}

// Function to log events to syslog
void log_event(int relay_pin, int state, const char *action) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    syslog(LOG_INFO, "%s - Relay %d: %s (State: %s)", buf, relay_pin, action, state ? "HIGH" : "LOW");
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        perror("gpioInitialise");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for pin %d", RELAY1_PIN);
        perror("gpioSetMode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for pin %d", RELAY2_PIN);
        perror("gpioSetMode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for pin %d", RELAY3_PIN);
        perror("gpioSetMode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set mode for pin %d", RELAY4_PIN);
        perror("gpioSetMode");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        perror("gpioSetTimerFuncEx");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up
    syslog(LOG_INFO, "Cleaning up...");
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    gpioTerminate();
    closelog();

    return 0;
}

