#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pthread.h>
#include <stdint.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Circular Buffer Structure
#define BUFFER_SIZE 100
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
int i2c_fd;
CircularBuffer accel_buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_i2c(int address);
int init_mpu6050();
int read_accel_data(float *x, float *y, float *z);
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z);
float get_latest_data(CircularBuffer *buffer, int axis);
int create_circular_buffer(CircularBuffer *buffer);
int write_latest_data_to_file(float x, float y, float z);
void signal_handler(int signum);
void *timer_handler(void *arg);

// I2C Initialization
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU6050 Initialization
int init_mpu6050() {
    // Wake up the MPU6050
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_smbus_write_byte_data(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Read Acceleration Data
int read_accel_data(float *x, float *y, float *z) {
    char data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    int16_t raw_x = (data[0] << 8) | data[1];
    int16_t raw_y = (data[2] << 8) | data[3];
    int16_t raw_z = (data[4] << 8) | data[5];

    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Create Circular Buffer
int create_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    return 0;
}

// Add Data to Circular Buffer
void add_to_buffer(CircularBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get Latest Data from Circular Buffer
float get_latest_data(CircularBuffer *buffer, int axis) {
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    if (axis == 0) {
        return buffer->x[index];
    } else if (axis == 1) {
        return buffer->y[index];
    } else {
        return buffer->z[index];
    }
}

// Write Latest Data to File
int write_latest_data_to_file(float x, float y, float z) {
    FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    fprintf(fp, "X: %.3f, Y: %.3f, Z: %.3f\n", x, y, z);
    fclose(fp);
    return 0;
}

// Signal Handler
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

// Timer Handler (Simulated with nanosleep)
void *timer_handler(void *arg) {
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = 10000000; // 10 ms (100 Hz)

    while (program_running) {
        float x, y, z;
        if (read_accel_data(&x, &y, &z) == 0) {
            add_to_buffer(&accel_buffer, x, y, z);
            if (write_latest_data_to_file(x, y, z) != 0) {
                fprintf(stderr, "Error writing to file in timer handler\n");
            }
        } else {
            fprintf(stderr, "Error reading data in timer handler\n");
        }

        nanosleep(&req, &rem);
    }
    return NULL;
}

int main() {
    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Create Circular Buffer
    create_circular_buffer(&accel_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create timer thread (simulated in main loop)
    pthread_t timer_thread;
    if (pthread_create(&timer_thread, NULL, timer_handler, NULL) != 0) {
        perror("Error creating timer thread");
        close(i2c_fd);
        return 1;
    }

    // Main loop (wait for signal)
    while (program_running) {
        sleep(1);
    }

    // Clean up
    pthread_join(timer_thread, NULL);
    close(i2c_fd);

    // Create sysfs directory if it doesn't exist
    if (mkdir("/sys/kernel/mpu6050_accel", 0755) == -1) {
        if (errno != EEXIST) {
            perror("Error creating sysfs directory");
        }
    }

    // Create latest file and write initial values (0,0,0)
    FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (fp != NULL) {
        fprintf(fp, "X: 0.000, Y: 0.000, Z: 0.000\n");
        fclose(fp);
    } else {
        perror("Error creating latest file");
    }

    printf("Program finished.\n");
    return 0;
}

