#define GPIO_25 25

// Define prime intervals (in seconds)
#define INTERVAL_2 2
#define INTERVAL_3 3
#define INTERVAL_5 5
#define INTERVAL_7 7

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_23, *line_24, *line_25;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void toggle_relay(int gpio_pin);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, cleaning up and exiting...\n", sig);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);
    line_25 = gpiod_chip_get_line(chip, GPIO_25);

    if (!line_18 || !line_23 || !line_24 || !line_25) {
        perror("Error requesting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request lines for output
    if (gpiod_line_request_output(line_18, "smart_lighting", 0) < 0) {
        perror("Error requesting line 18 for output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(line_23, "smart_lighting", 0) < 0) {
        perror("Error requesting line 23 for output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(line_24, "smart_lighting", 0) < 0) {
        perror("Error requesting line 24 for output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(line_25, "smart_lighting", 0) < 0) {
        perror("Error requesting line 25 for output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_23) {
        gpiod_line_release(line_23);
    }
    if (line_24) {
        gpiod_line_release(line_24);
    }
    if (line_25) {
        gpiod_line_release(line_25);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to toggle a relay
void toggle_relay(int gpio_pin) {
    struct gpiod_line *line;
    if (gpio_pin == GPIO_18) {
        line = line_18;
    } else if (gpio_pin == GPIO_23) {
        line = line_23;
    } else if (gpio_pin == GPIO_24) {
        line = line_24;
    } else if (gpio_pin == GPIO_25) {
        line = line_25;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting line value");
        return;
    }

    int new_value = (value == 0) ? 1 : 0;
    if (gpiod_line_set_value(line, new_value) < 0) {
        perror("Error setting line value");
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Toggle relay 18 every 2 seconds
        toggle_relay(GPIO_18);
        struct timespec req = {0};
        req.tv_sec = INTERVAL_2;
        req.tv_nsec = 0;
        nanosleep(&req, NULL);

        // Toggle relay 23 every 3 seconds
        toggle_relay(GPIO_23);
        req.tv_sec = INTERVAL_3;
        req.tv_nsec = 0;
        nanosleep(&req, NULL);

        // Toggle relay 24 every 5 seconds
        toggle_relay(GPIO_24);
        req.tv_sec = INTERVAL_5;
        req.tv_nsec = 0;
        nanosleep(&req, NULL);

        // Toggle relay 25 every 7 seconds
        toggle_relay(GPIO_25);
        req.tv_sec = INTERVAL_7;
        req.tv_nsec = 0;
        nanosleep(&req, NULL);
    }

    return 0;
}

