#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define ALARM_DURATION_MS 3000
#define DEBOUNCE_COOLDOWN_MS 2000
#define POLL_INTERVAL_MS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay(int duration_ms);
int log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate relay for a specified duration
int activate_relay(int duration_ms) {
    gpioWrite(RELAY_PIN, 1); // Turn relay ON
    gpioDelay(duration_ms);
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    return 0;
}

// Log alarm event to file
int log_alarm() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    fprintf(log_file, "%s: Alarm triggered\n", timestamp);
    fclose(log_file);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound-activated alarm system started. Press Ctrl+C to exit.\n");

    int alarm_active = 0;
    time_t alarm_start_time = 0;

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1 && !alarm_active) {
            printf("Sound detected! Activating alarm.\n");
            if (activate_relay(ALARM_DURATION_MS) != 0) {
                fprintf(stderr, "Error activating relay!\n");
            }
            if (log_alarm() != 0) {
                fprintf(stderr, "Error logging alarm!\n");
            }
            alarm_active = 1;
            alarm_start_time = time(NULL);
        } else if (sound_detected == 1 && alarm_active) {
            // Debounce: Check if cooldown period has passed
            if (time(NULL) - alarm_start_time >= (DEBOUNCE_COOLDOWN_MS / 1000.0)) {
                alarm_active = 0;
            }
        } else if (sound_detected == 0 && alarm_active) {
            alarm_active = 0;
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    return 0;
}

