#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity (deg/s)
#define THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold circular buffer data
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *device);
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
float calculate_magnitude(gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);

// Initialize I2C interface
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Initialize MPU-6050 sensor
int init_mpu6050(int fd) {
    // Wake up the sensor (clear sleep bit)
    unsigned char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    usleep(100000); // Wait for sensor to wake up

    // Verify device ID
    unsigned char who_am_i;
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }
    if (who_am_i != 0x68) {
