#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/time.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_READ_COMMAND {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define CO2_READ_COMMAND_LENGTH 9
#define TIMEOUT_MS 1000
#define RETRY_DELAY_MS 100
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define JSON_BUFFER_SIZE 256

// Global variables
int uart_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int co2_ppm;
    int error;
} sensor_data_t;

// Function prototypes
int initialize();
int open_uart(const char *device, int baud_rate);
int read_co2(int uart_handle, int *co2_ppm);
int validate_checksum(const unsigned char *data, int length);
int write_log(const char *json_string);
int write_error_log(const char *message);
void signal_handler(int signal);
char* format_json(int co2_ppm, int error);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and UART
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (open_uart(UART_DEVICE, BAUD_RATE) < 0) {
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        serClose(uart_handle);
        gpioTerminate();
        return -1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Open UART port
int open_uart(const char *device, int baud_rate) {
    uart_handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", device);
        return -1;
    }
    return uart_handle;
}

// Read CO2 concentration from MH-Z19B sensor
int read_co2(int uart_handle, int *co2_ppm) {
    unsigned char read_command[CO2_READ_COMMAND_LENGTH] = CO2_READ_COMMAND;
    unsigned char response[9];
    int bytes_read = 0;
    int timeout_counter = 0;

    while (timeout_counter < TIMEOUT_MS) {
        if (serWrite(uart_handle, (char *)read_command, CO2_READ_COMMAND_LENGTH) != CO2_READ_COMMAND_LENGTH) {
            fprintf(error_log_file, "Error writing to UART\n");
            fflush(error_log_file);
            return -1;
        }
        gpioDelay(100); // Wait for sensor to respond

        bytes_read = 0;
        timeout_counter = 0;
        while (bytes_read < 9 && timeout_counter < TIMEOUT_MS) {
            if (serDataAvailable(uart_handle) > 0) {
                response[bytes_read++] = serRead(uart_handle);
            } else {
                gpioDelay(1); // Small delay to avoid busy-waiting
                timeout_counter++;
            }
        }

        if (bytes_read == 9) {
            if (validate_checksum(response, 8) == 0) {
                *co2_ppm = (response[2] << 8) | response[3];
                return 0; // Success
            } else {
                fprintf(error_log_file, "Checksum validation failed\n");
                fflush(error_log_file);
                timeout_counter = TIMEOUT_MS; // Reset timeout to retry
            }
        } else {
            fprintf(error_log_file, "Incomplete read, retrying...\n");
            fflush(error_log_file);
            timeout_counter = TIMEOUT_MS; // Reset timeout to retry
        }
        gpioDelay(RETRY_DELAY_MS); // Wait before retrying
    }

    fprintf(error_log_file, "Timeout reading from UART\n");
    fflush(error_log_file);
    return -1; // Timeout
}

// Validate checksum
int validate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 1; i < length; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;
    return (checksum != data[length - 1]);
}

// Write data to log file
int write_log(const char *json_string) {
    if (fputs(json_string, log_file) == EOF) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Write error message to error log file
int write_error_log(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Format data into JSON string
char* format_json(int co2_ppm, int error) {
    static char json_string[JSON_BUFFER_SIZE];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long timestamp = (long long)tv.tv_sec * 1000000 + tv.tv_usec;

    snprintf(json_string, JSON_BUFFER_SIZE, "{\"timestamp\":%lld,\"co2_ppm\":%d,\"error\":%d}\n", timestamp, co2_ppm, error);
    return json_string;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() < 0) {
        return 1;
    }

    printf("CO2 monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int co2_ppm;
        if (read_co2(uart_handle, &co2_ppm) == 0) {
            char *json_string = format_json(co2_ppm, 0);
            if (write_log(json_string) != 0) {
                write_error_log("Failed to write to log file");
            }
            printf("%s", json_string);
        } else {
            char *json_string = format_json(0, 1);
            if (write_log(json_string) != 0) {
                write_error_log("Failed to write to log file");
            }
            printf("%s", json_string);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    printf("CO2 monitor stopped.\n");
    return 0;
}

