#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// GPIO pin for heading deviation indication
#define HEADING_GPIO 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold compensated heading data
typedef struct {
    float heading;
    float deviation;
} compensated_heading_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
compensated_heading_t heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
void compensate_heading(magnetometer_data_t raw_data, float *heading, float *deviation);
void update_circular_buffer(float heading);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configure register A: 8-average, 15 Hz output rate, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Configure register B: 1.3 Gauss gain
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to compensate heading data
void compensate_heading(magnetometer_data_t raw_data, float *heading, float *deviation) {
    // Hard-iron offsets
    float x_offset = 100.0;
    float y_offset = -50.0;

    // Calculate compensated values
    float x_comp = raw_data.x - x_offset;
    float y_comp = raw_data.y - y_offset;

    // Calculate heading in degrees
    *heading = atan2(y_comp, x_comp) * 180 / M_PI;

    // Calculate deviation from target heading (90 degrees)
    *deviation = fabs(*heading - 90.0);

    // Handle heading wrap-around
    if (*heading < 0) {
        *heading += 360.0;
    }
    if (*heading > 360.0) {
        *heading -= 360.0;
    }
}

// Function to update the circular buffer
void update_circular_buffer(float heading) {
    heading_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(HEADING_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Compensate heading data
        float heading, deviation;
        compensate_heading(raw_data, &heading, &deviation);

        // Update circular buffer
        update_circular_buffer(heading);

        // Check for heading deviation and control GPIO
        if (deviation > 10.0) {
            gpioWrite(HEADING_GPIO, 1); // Set GPIO high
        } else {
            gpioWrite(HEADING_GPIO, 0); // Set GPIO low
        }

        // Print heading data (optional)
        printf("Heading: %.2f, Deviation: %.2f\n", heading, deviation);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

