#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_MEDIUM 150
#define LUX_THRESHOLD_HIGH 300

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void set_relay_state(int red_state, int green_state, int blue_state);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_mode = 0x10; // Continuous high-resolution mode
    if (write(i2c_fd, &config_mode, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buffer[2];
    int bytes_read;

    // Wait for at least 120ms for the first conversion
    usleep(120000); // 120ms

    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the two bytes to form the raw lux value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];

    // Calculate lux value (datasheet formula)
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Set the state of the relays
void set_relay_state(int red_state, int green_state, int blue_state) {
    gpioWrite(RED_RELAY_PIN, red_state);
    gpioWrite(GREEN_RELAY_PIN, green_state);
    gpioWrite(BLUE_RELAY_PIN, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    float lux;
    int red_state, green_state, blue_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Determine relay states based on lux value
            if (lux < LUX_THRESHOLD_LOW) {
                red_state = 1; // ON
                green_state = 0; // OFF
                blue_state = 0; // OFF
            } else if (lux < LUX_THRESHOLD_MEDIUM) {
                red_state = 0; // OFF
                green_state = 1; // ON
                blue_state = 0; // OFF
            } else if (lux < LUX_THRESHOLD_HIGH) {
                red_state = 0; // OFF
                green_state = 1; // ON
                blue_state = 1; // ON
            } else {
                red_state = 1; // ON
                green_state = 1; // ON
                blue_state = 1; // ON
            }

            // Set relay states
            set_relay_state(red_state, green_state, blue_state);

            // Log data
            log_data(lux, red_state, green_state, blue_state);
        } else {
            fprintf(stderr, "Error reading lux value. Retrying in 1 second.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_relay_state(0, 0, 0); // Turn off all relays
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

