#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Distance range (cm)
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Threshold distance (cm)
#define THRESHOLD_DISTANCE 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Function to map distance to PWM duty cycle
int distance_to_pwm(int distance) {
    if (distance < MIN_DISTANCE) {
        return 255;
    } else if (distance > MAX_DISTANCE) {
        return 0;
    } else {
        return (int)(((float)(MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE)) * 255.0);
    }
}

