#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD 20000 // 20ms
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

// MPU-6050 Registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Global variables
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int gpio, int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int sig);

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Wake up the MPU-6050
    char data[2];
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from MPU-6050
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char reg = MPU6050_ACCEL_XOUT_H;
    char data[14];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000 * (1 << retries)); // Exponential backoff
            continue;
        }

        if (read(i2c_fd, data, 14) != 14) {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000 * (1 << retries)); // Exponential backoff
            continue;
        }

        *accel_x = (data[0] << 8) | data[1];
        *accel_y = (data[2] << 8) | data[3];
        *accel_z = (data[4] << 8) | data[5];
        *gyro_x = (data[8] << 8) | data[9];
        *gyro_y = (data[10] << 8) | data[11];
        *gyro_z = (data[12] << 8) | data[13];

        return 0; // Success
    }

    fprintf(stderr, "Failed to read MPU-6050 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate pitch and roll
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *roll = atan2(ay, sqrt(ax * ax + az * az)) * 180 / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180 / M_PI;
}

// Function to set servo angle using hardware PWM
int set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    // Calculate pulse width (1000us - 2000us for 0-180 degrees)
    int pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);

    // Set PWM duty cycle
    int duty_cycle = (int)(((float)pulse_width / PWM_PERIOD) * 1000000.0); // Convert to nanoseconds

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM duty cycle file");
        return -1;
    }

    char duty_str[16];
    snprintf(duty_str, sizeof(duty_str), "%d", duty_cycle);
    if (write(fd, duty_str, strlen(duty_str)) != strlen(duty_str)) {
        perror("Error writing to PWM duty cycle file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to log data to file
int log_data(float pitch, float roll, int servo_angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_angle;

    // Main loop
    while (!terminate) {
        // Read MPU-6050 data
        if (read_mpu6050(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            calculate_pitch_roll(accel_x, accel_y, accel_z, &pitch, &roll);

            // Set servo angle based on pitch
            servo_angle = (int)pitch; // Simple proportional control
            if (servo_angle < 0) servo_angle = 0;
            if (servo_angle > 180) servo_angle = 180;

            if (set_servo_angle(SERVO_GPIO, servo_angle) != 0) {
                fprintf(stderr, "Error setting servo angle\n");
            }

            // Log data
            log_data(pitch, roll, servo_angle);
        } else {
            fprintf(stderr, "Error reading MPU-6050 data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);
    gpioTerminate();

    return 0;
}

