#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Global variables
FILE *schedule_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 0 = off, 1 = on
} schedule_entry_t;

// Function prototypes
int read_schedule_entry(schedule_entry_t *entry);
int parse_schedule_entry(const char *line, schedule_entry_t *entry);
int apply_schedule(const schedule_entry_t *entry);
int fade_lamp(int relay_pin, int target_duty_cycle, int duration_seconds);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RELAY1_PIN, 100);
    gpioSetPWMrange(RELAY2_PIN, 100);
    gpioSetPWMrange(RELAY3_PIN, 100);
    gpioSetPWMrange(RELAY4_PIN, 100);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    gpioTerminate();
}

// Function to read a schedule entry from the file
int read_schedule_entry(schedule_entry_t *entry) {
    char line[256];
    if (fgets(line, sizeof(line), schedule_file) == NULL) {
        if (feof(schedule_file)) {
            // End of file reached, return 0 to indicate no more entries
            return 0;
        } else {
            fprintf(stderr, "Error reading schedule file\n");
            return 1;
        }
    }

    // Remove trailing newline character
    line[strcspn(line, "\n")] = 0;

    if (parse_schedule_entry(line, entry) != 0) {
        fprintf(stderr, "Error parsing schedule entry: %s\n", line);
        return 1;
    }

    return 0;
}

// Function to parse a schedule entry
int parse_schedule_entry(const char *line, schedule_entry_t *entry) {
    char *token;
    char *rest = (char *)line;

    token = strtok_r(rest, ":", &rest);
    if (token == NULL) return 1;
    entry->hour = atoi(token);

    token = strtok_r(rest, ":", &rest);
    if (token == NULL) return 1;
    entry->minute = atoi(token);

    token = strtok_r(rest, ":", &rest);
    if (token == NULL) return 1;
    entry->second = atoi(token);

    token = strtok_r(rest, ":", &rest);
    if (token == NULL) return 1;
    entry->relay_number = atoi(token);

    token = strtok_r(rest, ":", &rest);
    if (token == NULL) return 1;
    entry->state = atoi(token);

    return 0;
}

// Function to apply the schedule
int apply_schedule(const schedule_entry_t *entry) {
    time_t now = time(NULL);
    struct tm *current_time = localtime(&now);
    int current_hour = current_time->tm_hour;
    int current_minute = current_time->tm_min;
    int current_second = current_time->tm_sec;

    if (entry->hour == current_hour && entry->minute == current_minute && entry->second == current_second) {
        int relay_pin;
        switch (entry->relay_number) {
            case 1:
                relay_pin = RELAY1_PIN;
                break;
            case 2:
                relay_pin = RELAY2_PIN;
                break;
            case 3:
                relay_pin = RELAY3_PIN;
                break;
            case 4:
                relay_pin = RELAY4_PIN;
                break;
            default:
                fprintf(stderr, "Invalid relay number: %d\n", entry->relay_number);
                return 1;
        }

        if (entry->state == 1) {
            printf("Turning on relay %d\n", entry->relay_number);
            if (fade_lamp(relay_pin, 100, 1800) != 0) {
                fprintf(stderr, "Error fading lamp for relay %d\n", entry->relay_number);
                return 1;
            }
        } else {
            printf("Turning off relay %d\n", entry->relay_number);
            gpioPWM(relay_pin, 0); // Turn off the lamp immediately
        }
    }
    return 0;
}

// Function to fade the lamp brightness
int fade_lamp(int relay_pin, int target_duty_cycle, int duration_seconds) {
    int current_duty_cycle = 0;
    int increment = 1; // Increment duty cycle by 1 each second
    int delay_seconds = 1; // Delay for 1 second

    for (int i = 0; i <= target_duty_cycle; ++i) {
        current_duty_cycle = i;
        gpioPWM(relay_pin, current_duty_cycle);
        sleep(delay_seconds);
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open schedule file
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Error opening schedule file: %s\n", SCHEDULE_FILE);
        cleanup_gpio();
        return 1;
    }

    schedule_entry_t schedule_entry;

    // Main loop
    while (!terminate) {
        if (read_schedule_entry(&schedule_entry) == 0) {
            apply_schedule(&schedule_entry);
        } else {
            // No more schedule entries, sleep for a while before checking again
            sleep(5);
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close schedule file
    fclose(schedule_file);

    return 0;
}

