#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define frequency range
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000

// Define distance range
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 30.0

// Define timeout duration (in microseconds)
#define TIMEOUT 50000 // 50ms

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, silencing buzzer and exiting.\n");
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
        gpioTerminate(); // Terminate pigpio
        program_running = 0;
        exit(0);
    }
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, diff;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin did not go high within timeout.\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin did not go low within timeout.\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

// Function to calculate the distance from the pulse width
float calculateDistance(long pulse_width) {
    // Speed of sound in air (cm/us) = 0.0343 cm/us
    // Divide by 2 because the sound travels to the object and back
    return (pulse_width * 0.0343) / 2.0;
}

// Function to map distance to frequency
int mapDistanceToFrequency(float distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linearly map distance to frequency
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp frequency to the defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return (int)frequency;
}

// Function to set the buzzer frequency
void setBuzzerFrequency(int frequency) {
    gpioSetPWMfrequency(BUZZER_PIN, frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-1000 for finer control)
    gpioSetPWMrange(BUZZER_PIN, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
