#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
void set_rgb_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a color based on proximity value
void generate_color_from_proximity(float proximity, int *red, int *green, int *blue)
{
    if (proximity < 0.5) {
        // Red to Green transition
        *red = (int)(255 * (0.5 - fabs(proximity - 0.5)));
        *green = (int)(255 * (0.5 + fabs(proximity - 0.5)));
        *blue = 0;
    } else {
        // Green to Blue transition
        *red = 0;
        *green = (int)(255 * (0.5 - fabs(proximity - 0.5)));
        *blue = (int)(255 * (0.5 + fabs(proximity - 0.5)));
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for each pin
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate proximity value using a sine wave
        float proximity = sinf(M_PI * 2 * time(NULL) / 60.0) / 2.0 + 0.5;

        // Generate color based on proximity value
        int red, green, blue;
        generate_color_from_proximity(proximity, &red, &green, &blue);

        // Set the RGB LED color
        set_rgb_color(red, green, blue);

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Turn off the LED before exiting
    set_rgb_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

