const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile int playback_active = 0;
volatile unsigned long last_interrupt_time = 0;

// Function prototypes
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping PWM and terminating pigpio...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Interrupt handler for button press
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        last_interrupt_time = current_time;
        if (level == 0) { // Button pressed (active-low)
            if (!playback_active) {
                printf("Button pressed, starting melody...\n");
                play_melody();
            } else {
                printf("Button pressed during playback, stopping melody...\n");
                stop_melody();
            }
        }
    }
}

// Function to play the melody
void play_melody() {
    playback_active = 1;
    for (int i = 0; i < melody_length; i++) {
        gpioHardwarePWM(BUZZER_GPIO, melody[i], 500000); // 50% duty cycle (500000/1000000)
        gpioDelay(melody_duration[i] * 1000); // Convert milliseconds to microseconds
    }
    playback_active = 0;
    gpioHardwarePWM(BUZZER_GPIO, 0, 0); // Stop the PWM
    printf("Melody finished.\n");
}

// Function to stop the melody
void stop_melody() {
    gpioHardwarePWM(BUZZER_GPIO, 0, 0); // Stop the PWM
    playback_active = 0;
    printf("Melody stopped.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on the button GPIO
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set up interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler for GPIO%d\n", BUTTON_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100000); // Check every 100ms
    }

    return 0;
}

