#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>
#include <stdbool.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEFAULT_TIMEOUT_MS 1000
#define WINDOW_SIZE 5

// Structure to hold the event history
typedef struct {
    int value;
    struct timespec timestamp;
} Event;

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static Event event_history[WINDOW_SIZE];
static int history_index = 0;
static int history_count = 0; // Number of events in the history

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
int open_log_file(void);
int log_event(int value, const struct timespec *timestamp);
int check_earthquake_alert(int value, const struct timespec *timestamp);
void free_resources(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Signal received, terminating...\n");
        terminate = 1;
    }
}

// Initialize GPIO
int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", gpiod_line_name(line));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Open log file
int open_log_file(void) {
    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Acquire exclusive lock
    if (flock(fileno(log_file), LOCK_EX) == -1) {
        fprintf(stderr, "Error acquiring file lock: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    return 0;
}

// Log event
int log_event(int value, const struct timespec *timestamp) {
    if (!log_file) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    struct tm tm_info;
    char timestamp_str[30];

    localtime_r(timestamp, &tm_info);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", &tm_info);

    fprintf(log_file, "%s, %d\n", timestamp_str, value);
    fflush(log_file);

    // Release lock
    if (flock(fileno(log_file), LOCK_UN) == -1) {
        fprintf(stderr, "Error releasing file lock: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Check for earthquake alert
int check_earthquake_alert(int value, const struct timespec *timestamp) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    // Update event history
    event_history[history_index].value = value;
    event_history[history_index].timestamp = *timestamp;
    history_index = (history_index + 1) % WINDOW_SIZE;
    if (history_count < WINDOW_SIZE) {
        history_count++;
    }

    // Check for earthquake alert condition
    int high_count = 0;
    for (int i = 0; i < history_count; i++) {
        if (event_history[i].value == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        printf("EARTHQUAKE ALERT! Timestamp: %ld.%09ld\n", timestamp->tv_sec, timestamp->tv_nsec);
    }

    return 0;
}

// Free resources
void free_resources(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (log_file) {
        if (flock(fileno(log_file), LOCK_UN) == -1) {
            fprintf(stderr, "Error releasing file lock during cleanup: %s\n", strerror(errno));
        }
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    struct timespec timeout;
    struct timespec ts;

    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    // Convert timeout to nanoseconds
    timeout.tv_sec = timeout_ms / 1000;
    timeout.tv_nsec = (timeout_ms % 1000) * 1000000;

    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Log file initialization failed\n");
        free_resources();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int ret = gpiod_line_event_wait(line, timeout);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", gpiod_line_name(line));
            break;
        } else if (ret == 0) {
            // Timeout occurred
            continue;
        }

        int value = gpiod_line_event_read(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", gpiod_line_name(line));
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        if (log_event(value, &ts) != 0) {
            fprintf(stderr, "Error logging event\n");
            break;
        }

        if (check_earthquake_alert(value, &ts) != 0) {
            fprintf(stderr, "Error checking for earthquake alert\n");
            break;
        }
    }

    // Cleanup
    free_resources();

    return 0;
}

