#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// Magnetometer registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Calibration offsets
#define X_OFFSET 10.0
#define Y_OFFSET -5.0
#define Z_OFFSET 20.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, float x_offset, float y_offset, float z_offset);
float calculate_heading(float x, float y);
const char *determine_direction(float heading);
void log_data(FILE *fp, float x, float y, float z, float heading);
void signal_handler(int signum);

// I2C read function
int i2c_read_reg(int fd, unsigned char reg) {
  unsigned char buf[1];
  buf[0] = reg;
  if (write(fd, buf, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }
  if (read(fd, buf, 1) != 1) {
    perror("Failed to read register value");
    return -1;
  }
  return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
  unsigned char buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    perror("Failed to write register value");
    return -1;
  }
  return 0;
}

// Magnetometer initialization function
int init_magnetometer(int fd) {
  // Set continuous-conversion mode
  if (i2c_write_reg(fd, MR_REG_M, 0x00) < 0) {
    fprintf(stderr, "Failed to set continuous-conversion mode\n");
    return -1;
  }

  // Set output data rate to 15 Hz (optional)
  //if (i2c_write_reg(fd, CRA_REG_M, 0x14) < 0) {
  //  fprintf(stderr, "Failed to set output data rate\n");
  //  return -1;
  //}

  return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
  unsigned char buffer[6];
  unsigned char reg = OUT_X_H_M;

  if (write(fd, &reg, 1) != 1) {
    perror("Failed to write register address for reading");
    return -1;
  }

  if (read(fd, buffer, 6) != 6) {
    perror("Failed to read magnetometer data");
    return -1;
  }

  *x = (int16_t)((buffer[0] << 8) | buffer[1]);
  *z = (int16_t)((buffer[2] << 8) | buffer[3]);
  *y = (int16_t)((buffer[4] << 8) | buffer[5]);

  return 0;
}

// Magnetometer calibration function
float calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, float x_offset, float y_offset, float z_offset) {
  return (float)x - x_offset, (float)y - y_offset, (float)z - z_offset;
}

// Heading calculation function
float calculate_heading(float x, float y) {
  float heading = atan2f(y, x) * 180 / M_PI;
  if (heading < 0) {
    heading += 360;
  }
  return heading;
}

// Direction determination function
const char *determine_direction(float heading) {
  if (heading >= 337.5 || heading < 22.5) {
    return "N";
  } else if (heading >= 22.5 && heading < 67.5) {
    return "NE";
  } else if (heading >= 67.5 && heading < 112.5) {
    return "E";
  } else if (heading >= 112.5 && heading < 157.5) {
    return "SE";
  } else if (heading >= 157.5 && heading < 202.5) {
    return "S";
  } else if (heading >= 202.5 && heading < 247.5) {
    return "SW";
  } else if (heading >= 247.5 && heading < 292.5) {
    return "W";
  } else {
    return "NW";
  }
}

// Data logging function
void log_data(FILE *fp, float x, float y, float z, float heading) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[80];

  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, determine_direction(heading));
  fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signum) {
  if (signum == SIGINT || signum == SIGTERM) {
    printf("Received signal %d, exiting gracefully...\n", signum);
    program_running = 0;
  }
}

int main() {
  int16_t x, y, z;
  float calibrated_x, calibrated_y, calibrated_z, heading;

  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C device
  i2c_fd = open("/dev/i2c-1", O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C device");
    return 1;
  }

  // Specify slave address
  if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize magnetometer
  if (init_magnetometer(i2c_fd) < 0) {
    fprintf(stderr, "Magnetometer initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("mag_log.csv", "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Check if file is empty, if so, write the header
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
  }
  fseek(log_file, 0, SEEK_END);

  // Main loop
  while (program_running) {
    // Read magnetometer data
    if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
      // Calibrate magnetometer data
      calibrated_x = (float)x - X_OFFSET;
      calibrated_y = (float)y - Y_OFFSET;
      calibrated_z = (float)z - Z_OFFSET;

      // Calculate heading
      heading = calculate_heading(calibrated_x, calibrated_y);

      // Determine direction
      const char *direction = determine_direction(heading);

      // Log data
      log_data(log_file, calibrated_x, calibrated_y, calibrated_z, heading);

      // Print data to console
      printf("Calibrated X: %.2f, Y: %.2f, Z: %.2f, Heading: %.2f, Direction: %s\n", calibrated_x, calibrated_y, calibrated_z, heading, direction);
    } else {
      fprintf(stderr, "Failed to read magnetometer data\n");
    }

    // Wait for 1 second
    sleep(1);
  }

  // Close I2C device and log file
  close(i2c_fd);
  fclose(log_file);

  return 0;
}

