#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, uint32_t tick, void *user_data);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        gpioDelay(100); // Sleep for 100ms
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    if (toggle_relay() != 0) {
        fprintf(stderr, "Failed to set initial relay state\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on GPIO4
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int current_time = gpioTick();

    // Debounce the touch
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        if (toggle_relay() != 0) {
            fprintf(stderr, "Failed to toggle relay\n");
        }
        last_touch_time = current_time;
    }
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
        return 1;
    }
    return log_relay_state(relay_state);
}

// Log the relay state to file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Turning relay OFF and exiting.\n");

    // Turn relay OFF
    if (toggle_relay() != 0) {
        fprintf(stderr, "Failed to turn relay OFF\n");
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

