#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define NUM_RELAYS 4
#define RELAY_GPIO_1 17
#define RELAY_GPIO_2 23
#define RELAY_GPIO_3 24
#define RELAY_GPIO_4 25
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define MOISTURE_THRESHOLD 30
#define MOISTURE_HYSTERESIS 35
#define LOG_FILE "irrigation_log.txt"
#define CHIP_NAME "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int initialize_i2c(void);
int read_soil_moisture(void);
int control_relays(int moisture_level);
int log_event(int relay_number, int moisture_level);
void cleanup(int signal);
int set_gpio_value(int gpio, int value);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;

    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i] != NULL) {
            if (set_gpio_value(relay_lines[i], 1) != 0) {
                fprintf(stderr, "Error deactivating relay %d\n", i);
            }
        }
    }

    // Release GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i] != NULL) {
            gpiod_line_release(relay_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "irrigation";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    relay_lines[0] = gpiod_chip_get_line(chip, RELAY_GPIO_1);
    relay_lines[1] = gpiod_chip_get_line(chip, RELAY_GPIO_2);
    relay_lines[2] = gpiod_chip_get_line(chip, RELAY_GPIO_3);
    relay_lines[3] = gpiod_chip_get_line(chip, RELAY_GPIO_4);

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (!relay_lines[i]) {
            fprintf(stderr, "Error getting line %d\n", i);
            return -1;
        }

        if (gpiod_line_request(relay_lines[i], &config, 0) != 0) {
            perror("Error requesting GPIO line");
            return -1;
        }
    }

    return 0;
}

// Initialize I2C
int initialize_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read soil moisture from I2C sensor
int read_soil_moisture(void) {
    unsigned char buffer[2];
    int moisture_level;

    // Read two bytes from the I2C device
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    moisture_level = (buffer[0] << 8) | buffer[1];

    // Scale the value to a range of 0-100
    moisture_level = (int)(((float)moisture_level / 65535.0) * 100.0);

    return moisture_level;
}

// Control relays based on moisture level
int control_relays(int moisture_level) {
    int i;
    int moisture_hysteresis_level = MOISTURE_HYSTERESIS;

    if (moisture_level < moisture_hysteresis_level) {
        // Activate relays sequentially
        for (i = 0; i < NUM_RELAYS; i++) {
            if (set_gpio_value(relay_lines[i], 0) != 0) {
                fprintf(stderr, "Error activating relay %d\n", i);
                return -1;
            }
            log_event(i, moisture_level);
            sleep(5);
            if (set_gpio_value(relay_lines[i], 1) != 0) {
                fprintf(stderr, "Error deactivating relay %d\n", i);
                return -1;
            }
            sleep(1);
        }
    }

    return 0;
}

// Log event to file
int log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);

    return 0;
}

// Set GPIO value
int set_gpio_value(int gpio, int value) {
    struct gpiod_line *line = NULL;
    int index = -1;

    if (gpio == RELAY_GPIO_1) index = 0;
    else if (gpio == RELAY_GPIO_2) index = 1;
    else if (gpio == RELAY_GPIO_3) index = 2;
    else if (gpio == RELAY_GPIO_4) index = 3;

    if (index == -1) {
        fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
        return -1;
    }

    line = relay_lines[index];
    if (!line) {
        fprintf(stderr, "GPIO line not found for GPIO %d\n", gpio);
        return -1;
    }

    if (gpiod_line_set_value(line, value) != 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

int main() {
    int moisture_level;
    int last_moisture_level = 100; // Initialize to a high value

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup(0);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(0);
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read soil moisture
        moisture_level = read_soil_moisture();
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading soil moisture\n");
            sleep(10);
            continue;
        }

        // Control relays based on moisture level
        if (moisture_level < MOISTURE_THRESHOLD && last_moisture_level >= MOISTURE_THRESHOLD) {
            if (control_relays(moisture_level) != 0) {
                fprintf(stderr, "Error controlling relays\n");
            }
        }

        last_moisture_level = moisture_level;

        // Wait 10 seconds
        sleep(10);
    }

    cleanup(0);

    return 0;
}

