#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define moisture values for simulation
const int moisture_values[] = {20, 40, 60, 80, 100};
const int moisture_values_size = sizeof(moisture_values) / sizeof(moisture_values[0]);

// Define pulse widths for valve servo (degrees)
const int valve_pulse_widths[] = {500, 2500};
const int valve_pulse_widths_size = sizeof(valve_pulse_widths) / sizeof(valve_pulse_widths[0]);

// Define pulse widths for nozzle servo (degrees)
const int nozzle_pulse_widths[] = {500, 1150, 1500, 1850, 2500};
const int nozzle_pulse_widths_size = sizeof(nozzle_pulse_widths) / sizeof(nozzle_pulse_widths[0]);

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the pulse width of a servo motor
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        if (gpioServo(gpio_pin, pulse_width) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to set pulse width for GPIO %d, retrying...\n", gpio_pin);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Failed to set pulse width for GPIO %d after multiple retries\n", gpio_pin);
    return -1; // Failure
}

// Function to open the water valve
int open_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, valve_pulse_widths[1]); // Open (90 degrees)
}

// Function to close the water valve
int close_valve() {
    return set_servo_pulse_width(VALVE_SERVO_PIN, valve_pulse_widths[0]); // Close (0 degrees)
}

// Function to set the nozzle direction
int set_nozzle_direction(int direction) {
    int pulse_width = nozzle_pulse_widths[direction];
    return set_servo_pulse_width(NOZZLE_SERVO_PIN, pulse_width);
}

// Function to perform watering cycle
int watering_cycle(int moisture_value) {
    if (moisture_value < MOISTURE_THRESHOLD) {
        printf("Moisture level below threshold, starting watering cycle...\n");

        // Open the valve
        if (open_valve() != 0) {
            fprintf(stderr, "Failed to open water valve\n");
            return -1;
        }

        // Sweep the nozzle through all angles
        for (int i = 0; i < nozzle_pulse_widths_size; i++) {
            if (set_nozzle_direction(i) != 0) {
                fprintf(stderr, "Failed to set nozzle direction to %d\n", i);
                close_valve();
                return -1;
            }
            gpioDelay(2000); // Wait 2 seconds
        }

        // Hold the nozzle at the last angle for 5 seconds
        gpioDelay(5000);

        // Close the valve
        if (close_valve() != 0) {
            fprintf(stderr, "Failed to close water valve\n");
            return -1;
        }
    } else {
        printf("Moisture level above threshold, skipping watering cycle...\n");
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Simulate moisture reading
        int moisture_value = moisture_values[(moisture_values_size + (rand() % moisture_values_size)) % moisture_values_size];
        printf("Simulated moisture value: %d\n", moisture_value);

        // Perform watering cycle
        if (watering_cycle(moisture_value) != 0) {
            fprintf(stderr, "Watering cycle failed\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Stop servos and terminate pigpio
    set_servo_pulse_width(VALVE_SERVO_PIN, 0);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    printf("Program terminated cleanly\n");
    return 0;
}

