#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0f

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_degrees_per_second(int16_t raw_value);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Wake up the MPU-6050
    uint8_t wake_up = 0x00;
    if (write(fd, &wake_up, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees per second
float convert_to_degrees_per_second(int16_t raw_value) {
    return (float)raw_value / GYRO_SENSITIVITY;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_deg_s, y_deg_s, z_deg_s;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_deg_s = convert_to_degrees_per_second(raw_x);
            y_deg_s = convert_to_degrees_per_second(raw_y);
            z_deg_s = convert_to_degrees_per_second(raw_z);

            // Log the data
            log_data(x_deg_s, y_deg_s, z_deg_s);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

