    return 0;
}

// Function to convert raw gyroscope data to degrees per second
float convert_to_degrees_per_second(int16_t raw_value) {
    return (float)raw_value / GYRO_SENSITIVITY;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_deg_s, y_deg_s, z_deg_s;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_deg_s = convert_to_degrees_per_second(raw_x);
            y_deg_s = convert_to_degrees_per_second(raw_y);
            z_deg_s = convert_to_degrees_per_second(raw_z);

            // Log the data
            log_data(x_deg_s, y_deg_s, z_deg_s);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

