#define INTER_STEP_DELAY 3 // milliseconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    exit(0);
}

// Function to set the motor coils for full-step sequence
void set_motor_coils(int coil1, int coil2, int coil3, int coil4) {
    gpioWrite(IN1, coil1);
    gpioWrite(IN2, coil2);
    gpioWrite(IN3, coil3);
    gpioWrite(IN4, coil4);
}

// Function to rotate the motor a specified number of steps
void rotate_motor(int steps, int direction) {
    int i;
    for (i = 0; i < steps && program_running; i++) {
        // Full-step sequence
        if (direction == 1) { // Clockwise
            set_motor_coils(1, 0, 0, 0);
            gpioDelay(INTER_STEP_DELAY);
            set_motor_coils(0, 1, 0, 0);
            gpioDelay(INTER_STEP_DELAY);
            set_motor_coils(0, 0, 1, 0);
            gpioDelay(INTER_STEP_DELAY);
            set_motor_coils(0, 0, 0, 1);
            gpioDelay(INTER_STEP_DELAY);
        } else { // Counter-clockwise
            set_motor_coils(0, 0, 0, 1);
            gpioDelay(INTER_STEP_DELAY);
            set_motor_coils(0, 0, 1, 0);
            gpioDelay(INTER_STEP_DELAY);
            set_motor_coils(0, 1, 0, 0);
            gpioDelay(INTER_STEP_DELAY);
            set_motor_coils(1, 0, 0, 0);
            gpioDelay(INTER_STEP_DELAY);
        }
    }
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

// Function to read the lock button with debouncing
int read_lock_button() {
    int i;
    int stable_readings = 0;
    for (i = 0; i < 5; i++) {
        if (gpioRead(LOCK_BUTTON) == 0) { // Active-low
            stable_readings++;
        }
        gpioDelay(1); // 1 ms delay
    }
    return (stable_readings == 5) ? 1 : 0; // Return 1 if consistently low, 0 otherwise
}

// Function to read the unlock button with debouncing
int read_unlock_button() {
    int i;
    int stable_readings = 0;
    for (i = 0; i < 5; i++) {
