        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN2 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN3 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN4 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON as input\n");
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistors for buttons
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor for LOCK_BUTTON\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor for UNLOCK_BUTTON\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Automatic Door Lock System\n");
    printf("Press LOCK button to lock, UNLOCK button to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        // Check for lock button press
        if (read_lock_button()) {
            printf("Locking...\n");
            rotate_motor(STEPS_PER_ROTATION, 1); // Rotate clockwise
            gpioDelay(1000); // Delay after lock
        }

        // Check for unlock button press
        if (read_unlock_button()) {
            printf("Unlocking...\n");
            rotate_motor(STEPS_PER_ROTATION, 0); // Rotate counter-clockwise
            gpioDelay(1000); // Delay after unlock
        }

        gpioDelay(100); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();

    return 0;
}

