#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_GUARD_MS 60        // Minimum guard time in milliseconds
#define MAX_PULSE_WIDTH 1000000 // Maximum reasonable pulse width (1 second)

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
double measure_pulse_width(void);
double calculate_distance(double pulse_width);
int log_distance(double distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "trigger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(trigger_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request echo line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "echo";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(echo_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1;
    }

    return 0;
}

// Measure the pulse width of the echo signal
double measure_pulse_width(void) {
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line_event event;
    struct timespec start_time, end_time;
    double pulse_width = -1.0;
    int ret;

    // Set trigger pin low
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger pin low: %s\n", strerror(errno));
        return -1.0;
    }

    // Wait for a short period to allow the sensor to settle
    nanosleep(&(struct timespec){0, 20000000}, NULL); // 20ms

    // Send a 10us pulse on the trigger pin
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger pin high: %s\n", strerror(errno));
        return -1.0;
    }
    nanosleep(&(struct timespec){0, 10000}, NULL); // 10us
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger pin low: %s\n", strerror(errno));
        return -1.0;
    }

    // Measure the echo pulse width
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        return -1.0;
    }

    // Wait for the echo pin to go high (rising edge)
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (1) {
        ret = gpiod_line_event_wait(echo_line, &event, TIMEOUT_US);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for rising edge: %s\n", strerror(errno));
            return -1.0;
        } else if (ret == 0) {
            // Timeout
            return -1.0;
        }
        if (event.value == 1) {
            break;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Wait for the echo pin to go low (falling edge)
    clock_gettime(CLOCK_MONOTONIC, &end_time);
    while (1) {
        ret = gpiod_line_event_wait(echo_line, &event, TIMEOUT_US);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for falling edge: %s\n", strerror(errno));
            return -1.0;
        } else if (ret == 0) {
            // Timeout
            return -1.0;
        }
        if (event.value == 0) {
            break;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end_time);

    // Calculate pulse width in microseconds
    pulse_width = (end_time.tv_sec - start_time.tv_sec) * 1000000.0 +
                  (end_time.tv_nsec - start_time.tv_nsec) / 1000.0;

    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(double pulse_width) {
    if (pulse_width < 0) {
        return -1.0;
    }
    return pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to cm/s and divide by 2
}

// Log distance to file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup GPIO resources
void cleanup(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    double distance;
    double pulse_width;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Measure pulse width
        pulse_width = measure_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width.\n");
            log_distance(-1.0);
        } else {
            // Calculate distance
            distance = calculate_distance(pulse_width);
            if (distance < 0) {
                fprintf(stderr, "Error calculating distance.\n");
                log_distance(-1.0);
            } else {
                // Log distance
                if (log_distance(distance) < 0) {
                    fprintf(stderr, "Error logging distance.\n");
                }
            }
        }

        // Wait for the minimum guard time
        usleep(MIN_GUARD_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

