#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%X\n", sensor_id);
        return -1;
    }

    // Set ranging mode to short distance
    if (i2cWriteByteData(i2c_handle, 0x002d, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance(int *distance) {
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    if (range_status & 0x01) {
        // Data ready
        int msb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (msb < 0) {
            fprintf(stderr, "Error: Failed to read MSB of distance\n");
            return -1;
        }
        int lsb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
        if (lsb < 0) {
            fprintf(stderr, "Error: Failed to read LSB of distance\n");
            return -1;
        }

        *distance = (msb << 8) | lsb;
        return 0;
    } else {
        // Data not ready
        return -1;
    }
}

// Control the relay based on the distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // HIGH to open the door
    } else {
        gpioWrite(RELAY_GPIO, 0); // LOW to close the door
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially close the door

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is LOW on exit
    gpioTerminate();

    return 0;
}

