#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (set sleep bit to 0)
    uint8_t wake_up_data[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, wake_up_data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    uint8_t gyro_config_data[2] = {GYRO_CONFIG, 0x00};
    if (write(fd, gyro_config_data, 2) != 2) {
        perror("Error writing to GYRO_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[6];

    // Read 6 bytes of gyroscope data starting at register 0x43
    if (read(fd, data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees/second
void convert_to_dps(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *dps_x, float *dps_y, float *dps_z) {
    *dps_x = (float)gyro_x / GYRO_SENSITIVITY;
    *dps_y = (float)gyro_y / GYRO_SENSITIVITY;
    *dps_z = (float)gyro_z / GYRO_SENSITIVITY;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully.\n");

    // Main loop to read and print gyroscope data
    int16_t gyro_x, gyro_y, gyro_z;
    float dps_x, dps_y, dps_z;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert raw data to degrees/second
            convert_to_dps(gyro_x, gyro_y, gyro_z, &dps_x, &dps_y, &dps_z);

            // Print the gyroscope data
            printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n", dps_x, dps_y, dps_z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Delay for 100 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

