    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized successfully.\n");

    // Main loop to read and print gyroscope data
    int16_t gyro_x, gyro_y, gyro_z;
    float dps_x, dps_y, dps_z;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert raw data to degrees/second
            convert_to_dps(gyro_x, gyro_y, gyro_z, &dps_x, &dps_y, &dps_z);

