            printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n", dps_x, dps_y, dps_z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Delay for 100 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

