#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define watering duration (seconds)
#define WATERING_DURATION 5

// Define polling interval (seconds)
#define POLLING_INTERVAL 60

// Define watering cycle interval (seconds)
#define WATERING_CYCLE_INTERVAL 86400

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static struct gpiod_line *line27 = NULL;
static struct gpiod_line *line22 = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int activate_relay(int gpio);
int deactivate_relay(int gpio);
int log_watering_event(int gpio);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line18 = gpiod_chip_get_line(chip, GPIO18);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    line22 = gpiod_chip_get_line(chip, GPIO22);

    if (!line17 || !line18 || !line27 || !line22) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(line17, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(line18, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(line27, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27 as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(line22, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 22 as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Activate relay (set GPIO HIGH)
int activate_relay(int gpio) {
    int ret;
    struct gpiod_line *line = NULL;

    if (gpio == GPIO17) line = line17;
    else if (gpio == GPIO18) line = line18;
    else if (gpio == GPIO27) line = line27;
    else if (gpio == GPIO22) line = line22;
    else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error setting GPIO value HIGH");
        return -1;
    }

    return 0;
}

// Deactivate relay (set GPIO LOW)
int deactivate_relay(int gpio) {
    int ret;
    struct gpiod_line *line = NULL;

    if (gpio == GPIO17) line = line17;
    else if (gpio == GPIO18) line = line18;
    else if (gpio == GPIO27) line = line27;
    else if (gpio == GPIO22) line = line22;
    else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting GPIO value LOW");
        return -1;
    }

    return 0;
}

// Log watering event to file
int log_watering_event(int gpio) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Write to log file
    fprintf(fp, "%s - GPIO %d activated\n", timestamp, gpio);

    // Close log file
    fclose(fp);

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    time_t last_watering_time = time(NULL);
    time_t current_time;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting...\n");
        return EXIT_FAILURE;
    }

    printf("Automated Plant Watering System started.\n");

    // Main loop
    while (!terminate) {
        // Get current time
        current_time = time(NULL);

        // Check if it's time to water
        if (difftime(current_time, last_watering_time) >= WATERING_CYCLE_INTERVAL) {
            // Activate relays sequentially
            ret = activate_relay(GPIO17);
            if (ret == 0) {
                log_watering_event(GPIO17);
                sleep(WATERING_DURATION);
                deactivate_relay(GPIO17);
            }

            ret = activate_relay(GPIO18);
            if (ret == 0) {
                log_watering_event(GPIO18);
                sleep(WATERING_DURATION);
                deactivate_relay(GPIO18);
            }

            ret = activate_relay(GPIO27);
            if (ret == 0) {
                log_watering_event(GPIO27);
                sleep(WATERING_DURATION);
                deactivate_relay(GPIO27);
            }

            ret = activate_relay(GPIO22);
            if (ret == 0) {
                log_watering_event(GPIO22);
                sleep(WATERING_DURATION);
                deactivate_relay(GPIO22);
            }

            // Update last watering time
            last_watering_time = current_time;
        }

        // Sleep for polling interval
        sleep(POLLING_INTERVAL);
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Automated Plant Watering System stopped.\n");

    return EXIT_SUCCESS;
}

