#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the number of steps in the sunrise simulation
#define NUM_STEPS 1800 // 30 minutes * 60 seconds/minute / 1 second/step

// Define the PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, shutting down gracefully...\n");
    }
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for all GPIO pins
    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Sunrise simulation loop
    for (int i = 0; i < NUM_STEPS && program_running; i++) {
        // Calculate the duty cycle increment
        int duty_cycle_increment = 255 / NUM_STEPS;

        // Calculate the current duty cycle
        int duty_cycle = i * duty_cycle_increment;

        // Set the PWM duty cycle for all GPIO pins
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }
        if (set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }
        if (set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }
        if (set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }

        // Log the event
        char message[100];
        snprintf(message, sizeof(message), "Step %d: Duty cycle = %d", i, duty_cycle);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down relays...\n");
    // Set all relays to 0 duty cycle (off)
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

