        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }
        if (set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }
        if (set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }
        if (set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop if there's an error
            break;
        }

        // Log the event
        char message[100];
        snprintf(message, sizeof(message), "Step %d: Duty cycle = %d", i, duty_cycle);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down relays...\n");
    // Set all relays to 0 duty cycle (off)
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

