#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIOCHIP 0
#define CS_LINE_OFFSET 8
#define GYRO_SENSITIVITY 131.0 // dps/LSB for ±250 dps range
#define RETRY_COUNT 3
#define LOG_FILE "gyro_log.txt"

// MPU-9250 Registers
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double convert_to_dps(int16_t raw_data);
int log_data(FILE *fp, double x_rate, double y_rate, double z_rate);
void signal_handler(int sig);
int setup();
void cleanup();

// SPI transfer function with retry and error handling
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int retries = RETRY_COUNT;
    int status;

    while (retries > 0) {
        status = spi_xfer(fd, tx_buf, rx_buf, len);
        if (status == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (status=%d), retrying...\n", status);
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries, giving up.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to read gyroscope data from the MPU-9250
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[1];
    uint8_t rx_buf[6];
    int i;

    // Set the chip select line low to start the transfer
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to set CS line low");
        return -1;
    }

    // Read 6 bytes of data (X, Y, and Z axis)
    for (i = 0; i < 6; i++) {
        tx_buf[0] = 0x00; // Dummy byte for reading
        if (spi_transfer(fd, tx_buf, rx_buf + i, 1) < 0) {
            fprintf(stderr, "Failed to read byte %d\n", i);
            // Set CS high before returning
            if (gpiod_line_set_value(cs_line, 1) < 0) {
                perror("Failed to set CS line high");
                return -1;
            }
            return -1;
        }
    }

    // Set the chip select line high to end the transfer
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to set CS line high");
        return -1;
    }

    // Combine the bytes to form 16-bit values
    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees per second
double convert_to_dps(int16_t raw_data) {
    return (double)raw_data / GYRO_SENSITIVITY;
}

// Function to log data to a file
int log_data(FILE *fp, double x_rate, double y_rate, double z_rate) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Format the timestamp in ISO-8601 format with nanoseconds
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function to initialize SPI and GPIO
int setup() {
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return -1;
    }

    // Get GPIO line
    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(cs_line, "gyro_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Release GPIO line
    if (cs_line) {
        gpiod_line_release(cs_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    double x_rate, y_rate, z_rate;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() < 0) {
        fprintf(stderr, "Setup failed, exiting.\n");
        return 1;
    }

    fprintf(stderr, "Gyroscope data acquisition started.\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(spi_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_rate = convert_to_dps(raw_x);
            y_rate = convert_to_dps(raw_y);
            z_rate = convert_to_dps(raw_z);

            // Log the data
            if (log_data(log_file, x_rate, y_rate, z_rate) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Gyroscope data acquisition stopped.\n");
    return 0;
}

