#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <stdint.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void set_gpio_output(struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int result;
    uint8_t buf[1];

    buf[0] = reg;

    while (retries > 0) {
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        if (read(fd, buf, 1) != 1) {
            perror("Failed to read register value");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = buf[0];
        return result;
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            perror("Failed to write register value");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = 0; // Assume success
        return result;
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read sensor data
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    int result;

    result = i2c_read_reg(fd, AMBIENT_LIGHT_REG);
    if (result < 0) return -1;
    *ambient_light = (uint16_t)((result & 0xFF) | ((i2c_read_reg(fd, AMBIENT_LIGHT_REG + 1) & 0xFF) << 8));

    result = i2c_read_reg(fd, PROXIMITY_REG);
    if (result < 0) return -1;
    *proximity = (uint16_t)((result & 0xFF) | ((i2c_read_reg(fd, PROXIMITY_REG + 1) & 0xFF) << 8));

    return 0;
}

// Function to log data to file
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to set GPIO output
void set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint16_t ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "biometric_sensor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);

            if (proximity > PROXIMITY_THRESHOLD) {
                set_gpio_output(gpio_line, 1); // Turn LED on
            } else {
                set_gpio_output(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    set_gpio_output(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

