        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);

            if (proximity > PROXIMITY_THRESHOLD) {
                set_gpio_output(gpio_line, 1); // Turn LED on
            } else {
                set_gpio_output(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    set_gpio_output(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

