#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define SENSITIVITY 200.0 // LSB/deg/s
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int init_spi();
int read_gyro_register(int reg_addr);
void sample_gyro_data(gyro_data_t *data);
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from a gyroscope register
int read_gyro_register(int reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    // Set read bit (0x80)
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    return (rx_buf[0] << 8) | rx_buf[1];
}

// Sample gyroscope data
void sample_gyro_data(gyro_data_t *data) {
    data->x_rate = read_gyro_register(GYRO_X_REG);
    data->y_rate = read_gyro_register(GYRO_Y_REG);
}

