    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    fprintf(fp, "%ld,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header to CSV file
    fprintf(fp, "timestamp,x_rate,y_rate\n");

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        sample_gyro_data(&gyro_data);
        log_data(gyro_data);
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

