#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define SEISMIC_WINDOW_MS 500
#define SEISMIC_THRESHOLD_MS 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    unsigned long last_change_time;
} SensorStates;

SensorStates sensor_states = {0, 0, 0};

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void trigger_alert();
void log_event();
void handle_signal(int signal);
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);

// Signal handler function
void handle_signal(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Set ALERT_PIN LOW
    gpioWrite(ALERT_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs or output
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (not strictly needed with pigpio, but good practice)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    // Set initial states
    gpioWrite(ALERT_PIN, 0);

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(ALERT_DURATION_MS);
    gpioWrite(ALERT_PIN, 0);
}

// Function to log seismic event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for sensor changes
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (gpio == SENSOR1_PIN) {
        sensor_states.sensor1_state = level;
    } else if (gpio == SENSOR2_PIN) {
        sensor_states.sensor2_state = level;
    }

    if (sensor_states.sensor1_state == 1 && sensor_states.sensor2_state == 1) {
        // Both sensors are HIGH
        if (current_time - sensor_states.last_change_time >= SEISMIC_WINDOW_MS * 1000) {
            // Check if both sensors were HIGH for at least SEISMIC_THRESHOLD_MS
            if (sensor_states.sensor1_state == 1 && sensor_states.sensor2_state == 1) {
                if (current_time - sensor_states.last_change_time >= SEISMIC_THRESHOLD_MS * 1000) {
                    // Trigger alert and log event
                    trigger_alert();
                    log_event();
                    sensor_states.last_change_time = current_time;
                }
            }
        }
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register callbacks for sensor pins
    gpioSetAlertFuncEx(SENSOR1_PIN, sensor_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_PIN, sensor_callback, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    return 0;
}

