#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define ANGULAR_RATE_THRESHOLD 20.0 // deg/s
#define BUFFER_SIZE 100
#define SENSITIVITY 200.0 // LSB/deg/s
#define GYRO_SCALE_FACTOR 0.01 // deg/s/LSB

// ADXRS290 Registers
#define RATE_XL_REG 0x02
#define RATE_XH_REG 0x03

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
float angular_rate_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t led_mutex = PTHREAD_MUTEX_INITIALIZER;
int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int spi_read_register(uint8_t address, uint16_t *data);
float convert_to_degrees_per_second(uint16_t raw_data);
void add_to_circular_buffer(float angular_rate);
void *monitor_angular_rate(void *arg);
void signal_handler(int signal);

// SPI read register function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Set MSB for read operation
    address |= 0x80;

    tx_buffer[0] = address & 0x7F; // Ensure only lower 7 bits are used
    tx_buffer[1] = 0x00; // Dummy byte for reading
    tx_buffer[2] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *data = (rx_buffer[1] << 8) | rx_buffer[2];
    return 0;
}

// Convert raw data to degrees per second
float convert_to_degrees_per_second(uint16_t raw_data) {
    return (float)raw_data * GYRO_SCALE_FACTOR;
}

// Add angular rate to circular buffer
void add_to_circular_buffer(float angular_rate) {
    pthread_mutex_lock(&buffer_mutex);
    angular_rate_buffer[buffer_index] = angular_rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Monitor angular rate and control LED
void *monitor_angular_rate(void *arg) {
    while (!terminate) {
        pthread_mutex_lock(&buffer_mutex);
        float angular_rate = angular_rate_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE];
        pthread_mutex_unlock(&buffer_mutex);

        if (fabs(angular_rate) > ANGULAR_RATE_THRESHOLD) {
            pthread_mutex_lock(&led_mutex);
            if (led_state == 0) {
                gpioWrite(LED_GPIO, 1); // Turn on LED
                led_state = 1;
            }
            pthread_mutex_unlock(&led_mutex);
        } else {
            pthread_mutex_lock(&led_mutex);
            if (led_state == 1) {
                gpioWrite(LED_GPIO, 0); // Turn off LED
                led_state = 0;
            }
            pthread_mutex_unlock(&led_mutex);
        }

        gpioDelay(10000); // 10ms delay
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create thread for monitoring angular rate
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_angular_rate, NULL) != 0) {
        fprintf(stderr, "Failed to create monitor thread\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        if (spi_read_register(RATE_XL_REG, &raw_data) == 0) {
            float angular_rate = convert_to_degrees_per_second(raw_data);
            add_to_circular_buffer(angular_rate);
            printf("Angular Rate: %.2f deg/s\n", angular_rate);
        } else {
            fprintf(stderr, "Failed to read angular rate\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    pthread_join(monitor_thread, NULL);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

