#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency and range for each lamp
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    return 0; // Indicate success
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio_pin, int duration_seconds) {
    int i;
    for (i = PWM_RANGE; i >= 0; i--) {
        gpioPWM(gpio_pin, i);
        printf("Lamp on GPIO %d: PWM = %d\n", gpio_pin, i);
        gpioDelay(duration_seconds * 1000000 / PWM_RANGE); // Delay for the specified duration
    }
    printf("Lamp on GPIO %d: PWM = 0\n", gpio_pin);
}

// Function to turn off a lamp
void turn_off_lamp(int gpio_pin) {
    gpioPWM(gpio_pin, 0);
    printf("Lamp on GPIO %d: OFF\n", gpio_pin);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    turn_off_lamp(LAMP1_GPIO);
    turn_off_lamp(LAMP2_GPIO);
    turn_off_lamp(LAMP3_GPIO);
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main(int argc, char *argv[]) {
    int fade_duration;

    // Check for correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the fade duration from the command-line argument
    fade_duration = atoi(argv[1]);

    // Validate the fade duration
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Sunset Simulator started. Fade duration: %d seconds\n", fade_duration);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, fade_duration);
    gpioDelay(fade_duration * 1000000); // Delay for the specified duration
    fade_lamp(LAMP2_GPIO, fade_duration);
    gpioDelay(fade_duration * 1000000); // Delay for the specified duration
    fade_lamp(LAMP3_GPIO, fade_duration);

    printf("Smart Sunset Simulator finished.\n");

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

