    int i;

    // Read the sensor three times with a 50ms delay
    for (i = 0; i < 3; i++) {
        readings[i] = gpioRead(FLAME_SENSOR_PIN);
        gpioDelay(DEBOUNCE_INTERVAL * 1000); // Convert ms to microseconds
    }

    // Check if all readings are LOW (active-low)
    for (i = 0; i < 3; i++) {
        if (readings[i] != 0) {
            return 1; // Flame not detected
        }
    }

    return 0; // Flame detected
}

