    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin as output.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin as output.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_flame_sensor() == 0) {
            // Flame detected
            activate_buzzer();
            activate_led();
            log_event("Flame Detected");
        } else {
            // No flame detected
            deactivate_buzzer();
            deactivate_led();
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_buzzer();
    deactivate_led();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

