#define SOLENOID_2_PIN 27

// Define dispense duration and delay
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_DELAY_S 5

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Deactivating solenoids and exiting.\n");
        program_running = 0;
    }
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to configure GPIO pin as output
int configure_gpio_output(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return 1;
    }
    return 0;
}

// Function to activate solenoid
int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO %d\n", pin);
        return 1;
    }
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
    return 0;
}

// Function to deactivate solenoid
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO %d\n", pin);
        return 1;
    }
    return 0;
}

// Function to log dispense event to file
int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, GPIO %d, %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pins as outputs
    if (configure_gpio_output(SOLENOID_1_PIN) != 0) {
        gpioTerminate();
        return 1;
    }
    if (configure_gpio_output(SOLENOID_2_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense cycle
        if (activate_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            program_running = 0; // Stop on error
            break;
        }
        if (activate_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            program_running = 0; // Stop on error
            break;
