// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to state: %d\n", relay_state);
}

// Function to clean up GPIO pins
void cleanup_gpio() {
    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch Program Started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor
        if (read_touch_sensor() == 1) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

            // Toggle the relay
            toggle_relay();
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

