#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>
#include <errno.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Default sensitivity scaling factor
#define DEFAULT_SENSITIVITY 1.0

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static float sensitivity = DEFAULT_SENSITIVITY;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to map RMS amplitude to RGB values using a non-linear transition
void map_amplitude_to_rgb(float rms_amplitude, int *red, int *green, int *blue)
{
    // Non-linear mapping (cool to warm colors)
    float normalized_amplitude = rms_amplitude * sensitivity;
    float normalized_amplitude_clamped = fmin(1.0, fmax(0.0, normalized_amplitude));

    *red   = (int)(255.0 * (1.0 - pow(normalized_amplitude_clamped, 0.5)));
    *green = (int)(255.0 * pow(normalized_amplitude_clamped, 0.5));
    *blue  = (int)(255.0 * pow(normalized_amplitude_clamped, 1.5));
}

// Function to calculate the RMS amplitude of audio samples
float calculate_rms(const short *samples, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++)
    {
        sum_sq += (double)samples[i] * samples[i];
    }
    return sqrt(sum_sq / num_samples);
}

// Function to capture audio data from ALSA
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size)
{
    int frames = snd_pcm_readi(pcm_handle, buffer, buffer_size);
    if (frames < 0)
    {
        fprintf(stderr, "Error reading from PCM: %s\n", snd_strerror(frames));
        return -1;
    }
    return frames;
}

// Function to initialize ALSA for audio capture
int init_alsa(const char *device_name, snd_pcm_t **pcm_handle)
{
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, device_name, SND_PCM_STREAM_CAPTURE, 0)) < 0)
    {
        fprintf(stderr, "Error opening PCM device %s: %s\n", device_name, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0)
    {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0)
    {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

