void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to map RMS amplitude to RGB values using a non-linear transition
void map_amplitude_to_rgb(float rms_amplitude, int *red, int *green, int *blue)
{
    // Non-linear mapping (cool to warm colors)
    float normalized_amplitude = rms_amplitude * sensitivity;
    float normalized_amplitude_clamped = fmin(1.0, fmax(0.0, normalized_amplitude));

    *red   = (int)(255.0 * (1.0 - pow(normalized_amplitude_clamped, 0.5)));
    *green = (int)(255.0 * pow(normalized_amplitude_clamped, 0.5));
    *blue  = (int)(255.0 * pow(normalized_amplitude_clamped, 1.5));
}

// Function to calculate the RMS amplitude of audio samples
float calculate_rms(const short *samples, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++)
    {
        sum_sq += (double)samples[i] * samples[i];
    }
    return sqrt(sum_sq / num_samples);
}

// Function to capture audio data from ALSA
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size)
{
    int frames = snd_pcm_readi(pcm_handle, buffer, buffer_size);
    if (frames < 0)
    {
