#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
void log_message(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for log message.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    free(timestamp);
}

// Function to record a video using raspivid
int record_video() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for video filename.\n");
        return 1;
    }

    char filename[100];
    snprintf(filename, sizeof(filename), "%s%s", VIDEO_DIR, timestamp);
    free(timestamp);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        log_message("Error: Failed to execute raspivid command.");
        return 1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "raspivid exited with status %d", WEXITSTATUS(status));
        log_message(error_message);
        return 1;
    }

    char log_message_buffer[200];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Video recorded: %s", filename);
    log_message(log_message_buffer);

    return 0;
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        log_message("Error: pigpio initialisation failed.");
        return 1;
    }

    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_gpio();
        return 1;
    }

    log_message("Program started");

    time_t last_trigger_time = 0;

    while (program_running) {
        int motion_detected = gpioRead(MOTION_SENSOR_GPIO);

        if (motion_detected == 0) { // Active-low sensor
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) >= (DEBOUNCE_INTERVAL_MS / 1000.0)) {
                if (record_video() == 0) {
                    last_trigger_time = current_time;
                } else {
                    log_message("Error: Failed to record video.");
                }
            }
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup resources before exiting
    log_message("Program exiting");
    if (log_file != NULL) {
        fclose(log_file);
    }
    cleanup_gpio();

    return 0;
}

