// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    char buffer[14];
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read gyroscope data from registers 0x43-0x48
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 14) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        data.x = 0.0; // Set to 0 to avoid garbage values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw values to degrees per second
    data.x = (float)raw_x / GYRO_SENSITIVITY;
    data.y = (float)raw_y / GYRO_SENSITIVITY;
    data.z = (float)raw_z / GYRO_SENSITIVITY;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    char timestamp[30];

    // Get current timestamp with millisecond precision
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format timestamp
    struct tm *tm_info;
    tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    // Write data to log file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

