#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_adxl345();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(int16_t x, int16_t y, int16_t z);
int log_freefall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int init_adxl345() {
    // Set DATA_FORMAT register to enable full resolution and ±2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 256.0;
}

// Function to detect freefall
int detect_freefall(int16_t x, int16_t y, int16_t z) {
    return (abs(convert_to_g(x)) < FREEFALL_THRESHOLD &&
            abs(convert_to_g(y)) < FREEFALL_THRESHOLD &&
            abs(convert_to_g(z)) < FREEFALL_THRESHOLD);
}

// Function to log freefall event
int log_freefall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp,
            convert_to_g(x), convert_to_g(y), convert_to_g(z));
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    // Close I2C handle
    i2cClose(i2c_handle);

    // Set GPIO low
    gpioWrite(ALARM_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure it starts low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int freefall_count = 0;
    int freefall_confirmed = 0;

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            // Detect freefall
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= (int)(FREEFALL_DURATION * 10)) { // 10 readings per second
                    freefall_confirmed = 1;
                }
            } else {
                freefall_count = 0;
                freefall_confirmed = 0;
            }

            // Log freefall event if confirmed
            if (freefall_confirmed) {
                log_freefall_event(x, y, z);
                printf("Freefall detected and logged!\n");

                // Activate alarm
                gpioWrite(ALARM_PIN, 1);
                gpioDelay(5000); // 5 seconds
                gpioWrite(ALARM_PIN, 0);

                freefall_confirmed = 0; // Reset confirmation flag
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Continuing...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

