            abs(convert_to_g(y)) < FREEFALL_THRESHOLD &&
            abs(convert_to_g(z)) < FREEFALL_THRESHOLD);
}

// Function to log freefall event
int log_freefall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp,
            convert_to_g(x), convert_to_g(y), convert_to_g(z));
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    // Close I2C handle
    i2cClose(i2c_handle);

    // Set GPIO low
    gpioWrite(ALARM_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure it starts low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int freefall_count = 0;
    int freefall_confirmed = 0;

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            // Detect freefall
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= (int)(FREEFALL_DURATION * 10)) { // 10 readings per second
                    freefall_confirmed = 1;
                }
            } else {
                freefall_count = 0;
                freefall_confirmed = 0;
            }

            // Log freefall event if confirmed
            if (freefall_confirmed) {
                log_freefall_event(x, y, z);
                printf("Freefall detected and logged!\n");

                // Activate alarm
                gpioWrite(ALARM_PIN, 1);
                gpioDelay(5000); // 5 seconds
                gpioWrite(ALARM_PIN, 0);

                freefall_confirmed = 0; // Reset confirmation flag
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Continuing...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

