#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm (4 meters)
#define MAX_PULSE_WIDTH 23200   // Maximum pulse width in microseconds (4 meters)
#define TIMEOUT_US 100000       // Timeout in microseconds (100 ms)
#define TRIGGER_INTERVAL_MS 200 // Trigger interval in milliseconds

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_occurred = 0;
static pthread_mutex_t mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void timeout_callback();
void signal_handler(int signal);
void *logging_thread(void *arg);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt callback function for rising edge
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

// Interrupt callback function for timeout
void timeout_callback() {
    timeout_occurred = 1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Thread function for logging data
void *logging_thread(void *arg) {
    while (running) {
        pthread_mutex_lock(&mutex);
        if (echo_received && !timeout_occurred) {
            double pulse_width = (double)(end_tick - start_tick);
            if (pulse_width > 0 && pulse_width <= MAX_PULSE_WIDTH) {
                double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
                if (distance >= 0 && distance <= MAX_DISTANCE) {
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    long timestamp_ns = (ts.tv_sec * 1000000000) + (ts.tv_nsec);

                    fprintf(log_file, "%ld,%f\n", timestamp_ns, distance);
                    fflush(log_file); // Ensure data is written to file immediately
                    echo_received = 0;
                    timeout_occurred = 0;
                } else {
                    fprintf(stderr, "Invalid distance: %f cm\n", distance);
                }
            } else {
                fprintf(stderr, "Invalid pulse width: %f us\n", pulse_width);
            }
        }
        pthread_mutex_unlock(&mutex);
        gpioDelay(1000); // Check every 1 ms
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt callbacks
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_callback, NULL);
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, TIMEOUT_US, timeout_callback, NULL);

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create logging thread\n");
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(TRIGGER_INTERVAL_MS * 1000); // Delay for trigger interval
    }

    // Clean up
    pthread_join(logging_thread_id, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();

    return 0;
}

