#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_value);
double calculate_magnitude(double x, double y, double z);
int detect_freefall(double magnitude);
int detect_impact(double magnitude);
int activate_buzzer();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure LIS3DH accelerometer
int config_lis3dh() {
    // CTRL_REG1: 100 Hz, Normal mode, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: ±2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw acceleration value to g
double convert_to_g(int16_t raw_value) {
    return (double)raw_value / 16384.0;
}

// Calculate the magnitude of the acceleration vector
double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

// Detect freefall
int detect_freefall(double magnitude) {
    return (magnitude < freefall_threshold);
}

// Detect impact
int detect_impact(double magnitude) {
    return (magnitude > impact_threshold);
}

// Activate the buzzer
int activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    printf("Freefall threshold: %.2f g\n", freefall_threshold);
    printf("Impact threshold: %.2f g\n", impact_threshold);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double x_g, y_g, z_g, magnitude;

    printf("Fall detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Convert to g
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x_g, y_g, z_g);

            // Detect fall
            if (detect_freefall(magnitude)) {
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
                gpioDelay(500000); // Debounce delay
            } else if (detect_impact(magnitude)) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
                gpioDelay(500000); // Debounce delay
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            if (init_i2c() != 0 || config_lis3dh() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(10000); // Delay 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    printf("Fall detection system terminated.\n");
    return 0;
}

