            // Convert to g
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x_g, y_g, z_g);

            // Detect fall
            if (detect_freefall(magnitude)) {
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
                gpioDelay(500000); // Debounce delay
            } else if (detect_impact(magnitude)) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
                gpioDelay(500000); // Debounce delay
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            if (init_i2c() != 0 || config_lis3dh() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(10000); // Delay 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    printf("Fall detection system terminated.\n");
    return 0;
}

