    {0, 0, 0, 1}
};

// Conversion factor: steps per mm
#define STEPS_PER_MM 10

// Square side length in mm
#define SQUARE_SIDE_LENGTH 50

// Number of steps to move one side of the square
#define STEPS_PER_SIDE (SQUARE_SIDE_LENGTH * STEPS_PER_MM)

