// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to set GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    int result = gpioSetMode(pin, mode);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d mode to %d: %d\n", pin, mode, result);
        return -1;
    }
    return 0;
}

// Function to write a value to a GPIO pin
int write_gpio(int pin, int value) {
    int result = gpioWrite(pin, value);
    if (result != 0) {
        fprintf(stderr, "Error writing value %d to GPIO %d: %d\n", value, pin, result);
        return -1;
    }
    return 0;
}

// Function to control a stepper motor
void step_motor(int motor_id, int steps, int delay_us) {
    int in1, in2, in3, in4;
    if (motor_id == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor_id == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor ID: %d\n", motor_id);
        return;
    }

