        // Move Y-axis (Motor 2)
        step_motor(2, STEPS_PER_SIDE, STEP_DELAY);
        if (!program_running) break;

        // Move X-axis back
        step_motor(1, -STEPS_PER_SIDE, STEP_DELAY);
        if (!program_running) break;

        // Move Y-axis back
        step_motor(2, -STEPS_PER_SIDE, STEP_DELAY);
        if (!program_running) break;
    }

    printf("Square drawing complete.\n");

    // Stop motors (set all pins low)
    write_gpio(MOTOR1_IN1, 0);
    write_gpio(MOTOR1_IN2, 0);
    write_gpio(MOTOR1_IN3, 0);
    write_gpio(MOTOR1_IN4, 0);
    write_gpio(MOTOR2_IN1, 0);
    write_gpio(MOTOR2_IN2, 0);
    write_gpio(MOTOR2_IN3, 0);
    write_gpio(MOTOR2_IN4, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

