#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
static int i2c_handle = -1;
static int running = 1;
static float threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;

// Function prototypes
int initialize_i2c(int address);
int configure_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
void log_event(int axis, float g);
void shutdown_system();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initializes the I2C connection
int initialize_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, no flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configures the LIS3DH accelerometer
int configure_lis3dh(int i2c_handle) {
    // CTRL_REG1: 0x57 (ODR = 100Hz, FS = +/-2g, High Resolution)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 0x88 (High Resolution)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Reads acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6); // Read multiple bytes, auto-increment address

    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        *x = 0; *y = 0; *z = 0; // Set to zero to avoid using uninitialized values
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Converts raw acceleration data to g-force units
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 2048.0f; // 2g / 2048
}

// Logs an event to the log file
void log_event(int axis, float g) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - High acceleration detected on axis %d: %.4f g\n", s, axis, g);
    fclose(fp);
}

// Shuts down the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                if (strlen(optarg) != 2 || (optarg[0] < '0' || optarg[0] > '7') || (optarg[1] < '0' || optarg[1] > '7')) {
                    fprintf(stderr, "Invalid I2C address.  Must be a 2-digit hex value between 0x08 and 0x77.\n");
                    return 1;
                }
                i2c_address = (int)strtol(optarg, NULL, 16);
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold.  Must be a positive number.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float x_g, y_g, z_g;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Convert to g-force units
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Check for high acceleration
            if (fabs(x_g) > threshold) {
                log_event(0, x_g);
                shutdown_system();
            }
            if (fabs(y_g) > threshold) {
                log_event(1, y_g);
                shutdown_system();
            }
            if (fabs(z_g) > threshold) {
                log_event(2, z_g);
                shutdown_system();
            }
        }

        gpioDelay(100); // 100 ms delay (10 Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

