#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define THRESHOLD_MT_X100 (THRESHOLD_MT * 100)
#define SI7210_REG_START 0xC1
#define SI7210_REG_DATA 0xC0
#define SI7210_REG_STATUS 0xC1
#define SI7210_REG_CONFIG 0x80 // Example config register

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *raw_data);
float convert_to_mT(int16_t raw_data);
void control_relay(int state);
void log_event(const char *event_type, float field_mT);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *raw_data) {
    char buf[1];
    char data[2];
    int result;

    // Start measurement
    buf[0] = SI7210_REG_START;
    result = i2cWriteByteData(i2c_handle, buf[0], 0x01); // Start measurement
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (polling status register)
    int timeout = 50; // 50 attempts
    while (timeout > 0) {
        buf[0] = SI7210_REG_STATUS;
        result = i2cWriteByte(i2c_handle, buf[0]);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            return -1;
        }
        result = i2cReadByteData(i2c_handle, buf[0]);
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            return -1;
        }
        if (result == 0x00) {
            break; // Measurement complete
        }
        timeout--;
        gpioDelay(1); // Small delay
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement to complete.\n");
        return -1;
    }

    // Read data
    buf[0] = SI7210_REG_DATA;
    result = i2cWriteByte(i2c_handle, buf[0]);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    result = i2cReadI2CBlockData(i2c_handle, buf[0], data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *raw_data = (int16_t)((data[1] << 8) | data[0]);
    return 0;
}

// Function to convert raw data to milliTesla
float convert_to_mT(int16_t raw_data) {
    return (float)raw_data * 25.0 / 1000.0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events
void log_event(const char *event_type, float field_mT) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s - %s - Field: %.2f mT\n", timestamp, event_type, field_mT);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t raw_data;
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&raw_data) == 0) {
            // Convert to milliTesla
            field_mT = convert_to_mT(raw_data);

            // Check threshold and control relay
            if (field_mT > THRESHOLD_MT) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay ON", field_mT);
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay OFF", field_mT);
                }
            }

            // Log field reading
            log_event("Field Reading", field_mT);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
            log_event("Error", -999.0); // Log error
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

