#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for graceful shutdown
int server_fd = 0;
int client_fd = 0;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio();
int setup_socket();
void handle_client(int client_socket);
void log_event(const char *event);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close client socket if open
    if (client_fd > 0) {
        close(client_fd);
    }

    // Close server socket if open
    if (server_fd > 0) {
        close(server_fd);
    }

    // Turn off the relay
    gpioWrite(GPIO_PIN, 0);

    // Close log file if open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Sets up the GPIO pin for the relay
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Sets up the TCP socket
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    return 0;
}

// Handles communication with a client
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    int valread;

    while ((valread = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[valread] = '\0'; // Null-terminate the received data
        printf("Received: %s\n", buffer);

        // Remove trailing whitespace
        while (buffer[valread - 1] == ' ') {
            buffer[valread - 1] = '\0';
            valread--;
        }

        // Convert to uppercase for case-insensitive comparison
        for (int i = 0; buffer[i] != '\0'; i++) {
            buffer[i] = toupper(buffer[i]);
        }

        if (strcmp(buffer, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            log_event("Relay ON");
        } else if (strcmp(buffer, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            log_event("Relay OFF");
        } else {
            log_event("Invalid command");
            send(client_socket, "Invalid command\n", strlen("Invalid command\n"), 0);
        }
    }

    if (valread == 0) {
        printf("Client disconnected\n");
    } else if (valread < 0) {
        perror("recv failed");
    }

    close(client_socket);
}

// Logs an event to the log file with a timestamp
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
