#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_RELAY 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1.0 / 1500.0
#define START_MEASUREMENT_CMD {0x36, 0x08}
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
static volatile int running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr, int flags);
int write_i2c(int handle, const char *buf, int count);
int read_i2c(int handle, char *buf, int count);
int validate_crc(const char *data, int len);
float convert_to_ml_min(int raw_value);
void control_relay(int flow1, int flow2);
void log_flow_rates(int flow1, int flow2);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C handle
int open_i2c_handle(int bus, int addr, int flags) {
    int handle = i2cOpen(bus, addr, flags);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to write to an I2C device
int write_i2c(int handle, const char *buf, int count) {
    int result = i2cWriteDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read from an I2C device
int read_i2c(int handle, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(const char *data, int len) {
    if (len != 3) {
        return -1; // Invalid length
    }

    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != (uint8_t)data[len - 1]) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02x, received 0x%02x\n", crc, (uint8_t)data[len - 1]);
        return -1;
    }

    return 0;
}

// Function to convert raw value to ml/min
float convert_to_ml_min(int raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Function to control the relay
void control_relay(int flow1, int flow2) {
    static int relay_state = 0; // 0 = off, 1 = on

    if ((flow1 < FLOW_THRESHOLD) || (flow2 < FLOW_THRESHOLD)) {
        if (relay_state == 0) {
            gpioWrite(GPIO_RELAY, 1); // Energize relay
            relay_state = 1;
            printf("Relay ON\n");
        }
    } else {
        if (relay_state == 1) {
            gpioWrite(GPIO_RELAY, 0); // De-energize relay
            relay_state = 0;
            printf("Relay OFF\n");
        }
    }
}

// Function to log flow rates to a file
void log_flow_rates(int flow1, int flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Sensor1: %d ml/min, Sensor2: %d ml/min\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // De-energize relay
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Start measurement on both sensors
        if (write_i2c(i2c_handle1, START_MEASUREMENT_CMD, 2) != 0) {
            fprintf(stderr, "Failed to start measurement on sensor 1\n");
        }
        if (write_i2c(i2c_handle2, START_MEASUREMENT_CMD, 2) != 0) {
            fprintf(stderr, "Failed to start measurement on sensor 2\n");
        }

        // Read data from sensors
        char data1[3];
        if (read_i2c(i2c_handle1, data1, 3) != 0) {
            fprintf(stderr, "Failed to read data from sensor 1\n");
        } else {
            if (validate_crc(data1, 3) == 0) {
                int raw_flow1 = (data1[0] << 8) | data1[1];
                float flow1 = convert_to_ml_min(raw_flow1);
                //printf("Sensor 1 Flow: %.2f ml/min\n", flow1);
            } else {
                fprintf(stderr, "CRC validation failed for sensor 1\n");
            }
        }

        char data2[3];
        if (read_i2c(i2c_handle2, data2, 3) != 0) {
            fprintf(stderr, "Failed to read data from sensor 2\n");
        } else {
            if (validate_crc(data2, 3) == 0) {
                int raw_flow2 = (data2[0] << 8) | data2[1];
                float flow2 = convert_to_ml_min(raw_flow2);
                //printf("Sensor 2 Flow: %.2f ml/min\n", flow2);
            } else {
                fprintf(stderr, "CRC validation failed for sensor 2\n");
            }
        }

        // Control relay based on flow rates
        if (i2c_handle1 >= 0 && i2c_handle2 >= 0) {
            if (data1[0] != 0xFF && data2[0] != 0xFF) {
                control_relay((int)((data1[0] << 8) | data1[1]), (int)((data2[0] << 8) | data2[1]));
            }
        }

        // Log flow rates
        if (i2c_handle1 >= 0 && i2c_handle2 >= 0) {
            if (data1[0] != 0xFF && data2[0] != 0xFF) {
                log_flow_rates((int)((data1[0] << 8) | data1[1]), (int)((data2[0] << 8) | data2[1]));
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

