#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_S 5
#define DRY_COUNT_THRESHOLD 3

// Global variables
static volatile int running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_window();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping motor and exiting.");
    running = 0;
    stop_window();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Closing window.");
    if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to enable motor.");
        return;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 HIGH.");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 LOW.");
        return;
    }
    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Delay for 5 seconds
    if (gpioWrite(MOTOR_ENA_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to disable motor.");
        return;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN1 LOW.");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set IN2 LOW.");
        return;
