#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define BUTTON_LOCK_PIN 21
#define BUTTON_UNLOCK_PIN 22

// Define servo pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
    }
}

// Function to set the servo pulse width
int set_servo_pulse(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width to %d: %d\n", pulse_width, result);
        return -1;
    }
    return 0;
}

// Function to read the button state with debouncing
int read_button(int gpio) {
    int state = gpioRead(gpio);
    if (state == PI_LOW) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
        if (gpioRead(gpio) == PI_LOW) {
            return 1; // Button is still pressed after debounce
        }
    }
    return 0; // Button is not pressed or was released during debounce
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_LOCK_PIN, PI_INPUT);
    gpioSetMode(BUTTON_UNLOCK_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_LOCK_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_UNLOCK_PIN, PI_PUD_UP);

    // Set initial servo position to locked (2000us)
    if (set_servo_pulse(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for unlock button press
        if (read_button(BUTTON_UNLOCK_PIN)) {
            // Set servo to unlocked position (1000us)
            if (set_servo_pulse(SERVO_PIN, UNLOCK_PULSE_WIDTH) == 0) {
                printf("Door unlocked\n");
            }
            gpioDelay(5000000); // Keep unlocked for 5 seconds
            // Set servo back to locked position (2000us)
            if (set_servo_pulse(SERVO_PIN, LOCK_PULSE_WIDTH) == 0) {
                printf("Door locked\n");
            }
        }

        // Check for lock button press
        if (read_button(BUTTON_LOCK_PIN)) {
            // Set servo to locked position (2000us)
            if (set_servo_pulse(SERVO_PIN, LOCK_PULSE_WIDTH) == 0) {
                printf("Door locked\n");
            }
        }

        gpioDelay(10000); // Small delay to avoid busy-waiting (10ms)
    }

    // Clean up and exit
    printf("Setting servo to 0 and terminating pigpio...\n");
    if (set_servo_pulse(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error setting servo to 0 during shutdown\n");
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

