#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17

// Define activation duration (seconds)
#define ACTIVATION_DURATION 60

// Global variable to track floodlight state
static volatile int floodlight_on = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_floodlight(int duration_seconds);
int deactivate_floodlight();
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (floodlight_on) {
        deactivate_floodlight();
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set PIR sensor pin as input
    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR sensor pin as input\n");
        gpioTerminate();
        return -1;
    }

    // Set floodlight pin as output
    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin as output\n");
        gpioTerminate();
        return -1;
    }

    // Ensure floodlight is initially off
    deactivate_floodlight();

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate the floodlight
int activate_floodlight(int duration_seconds) {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate floodlight\n");
        return -1;
    }
    floodlight_on = 1;
    return 0;
}

// Function to deactivate the floodlight
int deactivate_floodlight() {
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate floodlight\n");
        return -1;
    }
    floodlight_on = 0;
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, const char *message) {
    FILE *fp = fopen("security_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - %s: %s\n", timestamp, event_type, message);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        // Check for motion
        if (motion_detected) {
            printf("Motion detected!\n");

            // Activate floodlight
            if (activate_floodlight(ACTIVATION_DURATION) == 0) {
                log_event("Activation", "Floodlight activated due to motion");
            } else {
                // Attempt to deactivate before exiting
                deactivate_floodlight();
                gpioTerminate();
                return 1;
            }

            // Wait for activation duration
            gpioDelay(ACTIVATION_DURATION * 1000000); // Delay in microseconds

            // Deactivate floodlight
            if (deactivate_floodlight() == 0) {
                log_event("Deactivation", "Floodlight deactivated");
            } else {
                // Attempt to deactivate before exiting
                gpioTerminate();
                return 1;
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100000); // 100ms
    }

    return 0;
}

