#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_I2C_ADDR 0x5A
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define DEBOUNCE_MS 200
#define RELAY_ON_TIME_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(unsigned short *touch_status);
int toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) { // MHD_R
        fprintf(stderr, "Error: Failed to write MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x05) < 0) { // NHD_R
        fprintf(stderr, "Error: Failed to write NHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { // NCL_R
        fprintf(stderr, "Error: Failed to write NCL_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // FDL_R
        fprintf(stderr, "Error: Failed to write FDL_R\n");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, DEBOUNCE_MS) < 0) {
        fprintf(stderr, "Error: Failed to write debounce register\n");
        return -1;
    }

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { // FFI
        fprintf(stderr, "Error: Failed to write FFI register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) { // SFI
        fprintf(stderr, "Error: Failed to write SFI register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // CDT
        fprintf(stderr, "Error: Failed to write CDT register\n");
        return -1;
    }

    // Set auto-config
