#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <stdarg.h>
#include <errno.h>

// Configuration
#define SERVO_PIN 17
#define PIR_PIN 4
#define TCP_PORT 5000
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define LOG_FILE "security.log"

// Global variables (minimize usage)
static int server_fd = -1;
static int client_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t pwm_thread;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void log_message(int priority, const char *format, ...);
void *pwm_thread_func(void *arg);
int set_servo_angle(int angle);
int read_pir_sensor();
int handle_client(int client_socket);
void signal_handler(int sig);
int setup_gpio();
void cleanup_gpio();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    syslog(priority, "%s ", timestamp);
    vfprintf(stderr, format, args);
    va_end(args);
}

// PWM thread function
void *pwm_thread_func(void *arg) {
    (void)arg; // Suppress unused parameter warning
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = PWM_PERIOD_US * 1000; // Convert microseconds to nanoseconds

    while (!terminate) {
        if (set_servo_angle(0) != 0) {
            log_message(LOG_ERR, "Failed to set servo angle to 0 in PWM thread.");
        }
        nanosleep(&req, &rem);
        if (set_servo_angle(180) != 0) {
            log_message(LOG_ERR, "Failed to set servo angle to 180 in PWM thread.");
        }
        nanosleep(&req, &rem);
    }
    pthread_exit(NULL);
}

// Set servo angle function
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width in microseconds (1-2ms for 0-180 degrees)
    int pulse_width = (int)(((float)angle / 180.0) * 2000.0 + 1000.0);

    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo line high.");
        return -1;
    }
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = pulse_width * 1000; // Convert microseconds to nanoseconds
    nanosleep(&delay, NULL);

    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo line low.");
        return -1;
    }
    return 0;
}

// Read PIR sensor function
int read_pir_sensor() {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value.");
        return -1;
    }
    return value;
}

// Handle client function
int handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received command: %s", buffer);

        if (strncmp(buffer, "SERVO ", 6) == 0) {
            int angle;
            if (sscanf(buffer, "SERVO %d", &angle) == 1) {
                if (set_servo_angle(angle) != 0) {
                    const char *error_message = "Failed to set servo angle.";
                    send(client_socket, error_message, strlen(error_message), 0);
                    log_message(LOG_ERR, "%s", error_message);
                }
            } else {
                const char *error_message = "Invalid servo command.";
                send(client_socket, error_message, strlen(error_message), 0);
                log_message(LOG_ERR, "%s", error_message);
            }
        } else if (strcmp(buffer, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value < 0) {
                const char *error_message = "Failed to read PIR sensor.";
                send(client_socket, error_message, strlen(error_message), 0);
                log_message(LOG_ERR, "%s", error_message);
            } else {
                char response[20];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                send(client_socket, response, strlen(response), 0);
                log_message(LOG_INFO, "Sent PIR value: %d", pir_value);
            }
        } else {
            const char *error_message = "Unknown command.";
            send(client_socket, error_message, strlen(error_message), 0);
            log_message(LOG_ERR, "%s", error_message);
        }
    }

    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s", strerror(errno));
    }

    close(client_socket);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received: %d. Terminating...", sig);
    terminate = 1;
}

// Setup GPIO function
int setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio() {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Initialize syslog
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed. Exiting.");
        closelog();
        return 1;
    }

    // Create PWM thread
    if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
        cleanup_gpio();
        closelog();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        log_message(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        pthread_cancel(pwm_thread);
        cleanup_gpio();
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Failed to bind socket: %s", strerror(errno));
        close(server_fd);
        pthread_cancel(pwm_thread);
        cleanup_gpio();
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Failed to listen on socket: %s", strerror(errno));
        close(server_fd);
        pthread_cancel(pwm_thread);
        cleanup_gpio();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d...", TCP_PORT);

    // Accept connections and handle clients
    while (!terminate) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            log_message(LOG_ERR, "Failed to accept connection: %s", strerror(errno));
            continue; // Continue listening
        }

        log_message(LOG_INFO, "Accepted connection from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_fd);

        client_fd = -1; // Reset client_fd after handling
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    close(server_fd);
    pthread_cancel(pwm_thread);
    pthread_join(pwm_thread, NULL);
    cleanup_gpio();
    closelog();

    return 0;
}

