void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(0); // Deactivate relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
                printf("Turning on grow light.\n");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
                printf("Turning off grow light.\n");
            }

            log_data(lux);
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    cleanup();
    return 0;
}

