    int sum = 0;
    for (i = 0; i < num_samples; i++) {
        int raw_value = hx711_read(dout_line, sck_line);
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return;
        }
        sum += raw_value;
        usleep(10000); // Small delay between samples
    }
    tare_offset = sum / num_samples;
    log_message(LOG_INFO, "Tare offset set to: %d", tare_offset);
}

// Signal handler function
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function
void cleanup(void) {
    log_message(LOG_INFO, "Cleaning up GPIO lines and chip...");

    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0); // Ensure solenoid is LOW
        gpiod_line_release(solenoid_line);
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    closelog();
}

// Logging function
void log_message(int priority, const char *message) {
    openlog("hx711_solenoid", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    struct gpiod_line_request_config config;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:i:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'i':
                poll_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-i poll_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("hx711_solenoid", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Starting hx711_solenoid program");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    dout_line = gpiod_chip_get_line(chip, HX711_DOUT);
    sck_line = gpiod_chip_get_line(chip, HX711_SCK);
    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout_line || !sck_line || !solenoid_line) {
        log_message(LOG_ERR, "Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO lines for input/output
    memset(&config, 0, sizeof(config));
    config.consumer = "hx711_solenoid";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (gpiod_line_request(dout_line, &config, 0) != 0) {
        log_message(LOG_ERR, "Failed to request DOUT line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(sck_line, &config, 0) != 0) {
        log_message(LOG_ERR, "Failed to request SCK line");
        cleanup();
        return EXIT_FAILURE;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(solenoid_line, &config, 0) != 0) {
        log_message(LOG_ERR, "Failed to request solenoid line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Tare the load cell
    tare(dout_line, sck_line, 10);

    // Main loop
    while (running) {
        int i;
        int sum = 0;
        int raw_value;

        // Average 5 readings
        for (i = 0; i < 5; i++) {
            raw_value = hx711_read(dout_line, sck_line);
            if (raw_value == -1) {
                log_message(LOG_ERR, "Error reading HX711, retrying...");
                usleep(100000); // Wait 100ms before retrying
                i--; // Retry the current iteration
                continue;
            }
            sum += raw_value;
            usleep(10000); // Small delay between readings
        }

        int average_raw = sum / 5;

        // Calculate weight
        float weight = calculate_weight(average_raw, tare_offset, scale);

        // Log weight
        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Weight: %.2f grams", weight);
        log_message(LOG_INFO, log_buffer);

        // Check threshold and activate solenoid if needed
        if (weight > threshold) {
            log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            solenoid_lock(solenoid_line, duration);
        }

        usleep(poll_interval * 1000); // Wait before next reading
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

