#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEPALIVE 60

static volatile int running = 1;
static struct mosquitto *mosq = NULL;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int connect_mqtt(struct mosquitto **mosq_ptr, const char *client_id, int keepalive, const char *host, int port) {
    int rc;
    *mosq_ptr = mosquitto_new(client_id, true, NULL);
    if (!*mosq_ptr) {
        syslog(LOG_ERR, "Out of memory.");
        return 1;
    }

    rc = mosquitto_connect(*mosq_ptr, host, port, keepalive);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq_ptr);
        *mosq_ptr = NULL;
        return 1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker.");
    return 0;
}

int subscribe_mqtt(struct mosquitto *mosq, const char *topic, int qos) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, qos);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s, error: %s", topic, mosquitto_strerror(rc));
        return 1;
    }
    syslog(LOG_INFO, "Subscribed to topic: %s", topic);
    return 0;
}

int message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // HIGH
            syslog(LOG_INFO, "Relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // LOW
            syslog(LOG_INFO, "Relay OFF");
        } else {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received.");
    }
    return 0;
}

int disconnect_mqtt(struct mosquitto **mosq_ptr) {
    if (*mosq_ptr) {
        int rc = mosquitto_disconnect(*mosq_ptr);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to disconnect from MQTT broker: %s", mosquitto_strerror(rc));
            return 1;
        }
        syslog(LOG_INFO, "Disconnected from MQTT broker.");
        mosquitto_destroy(*mosq_ptr);
        *mosq_ptr = NULL;
    }
    return 0;
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting MQTT relay controller...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (connect_mqtt(&mosq, MQTT_CLIENT_ID, KEEPALIVE, MQTT_BROKER, MQTT_PORT) != 0) {
        syslog(LOG_ERR, "MQTT connection failed, exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_message_callback_set(mosq, message_callback);

    if (subscribe_mqtt(mosq, MQTT_TOPIC, 0) != 0) {
        syslog(LOG_ERR, "MQTT subscription failed, exiting.");
        disconnect_mqtt(&mosq);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_forever(mosq, -1, 1);

    disconnect_mqtt(&mosq);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();
    return 0;
}

