// Define servo pins
#define SERVO1 7
#define SERVO2 8
#define SERVO3 9
#define SERVO4 10
#define SERVO5 11

// Define pulse widths (microseconds)
#define PULSE_WIDTH1 1000
#define PULSE_WIDTH2 1500
#define PULSE_WIDTH3 2000
#define PULSE_WIDTH4 500
#define PULSE_WIDTH5 2500

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set servo pulse width
int set_servo_pulse(int pin, int pulse_width) {
    if (gpioPWM(pin, pulse_width) != 0) {
        fprintf(stderr, "Error setting PWM for pin %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to hold servos for a specified duration
int hold_servos(int duration_ms) {
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(SERVO1, PI_OUTPUT);
    gpioSetMode(SERVO2, PI_OUTPUT);
    gpioSetMode(SERVO3, PI_OUTPUT);
    gpioSetMode(SERVO4, PI_OUTPUT);
    gpioSetMode(SERVO5, PI_OUTPUT);

    // Set PWM frequency and range (50Hz, 500-2500us)
    gpioSetPWMfrequency(SERVO1, 50);
    gpioSetPWMfrequency(SERVO2, 50);
    gpioSetPWMfrequency(SERVO3, 50);
    gpioSetPWMfrequency(SERVO4, 50);
    gpioSetPWMfrequency(SERVO5, 50);

    gpioSetPWMrange(SERVO1, 2500);
    gpioSetPWMrange(SERVO2, 2500);
    gpioSetPWMrange(SERVO3, 2500);
    gpioSetPWMrange(SERVO4, 2500);
    gpioSetPWMrange(SERVO5, 2500);

    // Set initial pulse widths
    if (set_servo_pulse(SERVO1, PULSE_WIDTH1) != 0 ||
        set_servo_pulse(SERVO2, PULSE_WIDTH2) != 0 ||
        set_servo_pulse(SERVO3, PULSE_WIDTH3) != 0 ||
        set_servo_pulse(SERVO4, PULSE_WIDTH4) != 0 ||
        set_servo_pulse(SERVO5, PULSE_WIDTH5) != 0) {
        gpioTerminate();
        return 1;
    }

    // Hold servos for 3 seconds
    if (hold_servos(3000) != 0) {
        gpioTerminate();
        return 1;
    }

    // Stop PWM and release resources
    gpioTerminate();

    return 0;
}

