#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target speed (RPM)
#define TARGET_SPEED 50.0

// PI controller parameters
#define Kp 0.5
#define Ki 0.05

// Encoder stall detection (seconds)
#define STALL_TIME 2.0

// Global variables (protected by mutex)
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared variables for PI controller
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void *encoder_a_isr(void *arg);
void *encoder_b_isr(void *arg);
void set_motor_a_speed(int speed);
void set_motor_b_speed(int speed);
double calculate_rpm(int encoder_count);
double calculate_pi_control(double setpoint, double current_rpm, double *integral, double last_error, double Kp, double Ki, double *last_error_ptr);
void signal_handler(int signal);
void log_data(double rpm_a, double rpm_b, int pwm_a, int pwm_b);

// Function to set motor A speed
void set_motor_a_speed(int speed) {
    if (speed > 0) {
        gpioWrite(MOTOR_A_IN2, 0);
        gpioPWM(MOTOR_A_IN1, speed);
    } else if (speed < 0) {
        gpioWrite(MOTOR_A_IN1, 0);
        gpioPWM(MOTOR_A_IN2, -speed);
    } else {
        gpioWrite(MOTOR_A_IN1, 0);
        gpioWrite(MOTOR_A_IN2, 0);
    }
}

// Function to set motor B speed
void set_motor_b_speed(int speed) {
    if (speed > 0) {
        gpioWrite(MOTOR_B_IN4, 0);
        gpioPWM(MOTOR_B_IN3, speed);
    } else if (speed < 0) {
        gpioWrite(MOTOR_B_IN3, 0);
        gpioPWM(MOTOR_B_IN4, -speed);
    } else {
        gpioWrite(MOTOR_B_IN3, 0);
        gpioWrite(MOTOR_B_IN4, 0);
    }
}

// Function to calculate RPM from encoder count
double calculate_rpm(int encoder_count) {
    return (double)encoder_count * 60.0 / 64.0; // 64 ticks per revolution
}

// Function to calculate PI controller output
double calculate_pi_control(double setpoint, double current_rpm, double *integral, double last_error, double Kp, double Ki, double *last_error_ptr) {
    double error = setpoint - current_rpm;
    *integral += error;
    // Anti-windup clamping
    if (*integral > 100) *integral = 100;
    if (*integral < -100) *integral = -100;

    double output = Kp * error + Ki * (*integral);

    *last_error_ptr = error;

    return output;
}

