#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define HYSSTERESIS 5
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
float read_bh1750();
void control_relay(float lux);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_bh1750() {
    char config_cmd = 0x21; // One-Time High-Resolution Mode 2
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1.0;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Control the relay based on lux value
void control_relay(float lux) {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    static int last_lux_low = 0;
    static int last_lux_high = 0;

    if (lux < LUX_THRESHOLD_LOW && relay_state == 0 && last_lux_low == 0) {
        gpioWrite(GPIO_RELAY, 1); // Turn ON
        relay_state = 1;
        last_lux_low = 1;
    } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1 && last_lux_high == 0) {
        gpioWrite(GPIO_RELAY, 0); // Turn OFF
        relay_state = 0;
        last_lux_high = 1;
    } else if (lux < LUX_THRESHOLD_LOW && relay_state == 0) {
        last_lux_low = 1;
    } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1) {
        last_lux_high = 1;
    } else if (lux >= LUX_THRESHOLD_HIGH && last_lux_high == 1) {
        last_lux_high = 0;
    } else if (lux < LUX_THRESHOLD_LOW && last_lux_low == 1) {
        last_lux_low = 0;
    }
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Chicken coop lighting system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading sensor, turning off relay.\n");
            gpioWrite(GPIO_RELAY, 0);
            log_data(-1.0, 0); // Log error
        } else {
            control_relay(lux);
            log_data(lux, gpioRead(GPIO_RELAY));
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

