#include <string.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int relay_state = 0; // 0 = OFF, 1 = ON
    int touch_detected = 0;
    int last_touch_state = 0;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO modes
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set initial relay state\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read touch sensor state
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        // Debouncing and edge detection
        if (touch_state == 1 && last_touch_state == 0) {
            // Touch detected
            touch_detected = 1;
        } else if (touch_state == 0 && last_touch_state == 1) {
            // Touch released
            touch_detected = 0;
        }

        last_touch_state = touch_state;

