#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_CONVERSION_FACTOR 60.0
#define FLOW_RATE_THRESHOLD 5.0
#define HYSTERESIS 0.5
#define DEBOUNCE_MS 1000 // 1 second debounce
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
void *sensor_node_thread(void *arg);
void signal_handler(int signal);

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses) {
    return (double)pulses / PULSES_PER_LITER * LPM_CONVERSION_FACTOR;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    static int solenoid_closed = 0; // Track solenoid state

    if (lpm > FLOW_RATE_THRESHOLD && !solenoid_closed) {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        solenoid_closed = 1;
        log_data(lpm, 0); // Log solenoid closing
    } else if (lpm < (FLOW_RATE_THRESHOLD - HYSTERESIS) && solenoid_closed) {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        solenoid_closed = 0;
        log_data(lpm, 1); // Log solenoid opening
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp,
                lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Thread function for sensor node
void *sensor_node_thread(void *arg) {
    // Simulate sending data to the central server
    while (program_running) {
        sleep(5); // Simulate sending data every 5 seconds
        // In a real implementation, this thread would send the data
        // to a central server using a suitable communication protocol.
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Shutdown signal received: %d\n", timestamp, signal);
        fclose(log_file);
    }

    pthread_mutex_destroy(&pulse_mutex);

    gpioWrite(SOLENOID_GPIO, 1); // Open solenoid on shutdown
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);
    gpioWrite(SOLENOID_GPIO, 1); // Initialize solenoid to open state

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_MS, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create sensor node thread
    pthread_t sensor_thread;
    if (pthread_create(&sensor_thread, NULL, sensor_node_thread, NULL) != 0) {
        fprintf(stderr, "Error creating sensor node thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        sleep(1); // Sample every 1 second

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(current_pulse_count);
        control_solenoid(lpm);
        log_data(lpm, gpioRead(SOLENOID_GPIO));
    }

    // Clean up (should not reach here if signal handler works correctly)
    pthread_join(sensor_thread, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    return 0;
}

