#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

// Configuration parameters
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345

// GPIO pins
#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24
#define SERVO_PIN 18

// Servo parameters
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_OPEN_PULSE_WIDTH 1500 // us (adjust as needed)
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us (adjust as needed)

// Network parameters
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345

// Global variables
static volatile int running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[20] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;

// Function prototypes
int read_config();
int init_gpio();
int read_hx711();
double calibrate_hx711(double known_weight);
int control_servo(double target_weight);
int dispense_ingredient(double target_weight);
int create_tcp_server();
int handle_client(int client_socket);
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int timeout = 1000; // Timeout after 1000 attempts
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    while (timeout > 0) {
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay

        if (gpioRead(HX711_DATA_PIN) == 0) {
            // Start bit detected
            break;
        }
        timeout--;
        gpioDelay(1); // Small delay
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: HX711 timeout waiting for start bit.\n");
        return -1; // Timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us clock pulse
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us clock pulse
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us clock pulse
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us clock pulse

    data = data ^ 0x800000; // Convert to signed 2's complement

    return data;
}

// Calibrate the HX711
double calibrate_hx711(double known_weight) {
    printf("Place the known weight (%.2f g) on the load cell.\n", known_weight);
    printf("Press Enter to start calibration.\n");
    getchar(); // Wait for user input

    double sum = 0.0;
    int num_readings = 10; // Take multiple readings for averaging

    for (int i = 0; i < num_readings; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed during calibration.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += raw_value;
        gpioDelay(100); // Small delay between readings
    }

    double average_raw_value = sum / num_readings;
    calibration_factor = known_weight / average_raw_value;
    printf("Calibration factor: %.2f\n", calibration_factor);
    return calibration_factor;
}

// Control the servo motor
int control_servo(double target_weight) {
    // Map target weight to pulse width
    double pulse_width = SERVO_MIN_PULSE_WIDTH + (target_weight / 100.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);

    // Limit pulse width to valid range
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    // Set servo pulse width
    gpioServo(SERVO_PIN, (int)pulse_width);

    // Wait for servo to reach the desired position (adjust as needed)
    gpioDelay(500); // Wait 500ms

    return 0;
}

// Dispense ingredient based on target weight
int dispense_ingredient(double target_weight) {
    printf("Opening servo to dispense...\n");
    if (control_servo(target_weight) != 0) {
        fprintf(stderr, "Error: Failed to open servo.\n");
        return -1;
    }

    gpioDelay(1000); // Wait for 1 second

    printf("Closing servo...\n");
    if (control_servo(0.0) != 0) {
        fprintf(stderr, "Error: Failed to close servo.\n");
        return -1;
    }

    return 0;
}

// Create TCP server
int create_tcp_server() {
    int server_socket;
    struct sockaddr_in server_address;

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error: Could not create socket");
        return -1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(server_ip);
    server_address.sin_port = htons(server_port);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error: Could not bind socket");
        close(server_socket);
        return -1;
    }

    // Listen for connections
    if (listen(server_socket, 3) < 0) {
        perror("Error: Could not listen on socket");
        close(server_socket);
        return -1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);
    return server_socket;
}

// Handle client connection
int handle_client(int client_socket) {
    char buffer[1024];
    double target_weight;
    int bytes_received;

    // Receive data from client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error: Could not receive data");
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Parse target weight from JSON
    cJSON *json = cJSON_Parse(buffer);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error: JSON parse error: %s\n", error_ptr);
            log_dispensing_event(0.0, 0.0, "JSON parse error");
        }
        cJSON_Delete(json);
        return -1;
    }

    cJSON *weight_json = cJSON_GetObjectItemCaseSensitive(json, "weight");
    if (!cJSON_IsNumber(weight_json)) {
        fprintf(stderr, "Error: 'weight' is not a number\n");
        log_dispensing_event(0.0, 0.0, "'weight' is not a number");
        cJSON_Delete(json);
        return -1;
    }

    target_weight = weight_json->valuedouble;
    cJSON_Delete(json);

    // Validate target weight
    if (target_weight < 0.0 || target_weight > 1000.0) {
        fprintf(stderr, "Error: Target weight out of range (0.0 - 1000.0 g)\n");
        log_dispensing_event(0.0, 0.0, "Target weight out of range");
        return -1;
    }

    // Dispense ingredient
    if (dispense_ingredient(target_weight) != 0) {
        fprintf(stderr, "Error: Dispensing failed.\n");
        log_dispensing_event(target_weight, 0.0, "Dispensing failed");
        return -1;
    }

    // Read actual weight
    double actual_weight = read_hx711();
    if (actual_weight == -1) {
        fprintf(stderr, "Error: Failed to read actual weight.\n");
        log_dispensing_event(target_weight, 0.0, "Failed to read actual weight");
        return -1;
    }
    actual_weight = actual_weight / calibration_factor;

    // Send actual weight back to client
    char response[50];
    snprintf(response, sizeof(response), "{\"weight\": %.2f}", actual_weight);
    if (send(client_socket, response, strlen(response), 0) < 0) {
        perror("Error: Could not send data");
        log_dispensing_event(target_weight, actual_weight, "Failed to send actual weight");
        return -1;
    }

    printf("Target weight: %.2f g, Actual weight: %.2f g\n", target_weight, actual_weight);
    log_dispensing_event(target_weight, actual_weight, NULL);

    return 0;
}

