#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variable for debounce time
int debounce_time_ms = DEFAULT_DEBOUNCE_TIME;

// Global variable to store the relay state
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int debounce_time_ms);
int toggle_relay(int current_state);
void log_relay_state(int new_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    toggle_relay(relay_state); // Turn off the relay
    gpioTerminate(); // Release pigpio resources
    exit(0); // Exit the program
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO 4 as input for the touch sensor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output for the relay
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    if (toggle_relay(0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF state\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the touch sensor with debouncing
int read_touch_sensor(int debounce_time_ms) {
    int current_state = gpioRead(TOUCH_SENSOR_PIN);
    gpioDelay(debounce_time_ms * 1000); // Convert ms to microseconds
    int confirmed_state = gpioRead(TOUCH_SENSOR_PIN);

    if (current_state != confirmed_state) {
        return 0; // Indicate no touch
    }

    return confirmed_state;
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = !current_state; // Toggle the state
    gpioWrite(RELAY_PIN, new_state);
    return new_state;
}

// Function to log the relay state with a timestamp
void log_relay_state(int new_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (new_state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        long debounce_value = strtol(argv[1], &endptr, 10);

        // Check for errors during conversion
        if (*endptr != '\0' || debounce_value <= 0) {
            fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
            debounce_time_ms = DEFAULT_DEBOUNCE_TIME;
        } else {
            debounce_time_ms = (int)debounce_value;
        }
    }

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch-controlled relay switch started. Debounce time: %d ms\n", debounce_time_ms);

    // Main loop
    while (1) {
        // Read the touch sensor
        int touch_detected = read_touch_sensor(debounce_time_ms);

        // If a touch is detected, toggle the relay
        if (touch_detected == 1) {
            relay_state = toggle_relay(relay_state);
            log_relay_state(relay_state);
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting (10ms)
    }

    return 0; // This line will never be reached due to the infinite loop
}

