            fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
            debounce_time_ms = DEFAULT_DEBOUNCE_TIME;
        } else {
            debounce_time_ms = (int)debounce_value;
        }
    }

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch-controlled relay switch started. Debounce time: %d ms\n", debounce_time_ms);

    // Main loop
    while (1) {
        // Read the touch sensor
        int touch_detected = read_touch_sensor(debounce_time_ms);

        // If a touch is detected, toggle the relay
        if (touch_detected == 1) {
            relay_state = toggle_relay(relay_state);
            log_relay_state(relay_state);
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting (10ms)
    }

    return 0; // This line will never be reached due to the infinite loop
}

