#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define INITIAL_ANGLE 90
#define INITIAL_PULSE_WIDTH 1500

volatile sig_atomic_t terminate = 0;
int current_angle = INITIAL_ANGLE;
int current_pulse_width = INITIAL_PULSE_WIDTH;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int term_flags;
    struct termios original_term, new_term;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-1000000 for 20ms period)
    gpioSetPWMrange(SERVO_PIN, 1000000 / PWM_FREQUENCY);

    // Set initial pulse width
    gpioPWM(SERVO_PIN, current_pulse_width);

    // Save terminal settings
    tcgetattr(STDIN_FILENO, &original_term);
    new_term = original_term;

    // Disable echo and canonical input processing
    new_term.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_term);
    term_flags = new_term.c_lflag;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Servo control started. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (!terminate) {
        int c = getchar();

        if (c == '+') {
            current_angle += 10;
            if (current_angle > MAX_ANGLE) {
                current_angle = MAX_ANGLE;
                current_pulse_width = MAX_PULSE_WIDTH;
            } else {
                current_pulse_width = (int)(((float)(current_angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
            }
            gpioPWM(SERVO_PIN, current_pulse_width);
            printf("Angle: %d, Pulse Width: %d\n", current_angle, current_pulse_width);
        } else if (c == '-') {
            current_angle -= 10;
            if (current_angle < MIN_ANGLE) {
                current_angle = MIN_ANGLE;
                current_pulse_width = MIN_PULSE_WIDTH;
            } else {
                current_pulse_width = (int)(((float)(current_angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
            }
            gpioPWM(SERVO_PIN, current_pulse_width);
            printf("Angle: %d, Pulse Width: %d\n", current_angle, current_pulse_width);
        } else if (c == 'q') {
            fprintf(stderr, "Quitting...\n");
            break;
        }
    }

    // Stop PWM and restore terminal settings
    gpioPWM(SERVO_PIN, 0);
    tcsetattr(STDIN_FILENO, TCSANOW, &original_term);

    fprintf(stderr, "Servo control stopped.\n");

    gpioTerminate();
    return 0;
}

