#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keep_running = 0;
}

// Function to initialize the GPIO line
int init_gpio(struct gpiod_chip **chip_ptr, struct gpiod_line **line_ptr)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }
    *chip_ptr = chip;

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }
    *line_ptr = line;

    int ret = gpiod_line_request_input_flags(line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EDGE_RISING);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the GPIO line and handle events
int read_gpio(struct gpiod_line *line)
{
    struct gpiod_line_event event;
    int ret = gpiod_line_event_wait(line, DEBOUNCE_MS * 1000, &event);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(-ret));
        return -1;
    }

    if (ret > 0) {
        // Rising edge detected
        return 1;
    } else {
        return 0;
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double time_elapsed)
{
    double rpm = (pulse_count / 5.0) * 60.0;
    return rpm;
}

// Function to log RPM data to a file
int log_rpm(double rpm)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(&chip, &line) != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    int pulse_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (keep_running) {
        if (read_gpio(line) == 1) {
            pulse_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double time_elapsed = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (time_elapsed >= 5.0) {
            double rpm = calculate_rpm(pulse_count, time_elapsed);
            printf("RPM: %.2f\n", rpm);
            log_rpm(rpm);
            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
        usleep(1000); // Check every 1 ms
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

