#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define failsafe timeout (in seconds)
#define FAILSAFE_TIMEOUT 10

// Global variables
static volatile int running = 1;
static volatile unsigned long last_interrupt_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int failsafe_active = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void toggle_relay();
void failsafe_check();
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) { // Initialize relay to OFF
        fprintf(stderr, "Failed to set initial relay state\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("GPIO cleanup complete\n");
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

// Function to check for failsafe timeout
void failsafe_check() {
    if (failsafe_active) {
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            last_interrupt_time = gpioTick();
        }

        if (gpioTick() - last_interrupt_time > FAILSAFE_TIMEOUT * 1000000) {
            printf("Failsafe triggered: Relay set to OFF\n");
            gpioWrite(RELAY_PIN, 0);
            failsafe_active = 0; // Reset failsafe after triggering
        }
    }
}

// Interrupt handler for touch sensor
void interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    if (gpio == TOUCH_SENSOR_PIN && level == 1) { // Rising edge detected
        toggle_relay();
        failsafe_active = 1; // Activate failsafe
        last_interrupt_time = gpioTick();
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup_gpio();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        failsafe_check();
        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

