#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define FLOW_SENSOR_PULSES_PER_LITER 450.0
#define LOG_FILE "flow_log.csv"

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count, double time_interval_seconds);
double calculate_pwm(double flow_rate, double target_flow_rate, double Kp);
void log_data(double timestamp_ms, double flow_rate, double valve_position);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Pulse counter interrupt handler
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double time_interval_seconds) {
    return (double)pulse_count / FLOW_SENSOR_PULSES_PER_LITER / time_interval_seconds * 60.0;
}

// Calculate PWM duty cycle using a proportional controller
double calculate_pwm(double flow_rate, double target_flow_rate, double Kp) {
    double error = target_flow_rate - flow_rate;
    double pwm = Kp * error;
    if (pwm < 0) {
        pwm = 0;
    } else if (pwm > PWM_RANGE) {
