#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000 // 100 kHz
#define RFID_SPI_MODE 0
#define RFID_SPI_CS 8
#define RFID_SPI_MOSI 10
#define RFID_SPI_MISO 9
#define RFID_SPI_SCLK 11
#define DEBOUNCE_DELAY_MS 50
#define LOCK_RELEASE_DURATION_S 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(unsigned char *tag);
int validate_tag(const unsigned char *tag, const unsigned char *valid_tag);
int read_button();
void release_locks();
void log_access(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read RFID tag data via SPI
int read_rfid_tag(unsigned char *tag) {
    int result = spiXfer(spi_handle, tag, tag, 10);
    if (result != 10) {
        log_access("SPI read failed.");
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to validate the RFID tag data
int validate_tag(const unsigned char *tag, const unsigned char *valid_tag) {
    if (tag == NULL || valid_tag == NULL) {
        log_access("Invalid tag data passed to validate_tag.");
        return -1;
    }
    for (int i = 0; i < 10; i++) {
        if (tag[i] != valid_tag[i]) {
            return -1; // Tag is invalid
        }
    }
    return 0; // Tag is valid
}

// Function to read the button press
int read_button() {
    int button_state = gpioRead(BUTTON_GPIO);
    if (button_state == PI_LOW) {
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
        if (gpioRead(BUTTON_GPIO) == PI_LOW) {
            return 1; // Button pressed
        }
    }
    return 0; // Button not pressed
}

// Function to release the locks
void release_locks() {
    gpioWrite(LOCK_1_GPIO, PI_LOW);
    gpioWrite(LOCK_2_GPIO, PI_LOW);
    gpioDelay(LOCK_RELEASE_DURATION_S * 1000000); // 5 seconds
    gpioWrite(LOCK_1_GPIO, PI_HIGH);
    gpioWrite(LOCK_2_GPIO, PI_HIGH);
}

// Function to log access attempts
void log_access(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, RFID_SPI_MODE);
    if (spi_handle < 0) {
        log_access("SPI open failed.");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Define valid RFID tag
    unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

    // Main loop
    while (program_running) {
        unsigned char rfid_tag[10];
        int rfid_read_result = read_rfid_tag(rfid_tag);

        if (rfid_read_result == 0) {
            int tag_valid = validate_tag(rfid_tag, valid_tag);
            if (tag_valid == 0) {
                if (read_button()) {
                    log_access("Authentication successful.");
                    release_locks();
                } else {
                    log_access("Button press without valid RFID tag.");
                }
            } else {
                log_access("Invalid RFID tag.");
            }
        } else {
            // Rfid read failed, already logged in read_rfid_tag
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LOCK_1_GPIO, PI_HIGH);
    gpioWrite(LOCK_2_GPIO, PI_HIGH);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

