#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <unistd.h>

// Motor 1 definitions
#define ENA_PIN 23
#define IN1_PIN 24
#define IN2_PIN 25

// Motor 2 definitions
#define ENB_PIN 12
#define IN3_PIN 16
#define IN4_PIN 20

// Encoder 1 definitions
#define ENCODER1_A_PIN 5
#define ENCODER1_B_PIN 6

// Encoder 2 definitions
#define ENCODER2_A_PIN 26
#define ENCODER2_B_PIN 19

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Sample time (ms)
#define SAMPLE_TIME 100

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *ena_line, *in1_line, *in2_line, *enb_line, *in3_line, *in4_line;
static struct gpiod_line *encoder1_a_line, *encoder1_b_line, *encoder2_a_line, *encoder2_b_line;
static int encoder1_count = 0;
static int encoder2_count = 0;
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder2_mutex = PTHREAD_INITIALIZER;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

// Function prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
void set_motor_speed(int motor, int speed);
int calculate_rpm(int encoder_count);
double pid_control(double target_rpm, double current_rpm, double *integral, double *previous_error);
void log_data(double rpm1, double rpm2, double pid_output1, double pid_output2, double p1, double i1, double d1, double p2, double i2, double d2);
void signal_handler(int sig);

// Encoder thread function
void *encoder1_thread(void *arg) {
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(encoder1_a_line, -1);
        if (ret < 0) {
            perror("gpiod_line_event_wait (Encoder 1 A) failed");
            continue; // Or exit thread on error
        }

        ret = gpiod_line_event_read(encoder1_a_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read (Encoder 1 A) failed");
            continue; // Or exit thread on error
        }

        if (event.value == 1) {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count++;
            pthread_mutex_unlock(&encoder1_mutex);

            // Read B pin to determine direction
            int b_value = gpiod_line_get_value(encoder1_b_line);
            if (b_value < 0) {
                perror("gpiod_line_get_value (Encoder 1 B) failed");
            }
        }
    }
    return NULL;
}

void *encoder2_thread(void *arg) {
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(encoder2_a_line, -1);
        if (ret < 0) {
            perror("gpiod_line_event_wait (Encoder 2 A) failed");
            continue; // Or exit thread on error
        }

        ret = gpiod_line_event_read(encoder2_a_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read (Encoder 2 A) failed");
            continue; // Or exit thread on error
        }

        if (event.value == 1) {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_count++;
            pthread_mutex_unlock(&encoder2_mutex);

            // Read B pin to determine direction
            int b_value = gpiod_line_get_value(encoder2_b_line);
            if (b_value < 0) {
                perror("gpiod_line_get_value (Encoder 2 B) failed");
            }
        }
    }
    return NULL;
}

// Function to set motor speed using software PWM
void set_motor_speed(int motor, int speed) {
    if (speed > 100) speed = 100;
    if (speed < -100) speed = -100;

    int ena_value = 0, in1_value = 0, in2_value = 0, enb_value = 0, in3_value = 0, in4_value = 0;

    if (speed > 0) {
        ena_value = 1;
        in1_value = 1;
        in2_value = 0;
    } else if (speed < 0) {
        ena_value = 1;
        in1_value = 0;
        in2_value = 1;
        speed = -speed; // Make speed positive for PWM calculation
    }

    // Software PWM with 100Hz frequency
    int pwm_duty_cycle = (int)((double)speed / 100.0 * 100.0); // Scale speed to 0-100
    int on_time = (int)((double)pwm_duty_cycle / 100.0 * SAMPLE_TIME); // Calculate on time in ms
    int off_time = SAMPLE_TIME - on_time;

    for (int i = 0; i < SAMPLE_TIME; i++) {
        if (i < on_time) {
            if (motor == 1) {
                gpiod_line_set_value(ena_line, ena_value);
