// Function to calculate RPM from encoder count
int calculate_rpm(int encoder_count) {
    return (int)((double)encoder_count * 60.0 / 600.0); // 600 pulses per revolution
}

// Function to implement PID control
double pid_control(double target_rpm, double current_rpm, double *integral, double *previous_error) {
    double error = target_rpm - current_rpm;
    *integral += error * (double)SAMPLE_TIME / 1000.0; // Integrate error over time
    double derivative = (error - *previous_error) / (double)SAMPLE_TIME / 1000.0; // Differentiate error over time
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to log data to file
void log_data(double rpm1, double rpm2, double pid_output1, double pid_output2, double p1, double i1, double d1, double p2, double i2, double d2) {
