            timestamp, rpm1, rpm2, pid_output1, pid_output2, p1, i1, d1, p2, i2, d2);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", sig);

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

