// Encoder thread function
void *encoder1_thread(void *arg) {
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(encoder1_a_line, -1);
        if (ret < 0) {
            perror("gpiod_line_event_wait (Encoder 1 A) failed");
            continue; // Or exit thread on error
        }

        ret = gpiod_line_event_read(encoder1_a_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read (Encoder 1 A) failed");
            continue; // Or exit thread on error
        }

        if (event.value == 1) {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count++;
            pthread_mutex_unlock(&encoder1_mutex);

            // Read B pin to determine direction
            int b_value = gpiod_line_get_value(encoder1_b_line);
            if (b_value < 0) {
                perror("gpiod_line_get_value (Encoder 1 B) failed");
            }
        }
    }
    return NULL;
}

