    // Initialize PID variables
    double integral1 = 0, previous_error1 = 0;
    double integral2 = 0, previous_error2 = 0;
    double pid_output1, pid_output2;
    double p1, i1, d1, p2, i2, d2;

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        // Calculate RPMs
        int rpm1 = calculate_rpm(encoder1_count);
        int rpm2 = calculate_rpm(encoder2_count);

        // Reset encoder counts
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = 0;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate PID outputs
        pid_output1 = pid_control(TARGET_RPM1, (double)rpm1, &integral1, &previous_error1);
        pid_output2 = pid_control(TARGET_RPM2, (double)rpm2, &integral2, &previous_error2);

        // Extract P, I, D components (for logging)
        p1 = KP * (TARGET_RPM1 - (double)rpm1);
        i1 = KI * integral1;
        d1 = KD * ((TARGET_RPM1 - (double)rpm1) - previous_error1) / (double)SAMPLE_TIME / 1000.0;
        p2 = KP * (TARGET_RPM2 - (double)rpm2);
        i2 = KI * integral2;
        d2 = KD * ((TARGET_RPM2 - (double)rpm2) - previous_error2) / (double)SAMPLE_TIME / 1000.0;

        // Set motor speeds
        set_motor_speed(1, (int)pid_output1);
        set_motor_speed(2, (int)pid_output2);

        // Log data
        log_data((double)rpm1, (double)rpm2, pid_output1, pid_output2, p1, i1, d1, p2, i2, d2);

        // Sleep for sample time
        usleep(SAMPLE_TIME * 1000); // Convert ms to us
    }

    // Join encoder threads
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Release GPIO lines and close chip (should not reach here if signal handler works correctly)
    if (ena_line) gpiod_line_release(ena_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (enb_line) gpiod_line_release(enb_line);
    if (in3_line) gpiod_line_release(in3_line);
    if (in4_line) gpiod_line_release(in4_line);
    if (encoder1_a_line) gpiod_line_release(encoder1_a_line);
    if (encoder1_b_line) gpiod_line_release(encoder1_b_line);
    if (encoder2_a_line) gpiod_line_release(encoder2_a_line);
    if (encoder2_b_line) gpiod_line_release(encoder2_b_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    return 0;
}

