#include <signal.h>
#include <pigpio.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_mpr121();
int read_touch_status(unsigned char *status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the MPR121
int initialize_mpr121() {
    unsigned char data[2];

    // Soft reset
    data[0] = 0x80; // Reset command
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error: Failed to send soft reset command.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering
    data[0] = 0x5B; // Filter configuration register
    data[1] = 0x01; // Default filter value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to write filter configuration.\n");
        return -1;
    }

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        data[0] = 0x41 + 2 * i; // Touch threshold register
        data[1] = 0x0F; // Default touch threshold
        if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d.\n", i);
            return -1;
        }

        data[0] = 0x42 + 2 * i; // Release threshold register
        data[1] = 0x0A; // Default release threshold
        if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    data[0] = 0x5E; // Electrode configuration register
    data[1] = 0x3F; // Enable all 12 electrodes
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to enable all electrodes.\n");
        return -1;
    }

    // Enter run mode
    data[0] = 0x5D; // Operation mode register
    data[1] = 0x01; // Enable all electrodes
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to enter run mode.\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(unsigned char *status) {
    if (i2cReadDevice(i2c_handle, (char *)status, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log the relay state
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    unsigned char touch_status[2];
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch status
        if (read_touch_status(touch_status) == 0) {
            int electrode_touched = (touch_status[1] >> 0) & 0x01; // Check electrode 0

            // Control relay based on touch status
            if (electrode_touched && !relay_state) {
                control_relay(1);
                relay_state = 1;
                log_relay_state(relay_state);
            } else if (!electrode_touched && relay_state) {
                control_relay(0);
                relay_state = 0;
                log_relay_state(relay_state);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
        }

        gpioDelay(50); // Delay 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is OFF on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

