#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the solenoid valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *valve1_line;
struct gpiod_line *valve2_line;
FILE *log_file;

// Function prototypes
int initialize_gpio(void);
int activate_valve(int gpio_pin, int duration_ms);
int deactivate_valve(int gpio_pin);
int log_event(int valve_number, int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", sig);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line for Valve 1
    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting GPIO line for Valve 1");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for Valve 2
    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting GPIO line for Valve 2");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(valve1_line, "valve1", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for Valve 1 output");
        gpiod_line_release(valve2_line);
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(valve2_line, "valve2", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for Valve 2 output");
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to activate a valve for a specified duration
int activate_valve(int gpio_pin, int duration_ms) {
    int ret;
    struct timespec ts;
    ts.tv_sec = duration_ms / 1000;
    ts.tv_nsec = (duration_ms % 1000) * 1000000;

    // Activate the valve (set GPIO pin HIGH)
    ret = gpiod_line_set_value(valve1_line, 1);
    if (ret < 0) {
        perror("Error setting GPIO value for Valve 1");
        return -1;
    }

    // Log the event
    log_event(gpio_pin == VALVE1_GPIO ? 1 : 2, 1);

    // Wait for the specified duration
    nanosleep(&ts, NULL);

    // Deactivate the valve (set GPIO pin LOW)
    ret = gpiod_line_set_value(valve1_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO value for Valve 1");
        return -1;
    }

    return 0;
}

// Function to deactivate a valve
int deactivate_valve(int gpio_pin) {
    int ret;

    // Deactivate the valve (set GPIO pin LOW)
    ret = gpiod_line_set_value(valve1_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO value for Valve 1");
        return -1;
    }

    // Log the event
    log_event(gpio_pin == VALVE1_GPIO ? 1 : 2, 0);

    return 0;
}

// Function to log valve events to a file
int log_event(int valve_number, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write log entry
    fprintf(log_file, "%s - Valve %d: %s\n", timestamp, valve_number, state ? "ON" : "OFF");

    // Close log file
    fclose(log_file);

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio(void) {
    int ret;

    // Release GPIO lines
    ret = gpiod_line_release(valve1_line);
    if (ret < 0) {
        perror("Error releasing GPIO line for Valve 1");
    }

    ret = gpiod_line_release(valve2_line);
    if (ret < 0) {
        perror("Error releasing GPIO line for Valve 2");
    }

    // Close GPIO chip
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        perror("Error closing GPIO chip");
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1 for 500ms
        if (activate_valve(VALVE1_GPIO, 500) < 0) {
            fprintf(stderr, "Error activating Valve 1. Exiting.\n");
            cleanup_gpio();
            return 1;
        }

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2 for 1000ms
        if (activate_valve(VALVE2_GPIO, 1000) < 0) {
            fprintf(stderr, "Error activating Valve 2. Exiting.\n");
            cleanup_gpio();
            return 1;
        }

        // Pause for 10 seconds
        sleep(10);
    }

    return 0;
}

