#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_SECONDS 2
#define LOG_FILE "door_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to log events with millisecond precision
void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    if (log_file != NULL) {
        fprintf(log_file, "%ld.%03ld: %s\n", ts.tv_sec, milliseconds, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle motion detection and unlock the door
void handle_motion() {
    static time_t last_unlock_time = 0;
    time_t current_time = time(NULL);

    if (difftime(current_time, last_unlock_time) >= RATE_LIMIT_SECONDS) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
        log_event("Door Unlocked");
        gpioDelay(UNLOCK_DURATION_MS);
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
        last_unlock_time = current_time;
        log_event("Door Locked");
    } else {
        log_event("Rate Limited");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Enable pull-down resistor

    // Initialize relay to OFF state
    gpioWrite(RELAY_GPIO, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (gpioRead(PIR_GPIO) == 1) {
            handle_motion();
        }
        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

