#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the minimum and maximum durations for each step (in milliseconds)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Global variable to indicate program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        shutdown = 1;
        printf("\nCaught SIGINT, stopping motors and exiting...\n");
    }
}

// Function to generate a random number between min and max
int random_number(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random duration between MIN_DURATION and MAX_DURATION
int random_duration() {
    return random_number(MIN_DURATION, MAX_DURATION);
}

// Function to generate a random duty cycle between 0 and 255
int random_duty_cycle() {
    return random_number(0, 255);
}

// Function to generate a random pattern
int* generate_pattern(int steps) {
    int* pattern = (int*)malloc(steps * sizeof(int));
    if (pattern == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for pattern.\n");
        return NULL;
    }

    for (int i = 0; i < steps; i++) {
        pattern[i] = random_duty_cycle();
    }

    return pattern;
}

// Function to play a pattern
void play_pattern(int* pattern, int steps, int duration) {
    for (int i = 0; i < steps; i++) {
        gpioPWM(MOTOR1_PIN, pattern[i]);
        gpioPWM(MOTOR2_PIN, pattern[i]);
        gpioDelay(random_duration());
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode.\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode.\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_PIN, 255);
    gpioSetPWMrange(MOTOR2_PIN, 255);

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!shutdown) {
        // Generate a random number of steps for the pattern
        int steps = random_number(MIN_STEPS, MAX_STEPS);

        // Generate the pattern
        int* pattern = generate_pattern(steps);
        if (pattern == NULL) {
            // Error already printed in generate_pattern
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Play the pattern
        play_pattern(pattern, steps, 0); // Duration is not used in play_pattern, so pass 0

        // Free the allocated memory
        free(pattern);
    }

    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

