    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > (int)(TIMEOUT_DURATION * 1000000)) { // 0.5 seconds in microseconds
            fprintf(error_file, "Error: HX711 timeout waiting for data pin to go low.\n");
            fflush(error_file);
            return -1; // Indicate timeout
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value, CalibrationData calibration) {
    return (raw_value - calibration.offset) / calibration.scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage lock
        printf("Weight: %.2f kg, Lock Engaged\n", weight);
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Release lock
        printf("Weight: %.2f kg, Lock Released\n", weight);
    }
}

// Function to log weight readings to a file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file);
}

// Function to load calibration data from file
int load_calibration_data(CalibrationData *calibration) {
    FILE *fp = fopen("calibration.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt for reading.\n");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read calibration data from calibration.txt.\n");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "%lf %lf", &calibration->scale_factor, &calibration->offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data format in calibration.txt.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to save calibration data to file
int save_calibration_data(const CalibrationData *calibration) {
    FILE *fp = fopen("calibration.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt for writing.\n");
        return -1;
    }

    fprintf(fp, "%lf %lf", calibration->scale_factor, calibration->offset);
    fclose(fp);
    return 0;
}

// Function to perform sensor calibration
int calibrate_sensor(CalibrationData *calibration) {
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(error_file, "Error: Calibration failed due to HX711 timeout.\n");
            fflush(error_file);
            return -1;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    calibration->offset = sum / CALIBRATION_READINGS;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

