    CalibrationData calibration;
    calibration.scale_factor = DEFAULT_SCALE_FACTOR;
    calibration.offset = DEFAULT_OFFSET;

    if (load_calibration_data(&calibration) != 0) {
        fprintf(stderr, "Warning: Could not load calibration data. Using default values.\n");
    }

