#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control parameters
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DUTY_CYCLE 150

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50

// Define motor run time
#define MOTOR_RUN_TIME_S 5

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_window();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, stopping motor and exiting...");
    stop_window();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        if (readings[i] == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    return (low_count >= DEBOUNCE_READINGS / 2) ? 0 : 1; // Return 0 if rain detected, 1 otherwise
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE);
    gpioPWM(MOTOR_PWM_PIN, DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Convert seconds to microseconds
    stop_window();
    log_event("Window closed.");
}

// Function to stop the window
void stop_window() {
    log_event("Stopping window...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Window stopped.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message)-1, "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    log_event("Window control program started.");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) {
            log_event("Rain detected!");
            close_window();
        }

        gpioDelay(60 * 1000000); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_window();
    gpioTerminate();
    closelog();

    return 0;
}

