#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define weight threshold (in grams)
#define WEIGHT_THRESHOLD 100

// Define solenoid activation time (in seconds)
#define SOLENOID_ACTIVATION_TIME 5

// Define timeout for HX711 read (in microseconds)
#define HX711_TIMEOUT 1000000 // 1 second

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float calculate_weight(int raw_value);
void activate_solenoid();
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Deactivate solenoid
    gpioWrite(SOLENOID_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    // Set DT pin as input
    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 DT line stuck high.\n");
            return -1; // Indicate error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT) == 1) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK 25th time to set gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
float calculate_weight(int raw_value) {
    // Calibration parameters (adjust these based on your setup)
    float offset = 0;  // Zero offset
    float scale = 1;   // Sensitivity (grams per unit)

    return (float)(raw_value - offset) / scale;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Wait for activation time
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
}

// Function to log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

