// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_ACTIVATE_TIME 5 // seconds
#define HX711_TIMEOUT_US 100000 // 100ms timeout

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0; // Default value

// Function prototypes
int read_hx711();
double convert_to_kg(int raw_value);
void control_solenoid(int activate);
void log_event(double weight);
void calibrate_load_cell();
void signal_handler(int signal);
int write_calibration_factor_to_file();
int read_calibration_factor_from_file();

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout error\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Control the solenoid lock
void control_solenoid(int activate) {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, activate);
    if (activate) {
        printf("Solenoid activated for %d seconds\n", SOLENOID_ACTIVATE_TIME);
        gpioDelay(SOLENOID_ACTIVATE_TIME * 1000000); // Delay in microseconds
        gpioWrite(SOLENOID_PIN, 0);
        printf("Solenoid deactivated\n");
    }
}

// Log weight event to file
void log_event(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Weight: %.2f kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

// Calibrate the load cell
void calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return;
    }

    printf("Reading raw value...\n");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Failed to read raw value during calibration.\n");
        return;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %.2f\n", calibration_factor);

    if (write_calibration_factor_to_file() != 0) {
        fprintf(stderr, "Failed to write calibration factor to file.\n");
    }
}

// Write calibration factor to file
int write_calibration_factor_to_file() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing!\n");
        return -1;
    }
    fprintf(fp, "%lf", calibration_factor);
    fclose(fp);
    return 0;
}

// Read calibration factor from file
int read_calibration_factor_from_file() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for reading! Using default calibration factor.\n");
        return -1; // Indicate failure to read, use default
    }

    double temp_factor;
    if (fscanf(fp, "%lf", &temp_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file! Using default calibration factor.\n");
        fclose(fp);
        return -1; // Indicate failure to read, use default
    }
    fclose(fp);
    calibration_factor = temp_factor;
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Unlock the door
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Read calibration factor from file
    if (read_calibration_factor_from_file() != 0) {
        // If reading fails, use the default calibration factor
        printf("Using default calibration factor: 1.0\n");
    }

    // Calibrate the load cell
    calibrate_load_cell();

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_kg(raw_value);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                log_event(weight);
                control_solenoid(1); // Activate the solenoid
            }
        } else {
            fprintf(stderr, "Failed to read weight. Retrying...\n");
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Unlock the door
    gpioTerminate(); // Terminate pigpio

    return 0;
}

