#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *relay_line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int toggle_relay(struct gpiod_line *relay_line);
int log_event(const char *event);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to toggle the relay state
int toggle_relay(struct gpiod_line *relay_line) {
    int current_value = gpiod_line_get_value(relay_line);
    if (current_value < 0) {
        fprintf(stderr, "Error getting current relay value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    int new_value = (current_value == 0) ? 1 : 0; // Toggle the value
    if (gpiod_line_set_value(relay_line, new_value) < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    return 0;
}

// Function to log the relay event
int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request sensor line as input
    if (gpiod_line_request(sensor_line, "sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting sensor line: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request relay line as output
    if (gpiod_line_request(relay_line, "relay", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error requesting relay line: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int relay_state = 0; // 0 = OFF, 1 = ON
    while (1) {
        int sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value == 0) { // Obstacle detected (active-low)
            if (toggle_relay(relay_line) == 0) {
