int toggle_relay(struct gpiod_line *relay_line) {
    int current_value = gpiod_line_get_value(relay_line);
    if (current_value < 0) {
        fprintf(stderr, "Error getting current relay value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    int new_value = (current_value == 0) ? 1 : 0; // Toggle the value
    if (gpiod_line_set_value(relay_line, new_value) < 0) {
