#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pin and chip name
#define GPIO_PIN 18
#define GPIO_CHIP "gpiochip0"

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int valve_gpio = GPIO_PIN; // Store GPIO pin number

// Function prototypes
int read_config(const char *filename, int *duration);
int validate_duration(int duration);
int control_valve(struct gpiod_line *line, int duration);
void signal_handler(int sig);
void log_message(const char *message);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        log_message("Received signal, shutting down...");
    }
}

// Function to read configuration from file
int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    // Remove trailing newline character
    line[strcspn(line, "\n")] = 0;

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Error: Invalid config file format in %s\n", filename);
        fclose(fp);
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: Invalid config file format in %s\n", filename);
        fclose(fp);
        return -1;
    }

    char *endptr;
    long val = strtol(value, &endptr, 10);

    if (*endptr != '\0' || val <= 0 || val > 3600) {
        fprintf(stderr, "Error: Invalid duration value in %s\n", filename);
        fclose(fp);
        return -1;
    }

    *duration = (int)val;
    fclose(fp);
    return 0;
}

// Function to validate duration
int validate_duration(int duration) {
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds\n");
        return -1;
    }
    return 0;
}

// Function to control the valve
int control_valve(struct gpiod_line *line, int duration) {
    if (line == NULL) {
        fprintf(stderr, "Error: Valve line is NULL\n");
        return -1;
    }

    // Activate valve (set GPIO high)
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO high: %s\n", strerror(errno));
        return -1;
    }
    log_message("Valve activated");

    // Wait for the specified duration
    struct timespec req = {0};
    req.tv_sec = duration;
    req.tv_nsec = 0;
    if (nanosleep(&req, NULL) < 0) {
        fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
        return -1;
    }

    // Deactivate valve (set GPIO low)
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO low: %s\n", strerror(errno));
        return -1;
    }
    log_message("Valve deactivated");

    return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stdout, "[%s] %s\n", timestamp, message);
    fflush(stdout); // Ensure the message is immediately written to stdout
}

int main() {
    int duration = 0;

    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Read configuration from file
    if (read_config("watering.conf", &duration) != 0) {
        fprintf(stderr, "Error reading configuration, exiting\n");
        return 1;
    }

    // Validate duration
    if (validate_duration(duration) != 0) {
        fprintf(stderr, "Error validating duration, exiting\n");
        return 1;
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, valve_gpio);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", valve_gpio, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line as output
    if (gpiod_line_request_output(line, "watering_system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (control_valve(line, duration) != 0) {
            fprintf(stderr, "Error controlling valve, exiting\n");
            break;
        }
    }

    // Cleanup
    gpiod_line_set_value(line, 0); // Ensure valve is off on exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    log_message("Watering system stopped");
    return 0;
}

