int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sensor pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Set motor control pins as outputs
    gpioSetMode(LEFT_MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_IN3, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_IN4, PI_OUTPUT);

