    gpioSetPWMfrequency(LEFT_MOTOR_IN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(LEFT_MOTOR_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_IN3, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_IN4, PWM_FREQUENCY);

