#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_THRESHOLD 150
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char buf[2];
    int result;

    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd); // Send configuration command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(180); // Wait for measurement (180ms)

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2); // Read 2 bytes of data
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the relay (1 = ON, 0 = OFF)
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Grow lamp control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read illuminance
        if (read_bh1750(&lux) == 0) {
            // Control relay based on lux threshold
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay ON\n", lux);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay OFF\n", lux);
            } else {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(100); // Check every 100ms
    }

    cleanup();
    return 0;
}

