#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *motor1_line;
struct gpiod_line *motor2_line;

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize a GPIO line for output
int init_gpio_line(struct gpiod_chip *chip, struct gpiod_line **line, int pin)
{
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    int ret = gpiod_line_request_output(*line, "vibration-motor", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to pulse a vibration motor
int pulse_motor(struct gpiod_line *line, int duration_ms)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value (HIGH)");
        return -1;
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value (LOW)");
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Initialize GPIO lines for both motors
    if (init_gpio_line(chip, &motor1_line, MOTOR1_PIN) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (init_gpio_line(chip, &motor2_line, MOTOR2_PIN) < 0) {
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to pulse the motors
    while (1) {
        if (pulse_motor(motor1_line, 200) < 0) {
            signal_handler(SIGTERM); // Simulate a termination signal
            break; // Exit the loop if there's an error
        }
        if (pulse_motor(motor2_line, 300) < 0) {
            signal_handler(SIGTERM); // Simulate a termination signal
            break; // Exit the loop if there's an error
        }
    }

    // Cleanup (should not reach here normally due to signal handler)
    gpiod_line_release(motor1_line);
    gpiod_line_release(motor2_line);
    gpiod_chip_close(chip);

    return 0;
}

