#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <zmq.h>
#include <gpiod.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ address and port
#define ZMQ_ADDRESS "tcp://*:5555"

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Define alarm duration (seconds)
#define ALARM_DURATION 1

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(int pin, const char *chipname);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
int gpio_release(int pin, const char *chipname);
void *zmq_context(void);
void *zmq_socket(void *context, int socket_type);
int zmq_bind(void *socket, const char *address);
int zmq_connect(void *socket, const char *address);
int zmq_publish(void *socket, const char *topic, const char *message);
int zmq_subscribe(void *socket, const char *topic);
int zmq_recv_message(void *socket, char *message, int max_size);
void signal_handler(int sig);
void cleanup(void);

// GPIO initialization function
int gpio_init(int pin, const char *chipname) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line, "sound_sensor");
    if (ret < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO get value function
int gpio_get_value(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int value;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error getting GPIO value");
        gpiod_chip_close(chip);
        return -1;
    }

    value = ret;
    gpiod_chip_close(chip);
    return value;
}

// GPIO release function
int gpio_release(int pin, const char *chipname) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// ZeroMQ context function
void *zmq_context(void) {
    void *context = zmq_ctx_new();
    if (!context) {
        perror("Error creating ZeroMQ context");
        return NULL;
    }
    return context;
}

// ZeroMQ socket function
void *zmq_socket(void *context, int socket_type) {
    void *socket = zmq_socket(context, socket_type);
    if (!socket) {
        perror("Error creating ZeroMQ socket");
        return NULL;
    }
    return socket;
}

// ZeroMQ bind function
int zmq_bind(void *socket, const char *address) {
    int rc = zmq_bind(socket, address);
    if (rc != 0) {
        perror("Error binding ZeroMQ socket");
        return -1;
    }
    return 0;
}

// ZeroMQ connect function
int zmq_connect(void *socket, const char *address) {
    int rc = zmq_connect(socket, address);
    if (rc != 0) {
        perror("Error connecting ZeroMQ socket");
        return -1;
    }
    return 0;
}

// ZeroMQ publish function
int zmq_publish(void *socket, const char *topic, const char *message) {
    zmq_msg_t msg;
    int rc;

    zmq_msg_init_size(&msg, strlen(message));
    memcpy(zmq_msg_data(&msg), message, strlen(message));

    rc = zmq_msg_send(&msg, socket, ZMQ_DONTWAIT);
    zmq_msg_close(&msg);

    if (rc == -1) {
        perror("Error publishing message");
        return -1;
    }

    return 0;
}

// ZeroMQ subscribe function
int zmq_subscribe(void *socket, const char *topic) {
    int rc = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, topic, strlen(topic));
    if (rc != 0) {
        perror("Error subscribing to topic");
        return -1;
    }
    return 0;
}

// ZeroMQ receive message function
int zmq_recv_message(void *socket, char *message, int max_size) {
    zmq_msg_t msg;
    int rc;

    rc = zmq_msg_init(&msg);
    if (rc != 0) {
        perror("Error initializing message");
        return -1;
    }

    rc = zmq_msg_recv(&msg, socket, 0);
    if (rc == -1) {
        zmq_msg_close(&msg);
        return -1;
    }

    strncpy(message, zmq_msg_data(&msg), max_size - 1);
    message[max_size - 1] = '\0';
    zmq_msg_close(&msg);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup function
void cleanup(void) {
    // Release GPIO lines
    gpio_release(SOUND_SENSOR_PIN, "gpiochip0");
    gpio_release(ALARM_LED_PIN, "gpiochip0");

    // Close ZeroMQ sockets and context
    if (zmq_context != NULL) {
        zmq_close(zmq_context);
    }
    if (zmq_socket != NULL) {
        zmq_close(zmq_socket);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    void *context = NULL;
    void *socket = NULL;
    char *message = NULL;
    int rc;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(SOUND_SENSOR_PIN, "gpiochip0") != 0) {
        fprintf(stderr, "Failed to initialize sound sensor GPIO. Exiting.\n");
        cleanup();
        return 1;
    }
    if (gpio_init(ALARM_LED_PIN, "gpiochip0") != 0) {
        fprintf(stderr, "Failed to initialize alarm LED GPIO. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize ZeroMQ
    context = zmq_context();
    if (context == NULL) {
        cleanup();
        return 1;
    }

    if (argc == 2 && strcmp(argv[1], "sound_sensor") == 0) {
        // Sound sensor mode
        socket = zmq_socket(context, ZMQ_PUB);
        if (socket == NULL) {
            cleanup();
            return 1;
        }

        if (zmq_bind(socket, ZMQ_ADDRESS) != 0) {
            cleanup();
            return 1;
        }

        printf("Sound sensor mode started. Publishing alerts on %s\n", ZMQ_ADDRESS);

        while (!terminate) {
            int sound_detected = gpio_get_value(SOUND_SENSOR_PIN);
            if (sound_detected == 0) {
                // Sound detected
                time_t now = time(NULL);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                char message_buffer[100];
                snprintf(message_buffer, sizeof(message_buffer), "%s - Sound detected!", timestamp);

                if (zmq_publish(socket, ZMQ_TOPIC, message_buffer) != 0) {
                    fprintf(stderr, "Error publishing message. Continuing...\n");
                }
                printf("Published: %s\n", message_buffer);
            }
            nanosleep(&sleep_time, NULL);
        }

    } else if (argc == 2 && strcmp(argv[1], "alarm_node") == 0) {
        // Alarm node mode
        socket = zmq_socket(context, ZMQ_SUB);
        if (socket == NULL) {
            cleanup();
            return 1;
        }

        if (zmq_connect(socket, ZMQ_ADDRESS) != 0) {
            cleanup();
            return 1;
        }

        if (zmq_subscribe(socket, ZMQ_TOPIC) != 0) {
            cleanup();
            return 1;
        }

        printf("Alarm node mode started. Subscribing to %s\n", ZMQ_ADDRESS);

        while (!terminate) {
            if (zmq_recv_message(socket, message, 100) == 0) {
                printf("Received message: %s\n", message);

                // Activate alarm LED
                gpio_set_value(ALARM_LED_PIN, 1);
                sleep(ALARM_DURATION);
                gpio_set_value(ALARM_LED_PIN, 0);
            } else {
                // No message received, avoid busy-waiting
                nanosleep(&sleep_time, NULL);
            }
        }

    } else {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        cleanup();
        return 1;
    }

    cleanup();
    return 0;
}

