    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(SOUND_SENSOR_PIN, "gpiochip0") != 0) {
        fprintf(stderr, "Failed to initialize sound sensor GPIO. Exiting.\n");
        cleanup();
        return 1;
    }
    if (gpio_init(ALARM_LED_PIN, "gpiochip0") != 0) {
