                // Sound detected
                time_t now = time(NULL);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                char message_buffer[100];
                snprintf(message_buffer, sizeof(message_buffer), "%s - Sound detected!", timestamp);

                if (zmq_publish(socket, ZMQ_TOPIC, message_buffer) != 0) {
                    fprintf(stderr, "Error publishing message. Continuing...\n");
                }
                printf("Published: %s\n", message_buffer);
            }
            nanosleep(&sleep_time, NULL);
        }

    } else if (argc == 2 && strcmp(argv[1], "alarm_node") == 0) {
        // Alarm node mode
        socket = zmq_socket(context, ZMQ_SUB);
        if (socket == NULL) {
            cleanup();
            return 1;
        }

        if (zmq_connect(socket, ZMQ_ADDRESS) != 0) {
            cleanup();
            return 1;
        }

        if (zmq_subscribe(socket, ZMQ_TOPIC) != 0) {
            cleanup();
            return 1;
        }

        printf("Alarm node mode started. Subscribing to %s\n", ZMQ_ADDRESS);

        while (!terminate) {
            if (zmq_recv_message(socket, message, 100) == 0) {
                printf("Received message: %s\n", message);

                // Activate alarm LED
                gpio_set_value(ALARM_LED_PIN, 1);
                sleep(ALARM_DURATION);
                gpio_set_value(ALARM_LED_PIN, 0);
            } else {
                // No message received, avoid busy-waiting
                nanosleep(&sleep_time, NULL);
            }
        }

    } else {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        cleanup();
        return 1;
    }

    cleanup();
    return 0;
}

