#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>
#include <time.h>

// Configuration
#define IR_GPIO 17          // BCM GPIO pin for IR receiver
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100

// NEC Protocol Constants
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_CHECKSUM_BITS 16

// Global Variables
static volatile int pulse_count = 0;
static volatile uint32_t pulse_lengths[PULSE_BUFFER_SIZE];
static volatile int last_tick = 0;
static volatile int nec_address = 0;
static volatile int nec_command = 0;
static volatile int nec_inverted_address = 0;
static volatile int nec_inverted_command = 0;
static volatile int nec_checksum = 0;
static volatile int nec_valid = 0;
static struct mosquitto *mqtt_client = NULL;

// Function Prototypes
void ir_callback(int gpio, int level, uint32_t tick, void *user);
int decode_nec();
int validate_nec();
int publish_mqtt(const char *json_payload);
void signal_handler(int signal);

// NEC Decoding Lookup Table
const int nec_lookup[2][2] = {
    {0, 1},  // Mark (0), Space (0)
    {1, 0}   // Mark (1), Space (1)
};

// Function to convert pulse length to microseconds
int pulse_to_micros(uint32_t pulse_length) {
    return pulse_length / 1000; // pigpio uses microseconds
}

// Callback function for IR receiver
void ir_callback(int gpio, int level, uint32_t tick, void *user) {
    int pulse_length = tick - last_tick;
    last_tick = tick;

    if (pulse_length > 10000) {
        // Reset pulse count and buffer on long gap
        pulse_count = 0;
        nec_valid = 0; // Reset validity flag
        return;
    }

    if (pulse_count < PULSE_BUFFER_SIZE) {
        pulse_lengths[pulse_count++] = pulse_length;
    } else {
        // Buffer overflow
        syslog(LOG_WARNING, "Pulse buffer overflow");
        pulse_count = 0;
        nec_valid = 0; // Reset validity flag
        return;
    }

    if (level == 0) { // Falling edge
        if (pulse_count >= 68) { // Expecting at least 68 pulses for NEC
            if (decode_nec()) {
                if (validate_nec()) {
                    nec_valid = 1;
                    syslog(LOG_INFO, "NEC decoded: Address = %d, Command = %d", nec_address, nec_command);
                } else {
                    syslog(LOG_WARNING, "NEC validation failed");
                    nec_valid = 0;
                }
            } else {
                syslog(LOG_WARNING, "NEC decoding failed");
                nec_valid = 0;
            }
            pulse_count = 0; // Reset for next frame
        }
    }
}

// Function to decode NEC frame
int decode_nec() {
    int i, bit;
    uint32_t address = 0;
    uint32_t command = 0;

    // Check for header
    if (pulse_lengths[0] < NEC_HDR_MARK - 500 || pulse_lengths[0] > NEC_HDR_MARK + 500 ||
        pulse_lengths[1] < NEC_HDR_SPACE - 500 || pulse_lengths[1] > NEC_HDR_SPACE + 500) {
        return 0;
    }

    // Decode address (8 bits)
    for (i = 2; i < 10; i++) {
        bit = nec_lookup[pulse_to_micros(pulse_lengths[i]) > NEC_BIT_MARK][pulse_to_micros(pulse_lengths[i + 1]) > NEC_ZERO_SPACE];
        address = (address << 1) | bit;
        i++;
    }

    // Decode command (8 bits)
    for (i = 10; i < 18; i++) {
        bit = nec_lookup[pulse_to_micros(pulse_lengths[i]) > NEC_BIT_MARK][pulse_to_micros(pulse_lengths[i + 1]) > NEC_ZERO_SPACE];
        command = (command << 1) | bit;
        i++;
    }

    // Decode inverted address (8 bits)
    for (i = 18; i < 26; i++) {
        bit = nec_lookup[pulse_to_micros(pulse_lengths[i]) > NEC_BIT_MARK][pulse_to_micros(pulse_lengths[i + 1]) > NEC_ZERO_SPACE];
        nec_inverted_address = (nec_inverted_address << 1) | bit;
        i++;
    }

    // Decode inverted command (8 bits)
    for (i = 26; i < 34; i++) {
        bit = nec_lookup[pulse_to_micros(pulse_lengths[i]) > NEC_BIT_MARK][pulse_to_micros(pulse_lengths[i + 1]) > NEC_ZERO_SPACE];
        nec_inverted_command = (nec_inverted_command << 1) | bit;
        i++;
    }

    // Decode checksum (16 bits)
    for (i = 34; i < 50; i++) {
        bit = nec_lookup[pulse_to_micros(pulse_lengths[i]) > NEC_BIT_MARK][pulse_to_micros(pulse_lengths[i + 1]) > NEC_ZERO_SPACE];
        nec_checksum = (nec_checksum << 1) | bit;
        i++;
    }

    nec_address = address;
    nec_command = command;

    return 1;
}

// Function to validate NEC checksum
int validate_nec() {
    uint32_t address_inv = ~nec_address & 0xFF;
    uint32_t command_inv = ~nec_command & 0xFF;
    uint32_t checksum_calculated = (address_inv << 8) | command_inv;

    return (checksum_calculated == nec_checksum);
}

// Function to publish MQTT message
int publish_mqtt(const char *json_payload) {
    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(json_payload), json_payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return 0;
    }
    return 1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    int rc = 0;
    json_t *root;
    json_t *address, *command;
    char *json_string;

    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode and alert function
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "MQTT client initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    rc = mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (nec_valid) {
            // Create JSON payload
            root = json_object();
            address = json_integer(nec_address);
            command = json_integer(nec_command);
            json_object_set_new(root, "address", address);
            json_object_set_new(root, "command", command);
            json_string = json_dumps(root, JSON_REAL_PRECISION(5));

            // Publish MQTT message
            if (!publish_mqtt(json_string)) {
                syslog(LOG_ERR, "Failed to publish MQTT message");
            }

            json_decref(root);
            free(json_string);
            nec_valid = 0; // Reset validity flag
        }
        usleep(10000); // Sleep for 10ms
    }

    // Cleanup (should not reach here under normal circumstances)
    mosquitto_loop_stop(mqtt_client, false);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

