#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SENSOR_ADDRS {0x23, 0x24, 0x25, 0x26}
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x20
#define LUX_CONVERSION_FACTOR 1.2

// Global variables
static volatile int keep_running = 1;
static int i2c_fds[NUM_SENSORS];
static int udp_socket = -1;

// Function prototypes
int init_i2c(int sensor_id, int address);
float read_bh1750(int fd);
float convert_to_lux(uint16_t raw_data);
void format_data(float lux_values[], char *buffer, size_t buffer_size);
int send_udp_packet(const char *packet);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// Initialize I2C bus
int init_i2c(int sensor_id, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1"); // Use /dev/i2c-1 for all sensors
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from BH1750 sensor
float read_bh1750(int fd) {
    uint8_t data[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(180000); // Wait 180ms for conversion

        if (read(fd, data, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        uint16_t raw_data = (data[0] << 8) | data[1];
        return convert_to_lux(raw_data);
    }

    fprintf(stderr, "Failed to read from sensor after multiple retries.\n");
    return NAN; // Return NaN on failure
}

// Convert raw data to lux
float convert_to_lux(uint16_t raw_data) {
    return (float)raw_data / LUX_CONVERSION_FACTOR;
}

// Format data into a string
void format_data(float lux_values[], char *buffer, size_t buffer_size) {
    int i;
    int count = 0;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (!isnan(lux_values[i])) {
            count++;
        }
    }

    int start = 0;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (!isnan(lux_values[i])) {
            if (i > 0) {
                start += strlen(sensor_id_to_string(i)) + 1; // +1 for the comma
            }
            snprintf(buffer + start, buffer_size - start, "%s,%.1f", sensor_id_to_string(i), lux_values[i]);
        }
    }

    // Remove trailing semicolon if not all sensors are present
    size_t len = strlen(buffer);
    if (count < NUM_SENSORS) {
        if (len > 0 && buffer[len - 1] == ';') {
            buffer[len - 1] = '\0';
        }
    }
}

// Convert sensor ID to string
char* sensor_id_to_string(int sensor_id) {
    static char id_str[3]; // Static to persist across calls
    snprintf(id_str, sizeof(id_str), "%d", sensor_id + 1); // +1 because IDs are 1-based
    return id_str;
}

// Send UDP packet
int send_udp_packet(const char *packet) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, packet, strlen(packet), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending UDP packet: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    int i;
    for (i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
}

int main() {
    int i;
    float lux_values[NUM_SENSORS];
    char packet_buffer[256];

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C devices
    int sensor_addrs[] = SENSOR_ADDRS;
    for (i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = init_i2c(i, sensor_addrs[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize I2C device for sensor %d at address 0x%02x\n", i + 1, sensor_addrs[i]);
            cleanup();
            return 1;
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read sensor data
        for (i = 0; i < NUM_SENSORS; i++) {
            lux_values[i] = read_bh1750(i2c_fds[i]);
        }

        // Format data
        format_data(lux_values, packet_buffer, sizeof(packet_buffer));

        // Send UDP packet
        if (send_udp_packet(packet_buffer) != 0) {
            fprintf(stderr, "Failed to send UDP packet.\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

