#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define LOG_FILE "airflow_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold configuration data
typedef struct {
    char i2c_bus[20];
    int sensor_address;
    char log_file_path[50];
} config_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_airflow(int fd);
float convert_to_slpm(int raw_value);
int log_data(const char *timestamp, float flow_rate);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    exit(0);
}

// Initialize I2C communication
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read airflow data from the sensor
int read_airflow(int fd) {
    unsigned char buffer[2];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        if (write(fd, "", 0) != 0) {
            perror("Error writing to I2C device");
            retries--;
            usleep(100000); // 100ms delay
            continue;
        }

        bytes_read = read(fd, buffer, 2);
        if (bytes_read == 2) {
            return (buffer[0] << 8) | buffer[1];
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // 100ms delay
        }
    }

    fprintf(stderr, "Failed to read airflow after multiple retries.\n");
    return -1; // Indicate failure
}

// Convert raw sensor value to SLPM
float convert_to_slpm(int raw_value) {
    return (raw_value - 3277) * 0.1;
}

// Log data to file
int log_data(const char *timestamp, float flow_rate) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to preserve value between calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .sensor_address = SENSOR_ADDR,
        .log_file_path = LOG_FILE
    };

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(config.i2c_bus, config.sensor_address);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_value = read_airflow(i2c_fd);
        if (raw_value != -1) {
            float flow_rate = convert_to_slpm(raw_value);
            char* timestamp = get_timestamp();
            if (log_data(timestamp, flow_rate) == 0) {
                printf("%s, Flow: %.2f SLPM\n", timestamp, flow_rate);
            } else {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }

        sleep(1); // Sample once per second
    }

    // Cleanup (should not reach here if signal handler works)
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

