#define AS7341_F8DATAH 0x6E
#define AS7341_F8DATAL 0x6F
#define AS7341_CDATAH 0x70
#define AS7341_CDATAL 0x71
#define AS7341_NIRDATAH 0x72
#define AS7341_NIRDATAL 0x73

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int as7341_init(int fd);
int read_spectral_data(int fd, uint16_t *data);
float calculate_lux(uint16_t *data);
int log_data(FILE *fp, float lux);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    uint8_t buffer[1];
    if (read(fd, buffer, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }

    return buffer[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, buffer, 2) != 2) {
        perror("Error: Could not write register value");
        return -1;
    }

    return 0;
}

// AS7341 initialization function
int as7341_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, AS7341_WHO_AM_I);
    if (who_am_i != 0x19) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x19\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_reg(fd, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not power on sensor\n");
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_write_reg(fd, AS7341_CFG6, 0x40) < 0) {
        fprintf(stderr, "Error: Could not configure SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_reg(fd, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable spectral measurement\n");
        return -1;
    }

    return 0;
}

// Read spectral data function
int read_spectral_data(int fd, uint16_t *data) {
    data[0] = (uint16_t)i2c_read_reg(fd, AS7341_F1DATAH) << 8 | i2c_read_reg(fd, AS7341_F1DATAL);
    data[1] = (uint16_t)i2c_read_reg(fd, AS7341_F2DATAH) << 8 | i2c_read_reg(fd, AS7341_F2DATAL);
    data[2] = (uint16_t)i2c_read_reg(fd, AS7341_F3DATAH) << 8 | i2c_read_reg(fd, AS7341_F3DATAL);
    data[3] = (uint16_t)i2c_read_reg(fd, AS7341_F4DATAH) << 8 | i2c_read_reg(fd, AS7341_F4DATAL);
    data[4] = (uint16_t)i2c_read_reg(fd, AS7341_F5DATAH) << 8 | i2c_read_reg(fd, AS7341_F5DATAL);
    data[5] = (uint16_t)i2c_read_reg(fd, AS7341_F6DATAH) << 8 | i2c_read_reg(fd, AS7341_F6DATAL);
    data[6] = (uint16_t)i2c_read_reg(fd, AS7341_F7DATAH) << 8 | i2c_read_reg(fd, AS7341_F7DATAL);
    data[7] = (uint16_t)i2c_read_reg(fd, AS7341_F8DATAH) << 8 | i2c_read_reg(fd, AS7341_F8DATAL);
    data[8] = (uint16_t)i2c_read_reg(fd, AS7341_CDATAH) << 8 | i2c_read_reg(fd, AS7341_CDATAL);
    data[9] = (uint16_t)i2c_read_reg(fd, AS7341_NIRDATAH) << 8 | i2c_read_reg(fd, AS7341_NIRDATAL);

    return 0;
}

// Lux calculation function
float calculate_lux(uint16_t *data) {
    // Simplified lux approximation (adjust based on sensor calibration)
    float lux = 0.0f;
    for (int i = 0; i < 10; i++) {
        lux += data[i];
    }
    return lux * 0.1f; // Example scaling factor
}

// Log data function
int log_data(FILE *fp, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, lux) < 0) {
        perror("Error: Could not write to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Initialize AS7341 sensor
    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Lux\n");
    }
    rewind(log_file);

    uint16_t spectral_data[10];
    float lux;

    // Main loop
    while (program_running) {
        // Read spectral data
        if (read_spectral_data(i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Error: Could not read spectral data\n");
        } else {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            if (log_data(log_file, lux) < 0) {
                fprintf(stderr, "Error: Could not log data\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        }

        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

