#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define NUM_AXES 3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(int fd, sensor_data_t *data);
float convert_to_g(int16_t raw_data);
int log_data(FILE *fp, sensor_data_t data);
int log_error(FILE *fp, const char *message);
void signal_handler(int sig);
int parse_arguments(int argc, char *argv[]);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;
    }
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    unsigned char buffer[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (read(fd, buffer, 6) == 6) {
            // Combine high and low bytes for each axis
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

            // Convert to g
            data->x_g = convert_to_g(x_raw);
            data->y_g = convert_to_g(y_raw);
            data->z_g = convert_to_g(z_raw);

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            log_error(error_file, "I2C read failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    log_error(error_file, "I2C read failed after multiple retries");
    return -1; // Failure
}

// Convert raw data to g
float convert_to_g(int16_t raw_data) {
    return (float)raw_data * 0.000244;
}

// Log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x_g, data.y_g, data.z_g) < 0) {
        perror("Error writing to CSV file");
        log_error(error_file, "Error writing to CSV file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Log errors to error log file
int log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("Error writing to error log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) {
                    fprintf(stderr, "Invalid interval. Using default value (%d seconds).\n", DEFAULT_INTERVAL);
                    interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(i2c_address);
    if (i2c_fd < 0) {
        log_error(error_file, "I2C initialization failed");
        fclose(error_file);
        return 1;
    }

    // Open data log file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        perror("Error opening data log file");
        log_error(error_file, "Data log file opening failed");
        close(i2c_fd);
        fclose(error_file);
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(data_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (keep_running) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            if (log_data(data_file, sensor_data) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(interval);
    }

    // Cleanup
    close(i2c_fd);
    fclose(data_file);
    fclose(error_file);

    printf("Exiting cleanly.\n");
    return 0;
}

