#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_MULTICAST_PORT 5000
#define I2C_RETRY_COUNT 3

int i2c_fd = -1; // Global I2C file descriptor
int udp_socket = -1; // Global UDP socket

// Function to initialize the I2C bus
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// Function to write a byte to the I2C device
int write_i2c(int fd, uint8_t addr, uint8_t data) {
    int retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        if (write(fd, &data, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        return 0; // Success
    }
    return -1; // Failure after retries
}

// Function to read a byte from the I2C device
int read_i2c(int fd, uint8_t addr, uint8_t *data) {
    int retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        if (read(fd, data, 1) != 1) {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        return 0; // Success
    }
    return -1; // Failure after retries
}

// Function to read the light level from the BH1750 sensor
int read_light_level(int fd, uint16_t *raw_value) {
    uint8_t data[2];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (write(fd, "\x00", 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        usleep(180000); // Wait for measurement (at least 180ms)

        if (read(fd, data, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        *raw_value = (data[0] << 8) | data[1];
        return 0; // Success
    }
    return -1; // Failure after retries
}

// Function to convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    int ttl = 1;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_MULTICAST_PORT);

    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        return -1;
    }

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Configure BH1750 sensor
    if (write_i2c(i2c_fd, BH1750_ADDR, 0x01) < 0) { // Power on
        fprintf(stderr, "Failed to power on BH1750. Exiting.\n");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }
    usleep(50000); // Wait 50ms
    if (write_i2c(i2c_fd, BH1750_ADDR, 0x10) < 0) { // Continuous high-resolution mode
        fprintf(stderr, "Failed to set BH1750 to continuous mode. Exiting.\n");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t raw_value;
        if (read_light_level(i2c_fd, &raw_value) == 0) {
            float lux = convert_to_lux(raw_value);
            if (send_udp_multicast(lux) != 0) {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }
        sleep(1);
    }

    return 0;
}

