#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_LENGTH 8
#define MAGIC_WORD {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09}
#define TLV_TYPE_DETECTED_OBJECTS 6
#define MAX_RANGE 10.0  // Maximum expected range in meters
#define MAX_VELOCITY 5.0 // Maximum expected velocity in m/s

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    double range;
    double velocity;
} RadarData;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int max_length);
int validate_tlv_header(unsigned char *header);
int parse_tlv_payload(unsigned char *payload, int payload_length, RadarData *radar_data, int *num_objects);
int write_data_to_csv(RadarData *radar_data, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart_data(char *buffer, int max_length) {
    int bytes_read = serRead(uart_handle, buffer, max_length);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    }
    return bytes_read;
}

// Validate TLV header
int validate_tlv_header(unsigned char *header) {
    unsigned short type = (header[1] << 8) | header[0];
    unsigned short length = (header[3] << 8) | header[2];

    if (type != TLV_TYPE_DETECTED_OBJECTS) {
        fprintf(stderr, "Invalid TLV type: %d\n", type);
        return -1;
    }

    if (length < 8 || length > 2048) { // Reasonable length check
        fprintf(stderr, "Invalid TLV length: %d\n", length);
        return -1;
    }

    return 0;
}

// Parse TLV payload
int parse_tlv_payload(unsigned char *payload, int payload_length, RadarData *radar_data, int *num_objects) {
    *num_objects = 0;
    for (int i = 0; i < payload_length; i += 8) {
        if (i + 8 > payload_length) {
            fprintf(stderr, "Incomplete object data, skipping.\n");
            continue;
        }

        float range = *((float *)(payload + i));
        float velocity = *((float *)(payload + i + 4));

        if (range > MAX_RANGE || velocity > MAX_VELOCITY) {
            fprintf(stderr, "Invalid range or velocity, skipping object.\n");
            continue;
        }

        radar_data[*num_objects].range = range;
        radar_data[*num_objects].velocity = velocity;
        (*num_objects)++;
    }
    return 0;
}

// Write data to CSV file
int write_data_to_csv(RadarData *radar_data, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, radar_data[i].range, radar_data[i].velocity);
    }
    fflush(csv_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    char buffer[2048];
    unsigned char magic_word[MAGIC_WORD_LENGTH] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};
    unsigned char *current_buffer = buffer;
    int bytes_read;
    int magic_word_index = 0;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart_data(buffer, sizeof(buffer));

        if (bytes_read > 0) {
            // Process the received data
            for (int i = 0; i < bytes_read; i++) {
                unsigned char byte = buffer[i];

                if (magic_word_index < MAGIC_WORD_LENGTH) {
                    if (byte == magic_word[magic_word_index]) {
                        current_buffer[magic_word_index++] = byte;
                        if (magic_word_index == MAGIC_WORD_LENGTH) {
                            // Magic word found, reset index and continue processing
                            magic_word_index = 0;
                            // Validate TLV header
                            unsigned char *header = current_buffer;
                            if (validate_tlv_header(header) == 0) {
                                // Validate TLV payload
                                unsigned char *payload = current_buffer + 8; // After header
                                int payload_length = header[3] << 8 | header[2];
                                RadarData radar_data[100]; // Assuming a maximum of 100 objects
                                int num_objects;

                                if (parse_tlv_payload(payload, payload_length, radar_data, &num_objects) == 0) {
                                    // Write data to CSV
                                    if (write_data_to_csv(radar_data, num_objects) != 0) {
                                        fprintf(stderr, "Error writing to CSV file.\n");
                                    }
                                } else {
                                    fprintf(stderr, "Error parsing TLV payload.\n");
                                }
                            } else {
                                fprintf(stderr, "Error validating TLV header.\n");
                            }
