#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 0
#define TIMEOUT_USEC 500000 // 0.5 seconds
#define MAX_LINE_LENGTH 256
#define MAX_TIMESTAMP_LENGTH 32

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize the UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_SEC;                    // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART with timeout
int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

// Function to parse the radar data
int parse_radar_data(const char *data, long *timestamp, float *range) {
    char *token;
    char *data_copy = strdup(data); // Duplicate the string for strtok
    if (data_copy == NULL) {
        fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(data_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp\n");
        free(data_copy);
        return -1;
    }

    char timestamp_str[MAX_TIMESTAMP_LENGTH];
    strncpy(timestamp_str, token, MAX_TIMESTAMP_LENGTH - 1);
    timestamp_str[MAX_TIMESTAMP_LENGTH - 1] = '\0';

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range\n");
        free(data_copy);
        return -1;
    }

    *range = atof(token);

    free(data_copy);
    return 0;
}

// Function to log the radar data
void log_radar_data(long timestamp, float range) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char line_buffer[MAX_LINE_LENGTH];
    long timestamp;
    float range;

    fprintf(stderr, "Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, line_buffer, sizeof(line_buffer));
        if (bytes_read > 0) {
            if (parse_radar_data(line_buffer, &timestamp, &range) == 0) {
                log_radar_data(timestamp, range);
            } else {
                fprintf(stderr, "Error parsing data: %s\n", line_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
    }

    fprintf(stderr, "Radar data acquisition stopped.\n");

    return EXIT_SUCCESS;
}

