#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define the serial port and baud rate
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for the serial port file descriptor
int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio);
int check_emergency_stop(int left, int middle, int right);
int send_emergency_stop(int serial_fd);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (serial_fd != -1) {
        close(serial_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check for emergency stop condition
int check_emergency_stop(int left, int middle, int right) {
    return (left == 0 && middle == 0 && right == 0);
}

// Function to send emergency stop message over serial port
int send_emergency_stop(int serial_fd) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    char message[256];
    snprintf(message, sizeof(message), "%s EMERGENCY STOP!\n", buf);

    if (serial_fd == -1) {
        fprintf(stderr, "Serial port not initialized\n");
        return -1;
    }

    ssize_t bytes_written = write(serial_fd, message, strlen(message));
    if (bytes_written == -1) {
        fprintf(stderr, "Error writing to serial port\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Open the serial port
    serial_fd = open(SERIAL_PORT, O_WRONLY | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        fprintf(stderr, "Error opening serial port %s\n", SERIAL_PORT);
        gpioTerminate();
        return 1;
    }

    // Configure the serial port (8N1, 115200 baud, no flow control)
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", SERIAL_PORT);
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag &= ~PARENB;        // No parity
    tty.c_cflag &= ~CSTOPB;        // 1 stop bit
    tty.c_cflag &= ~CSIZE;         // Clear size bits
    tty.c_cflag |= CS8;            // 8 data bits
    tty.c_cflag &= ~CRTSCTS;       // No flow control

    tty.c_cflag |= CREAD | CLOCAL; // Turn on READ & ignore ctrl lines

    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_lflag &= ~ECHOE;  // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG;   // Disable interpretation of INTR, QUIT and SUSP

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // Wait 0.5 seconds (5 * 0.1s)

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", SERIAL_PORT);
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            // Error reading sensor, continue to the next iteration
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Log sensor states to the console
        printf("%s Left: %d, Middle: %d, Right: %d\n", buf, left_value, middle_value, right_value);

        // Check for emergency stop condition
        if (check_emergency_stop(left_value, middle_value, right_value)) {
            printf("%s EMERGENCY STOP!\n", buf);
            if (send_emergency_stop(serial_fd) != 0) {
